struct CraftRateState {
    next_allowed: Instant,
    penalty_level: u32,
}

struct CraftRateLimiter {
    state: AsyncMutex<CraftRateState>,
    rate_limit_events: AtomicU64,
    cooldown_until: AtomicI64,
}

impl Default for CraftRateLimiter {
    fn default() -> Self {
        Self {
            state: AsyncMutex::new(CraftRateState {
                next_allowed: Instant::now(),
                penalty_level: 0,
            }),
            rate_limit_events: AtomicU64::new(0),
            cooldown_until: AtomicI64::new(0),
        }
    }
}

impl CraftRateLimiter {
    async fn wait_turn(&self) {
        self.wait_turn_with_interval(CRAFT_REQUEST_INTERVAL_MS)
            .await;
    }

    async fn wait_turn_with_interval(&self, interval_ms: u64) {
        let delay = {
            let mut state = self.state.lock().await;
            let now = Instant::now();
            let scheduled = state.next_allowed.max(now);
            state.next_allowed = scheduled + Duration::from_millis(interval_ms);
            scheduled.saturating_duration_since(now)
        };
        if !delay.is_zero() {
            tokio::time::sleep(delay).await;
        }
    }

    async fn record_success(&self) {
        let mut state = self.state.lock().await;
        state.penalty_level = state.penalty_level.saturating_sub(1);
        if self.cooldown_until.load(Ordering::Relaxed) <= now_timestamp() {
            self.cooldown_until.store(0, Ordering::Relaxed);
        }
    }

    async fn record_rate_limit(&self, retry_after_seconds: u64, attempt: u32) {
        self.rate_limit_events.fetch_add(1, Ordering::Relaxed);
        let mut state = self.state.lock().await;
        state.penalty_level = state.penalty_level.saturating_add(1).min(6);
        let exponential = 2_u64.saturating_pow((attempt + state.penalty_level).min(5));
        let jitter = rand::thread_rng().next_u64() % 750;
        let delay = Duration::from_millis(
            retry_after_seconds
                .max(exponential)
                .min(60)
                .saturating_mul(1_000)
                .saturating_add(jitter),
        );
        let next = Instant::now() + delay;
        if next > state.next_allowed {
            state.next_allowed = next;
        }
        self.cooldown_until.store(
            now_timestamp().saturating_add(delay.as_secs() as i64),
            Ordering::Relaxed,
        );
    }
}

