fn craft_markdown_tags(markdown: &str) -> Vec<String> {
    let mut tags = Vec::new();
    let mut seen = HashSet::new();
    let mut in_code_fence = false;
    for line in markdown.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            in_code_fence = !in_code_fence;
            continue;
        }
        if in_code_fence {
            continue;
        }
        let mut in_inline_code = false;
        let characters = line.char_indices().collect::<Vec<_>>();
        let mut index = 0;
        while index < characters.len() {
            let (_, character) = characters[index];
            if character == '`' {
                in_inline_code = !in_inline_code;
                index += 1;
                continue;
            }
            if in_inline_code || character != '#' {
                index += 1;
                continue;
            }
            let previous = index.checked_sub(1).map(|value| characters[value].1);
            let Some((start, first)) = characters.get(index + 1).copied() else {
                break;
            };
            let boundary_before = previous.is_none_or(|value| {
                value.is_whitespace()
                    || matches!(
                        value,
                        '(' | '['
                            | '{'
                            | '\''
                            | '"'
                            | '（'
                            | '【'
                            | '「'
                            | '『'
                            | '，'
                            | '。'
                            | '；'
                            | '：'
                            | '！'
                            | '？'
                            | '、'
                    )
            });
            if !boundary_before
                || first.is_whitespace()
                || first == '#'
                || (!first.is_alphabetic() && first != '_')
            {
                index += 1;
                continue;
            }
            let end_index = characters
                .iter()
                .enumerate()
                .skip(index + 1)
                .find(|(_, (_, value))| {
                    !(value.is_alphanumeric() || matches!(value, '_' | '-' | '/'))
                })
                .map(|(position, _)| position)
                .unwrap_or(characters.len());
            let end = characters
                .get(end_index)
                .map(|(offset, _)| *offset)
                .unwrap_or(line.len());
            let tag = line[start..end].trim_matches('/');
            let normalized = tag.to_lowercase();
            let looks_like_color = matches!(tag.len(), 3 | 4 | 6 | 8)
                && tag.chars().all(|value| value.is_ascii_hexdigit());
            if !tag.is_empty()
                && tag.chars().count() <= 80
                && !looks_like_color
                && seen.insert(normalized)
            {
                tags.push(tag.to_string());
            }
            index = end_index.max(index + 1);
        }
    }
    tags
}

