enum CraftFetchedDocument {
    Content(IndexedDocument),
    AttachmentsOnly(IndexedDocument),
}

fn classify_craft_document_fetch(
    previous_hash: Option<&str>,
    document: IndexedDocument,
) -> CraftFetchedDocument {
    if previous_hash == Some(document.content_hash.as_str()) {
        CraftFetchedDocument::AttachmentsOnly(document)
    } else {
        CraftFetchedDocument::Content(document)
    }
}

