fn random_url_safe(byte_count: usize) -> String {
    let mut bytes = vec![0_u8; byte_count];
    rand::thread_rng().fill_bytes(&mut bytes);
    URL_SAFE_NO_PAD.encode(bytes)
}

#[cfg(windows)]
fn open_external(_app: &AppHandle, target: &str) -> Result<(), String> {
    use std::process::Command;

    if target.starts_with("https://") || target.starts_with("http://") {
        return tauri_plugin_opener::open_url(target, None::<&str>)
            .map_err(|error| format!("无法交给系统浏览器打开：{error}"));
    }

    let direct_app = if target.starts_with("obsidian://") {
        [
            PathBuf::from(r"C:\Program Files\Obsidian\Obsidian.exe"),
            std::env::var_os("LOCALAPPDATA")
                .map(PathBuf::from)
                .unwrap_or_default()
                .join(r"Programs\Obsidian\Obsidian.exe"),
        ]
        .into_iter()
        .find(|path| path.is_file())
    } else if target.starts_with("craftdocs://") || target.starts_with("craft://") {
        std::env::var_os("LOCALAPPDATA")
            .map(PathBuf::from)
            .map(|path| path.join(r"Programs\Craft\Craft.exe"))
            .filter(|path| path.is_file())
    } else {
        None
    };

    let mut command = if let Some(executable) = direct_app {
        let mut command = Command::new(executable);
        command.arg(target);
        command
    } else {
        let mut command = Command::new("explorer.exe");
        command.arg(target);
        command
    };
    command
        .spawn()
        .map(|_| ())
        .map_err(|error| format!("无法交给系统打开：{error}"))
}

#[cfg(all(not(windows), not(mobile)))]
fn open_external(_app: &AppHandle, target: &str) -> Result<(), String> {
    tauri_plugin_opener::open_url(target, None::<&str>).map_err(|error| error.to_string())
}

#[cfg(mobile)]
fn open_external(app: &AppHandle, target: &str) -> Result<(), String> {
    #[cfg(target_os = "android")]
    if Url::parse(target).ok().is_some_and(|url| {
        matches!(url.host_str(), Some("dida365.com" | "ticktick.com"))
            && url.path().starts_with("/webapp")
    }) {
        return app
            .state::<AndroidSourceOpener>()
            .0
            .run_mobile_plugin::<()>("openDida", serde_json::json!({ "url": target }))
            .map_err(|error| error.to_string());
    }
    app.opener()
        .open_url(target, None::<&str>)
        .map_err(|error| error.to_string())
}

#[cfg(target_os = "android")]
struct AndroidSourceOpener(tauri::plugin::PluginHandle<tauri::Wry>);

#[tauri::command]
fn open_external_url(app: AppHandle, url: String) -> Result<(), String> {
    let parsed = Url::parse(url.trim()).map_err(|_| "无效的外部链接".to_string())?;
    if !matches!(parsed.scheme(), "http" | "https" | "obsidian" | "craftdocs") {
        return Err("不支持此链接类型".to_string());
    }
    open_external(&app, parsed.as_str())
}

fn is_allowed_craft_web_host(host: Option<&str>) -> bool {
    host.map(|host| {
        let host = host.to_ascii_lowercase();
        host == "craft.do" || host.ends_with(".craft.do")
    })
    .unwrap_or(false)
}

fn normalize_craft_open_mode(mode: &str) -> Option<&'static str> {
    match mode {
        CRAFT_OPEN_MODE_BRIDGE | CRAFT_OPEN_MODE_BACKGROUND_WEB => Some(CRAFT_OPEN_MODE_BRIDGE),
        CRAFT_OPEN_MODE_WEB => Some(CRAFT_OPEN_MODE_WEB),
        CRAFT_OPEN_MODE_CLIENT => Some(CRAFT_OPEN_MODE_CLIENT),
        _ => None,
    }
}

fn craft_bridge_client() -> Result<&'static reqwest::Client, String> {
    match CRAFT_BRIDGE_CLIENT.get_or_init(|| {
        reqwest::Client::builder()
            // CraftBridge is loopback-only. Environment proxy variables must not
            // reroute 127.0.0.1 requests to a desktop HTTP proxy.
            .no_proxy()
            .timeout(CRAFT_BRIDGE_OPEN_TIMEOUT)
            .build()
            .map_err(|error| format!("无法初始化 CraftBridge 客户端：{error}"))
    }) {
        Ok(client) => Ok(client),
        Err(error) => Err(error.clone()),
    }
}

#[derive(Serialize)]
struct CraftBridgeOpenRequest<'a> {
    url: &'a str,
}

#[derive(Deserialize)]
struct CraftBridgeOpenResponse {
    ok: bool,
    action: Option<String>,
    error: Option<String>,
}

#[derive(Deserialize)]
struct CraftBridgeHealthResponse {
    ok: bool,
    runtime: String,
    service: String,
    version: String,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct OpenResultOutcome {
    #[serde(skip_serializing_if = "Option::is_none")]
    craft_bridge_action: Option<String>,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct CraftBridgeStatus {
    available: bool,
    version: Option<String>,
    message: String,
}

fn safe_craft_bridge_error(body: &str) -> String {
    let candidate = serde_json::from_str::<CraftBridgeOpenResponse>(body)
        .ok()
        .and_then(|payload| payload.error)
        .unwrap_or_else(|| body.trim().to_string());
    let candidate = candidate.chars().take(240).collect::<String>();
    if candidate.is_empty()
        || candidate.contains("http://")
        || candidate.contains("https://")
        || candidate.contains("?s=")
        || candidate.contains("&s=")
    {
        "CraftBridge 拒绝了打开请求".to_string()
    } else {
        candidate
    }
}

fn parse_craft_bridge_success(body: &str) -> Result<String, String> {
    let payload = serde_json::from_str::<CraftBridgeOpenResponse>(body)
        .map_err(|_| "CraftBridge 返回了无法识别的响应".to_string())?;
    if !payload.ok {
        return Err(payload
            .error
            .as_deref()
            .map(safe_craft_bridge_error)
            .unwrap_or_else(|| "CraftBridge 拒绝了打开请求".to_string()));
    }
    match payload.action.as_deref() {
        // CraftBridge 0.15.1+ accepts requests while Craft is starting and
        // finishes them asynchronously after the editor becomes ready.
        Some("activated" | "updated" | "opened" | "queued") => {
            Ok(payload.action.unwrap_or_default())
        }
        _ => Err("CraftBridge 返回了未知的打开状态".to_string()),
    }
}

fn parse_craft_bridge_health(body: &str) -> Result<String, String> {
    let payload = serde_json::from_str::<CraftBridgeHealthResponse>(body)
        .map_err(|_| "CraftBridge 健康检查响应无法识别".to_string())?;
    if !payload.ok || payload.service != "CraftBridge" || payload.runtime != "rust-native" {
        return Err("5595 端口不是受支持的 CraftBridge 服务".to_string());
    }
    if payload.version.trim().is_empty() {
        return Err("CraftBridge 没有返回版本号".to_string());
    }
    Ok(payload.version)
}

async fn check_craft_bridge_health(client: &reqwest::Client) -> Result<String, String> {
    let response = client
        .get(CRAFT_BRIDGE_HEALTH_URL)
        .timeout(Duration::from_secs(3))
        .send()
        .await
        .map_err(|_| "CraftBridge 服务不可用，请启动或重新安装 CraftBridge 后重试".to_string())?;
    let status = response.status();
    let body = response
        .text()
        .await
        .map_err(|_| "无法读取 CraftBridge 健康检查响应".to_string())?;
    if !status.is_success() {
        return Err(format!(
            "CraftBridge 健康检查失败（HTTP {}）",
            status.as_u16()
        ));
    }
    parse_craft_bridge_health(&body)
}

async fn craft_bridge_health_error(client: &reqwest::Client) -> String {
    match check_craft_bridge_health(client).await {
        Ok(_) => "CraftBridge 服务可访问，但本次打开请求失败，请重试".to_string(),
        Err(error) => error,
    }
}

#[cfg(windows)]
fn craft_bridge_executable_in(local_app_data: &Path) -> PathBuf {
    local_app_data.join(r"Programs\CraftBridge\CraftBridge.exe")
}

#[cfg(windows)]
fn start_installed_craft_bridge() -> Result<(), String> {
    use std::{os::windows::process::CommandExt, process::Stdio};

    const CREATE_NO_WINDOW: u32 = 0x0800_0000;
    let local_app_data = std::env::var_os("LOCALAPPDATA")
        .map(PathBuf::from)
        .ok_or_else(|| "无法定位 Windows LocalAppData 目录".to_string())?;
    let executable = craft_bridge_executable_in(&local_app_data);
    if !executable.is_file() {
        return Err("未找到 CraftBridge，请先安装 CraftBridge".to_string());
    }
    Command::new(executable)
        .creation_flags(CREATE_NO_WINDOW)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .map(|_| ())
        .map_err(|error| format!("无法启动 CraftBridge：{error}"))
}

#[cfg(not(windows))]
fn start_installed_craft_bridge() -> Result<(), String> {
    Err("当前平台不支持自动启动 CraftBridge".to_string())
}

async fn recover_craft_bridge(client: &reqwest::Client) -> Result<(), String> {
    if check_craft_bridge_health(client).await.is_ok() {
        return Ok(());
    }
    start_installed_craft_bridge()?;
    for _ in 0..20 {
        tokio::time::sleep(Duration::from_millis(250)).await;
        if check_craft_bridge_health(client).await.is_ok() {
            return Ok(());
        }
    }
    Err("CraftBridge 已启动，但未能在 5 秒内就绪，请检查其运行状态".to_string())
}

async fn open_craft_via_bridge(target: &str) -> Result<String, String> {
    let target_url =
        Url::parse(target).map_err(|_| "CraftBridge 需要有效的 Craft HTTPS 链接".to_string())?;
    if target_url.scheme() != "https" || !is_allowed_craft_web_host(target_url.host_str()) {
        return Err("CraftBridge 只允许打开 Craft 官方 HTTPS 地址".to_string());
    }

    let client = craft_bridge_client()?;
    let mut recovered_connection = false;
    let mut retried_unavailable = false;
    loop {
        let response = match client
            .post(CRAFT_BRIDGE_OPEN_URL)
            .header("X-CraftBridge-Request", "open-url")
            .json(&CraftBridgeOpenRequest { url: target })
            .send()
            .await
        {
            Ok(response) => response,
            Err(error) => {
                if error.is_connect() && !recovered_connection {
                    recovered_connection = true;
                    recover_craft_bridge(client).await?;
                    continue;
                }
                let health_error = craft_bridge_health_error(client).await;
                return if error.is_timeout() {
                    Err(format!(
                        "CraftBridge 请求超时，Craft 可能已经打开；{health_error}"
                    ))
                } else {
                    Err(health_error)
                };
            }
        };
        let status = response.status();
        let body = response
            .text()
            .await
            .map_err(|_| "无法读取 CraftBridge 响应".to_string())?;
        if status.as_u16() == 503 && !retried_unavailable {
            retried_unavailable = true;
            check_craft_bridge_health(client).await?;
            tokio::time::sleep(Duration::from_millis(750)).await;
            continue;
        }
        if !status.is_success() {
            return Err(format!(
                "CraftBridge 打开失败（HTTP {}）：{}",
                status.as_u16(),
                safe_craft_bridge_error(&body)
            ));
        }
        return parse_craft_bridge_success(&body);
    }
}

fn resource_metadata_url(challenge: &str) -> Result<String, String> {
    let prefix = "resource_metadata=\"";
    let start = challenge
        .find(prefix)
        .ok_or_else(|| "MCP 服务没有提供 OAuth resource metadata".to_string())?
        + prefix.len();
    let remainder = &challenge[start..];
    let end = remainder
        .find('"')
        .ok_or_else(|| "OAuth resource metadata 地址格式不正确".to_string())?;
    Ok(remainder[..end].to_string())
}

fn authorization_metadata_urls(
    issuer: &str,
    resource_metadata_url: &str,
) -> Result<Vec<Url>, String> {
    let issuer_url = Url::parse(issuer).map_err(|error| format!("OAuth issuer 无效：{error}"))?;
    let issuer_path = issuer_url.path().trim_end_matches('/');
    let mut candidates = Vec::new();

    let mut issuer_metadata = issuer_url.clone();
    issuer_metadata.set_path(&format!(
        "/.well-known/oauth-authorization-server{issuer_path}"
    ));
    issuer_metadata.set_query(None);
    issuer_metadata.set_fragment(None);
    candidates.push(issuer_metadata);

    let mut issuer_root_metadata = issuer_url.clone();
    issuer_root_metadata.set_path("/.well-known/oauth-authorization-server");
    issuer_root_metadata.set_query(None);
    issuer_root_metadata.set_fragment(None);
    if !candidates
        .iter()
        .any(|candidate| candidate == &issuer_root_metadata)
    {
        candidates.push(issuer_root_metadata);
    }

    if let Ok(mut resource_metadata) = Url::parse(resource_metadata_url) {
        resource_metadata.set_path("/.well-known/oauth-authorization-server");
        resource_metadata.set_query(None);
        resource_metadata.set_fragment(None);
        if !candidates
            .iter()
            .any(|candidate| candidate == &resource_metadata)
        {
            candidates.push(resource_metadata);
        }
    }
    Ok(candidates)
}

async fn discover_oauth(
    client: &reqwest::Client,
    endpoint: &str,
) -> Result<(ProtectedResourceMetadata, AuthorizationServerMetadata), String> {
    let response = client
        .post(endpoint)
        .header("Accept", "application/json, text/event-stream")
        .json(&json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": MCP_PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": { "name": "Hub", "version": env!("CARGO_PKG_VERSION") }
            }
        }))
        .send()
        .await
        .map_err(|error| format!("无法连接 MCP：{error}"))?;

    if response.status() != reqwest::StatusCode::UNAUTHORIZED {
        return Err(format!(
            "MCP OAuth 探测返回了意外状态：{}",
            response.status()
        ));
    }

    let challenge = response
        .headers()
        .get(WWW_AUTHENTICATE)
        .and_then(|value| value.to_str().ok())
        .ok_or_else(|| "MCP 没有返回 WWW-Authenticate".to_string())?;
    let resource_url = resource_metadata_url(challenge)?;

    let protected: ProtectedResourceMetadata = client
        .get(&resource_url)
        .header("Accept", "application/json")
        .send()
        .await
        .map_err(|error| format!("无法读取 OAuth 资源信息：{error}"))?
        .error_for_status()
        .map_err(|error| format!("OAuth 资源信息请求失败：{error}"))?
        .json()
        .await
        .map_err(|error| format!("OAuth 资源信息无法解析：{error}"))?;

    let issuer = protected
        .authorization_servers
        .first()
        .ok_or_else(|| "OAuth 没有提供 authorization server".to_string())?;
    let metadata_urls = authorization_metadata_urls(issuer, &resource_url)?;
    let mut failures = Vec::new();
    let mut authorization = None;
    for metadata_url in metadata_urls {
        let response = match client
            .get(metadata_url.clone())
            .header("Accept", "application/json")
            .header("MCP-Protocol-Version", MCP_PROTOCOL_VERSION)
            .send()
            .await
        {
            Ok(response) => response,
            Err(error) => {
                failures.push(format!("{metadata_url}：{error}"));
                continue;
            }
        };
        if !response.status().is_success() {
            failures.push(format!("{metadata_url}：HTTP {}", response.status()));
            continue;
        }
        match response.json::<AuthorizationServerMetadata>().await {
            Ok(metadata) => {
                authorization = Some(metadata);
                break;
            }
            Err(error) => failures.push(format!("{metadata_url}：{error}")),
        }
    }
    let authorization =
        authorization.ok_or_else(|| format!("OAuth 服务信息请求失败：{}", failures.join("；")))?;

    Ok((protected, authorization))
}

async fn register_client(
    client: &reqwest::Client,
    metadata: &AuthorizationServerMetadata,
    redirect_uri: &str,
) -> Result<ClientRegistration, String> {
    let auth_method = if metadata
        .token_endpoint_auth_methods_supported
        .iter()
        .any(|method| method == "client_secret_post")
    {
        "client_secret_post"
    } else if metadata
        .token_endpoint_auth_methods_supported
        .iter()
        .any(|method| method == "none")
    {
        "none"
    } else {
        "client_secret_basic"
    };
    let mut grant_types = vec!["authorization_code"];
    if metadata
        .grant_types_supported
        .iter()
        .any(|grant| grant == "refresh_token")
    {
        grant_types.push("refresh_token");
    }
    client
        .post(&metadata.registration_endpoint)
        .header("Accept", "application/json")
        .json(&json!({
            "client_name": "Hub Desktop",
            "redirect_uris": [redirect_uri],
            "grant_types": grant_types,
            "response_types": ["code"],
            "token_endpoint_auth_method": auth_method
        }))
        .send()
        .await
        .map_err(|error| format!("OAuth 客户端注册失败：{error}"))?
        .error_for_status()
        .map_err(|error| format!("OAuth 客户端注册被拒绝：{error}"))?
        .json()
        .await
        .map_err(|error| format!("OAuth 客户端信息无法解析：{error}"))
}

async fn write_callback_response(
    stream: &mut tokio::net::TcpStream,
    status: &str,
    html: &str,
) -> Result<(), String> {
    let response = format!(
        "HTTP/1.1 {status}\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{html}",
        html.as_bytes().len()
    );
    stream
        .write_all(response.as_bytes())
        .await
        .map_err(|error| format!("无法响应 OAuth 回调：{error}"))
}

async fn wait_for_oauth_callback(
    listener: TcpListener,
    expected_state: &str,
) -> Result<String, String> {
    loop {
        let (mut stream, _) = listener
            .accept()
            .await
            .map_err(|error| format!("OAuth 回调监听失败：{error}"))?;
        let mut buffer = vec![0_u8; 16 * 1024];
        let bytes_read = stream
            .read(&mut buffer)
            .await
            .map_err(|error| format!("OAuth 回调读取失败：{error}"))?;
        let request = String::from_utf8_lossy(&buffer[..bytes_read]);
        let target = request
            .lines()
            .next()
            .and_then(|line| line.split_whitespace().nth(1));
        let Some(target) = target else {
            continue;
        };
        let callback_url = Url::parse(&format!("http://127.0.0.1{target}"))
            .map_err(|error| format!("OAuth 回调地址无效：{error}"))?;
        if callback_url.path() != "/oauth/callback" {
            continue;
        }

        let params = callback_url
            .query_pairs()
            .collect::<std::collections::HashMap<_, _>>();
        if let Some(error) = params.get("error") {
            let html = "<meta charset=\"utf-8\"><h1>资料库授权失败</h1><p>可以关闭此页面。</p>";
            write_callback_response(&mut stream, "400 Bad Request", html).await?;
            return Err(format!("资料库授权失败：{error}"));
        }
        if params.get("state").map(|value| value.as_ref()) != Some(expected_state) {
            let html = "<meta charset=\"utf-8\"><h1>授权状态无效</h1><p>请返回应用重新连接。</p>";
            write_callback_response(&mut stream, "400 Bad Request", html).await?;
            return Err("OAuth state 校验失败".to_string());
        }
        let code = params
            .get("code")
            .map(|value| value.to_string())
            .ok_or_else(|| "OAuth 回调没有 authorization code".to_string())?;
        let html = r#"<!doctype html><meta charset="utf-8"><title>Hub</title>
<style>body{font:16px system-ui;display:grid;place-items:center;min-height:90vh;color:#222}main{max-width:520px;text-align:center}</style>
<main><h1>资料库授权完成</h1><p>可以关闭此页面并返回 Hub。</p></main>"#;
        write_callback_response(&mut stream, "200 OK", html).await?;
        return Ok(code);
    }
}

async fn exchange_code(
    client: &reqwest::Client,
    metadata: &AuthorizationServerMetadata,
    registration: &ClientRegistration,
    code: &str,
    redirect_uri: &str,
    code_verifier: &str,
    resource: &str,
) -> Result<TokenResponse, String> {
    let mut form = vec![
        ("grant_type", "authorization_code".to_string()),
        ("code", code.to_string()),
        ("redirect_uri", redirect_uri.to_string()),
        ("client_id", registration.client_id.clone()),
        ("code_verifier", code_verifier.to_string()),
        ("resource", resource.to_string()),
    ];
    if let Some(secret) = &registration.client_secret {
        form.push(("client_secret", secret.clone()));
    }

    client
        .post(&metadata.token_endpoint)
        .header("Accept", "application/json")
        .form(&form)
        .send()
        .await
        .map_err(|error| format!("OAuth Token 请求失败：{error}"))?
        .error_for_status()
        .map_err(|error| format!("OAuth Token 交换失败：{error}"))?
        .json()
        .await
        .map_err(|error| format!("OAuth Token 无法解析：{error}"))
}

fn parse_mcp_body(text: &str, content_type: Option<&str>) -> Result<Value, String> {
    if text.trim().is_empty() {
        return Ok(Value::Null);
    }
    if content_type
        .unwrap_or_default()
        .contains("text/event-stream")
    {
        let data = text
            .lines()
            .filter_map(|line| line.strip_prefix("data:"))
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .collect::<Vec<_>>()
            .join("\n");
        return serde_json::from_str(&data)
            .map_err(|error| format!("MCP SSE 响应无法解析：{error}"));
    }
    serde_json::from_str(text).map_err(|error| format!("MCP JSON 响应无法解析：{error}"))
}

async fn mcp_post(
    client: &reqwest::Client,
    endpoint: &str,
    access_token: &str,
    session_id: Option<&str>,
    protocol_version: &str,
    payload: &Value,
) -> Result<(Value, Option<String>), String> {
    let mut observation = craft_cache_probe::McpRequestObservation::begin(payload);
    let mut request = client
        .post(endpoint)
        .bearer_auth(access_token)
        .header("Accept", "application/json, text/event-stream")
        .json(payload);
    if payload.get("method").and_then(Value::as_str) != Some("initialize") {
        request = request.header("MCP-Protocol-Version", protocol_version);
    }
    if let Some(session_id) = session_id {
        request = request.header("Mcp-Session-Id", session_id);
    }
    let response = request.send().await.map_err(|error| {
        observation.transport_error(&error);
        format!("MCP 请求失败：{error}")
    })?;
    let status = response.status();
    observation.response(status);
    let retry_after_seconds = response
        .headers()
        .get(RETRY_AFTER)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.trim().parse::<u64>().ok())
        .unwrap_or(0);
    let response_session = response
        .headers()
        .get("mcp-session-id")
        .and_then(|value| value.to_str().ok())
        .map(str::to_string)
        .or_else(|| session_id.map(str::to_string));
    let content_type = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(str::to_string);
    let text = craft_cache_probe::response_text(response)
        .await
        .map_err(|error| {
            observation.failed("responseBody");
            error
        })?;
    if !status.is_success() {
        observation.failed("httpError");
        if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
            return Err(format!("MCP_RATE_LIMIT:{retry_after_seconds}"));
        }
        let detail = text.trim();
        return Err(if detail.is_empty() {
            format!("MCP 返回 {status}")
        } else {
            format!(
                "MCP 返回 {status}：{}",
                detail.chars().take(500).collect::<String>()
            )
        });
    }
    let body = parse_mcp_body(&text, content_type.as_deref()).map_err(|error| {
        observation.failed("responseParse");
        error
    })?;
    observation.completed(&body);
    if let Some(error) = body.get("error") {
        return Err(format!("MCP JSON-RPC 错误：{error}"));
    }
    Ok((body, response_session))
}

async fn feishu_mcp_post(
    client: &reqwest::Client,
    endpoint: &str,
    access_token: &str,
    session_id: Option<&str>,
    payload: &Value,
) -> Result<(Value, Option<String>), String> {
    let mut request = client
        .post(endpoint)
        .header("X-Lark-MCP-UAT", access_token)
        .header("X-Lark-MCP-Allowed-Tools", FEISHU_ALLOWED_TOOLS)
        .header("Accept", "application/json, text/event-stream")
        .json(payload);
    if payload.get("method").and_then(Value::as_str) != Some("initialize") {
        request = request.header("MCP-Protocol-Version", FEISHU_MCP_PROTOCOL_VERSION);
    }
    if let Some(session_id) = session_id {
        request = request.header("Mcp-Session-Id", session_id);
    }
    let response = request
        .send()
        .await
        .map_err(|error| format!("飞书 MCP 请求失败：{error}"))?;
    let status = response.status();
    let response_session = response
        .headers()
        .get("mcp-session-id")
        .and_then(|value| value.to_str().ok())
        .map(str::to_string)
        .or_else(|| session_id.map(str::to_string));
    let content_type = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(str::to_string);
    let text = if status.is_success() {
        http_body::text(response, http_body::MCP_BYTES).await?
    } else {
        http_body::diagnostic(response).await
    };
    if !status.is_success() {
        return Err(format!("飞书 MCP 返回 HTTP {status}：{}", text.trim()));
    }
    let body = parse_mcp_body(&text, content_type.as_deref())?;
    if let Some(error) = body.get("error") {
        return Err(format!("飞书 MCP JSON-RPC 错误：{error}"));
    }
    Ok((body, response_session))
}

async fn initialize_feishu_transport(
    client: &reqwest::Client,
    access_token: String,
) -> Result<AuthenticatedConnection, String> {
    let (initialized, session_id) = feishu_mcp_post(
        client,
        FEISHU_MCP_URL,
        &access_token,
        None,
        &json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": FEISHU_MCP_PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": { "name": "Hub", "version": env!("CARGO_PKG_VERSION") }
            }
        }),
    )
    .await?;
    let (tool_list, _) = feishu_mcp_post(
        client,
        FEISHU_MCP_URL,
        &access_token,
        session_id.as_deref(),
        &json!({"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}),
    )
    .await?;
    let tools = tool_list["result"]["tools"]
        .as_array()
        .into_iter()
        .flatten()
        .map(|tool| ToolSummary {
            name: tool["name"].as_str().unwrap_or_default().to_string(),
            description: tool["description"].as_str().unwrap_or_default().to_string(),
            inputs: tool["inputSchema"]["properties"]
                .as_object()
                .map(|properties| properties.keys().cloned().collect::<BTreeSet<_>>())
                .unwrap_or_default()
                .into_iter()
                .collect(),
        })
        .collect::<Vec<_>>();
    Ok(AuthenticatedConnection {
        session: McpSession {
            space_id: String::new(),
            space_name: String::new(),
            endpoint: FEISHU_MCP_URL.to_string(),
            access_token,
            session_id,
            protocol_version: FEISHU_MCP_PROTOCOL_VERSION.to_string(),
            deep_link_template: None,
            rate_limiter: Arc::new(CraftRateLimiter::default()),
        },
        server_name: initialized["result"]["serverInfo"]["name"]
            .as_str()
            .unwrap_or("飞书 MCP")
            .to_string(),
        server_version: initialized["result"]["serverInfo"]["version"]
            .as_str()
            .unwrap_or_default()
            .to_string(),
        tools,
    })
}

async fn call_feishu_tool_raw(
    client: &reqwest::Client,
    session: &McpSession,
    tool_name: &str,
    arguments: Value,
    request_id: u64,
) -> Result<Value, String> {
    if !FEISHU_ALLOWED_TOOLS
        .split(',')
        .any(|allowed| allowed == tool_name)
    {
        return Err(format!("飞书只读模式禁止调用 MCP 工具 {tool_name}"));
    }
    let (body, _) = feishu_mcp_post(
        client,
        &session.endpoint,
        &session.access_token,
        session.session_id.as_deref(),
        &json!({
            "jsonrpc":"2.0",
            "id":request_id,
            "method":"tools/call",
            "params":{"name":tool_name,"arguments":arguments}
        }),
    )
    .await?;
    let result = body.get("result").cloned().unwrap_or(Value::Null);
    if result
        .get("isError")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Err(format!(
            "飞书工具 {tool_name} 调用失败：{}",
            tool_result_text(&result)
        ));
    }
    Ok(result)
}

async fn call_craft_read_raw(
    client: &reqwest::Client,
    session: &McpSession,
    command: &str,
    request_id: u64,
) -> Result<Value, String> {
    let mut body = None;
    for attempt in 0..CRAFT_REQUEST_MAX_ATTEMPTS {
        session.rate_limiter.wait_turn().await;
        match mcp_post(
            client,
            &session.endpoint,
            &session.access_token,
            session.session_id.as_deref(),
            &session.protocol_version,
            &json!({
                "jsonrpc": "2.0",
                "id": request_id,
                "method": "tools/call",
                "params": {
                    "name": "craft_read",
                    "arguments": { "command": command }
                }
            }),
        )
        .await
        {
            Ok((value, _)) => {
                session.rate_limiter.record_success().await;
                body = Some(value);
                break;
            }
            Err(error) => {
                if let Some(retry_after) = error
                    .strip_prefix("MCP_RATE_LIMIT:")
                    .and_then(|value| value.parse::<u64>().ok())
                {
                    session
                        .rate_limiter
                        .record_rate_limit(retry_after, attempt)
                        .await;
                } else if craft_transport_error_is_transient(&error)
                    && attempt + 1 < CRAFT_REQUEST_MAX_ATTEMPTS
                {
                    tokio::time::sleep(Duration::from_millis(
                        300_u64.saturating_mul(1_u64 << attempt.min(4)),
                    ))
                    .await;
                } else {
                    return Err(error);
                }
            }
        }
    }
    let body =
        body.ok_or_else(|| "Craft 请求持续受到频率限制，已暂停本轮读取并保留同步进度".to_string())?;
    let result = body.get("result").cloned().unwrap_or(Value::Null);
    if result
        .get("isError")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Err(format!("Craft 读取失败：{}", tool_result_text(&result)));
    }
    Ok(result)
}

async fn call_craft_tool_raw(
    client: &reqwest::Client,
    session: &McpSession,
    tool_name: &str,
    arguments: Value,
    request_id: u64,
) -> Result<Value, String> {
    let retry_safe = craft_tool_call_is_retry_safe(tool_name, &arguments);
    let mut body = None;
    for attempt in 0..CRAFT_REQUEST_MAX_ATTEMPTS {
        session.rate_limiter.wait_turn().await;
        task_sync_library_checkpoint(None)?;
        task_sync_library_checkpoint(Some(&session.space_id))?;
        match mcp_post(
            client,
            &session.endpoint,
            &session.access_token,
            session.session_id.as_deref(),
            &session.protocol_version,
            &json!({
                "jsonrpc": "2.0",
                "id": request_id,
                "method": "tools/call",
                "params": { "name": tool_name, "arguments": arguments.clone() }
            }),
        )
        .await
        {
            Ok((value, _)) => {
                body = Some(value);
                break;
            }
            Err(error) => {
                if let Some(retry_after) = error
                    .strip_prefix("MCP_RATE_LIMIT:")
                    .and_then(|value| value.parse::<u64>().ok())
                {
                    session
                        .rate_limiter
                        .record_rate_limit(retry_after, attempt)
                        .await;
                } else if retry_safe
                    && craft_transport_error_is_transient(&error)
                    && attempt + 1 < CRAFT_REQUEST_MAX_ATTEMPTS
                {
                    tokio::time::sleep(Duration::from_millis(
                        300_u64.saturating_mul(1_u64 << attempt.min(4)),
                    ))
                    .await;
                } else {
                    return Err(error);
                }
            }
        }
    }
    let body = body.ok_or_else(|| "Craft 请求重试后仍未返回结果".to_string())?;
    let result = body.get("result").cloned().unwrap_or(Value::Null);
    if result
        .get("isError")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Err(format!(
            "Craft 工具 {tool_name} 调用失败：{}",
            tool_result_text(&result)
        ));
    }
    session.rate_limiter.record_success().await;
    Ok(result)
}

fn craft_transport_error_is_transient(error: &str) -> bool {
    // This prefix is produced by mcp_post from the actual HTTP status. An
    // upstream error body must not grant recovery for a permanent HTTP error.
    if let Some(status) = error
        .strip_prefix("MCP 返回 ")
        .map(|detail| detail.strip_prefix("HTTP ").unwrap_or(detail))
        .and_then(|detail| detail.split([' ', '：']).next())
        .and_then(|status| status.parse::<u16>().ok())
    {
        return matches!(status, 502 | 503 | 504);
    }
    let lower = error.to_ascii_lowercase();
    lower.contains("error sending request")
        || lower.contains("timed out")
        || lower.contains("timeout")
        || lower.contains("connection reset")
        || lower.contains("connection closed")
        || lower.contains("connection aborted")
        || lower.contains("dns error")
        || lower.contains("tcp connect")
        || lower.contains("http 502")
        || lower.contains("http 503")
        || lower.contains("http 504")
}

fn craft_tool_call_is_retry_safe(tool_name: &str, arguments: &Value) -> bool {
    if tool_name != "craft_write" {
        return true;
    }
    let Some(command) = arguments.get("command").and_then(Value::as_str) else {
        return false;
    };
    command.split(';').all(|part| {
        let part = part.trim_start();
        // Deletes are idempotent from the syncer's perspective: if the first
        // request reached Craft but its response was lost, retrying confirms
        // the same end state instead of leaving a false sync failure.
        part.starts_with("tasks update ")
            || part.starts_with("tasks delete ")
            || part.starts_with("blocks delete ")
            || part.starts_with("blocks move ")
    })
}

async fn craft_tool_names(
    client: &reqwest::Client,
    session: &McpSession,
    request_id: u64,
) -> Result<HashSet<String>, String> {
    let (body, _) = mcp_post(
        client,
        &session.endpoint,
        &session.access_token,
        session.session_id.as_deref(),
        &session.protocol_version,
        &json!({"jsonrpc":"2.0","id":request_id,"method":"tools/list","params":{}}),
    )
    .await?;
    Ok(body["result"]["tools"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|tool| tool["name"].as_str().map(str::to_string))
        .collect())
}

async fn mcp_tool_summaries(
    client: &reqwest::Client,
    session: &McpSession,
    request_id: u64,
) -> Result<Vec<ToolSummary>, String> {
    let (body, _) = mcp_post(
        client,
        &session.endpoint,
        &session.access_token,
        session.session_id.as_deref(),
        &session.protocol_version,
        &json!({"jsonrpc":"2.0","id":request_id,"method":"tools/list","params":{}}),
    )
    .await?;
    Ok(body["result"]["tools"]
        .as_array()
        .into_iter()
        .flatten()
        .map(|tool| ToolSummary {
            name: tool["name"].as_str().unwrap_or_default().to_string(),
            description: tool["description"].as_str().unwrap_or_default().to_string(),
            inputs: tool["inputSchema"]["properties"]
                .as_object()
                .map(|properties| properties.keys().cloned().collect::<BTreeSet<_>>())
                .unwrap_or_default()
                .into_iter()
                .collect(),
        })
        .collect())
}

async fn call_mcp_tool_raw(
    client: &reqwest::Client,
    session: &McpSession,
    tool_name: &str,
    arguments: Value,
    request_id: u64,
) -> Result<Value, String> {
    if !DIDA_READ_ONLY_TOOLS.contains(&tool_name) {
        return Err(format!("滴答清单只读模式禁止调用 MCP 工具 {tool_name}"));
    }
    for attempt in 0..=1 {
        session
            .rate_limiter
            .wait_turn_with_interval(DIDA_REQUEST_INTERVAL_MS)
            .await;
        let response = mcp_post(
            client,
            &session.endpoint,
            &session.access_token,
            session.session_id.as_deref(),
            &session.protocol_version,
            &json!({
                "jsonrpc": "2.0",
                "id": request_id,
                "method": "tools/call",
                "params": {
                    "name": tool_name,
                    "arguments": arguments.clone()
                }
            }),
        )
        .await;
        let (body, _) = match response {
            Ok(response) => response,
            Err(error) if attempt == 0 && dida_rate_limit_error(&error) => {
                session.rate_limiter.record_rate_limit(60, attempt).await;
                continue;
            }
            Err(error) => return Err(error),
        };
        let result = body.get("result").cloned().unwrap_or(Value::Null);
        if result
            .get("isError")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            let error = format!(
                "滴答清单工具 {tool_name} 调用失败：{}",
                tool_result_text(&result)
            );
            if attempt == 0 && dida_rate_limit_error(&error) {
                session.rate_limiter.record_rate_limit(60, attempt).await;
                continue;
            }
            return Err(error);
        }
        session.rate_limiter.record_success().await;
        return Ok(result);
    }
    unreachable!()
}

fn dida_rate_limit_error(error: &str) -> bool {
    let lower = error.to_ascii_lowercase();
    lower.contains("exceed_query_limit")
        || lower.contains("query rate limit exceeded")
        || lower.contains("too many requests")
        || lower.contains("http 429")
}

fn dida_lookup_confirms_missing(matching_remote_status: Option<i64>, response_text: &str) -> bool {
    // A matching task-level response is authoritative evidence that the task
    // still exists, regardless of whether it is open or completed. Inventory
    // absence or an unrecognized empty response is never deletion evidence.
    matching_remote_status.is_none() && error_confirms_missing(response_text)
}

fn dida_lookup_error_confirms_missing(error: &str) -> bool {
    error_confirms_missing(error)
}

fn dida_empty_json_response_error(error: &str) -> bool {
    let lower = error.to_ascii_lowercase();
    lower.contains("expecting value: line 1 column 1")
        || lower.contains("unexpected end of json input")
        || lower.contains("unexpected eof while parsing")
}

fn dida_empty_lookup_confirms_missing(
    task_missing_from_inventory: bool,
    lookup_channel_healthy: bool,
    error: &str,
) -> bool {
    task_missing_from_inventory && lookup_channel_healthy && dida_empty_json_response_error(error)
}

fn dida_empty_success_lookup_confirms_missing(
    task_missing_from_undone_inventory: bool,
    lookup_channel_healthy: bool,
    matching_remote_status: Option<i64>,
    response_text: &str,
) -> bool {
    task_missing_from_undone_inventory
        && lookup_channel_healthy
        && matching_remote_status.is_none()
        && response_text.trim().is_empty()
}

async fn probe_dida_task_lookup_channel(
    client: &reqwest::Client,
    session: &McpSession,
    records: &[TaskSyncRecord],
    library_id: &str,
    excluded_task_id: &str,
    default_project_id: &str,
    request_id: u64,
) -> Result<(), String> {
    // `load_task_sync_records` only keeps open Dida rows with missing_syncs=0,
    // so an unfinished record here was returned by this run's remote inventory
    // and is a safe control task for the single-task endpoint.
    let probe = records
        .iter()
        .find(|record| {
            record.provider == PROVIDER_DIDA365
                && record.library_id == library_id
                && !record.completed
                && record.source_id != excluded_task_id
        })
        .ok_or_else(|| "当前滴答远端清单没有可用于验证单任务接口的活动任务".to_string())?;
    let result = call_mcp_tool_raw(
        client,
        session,
        "get_task_by_id",
        json!({"task_id": probe.source_id}),
        request_id,
    )
    .await?;
    let mut returned = Vec::new();
    collect_dida_tasks(
        &tool_result_json(&result),
        default_project_id,
        &mut returned,
    );
    if returned.iter().any(|task| task.id == probe.source_id) {
        Ok(())
    } else {
        Err(format!(
            "健康探针任务“{}”未出现在 get_task_by_id 响应中",
            probe.title
        ))
    }
}

async fn call_dida_write_tool_raw(
    client: &reqwest::Client,
    session: &McpSession,
    tool_name: &str,
    arguments: Value,
    request_id: u64,
) -> Result<Value, String> {
    call_dida_write_tool_raw_with_retries(client, session, tool_name, arguments, request_id, 1)
        .await
}

/// Durable status intents own retry/readback. The transport must never replay
/// their stale payload after a cooldown without returning to that owner.
async fn call_dida_write_tool_raw_once(
    client: &reqwest::Client,
    session: &McpSession,
    tool_name: &str,
    arguments: Value,
    request_id: u64,
) -> Result<Value, String> {
    call_dida_write_tool_raw_with_retries(client, session, tool_name, arguments, request_id, 0)
        .await
}

async fn call_dida_write_tool_raw_with_retries(
    client: &reqwest::Client,
    session: &McpSession,
    tool_name: &str,
    arguments: Value,
    request_id: u64,
    retries: u32,
) -> Result<Value, String> {
    const TASK_WRITE_TOOLS: [&str; 4] =
        ["create_task", "update_task", "complete_task", "delete_task"];
    if !TASK_WRITE_TOOLS.contains(&tool_name) {
        return Err(format!("任务同步不允许调用滴答工具 {tool_name}"));
    }
    for attempt in 0..=retries {
        session
            .rate_limiter
            .wait_turn_with_interval(DIDA_REQUEST_INTERVAL_MS)
            .await;
        task_sync_library_checkpoint(None)?;
        task_sync_library_checkpoint(Some(&session.space_id))?;
        x_bookmarks::dida_reading::write_checkpoint(client, session).await?;
        let response = mcp_post(
            client,
            &session.endpoint,
            &session.access_token,
            session.session_id.as_deref(),
            &session.protocol_version,
            &json!({
                "jsonrpc": "2.0",
                "id": request_id,
                "method": "tools/call",
                "params": { "name": tool_name, "arguments": arguments.clone() }
            }),
        )
        .await;
        let (body, _) = match response {
            Ok(response) => response,
            Err(error) if dida_rate_limit_error(&error) => {
                session.rate_limiter.record_rate_limit(60, attempt).await;
                if attempt < retries {
                    continue;
                }
                return Err(error);
            }
            Err(error) => return Err(error),
        };
        let result = body.get("result").cloned().unwrap_or(Value::Null);
        if result
            .get("isError")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            let error = format!(
                "滴答清单工具 {tool_name} 调用失败：{}",
                tool_result_text(&result)
            );
            if dida_rate_limit_error(&error) {
                session.rate_limiter.record_rate_limit(60, attempt).await;
                if attempt < retries {
                    continue;
                }
            }
            return Err(error);
        }
        session.rate_limiter.record_success().await;
        return Ok(result);
    }
    unreachable!()
}

fn dida_oauth_scope(scopes_supported: &[String]) -> Result<String, String> {
    let missing = DIDA_REQUIRED_SCOPES
        .iter()
        .filter(|scope| {
            !scopes_supported
                .iter()
                .any(|supported| supported == **scope)
        })
        .copied()
        .collect::<Vec<_>>();
    if !missing.is_empty() {
        return Err(format!(
            "滴答 MCP 未声明所需 OAuth 权限：{}",
            missing.join("、")
        ));
    }
    Ok(DIDA_REQUIRED_SCOPES.join(" "))
}

fn tool_result_text(value: &Value) -> String {
    value
        .get("content")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|item| item.get("text").and_then(Value::as_str))
        .collect::<Vec<_>>()
        .join("\n")
}

fn find_deep_link_template(value: &Value) -> Option<String> {
    match value {
        Value::String(text) => {
            if let Ok(json) = serde_json::from_str::<Value>(text) {
                if let Some(found) = find_deep_link_template(&json) {
                    return Some(found);
                }
            }
            text.find("craftdocs://open?").map(|start| {
                text[start..]
                    .split(|character: char| character.is_whitespace() || character == '"')
                    .next()
                    .unwrap_or_default()
                    .to_string()
            })
        }
        Value::Array(items) => items.iter().find_map(find_deep_link_template),
        Value::Object(map) => map.values().find_map(find_deep_link_template),
        _ => None,
    }
}

fn parse_tool_json(value: &Value) -> Option<Value> {
    if let Some(structured) = value.get("structuredContent") {
        return Some(structured.clone());
    }
    let text = tool_result_text(value);
    serde_json::from_str(text.trim()).ok()
}

fn tool_result_json(value: &Value) -> Value {
    parse_tool_json(value).unwrap_or_else(|| value.clone())
}

fn find_nested_string(value: &Value, keys: &[&str]) -> Option<String> {
    match value {
        Value::Object(map) => {
            for key in keys {
                if let Some(text) = map
                    .get(*key)
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|text| !text.is_empty())
                {
                    return Some(text.to_string());
                }
            }
            map.values()
                .find_map(|child| find_nested_string(child, keys))
        }
        Value::Array(items) => items
            .iter()
            .find_map(|child| find_nested_string(child, keys)),
        _ => None,
    }
}

fn find_created_craft_id(value: &Value) -> Option<String> {
    find_nested_string(
        value,
        &["blockId", "block_id", "documentId", "document_id", "id"],
    )
    .filter(|id| valid_craft_block_id(id))
    .or_else(|| {
        let text = tool_result_text(value);
        if let Some(url) = find_deep_link_template(&Value::String(text.clone())) {
            if let Ok(parsed) = Url::parse(&url) {
                if let Some(id) = parsed.query_pairs().find_map(|(key, value)| {
                    matches!(key.as_ref(), "blockId" | "documentId").then(|| value.into_owned())
                }) {
                    return valid_craft_block_id(&id).then_some(id);
                }
            }
        }
        text.split(|character: char| !(character.is_ascii_alphanumeric() || character == '-'))
            .find(|candidate| candidate.len() >= 20 && valid_craft_block_id(candidate))
            .map(str::to_string)
    })
}

fn feishu_user_identity(value: Option<&Value>) -> (Option<String>, Option<String>) {
    let value = value.map(tool_result_json);
    let name = value.as_ref().and_then(|value| {
        find_nested_string(
            value,
            &["name", "display_name", "displayName", "nickname", "en_name"],
        )
    });
    let avatar_url = value
        .as_ref()
        .and_then(|value| {
            find_nested_string(
                value,
                &[
                    "avatar_url",
                    "avatarUrl",
                    "avatar_640",
                    "avatar_240",
                    "avatar_72",
                ],
            )
        })
        .and_then(|value| valid_https_url(&value));
    (name, avatar_url)
}

type FeishuDocumentRef = (String, String, String, String, Option<i64>);

fn collect_feishu_document_refs(value: &Value, refs: &mut Vec<FeishuDocumentRef>) {
    match value {
        Value::Array(items) => {
            for item in items {
                collect_feishu_document_refs(item, refs);
            }
        }
        Value::Object(map) => {
            let explicit_id = [
                "docID",
                "doc_id",
                "document_id",
                "doc_token",
                "obj_token",
                "node_token",
                "token",
            ]
            .iter()
            .find_map(|key| map.get(*key).and_then(Value::as_str))
            .map(str::trim)
            .filter(|text| !text.is_empty())
            .map(str::to_string);
            let url = ["url", "link", "web_url"]
                .iter()
                .find_map(|key| map.get(*key).and_then(Value::as_str))
                .map(str::trim)
                .filter(|text| text.starts_with("http://") || text.starts_with("https://"))
                .map(str::to_string);
            let title = ["title", "name", "document_name", "node_name"]
                .iter()
                .find_map(|key| map.get(*key).and_then(Value::as_str))
                .map(str::trim)
                .filter(|text| !text.is_empty())
                .unwrap_or("未命名飞书文档")
                .to_string();
            let object_type = ["obj_type", "document_type", "docs_type", "type"]
                .iter()
                .find_map(|key| map.get(*key).and_then(Value::as_str))
                .map(str::trim)
                .unwrap_or_default()
                .to_string();
            // A generic `id` also appears on user, request and pagination objects.
            // Accept it only when the same object otherwise resembles a document.
            let generic_id = (url.is_some()
                || ["title", "name", "document_name", "node_name"]
                    .iter()
                    .any(|key| map.get(*key).and_then(Value::as_str).is_some()))
            .then(|| map.get("id").and_then(Value::as_str))
            .flatten()
            .map(str::trim)
            .filter(|text| !text.is_empty())
            .map(str::to_string);
            let id = explicit_id.or(generic_id);
            if let Some(reference) = url.clone().or(id.clone()) {
                let stable_id =
                    id.unwrap_or_else(|| encode_digest_hex(&Sha256::digest(reference.as_bytes())));
                let modified_at = [
                    "obj_edit_time",
                    "modified_time",
                    "modifiedAt",
                    "update_time",
                    "updated_at",
                ]
                .iter()
                .find_map(|key| map.get(*key))
                .and_then(value_timestamp);
                refs.push((stable_id, title, reference, object_type, modified_at));
            }
            for child in map.values() {
                collect_feishu_document_refs(child, refs);
            }
        }
        _ => {}
    }
}

fn markdown_title(markdown: &str) -> Option<String> {
    markdown.lines().find_map(|line| {
        let text = line.trim().trim_start_matches('#').trim();
        (!text.is_empty()
            && !text.starts_with('{')
            && !text.starts_with('[')
            && serde_json::from_str::<Value>(text).is_err())
        .then(|| text.to_string())
    })
}

fn is_serialized_json_payload(text: &str) -> bool {
    let trimmed = text.trim();
    (!trimmed.is_empty() && (trimmed.starts_with('{') || trimmed.starts_with('[')))
        && serde_json::from_str::<Value>(trimmed).is_ok()
}

fn is_feishu_web_host(host: &str) -> bool {
    host == "feishu.cn"
        || host.ends_with(".feishu.cn")
        || host == "larksuite.com"
        || host.ends_with(".larksuite.com")
}

fn valid_feishu_document_token(value: &str) -> bool {
    let value = value.trim();
    (6..=256).contains(&value.len())
        && value
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || matches!(character, '-' | '_'))
}

/// Upgrades the Wiki node tokens stored by older Hub builds to an openable Feishu web URL.
fn normalize_feishu_document_url(value: &str, fallback_token: &str) -> Option<String> {
    let value = value.trim();
    if let Ok(parsed) = Url::parse(value) {
        if parsed.scheme() == "https" && parsed.host_str().is_some_and(is_feishu_web_host) {
            return Some(parsed.to_string());
        }
    }
    let token = if valid_feishu_document_token(value) {
        value
    } else if valid_feishu_document_token(fallback_token) {
        fallback_token.trim()
    } else {
        return None;
    };
    Some(format!("https://feishu.cn/wiki/{token}"))
}

fn feishu_document_from_result(
    fallback_id: &str,
    fallback_title: &str,
    fallback_url: &str,
    result: &Value,
) -> FeishuDocument {
    let parsed = tool_result_json(result);
    let raw_text = tool_result_text(result);
    let markdown = find_nested_string(&parsed, &["markdown", "content", "text", "body"])
        .filter(|text| !text.trim().is_empty())
        .unwrap_or_else(|| {
            if is_serialized_json_payload(&raw_text) {
                String::new()
            } else {
                raw_text
            }
        });
    let title = find_nested_string(&parsed, &["title", "name", "document_name"])
        .or_else(|| markdown_title(&markdown))
        .filter(|text| !text.trim().is_empty())
        .unwrap_or_else(|| fallback_title.to_string());
    let url = find_nested_string(&parsed, &["url", "link", "web_url"])
        .filter(|text| text.starts_with("http://") || text.starts_with("https://"))
        .unwrap_or_else(|| fallback_url.to_string());
    let id = find_nested_string(
        &parsed,
        &[
            "docID",
            "doc_id",
            "document_id",
            "doc_token",
            "obj_token",
            "token",
            "id",
        ],
    )
    .unwrap_or_else(|| fallback_id.to_string());
    let modified_at = find_nested_string(
        &parsed,
        &["modified_time", "modifiedAt", "update_time", "updated_at"],
    )
    .and_then(|value| parse_remote_timestamp(Some(&value)));
    FeishuDocument {
        id,
        title,
        path: "飞书知识库".to_string(),
        markdown,
        url,
        modified_at,
        content_type: "feishu_document".to_string(),
    }
}

fn value_string(value: &Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        value
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|text| !text.is_empty())
            .map(str::to_string)
    })
}

fn value_i64(value: &Value, keys: &[&str]) -> Option<i64> {
    keys.iter().find_map(|key| {
        value.get(*key).and_then(|item| {
            item.as_i64()
                .or_else(|| item.as_str().and_then(|text| text.parse().ok()))
        })
    })
}

fn is_dida_project_icon_char(character: char) -> bool {
    matches!(
        character as u32,
        0x200D
            | 0x20E3
            | 0xFE0E
            | 0xFE0F
            | 0x2300..=0x23FF
            | 0x2600..=0x27BF
            | 0x2B00..=0x2BFF
            | 0x1F000..=0x1FAFF
    )
}

fn dida_project_display_name(name: &str) -> String {
    let trimmed = name.trim();
    if trimmed.eq_ignore_ascii_case("inbox") {
        return "收件箱".to_string();
    }
    let prefix_bytes = trimmed
        .char_indices()
        .take_while(|(_, character)| is_dida_project_icon_char(*character))
        .map(|(index, character)| index + character.len_utf8())
        .last()
        .unwrap_or(0);
    if prefix_bytes == 0 {
        return trimmed.to_string();
    }
    let display_name = trimmed[prefix_bytes..].trim_start();
    if display_name.is_empty() {
        trimmed.to_string()
    } else {
        display_name.to_string()
    }
}

fn is_dida_inbox_project_id(project_id: &str) -> bool {
    project_id.trim().to_ascii_lowercase().starts_with("inbox")
}

fn is_dida_default_column_name(name: &str) -> bool {
    matches!(
        name.trim().to_ascii_lowercase().as_str(),
        "未分组" | "无分组" | "no section" | "unsectioned"
    )
}

fn is_allowed_dida_web_host(host: Option<&str>) -> bool {
    host.map(|host| {
        let host = host.to_ascii_lowercase();
        host == "dida365.com"
            || host.ends_with(".dida365.com")
            || host == "ticktick.com"
            || host.ends_with(".ticktick.com")
    })
    .unwrap_or(false)
}

const DIDA_ATTACHMENT_LOGIN_WINDOW: &str = "dida-attachment-login";

#[cfg(desktop)]
fn dida_attachment_cookie_header(app: &AppHandle) -> Result<(String, usize), String> {
    let url = Url::parse("https://api.dida365.com/")
        .map_err(|error| format!("滴答附件 Cookie 地址无效：{error}"))?;
    let mut available = false;
    let mut read_error = None;
    for window in [
        app.get_webview_window("main"),
        app.get_webview_window(DIDA_ATTACHMENT_LOGIN_WINDOW),
    ]
    .into_iter()
    .flatten()
    {
        available = true;
        let cookies = match window.cookies_for_url(url.clone()) {
            Ok(cookies) => cookies,
            Err(error) => {
                read_error = Some(format!("无法读取滴答网页会话：{error}"));
                continue;
            }
        };
        if !cookies
            .iter()
            .any(|cookie| cookie.name().eq_ignore_ascii_case("t") && !cookie.value().is_empty())
        {
            continue;
        }
        let values = cookies
            .iter()
            .filter(|cookie| !cookie.name().trim().is_empty())
            .map(|cookie| format!("{}={}", cookie.name(), cookie.value()))
            .collect::<Vec<_>>();
        return Ok((values.join("; "), values.len()));
    }
    if !available {
        return Err("无法访问 Hub 的网页会话存储".into());
    }
    Err(read_error.unwrap_or_else(|| "尚未检测到已登录的滴答网页会话，请完成登录后再检查".into()))
}

#[cfg(mobile)]
fn dida_attachment_cookie_header(_app: &AppHandle) -> Result<(String, usize), String> {
    Err("当前移动端版本暂不支持滴答附件网页登录".to_string())
}

// Keep each Hub webview session separate. A login window may have a newer
// session than the main window; neither presence nor ordering proves validity.
fn dida_web_cookie_candidate(
    cookies: Vec<(String, String)>,
) -> Result<Option<(String, usize)>, String> {
    let tokens = cookies
        .iter()
        .filter(|(name, value)| name.eq_ignore_ascii_case("t") && !value.is_empty())
        .map(|(_, value)| value.as_str())
        .collect::<HashSet<_>>();
    if tokens.is_empty() {
        return Ok(None);
    }
    if tokens.len() != 1 {
        return Err("滴答网页会话包含不同登录凭据，请重新登录后检查".into());
    }
    let mut session_emitted = false;
    let values = cookies
        .into_iter()
        .filter(|(name, _)| !name.trim().is_empty())
        .filter_map(|(name, value)| {
            if name.eq_ignore_ascii_case("t") {
                if value.is_empty() || session_emitted {
                    return None;
                }
                session_emitted = true;
            }
            Some(format!("{name}={value}"))
        })
        .collect::<Vec<_>>();
    Ok(Some((values.join("; "), values.len())))
}

#[cfg(desktop)]
fn dida_attachment_cookie_candidates(app: &AppHandle) -> Result<Vec<(String, usize)>, String> {
    let url = Url::parse("https://api.dida365.com/").map_err(|_| "滴答网页登录地址无效")?;
    let mut candidates = Vec::new();
    let mut seen = HashSet::new();
    let mut available = false;
    let mut read_error = None;
    for window in [
        app.get_webview_window(DIDA_ATTACHMENT_LOGIN_WINDOW),
        app.get_webview_window("main"),
    ]
    .into_iter()
    .flatten()
    {
        available = true;
        let cookies = match window.cookies_for_url(url.clone()) {
            Ok(cookies) => cookies,
            Err(_) => {
                read_error = Some("无法读取滴答网页登录会话，请重新登录后检查".to_string());
                continue;
            }
        };
        let values = cookies
            .iter()
            .map(|cookie| (cookie.name().to_string(), cookie.value().to_string()))
            .collect();
        match dida_web_cookie_candidate(values) {
            Ok(Some(candidate)) if seen.insert(candidate.0.clone()) => candidates.push(candidate),
            Ok(_) => {}
            Err(error) => read_error = Some(error),
        }
    }
    if !candidates.is_empty() {
        return Ok(candidates);
    }
    if !available {
        return Err("无法访问 Hub 的网页会话存储".into());
    }
    Err(read_error.unwrap_or_else(|| "尚未检测到已登录的滴答网页会话，请完成登录后再检查".into()))
}

