#[tauri::command]
async fn tag_assignment(
    app: AppHandle,
    state: State<'_, AppState>,
    args: Value,
) -> Result<Value, String> {
    let root = active_data_root(&app)?;
    if args["action"]
        .as_str()
        .is_some_and(|action| action.starts_with("source_writeback_"))
    {
        return tag_source_writeback::ui(&app, &state, &args).await;
    }
    let mut result = tokio::task::spawn_blocking(move || hub_mcp::tag_assignment::ui(&root, &args))
        .await
        .map_err(|e| e.to_string())??;
    if result["internalTagsChanged"] == true {
        // Membership is already committed; a recoverable indexing failure must not look
        // like the approval failed and invite another write.
        if let Err(error) = flush_index_jobs(&app, &state).await {
            result["indexWarning"] = json!(error);
        }
        let _ = app.emit("hub-content-tags-changed", ());
    }
    Ok(result)
}

