fn storage_directory_stats(root: &Path) -> (u64, u64) {
    let mut files = 0_u64;
    let mut bytes = 0_u64;
    let mut pending = vec![root.to_path_buf()];
    while let Some(directory) = pending.pop() {
        let Ok(entries) = fs::read_dir(directory) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            let Ok(metadata) = entry.metadata() else {
                continue;
            };
            if metadata.is_dir() {
                pending.push(path);
            } else if metadata.is_file() {
                files = files.saturating_add(1);
                bytes = bytes.saturating_add(metadata.len());
            }
        }
    }
    (files, bytes)
}

fn validate_storage_target(
    source: &Path,
    target: &Path,
    allow_control_file: bool,
) -> Result<(), String> {
    craft_backup::reject_links(source)?;
    craft_backup::reject_links(target)?;
    fs::create_dir_all(target)
        .map_err(|error| format!("无法创建目标数据文件夹 {}：{error}", target.display()))?;
    let source = source
        .canonicalize()
        .map_err(|error| format!("无法确认当前数据目录：{error}"))?;
    let target = target
        .canonicalize()
        .map_err(|error| format!("无法确认目标数据目录：{error}"))?;
    if source == target {
        return Ok(());
    }
    if source.starts_with(&target) || target.starts_with(&source) {
        return Err("目标文件夹不能位于当前数据目录内部或包含当前数据目录".to_string());
    }
    let probe = target.join(format!(
        ".craft-search-write-test-{:016x}",
        rand::thread_rng().next_u64()
    ));
    fs::write(&probe, b"ok").map_err(|error| format!("目标文件夹不可写：{error}"))?;
    let _ = fs::remove_file(&probe);
    let mut unexpected = Vec::new();
    for entry in fs::read_dir(&target)
        .map_err(|error| format!("无法检查目标文件夹：{error}"))?
        .flatten()
    {
        if allow_control_file && entry.file_name() == STORAGE_CONFIG_FILE {
            continue;
        }
        if entry.file_name() == data_portability::SESSION_LOCK
            || entry.file_name() == data_portability::MAINTENANCE_LOCK
        {
            craft_backup::reject_links(&entry.path())?;
            continue;
        }
        unexpected.push(entry.file_name().to_string_lossy().to_string());
        if unexpected.len() >= 3 {
            break;
        }
    }
    if !unexpected.is_empty() {
        return Err(format!(
            "目标文件夹必须为空；当前包含：{}",
            unexpected.join("、")
        ));
    }
    Ok(())
}

fn copy_storage_tree(source: &Path, target: &Path) -> Result<(u64, u64), String> {
    craft_backup::reject_links(source)?;
    craft_backup::reject_links(target)?;
    fs::create_dir_all(target).map_err(|error| format!("无法创建迁移目标目录：{error}"))?;
    let mut pending = vec![(source.to_path_buf(), target.to_path_buf(), true)];
    let mut files = 0_u64;
    let mut bytes = 0_u64;
    while let Some((from, to, root_level)) = pending.pop() {
        fs::create_dir_all(&to)
            .map_err(|error| format!("无法创建迁移目录 {}：{error}", to.display()))?;
        let entries = fs::read_dir(&from)
            .map_err(|error| format!("无法读取数据目录 {}：{error}", from.display()))?;
        for entry in entries {
            let entry = entry.map_err(|error| format!("无法读取数据文件：{error}"))?;
            let name = entry.file_name();
            if root_level
                && (name == STORAGE_CONFIG_FILE
                    || name == PORTABLE_MARKER_FILE
                    || name == data_portability::SESSION_LOCK
                    || name == data_portability::MAINTENANCE_LOCK)
            {
                continue;
            }
            let source_path = entry.path();
            let target_path = to.join(&name);
            craft_backup::reject_links(&source_path)?;
            craft_backup::reject_links(&target_path)?;
            let metadata = entry
                .metadata()
                .map_err(|error| format!("无法读取 {} 的属性：{error}", source_path.display()))?;
            if metadata.is_dir() {
                pending.push((source_path, target_path, false));
            } else if metadata.is_file() {
                if target_path.exists() {
                    return Err(format!("迁移目标中已存在文件：{}", target_path.display()));
                }
                let copied = fs::copy(&source_path, &target_path)
                    .map_err(|error| format!("无法复制 {}：{error}", source_path.display()))?;
                if copied != metadata.len() {
                    return Err(format!("文件复制校验失败：{}", source_path.display()));
                }
                if craft_backup::hash_file(&source_path)? != craft_backup::hash_file(&target_path)?
                {
                    return Err(format!("文件内容校验失败：{}", source_path.display()));
                }
                files = files.saturating_add(1);
                bytes = bytes.saturating_add(copied);
            }
        }
    }
    Ok((files, bytes))
}

fn complete_pending_storage_migration(app: &AppHandle) -> Result<(), String> {
    if isolated_runtime::enabled() {
        return Ok(());
    }
    let mut config = read_storage_bootstrap(app);
    let original_config = config.clone();
    let Some(pending) = config.pending.clone() else {
        return Ok(());
    };
    let source = PathBuf::from(&pending.source_path);
    let target = PathBuf::from(&pending.target_path);
    let outcome = (|| {
        if !source.is_dir() {
            return Err(format!("原数据目录不存在：{}", source.display()));
        }
        let _session = data_portability::exclusive_session(&source)?;
        let _maintenance = data_portability::maintenance_lock(&source)?;
        let _target_session = data_portability::exclusive_session(&target)?;
        let _target_maintenance = data_portability::maintenance_lock(&target)?;
        let copied = copy_storage_tree(&source, &target)?;
        let target_stats = storage_directory_stats(&target);
        if target_stats.0 < copied.0 || target_stats.1 < copied.1 {
            return Err("迁移后的文件数量或大小校验未通过".to_string());
        }
        data_portability::verify_database(&target)?;
        // Source and target session leases remain exclusive. Consolidation owns
        // its maintenance lease and writes its temporary files on the new disk.
        drop(_target_maintenance);
        let prepared = data_portability::finish_storage_move(&source, &target)?;
        config.mode = pending.mode.clone();
        config.custom_path = pending.custom_path.clone();
        config.pending = None;
        config.last_error = if prepared["ready"] == false {
            Some("软件数据已迁移；部分原件或附件当前缺失，可在“整体搬家”中检查缺项。".into())
        } else {
            None
        };
        config.prefer_config = true;
        write_storage_bootstrap(app, &config)?;
        if pending.mode == STORAGE_MODE_PORTABLE {
            let marker = portable_marker_path()?;
            if let Err(error) = data_portability::atomic_write(&marker, b"{\"version\":1}\n") {
                config.last_error = Some(format!(
                    "数据已迁移；便携识别标记未保存，换机时请手动打开此目录：{error}"
                ));
                let _ = write_storage_bootstrap(app, &config);
            }
        }
        Ok::<(), String>(())
    })();
    if let Err(error) = outcome {
        config = original_config;
        config.pending = None;
        config.last_error = Some(error.clone());
        let _ = write_storage_bootstrap(app, &config);
        return Err(error);
    }
    Ok(())
}

fn metadata_u64(connection: &Connection, key: &str, default: u64) -> u64 {
    connection
        .query_row(
            "SELECT value FROM metadata WHERE key=?1",
            params![key],
            |row| row.get::<_, String>(0),
        )
        .ok()
        .and_then(|value| value.parse::<u64>().ok())
        .unwrap_or(default)
}

fn metadata_bool(connection: &Connection, key: &str, default: bool) -> bool {
    connection
        .query_row(
            "SELECT value FROM metadata WHERE key=?1",
            params![key],
            |row| row.get::<_, String>(0),
        )
        .ok()
        .and_then(|value| match value.as_str() {
            "1" | "true" => Some(true),
            "0" | "false" => Some(false),
            _ => None,
        })
        .unwrap_or(default)
}

fn metadata_f64(connection: &Connection, key: &str, default: f64) -> f64 {
    connection
        .query_row(
            "SELECT value FROM metadata WHERE key=?1",
            params![key],
            |row| row.get::<_, String>(0),
        )
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(default)
}

fn craft_open_mode(connection: &Connection, key: &str) -> String {
    let selected = connection
        .query_row(
            "SELECT value FROM metadata WHERE key=?1",
            params![key],
            |row| row.get::<_, String>(0),
        )
        .ok()
        .and_then(|value| normalize_craft_open_mode(&value).map(str::to_string));
    selected
        .or_else(|| {
            connection
                .query_row(
                    "SELECT value FROM metadata WHERE key='craft_open_mode'",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .ok()
                .and_then(|value| normalize_craft_open_mode(&value).map(str::to_string))
        })
        .unwrap_or_else(|| CRAFT_OPEN_MODE_BRIDGE.to_string())
}

fn metadata_string(connection: &Connection, key: &str) -> String {
    connection
        .query_row(
            "SELECT value FROM metadata WHERE key=?1",
            params![key],
            |row| row.get::<_, String>(0),
        )
        .unwrap_or_default()
}

fn normalize_excluded_paths(values: Vec<String>) -> Vec<String> {
    let mut normalized = values
        .into_iter()
        .map(|value| {
            value
                .trim()
                .trim_start_matches(['/', '\\'])
                .replace('\\', "/")
        })
        .filter(|value| !value.is_empty() && value.len() <= 512)
        .collect::<Vec<_>>();
    normalized.sort_by_key(|value| value.to_lowercase());
    normalized.dedup_by(|left, right| left.eq_ignore_ascii_case(right));
    normalized.truncate(200);
    normalized
}

fn excluded_paths_from_metadata(metadata_json: Option<&str>) -> Vec<String> {
    metadata_json
        .and_then(|raw| serde_json::from_str::<Value>(raw).ok())
        .and_then(|value| value.get("excludedPaths").cloned())
        .and_then(|value| serde_json::from_value::<Vec<String>>(value).ok())
        .map(normalize_excluded_paths)
        .unwrap_or_default()
}

fn icon_svg_from_metadata(metadata_json: Option<&str>) -> Option<String> {
    metadata_json
        .and_then(|raw| serde_json::from_str::<Value>(raw).ok())
        .and_then(|value| {
            value
                .get("iconSvg")
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .filter(|value| !value.trim().is_empty())
}

fn default_icon_url_from_metadata(metadata_json: Option<&str>) -> Option<String> {
    metadata_json
        .and_then(|raw| serde_json::from_str::<Value>(raw).ok())
        .and_then(|value| {
            value
                .get("accountAvatarUrl")
                .and_then(Value::as_str)
                .and_then(valid_https_url)
        })
}

fn update_feishu_identity_metadata(
    path: &PathBuf,
    library_id: &str,
    account_name: Option<&str>,
    account_avatar_url: Option<&str>,
) -> Result<(), String> {
    if account_name.is_none() && account_avatar_url.is_none() {
        return Ok(());
    }
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始更新飞书账号信息：{error}"))?;
    transaction
        .execute(
            "UPDATE libraries
             SET metadata_json=json_set(
                   COALESCE(metadata_json,'{}'),
                   '$.accountName',COALESCE(?1,json_extract(metadata_json,'$.accountName')),
                   '$.accountAvatarUrl',COALESCE(?2,json_extract(metadata_json,'$.accountAvatarUrl'))
                 ),
                 name=CASE
                   WHEN location='space:my_library'
                     AND COALESCE(json_extract(metadata_json,'$.displayNameCustomized'),0)<>1
                     AND NULLIF(TRIM(?1),'') IS NOT NULL
                   THEN TRIM(?1) ELSE name END
             WHERE id=?3 AND provider='feishu' AND enabled=1",
            params![account_name, account_avatar_url, library_id],
        )
        .map_err(|error| format!("无法更新飞书账号信息：{error}"))?;
    transaction
        .execute(
            "UPDATE spaces
             SET name=(SELECT name FROM libraries WHERE id=?1)
             WHERE id=?1 AND provider='feishu'",
            params![library_id],
        )
        .map_err(|error| format!("无法同步飞书账号名称：{error}"))?;
    transaction
        .commit()
        .map_err(|error| format!("无法保存飞书账号信息：{error}"))
}

fn valid_https_url(value: &str) -> Option<String> {
    let value = value.trim();
    let parsed = Url::parse(value).ok()?;
    (parsed.scheme() == "https" && parsed.host_str().is_some()).then(|| value.to_string())
}

fn validate_library_icon_svg(icon_svg: Option<String>) -> Result<Option<String>, String> {
    let Some(icon_svg) = icon_svg else {
        return Ok(None);
    };
    let icon_svg = icon_svg.trim().to_string();
    if icon_svg.is_empty() {
        return Ok(None);
    }
    let lower = icon_svg.to_ascii_lowercase();
    let raster_prefix = [
        "data:image/png;base64,",
        "data:image/jpeg;base64,",
        "data:image/webp;base64,",
        "data:image/gif;base64,",
    ]
    .into_iter()
    .find(|prefix| lower.starts_with(prefix));
    if let Some(prefix) = raster_prefix {
        let payload = &icon_svg[prefix.len()..];
        let bytes = STANDARD
            .decode(payload)
            .map_err(|_| "请选择有效的本地图片图标".to_string())?;
        if bytes.len() > 2 * 1024 * 1024 {
            return Err("图片图标不能超过 2 MB".to_string());
        }
        return Ok(Some(icon_svg));
    }
    if icon_svg.len() > 64 * 1024 {
        return Err("SVG 图标不能超过 64 KB".to_string());
    }
    if !lower.contains("<svg") || !lower.contains("</svg>") {
        return Err("请选择有效的 SVG 图标文件".to_string());
    }
    for forbidden in [
        "<script",
        "<foreignobject",
        "<iframe",
        "<object",
        "<embed",
        "<image",
        "<!doctype",
        "<!entity",
        "<?xml-stylesheet",
        "javascript:",
        "http://",
        "https://",
        " onload=",
        " onerror=",
    ] {
        if lower.contains(forbidden) {
            return Err("SVG 图标包含不受支持的脚本或外部资源".to_string());
        }
    }
    Ok(Some(icon_svg))
}

fn library_excluded_paths(
    connection: &Connection,
    library_id: &str,
) -> Result<Vec<String>, String> {
    let metadata_json = connection
        .query_row(
            "SELECT metadata_json FROM libraries
             WHERE id=?1 AND provider='obsidian' AND enabled=1",
            params![library_id],
            |row| row.get::<_, Option<String>>(0),
        )
        .map_err(|_| "找不到已启用的 Obsidian 资料库".to_string())?;
    Ok(excluded_paths_from_metadata(metadata_json.as_deref()))
}

