#[tauri::command]
async fn library_content_policy(app: AppHandle, args: Value) -> Result<Value, String> {
    let path = database_path(&app)?;
    tokio::task::spawn_blocking(move || {
        let id = args["libraryId"].as_str().filter(|value| !value.trim().is_empty());
        match args["action"].as_str().unwrap_or("get") {
            "get" => library_policy::get(&open_database(&path)?,id),
            "save" => {
                if let Some(id) = id { library_runtime::exists_gate(path.parent().ok_or("资料库路径不可用。")?,id)?; }
                let (mut connection,_writer) = open_write_database(&path)?;
                if let Some(id) = id { library_runtime::exists_gate(path.parent().ok_or("资料库路径不可用。")?,id)?; }
                let mut write=||library_policy::save(&mut connection,id,&args);
                if let Some(id)=id {library_runtime::commit_existing(path.parent().ok_or("资料库路径不可用。")?,id,write)} else {write()}
            }
            "supplement" => {
                let id = id.ok_or("请指定要补齐的资料库。")?;
                let root = path.parent().ok_or("资料库路径不可用。")?;
                let operation=library_runtime::begin(root,id,"准备补齐任务")?;
                let (mut connection,_writer) = open_write_database(&path)?;
                operation.checkpoint()?;
                let queued = operation.commit(||library_policy::supplement(&mut connection,id))?;
                Ok(json!({"libraryId":id,"queued":queued,"notice":format!("已安排 {queued} 个附件补齐任务；按当前资料库策略处理。") }))
            }
            _ => Err("未知的资料库内容策略操作。".into()),
        }
    }).await.map_err(|_|"资料库内容策略操作中断。".to_string())?
}

fn error_chain(error: &(dyn std::error::Error + 'static)) -> String {
    let mut messages = vec![error.to_string()];
    let mut source = error.source();
    while let Some(error) = source {
        let message = error.to_string();
        if !messages.contains(&message) {
            messages.push(message);
        }
        source = error.source();
    }
    messages.join(" → ")
}

