async fn controlled_library_sync(
    app: AppHandle,
    library_id: String,
    state: State<'_, AppState>,
    full: bool,
) -> Result<SyncSummary, String> {
    let path = database_path(&app)?;
    let root = path.parent().ok_or("资料库目录不可用")?;
    let operation = Arc::new(library_runtime::begin(root, &library_id, "同步资料库")?);
    controlled_library_sync_operation(app, library_id, state, full, operation).await
}

async fn controlled_library_sync_operation(
    app: AppHandle,
    library_id: String,
    state: State<'_, AppState>,
    full: bool,
    operation: Arc<library_runtime::Operation>,
) -> Result<SyncSummary, String> {
    let path = database_path(&app)?;
    let root = path.parent().ok_or("资料库目录不可用")?;
    operation.phase("queued", "等待当前资料库的同步完成")?;
    let admission = library_runtime::admission(root, &library_id)?;
    let waiting = admission.lock();
    tokio::pin!(waiting);
    let _guard = loop {
        operation.checkpoint()?;
        tokio::select! {
            guard = &mut waiting => break guard,
            _ = tokio::time::sleep(Duration::from_millis(250)) => {},
        }
    };
    operation.checkpoint()?;
    operation.phase("listing", "正在读取资料库目录")?;
    let result = sync_library_inner(
        app.clone(),
        library_id.clone(),
        state,
        full,
        operation.clone(),
    )
    .await;
    operation.checkpoint()?;
    let status_result =
        record_library_sync_outcome_controlled(&path, &library_id, &result, Some(&operation));
    let result = match (result, status_result) {
        (Ok(summary), Ok(())) => Ok(summary),
        (Ok(_), Err(error)) | (Err(error), _) => Err(error),
    };
    if let Err(error) = &result {
        operation.failed(error);
    }
    drop(operation);
    if let Ok(status) = library_runtime::status(root, &library_id) {
        let _ = app.emit("library-runtime-updated", status);
    }
    result
}

#[tauri::command]
async fn start_library_sync(
    app: AppHandle,
    library_id: String,
    full_reconcile: Option<bool>,
) -> Result<library_runtime::Snapshot, String> {
    let path = database_path(&app)?;
    let root = path.parent().ok_or("资料库目录不可用")?;
    let operation = Arc::new(library_runtime::begin(root, &library_id, "同步资料库")?);
    operation.phase("queued", "同步已受理")?;
    let snapshot = library_runtime::status(root, &library_id)?;
    let worker_app = app.clone();
    tauri::async_runtime::spawn(async move {
        let state = worker_app.state::<AppState>();
        let result = match operation.checkpoint() {
            Ok(()) => {
                controlled_library_sync_operation(
                    worker_app.clone(),
                    library_id.clone(),
                    state,
                    full_reconcile.unwrap_or(true),
                    operation.clone(),
                )
                .await
            }
            Err(error) => Err(error),
        };
        if let Err(error) = &result {
            operation.failed(error);
        }
        drop(operation);
        if let Ok(path) = database_path(&worker_app) {
            if let Some(root) = path.parent() {
                if let Ok(status) = library_runtime::status(root, &library_id) {
                    let _ = worker_app.emit("library-runtime-updated", status);
                }
            }
        }
    });
    Ok(snapshot)
}

async fn sync_all_spaces_mode(
    app: AppHandle,
    state: State<'_, AppState>,
    force_full_reconcile: bool,
) -> Result<SyncSummary, String> {
    let sync_state = state.clone();
    let connected_space_ids = state
        .sessions
        .lock()
        .map_err(|_| "MCP 会话状态不可用".to_string())?
        .keys()
        .cloned()
        .collect::<Vec<_>>();
    // This legacy command synchronizes Craft MCP spaces only. Other remote
    // providers share the session map but have their own sync implementations.
    let database = database_path(&app)?;
    let space_ids = tokio::task::spawn_blocking(move || {
        let connection = open_database(&database)?;
        let mut statement = connection
            .prepare("SELECT id FROM libraries WHERE provider=?1 AND enabled=1")
            .map_err(|error| format!("无法准备 Craft 空间同步查询：{error}"))?;
        let rows = statement
            .query_map([PROVIDER_CRAFT], |row| row.get::<_, String>(0))
            .map_err(|error| format!("无法读取 Craft 空间：{error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法收集 Craft 空间：{error}"))
    })
    .await
    .map_err(|error| format!("Craft 空间查询任务失败：{error}"))??
    .into_iter()
    .filter(|space_id| connected_space_ids.contains(space_id))
    .collect::<Vec<_>>();
    let mut total = SyncSummary {
        indexed: 0,
        skipped: 0,
        deleted: 0,
        failed: 0,
    };
    for space_id in space_ids {
        let full_reconcile = force_full_reconcile
            || database_path(&app)
                .and_then(|path| full_reconcile_due(&path, &space_id))
                .unwrap_or(true);
        let result = controlled_library_sync(
            app.clone(),
            space_id.clone(),
            sync_state.clone(),
            full_reconcile,
        )
        .await;
        match result {
            Ok(summary) => {
                total.indexed += summary.indexed;
                total.skipped += summary.skipped;
                total.deleted += summary.deleted;
                total.failed += summary.failed;
            }
            Err(error) if library_runtime::is_control_error(&error) => {
                total.skipped += 1;
            }
            Err(_) => {
                total.failed += 1;
            }
        }
    }
    Ok(total)
}

#[tauri::command]
async fn sync_all_spaces(
    app: AppHandle,
    state: State<'_, AppState>,
) -> Result<SyncSummary, String> {
    sync_all_spaces_mode(app, state, true).await
}

async fn sync_due_libraries(app: AppHandle, state: State<'_, AppState>) -> Result<(), String> {
    let path = database_path(&app)?;
    let ids = {
        let c = open_database(&path)?;
        let mut q = c
            .prepare("SELECT id FROM libraries WHERE enabled=1 ORDER BY added_at")
            .map_err(|e| e.to_string())?;
        let rows = q
            .query_map([], |r| r.get::<_, String>(0))
            .map_err(|e| e.to_string())?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|e| e.to_string())?
    };
    for id in ids {
        if library_sync_schedule::claim(&path, &id)? {
            let _ = controlled_library_sync(app.clone(), id, state.clone(), false).await;
        }
    }
    Ok(())
}

async fn sync_all_libraries_mode(
    app: AppHandle,
    state: State<'_, AppState>,
    force_full_reconcile: bool,
) -> Result<SyncSummary, String> {
    let sync_state = state.clone();
    let path = database_path(&app)?;
    let library_ids = tokio::task::spawn_blocking(move || {
        let connection = open_database(&path)?;
        let mut statement = connection
            .prepare("SELECT id FROM libraries WHERE enabled=1 ORDER BY added_at")
            .map_err(|error| format!("无法准备全部资料库同步：{error}"))?;
        let rows = statement
            .query_map([], |row| row.get::<_, String>(0))
            .map_err(|error| format!("无法读取待同步资料库：{error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("待同步资料库无法读取：{error}"))
    })
    .await
    .map_err(|error| format!("全部资料库查询任务失败：{error}"))??;
    let mut total = SyncSummary {
        indexed: 0,
        skipped: 0,
        deleted: 0,
        failed: 0,
    };
    for library_id in library_ids {
        match controlled_library_sync(
            app.clone(),
            library_id,
            sync_state.clone(),
            force_full_reconcile,
        )
        .await
        {
            Ok(summary) => {
                total.indexed += summary.indexed;
                total.skipped += summary.skipped;
                total.deleted += summary.deleted;
                total.failed += summary.failed;
            }
            Err(error) if library_runtime::is_control_error(&error) => total.skipped += 1,
            Err(_) => total.failed += 1,
        }
    }
    Ok(total)
}

#[tauri::command]
async fn sync_all_libraries(
    app: AppHandle,
    state: State<'_, AppState>,
) -> Result<SyncSummary, String> {
    sync_all_libraries_mode(app, state, true).await
}

fn indexed_source_type(content_type: &str) -> String {
    match content_type {
        "pdf_page" => "pdf_native",
        "pdf_ocr" => "pdf_ocr",
        "pdf_attachment" => "pdf_attachment",
        "image_ocr" => "image_ocr",
        "media_attachment" => "media_attachment",
        "file_attachment" => "file_attachment",
        "obsidian_markdown" => "obsidian_page",
        "dida_task" => "dida_task",
        "feishu_document" => "feishu_page",
        "feishu_bitable_record" => "feishu_bitable_record",
        "feishu_bitable_table" => "feishu_bitable_table",
        _ => "craft_page",
    }
    .to_string()
}

fn indexed_search_match(hit: &SearchSubHit) -> IndexedSearchMatch {
    let title = if !hit.heading.trim().is_empty() {
        hit.heading.clone()
    } else if !hit.source_title.trim().is_empty() {
        hit.source_title.clone()
    } else {
        "正文命中".to_string()
    };
    IndexedSearchMatch {
        id: hit.item_id.clone(),
        block_id: hit.block_id.clone(),
        content_type: hit.content_type.clone(),
        source_item_id: (!hit.source_item_id.is_empty()).then_some(hit.source_item_id.clone()),
        source_type: indexed_source_type(&hit.content_type),
        source_title: (!hit.source_title.trim().is_empty()).then_some(hit.source_title.clone()),
        page_number: hit.page_number,
        title,
        snippet: make_search_snippet(&hit.body, &hit.match_terms),
        match_terms: hit.match_terms.clone(),
        match_field: hit.match_field.clone(),
    }
}

#[tauri::command]
async fn list_tags(
    app: AppHandle,
    space_ids: Option<Vec<String>>,
    limit: Option<usize>,
) -> Result<Vec<TagSummary>, String> {
    let path = database_path(&app)?;
    let limit = limit.unwrap_or(300).clamp(1, 1000) as i64;
    tokio::task::spawn_blocking(move || {
        if space_ids.as_ref().is_some_and(Vec::is_empty) {
            return Ok(Vec::new());
        }
        let connection = open_database(&path)?;
        let selected = space_ids
            .map(|ids| serde_json::to_string(&ids))
            .transpose()
            .map_err(|error| format!("资料库标签筛选无效：{error}"))?
            .unwrap_or_default();
        let mut statement = connection
            .prepare(
                "WITH all_tags(space_id,entity_id,tag,normalized_tag) AS (
                   SELECT space_id, document_id || ':' || page_id, tag, normalized_tag
                   FROM craft_tags
                   UNION ALL
                   SELECT space_id, document_id, tag, normalized_tag FROM obsidian_tags
                   UNION ALL
                   SELECT library_id, task_id, tag, normalized_tag FROM dida_task_tags
                   UNION ALL
                   SELECT library_id, entity_id, tag, normalized_tag FROM hub_content_tag_memberships
                 )
                 SELECT MIN(tag), normalized_tag, COUNT(DISTINCT space_id || ':' || entity_id)
                 FROM all_tags
                 WHERE (?1='' OR space_id IN (SELECT value FROM json_each(?1)))
                 GROUP BY normalized_tag
                 ORDER BY COUNT(DISTINCT space_id || ':' || entity_id) DESC,
                          normalized_tag COLLATE NOCASE
                 LIMIT ?2",
            )
            .map_err(|error| format!("无法准备标签列表：{error}"))?;
        let rows = statement
            .query_map(params![selected, limit], |row| {
                Ok(TagSummary {
                    name: row.get(0)?,
                    normalized_name: row.get(1)?,
                    count: row.get(2)?,
                })
            })
            .map_err(|error| format!("无法读取标签列表：{error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法收集标签列表：{error}"))
    })
    .await
    .map_err(|error| format!("标签读取任务失败：{error}"))?
}

#[tauri::command]
async fn list_related_tags(
    app: AppHandle,
    normalized_name: String,
    space_ids: Option<Vec<String>>,
    limit: Option<usize>,
) -> Result<Vec<TagSummary>, String> {
    let path = database_path(&app)?;
    let normalized_name = normalized_name.trim().to_lowercase();
    let limit = limit.unwrap_or(3).clamp(1, 20) as i64;
    if normalized_name.is_empty() || space_ids.as_ref().is_some_and(Vec::is_empty) {
        return Ok(Vec::new());
    }
    tokio::task::spawn_blocking(move || {
        let connection = open_database(&path)?;
        let selected = space_ids
            .map(|ids| serde_json::to_string(&ids))
            .transpose()
            .map_err(|error| format!("资料库相关标签筛选无效：{error}"))?
            .unwrap_or_default();
        let mut statement = connection
            .prepare(
                "WITH all_tags(space_id,entity_id,tag,normalized_tag) AS (
                   SELECT space_id, document_id || ':' || page_id, tag, normalized_tag
                   FROM craft_tags
                   UNION ALL
                   SELECT space_id, document_id, tag, normalized_tag FROM obsidian_tags
                   UNION ALL
                   SELECT library_id, task_id, tag, normalized_tag FROM dida_task_tags
                   UNION ALL
                   SELECT library_id, entity_id, tag, normalized_tag FROM hub_content_tag_memberships
                 ), selected_entities AS (
                   SELECT DISTINCT space_id, entity_id
                   FROM all_tags
                   WHERE normalized_tag=?1
                     AND (?2='' OR space_id IN (SELECT value FROM json_each(?2)))
                 )
                 SELECT MIN(related.tag), related.normalized_tag,
                        COUNT(DISTINCT related.space_id || ':' || related.entity_id) AS cooccurrence
                 FROM all_tags related
                 INNER JOIN selected_entities selected_entity
                    ON selected_entity.space_id=related.space_id
                   AND selected_entity.entity_id=related.entity_id
                 WHERE related.normalized_tag<>?1
                 GROUP BY related.normalized_tag
                 ORDER BY cooccurrence DESC, related.normalized_tag COLLATE NOCASE
                 LIMIT ?3",
            )
            .map_err(|error| format!("无法准备相关标签列表：{error}"))?;
        let rows = statement
            .query_map(params![normalized_name, selected, limit], |row| {
                Ok(TagSummary {
                    name: row.get(0)?,
                    normalized_name: row.get(1)?,
                    count: row.get(2)?,
                })
            })
            .map_err(|error| format!("无法读取相关标签列表：{error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法收集相关标签列表：{error}"))
    })
    .await
    .map_err(|error| format!("相关标签读取任务失败：{error}"))?
}

fn internal_tag_search_family(
    connection: &Connection,
    normalized_tag: &str,
) -> Result<Vec<String>, String> {
    let mut statement = connection
        .prepare(
            "WITH RECURSIVE
             equivalent_edges(source_tag_id,target_tag_id) AS (
               SELECT source_tag_id,target_tag_id FROM tag_taxonomy_relations
               WHERE relation_type IN ('alias','merge','retire') AND target_tag_id<>''
               UNION ALL
               SELECT target_tag_id,source_tag_id FROM tag_taxonomy_relations
               WHERE relation_type IN ('alias','merge','retire') AND target_tag_id<>''
             ), tag_family(tag_id) AS (
               SELECT ?1
               UNION
               SELECT edge.target_tag_id
               FROM equivalent_edges edge
               JOIN tag_family family ON family.tag_id=edge.source_tag_id
             )
             SELECT tag_id FROM tag_family ORDER BY tag_id COLLATE NOCASE",
        )
        .map_err(|error| format!("无法准备 Hub 内部标签检索族：{error}"))?;
    let rows = statement
        .query_map(params![normalized_tag], |row| row.get::<_, String>(0))
        .map_err(|error| format!("无法读取 Hub 内部标签检索族：{error}"))?;
    rows.collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("无法收集 Hub 内部标签检索族：{error}"))
}

#[tauri::command]
async fn local_search(
    app: AppHandle,
    state: State<'_, AppState>,
    query: String,
    limit: Option<usize>,
    space_id: Option<String>,
    space_ids: Option<Vec<String>>,
    folder_id: Option<String>,
    folder_ids: Option<Vec<String>>,
    document_ids: Option<Vec<String>>,
    page_ids: Option<Vec<String>>,
    updated_after: Option<i64>,
    include_craft_pages: Option<bool>,
    include_dida_tasks: Option<bool>,
    include_image_ocr: Option<bool>,
    include_pdf: Option<bool>,
    include_pdf_ocr: Option<bool>,
    include_attachments: Option<bool>,
    search_scope: Option<String>,
) -> Result<Vec<IndexedSearchResult>, String> {
    let query = query.trim().to_string();
    let index = search_index_for(&app, &state)?;
    let path = database_path(&app)?;
    let limit = limit.unwrap_or(50).clamp(1, 200);
    tokio::task::spawn_blocking(move || {
        let connection = open_database(&path)?;
        let visible=visible_library_ids(&path,&connection)?;
        let selected_space_ids = space_ids.or_else(|| space_id.map(|id| vec![id]))
            .map(|ids|ids.into_iter().filter(|id|visible.contains(id)).collect::<Vec<_>>()).unwrap_or(visible);
        if selected_space_ids.is_empty() {return Ok(Vec::new());}
        let page_items = page_ids.as_ref().map(|pages| library_browse::page_content_ids(&connection, &selected_space_ids, pages)).transpose()?;
        let include_pages = include_craft_pages.unwrap_or(true);
        let include_tasks = include_dida_tasks.unwrap_or(true);
        let field_scope = search_scope.as_deref().unwrap_or("all");
        let search_queries = if field_scope == "tag" && !query.is_empty() {
            internal_tag_search_family(&connection, &query.to_lowercase())?
        } else {
            vec![query.clone()]
        };
        let mut hits = Vec::new();
        for search_query in search_queries {
            let legacy_folder = folder_id.as_ref().filter(|id| !id.is_empty()).map(std::slice::from_ref);
            hits.extend(index.search_in_folders(
                &search_query,
                limit,
                Some(selected_space_ids.as_slice()),
                folder_ids.as_deref().or(legacy_folder),
                document_ids.as_deref(),
                page_items.as_deref(),
                updated_after,
                include_pages || include_tasks,
                include_image_ocr.unwrap_or(true),
                include_pdf.unwrap_or(true),
                include_pdf_ocr.unwrap_or(true),
                include_attachments.unwrap_or(true),
                field_scope,
            )?);
        }
        hits.sort_by(|left, right| {
            right
                .score
                .total_cmp(&left.score)
                .then_with(|| right.modified_at.cmp(&left.modified_at))
        });
        let mut seen_entities = HashSet::new();
        let hidden=hidden_library_ids(&path,&connection)?;
        hits.retain(|hit| !hidden.contains(&hit.space_id) && seen_entities.insert(hit.entity_key.clone()));
        hits.truncate(limit);
        let mut libraries = HashMap::new();
        let mut statement = connection
            .prepare("SELECT id, provider, name FROM libraries WHERE enabled=1")
            .map_err(|error| format!("无法读取资料库名称：{error}"))?;
        let rows = statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                ))
            })
            .map_err(|error| format!("资料库名称查询失败：{error}"))?;
        for row in rows {
            let (id, provider, name) =
                row.map_err(|error| format!("资料库名称无法读取：{error}"))?;
            libraries.insert(id, (provider, name));
        }
        Ok(hits
            .into_iter()
            .filter(|hit| {
                if hit.provider == PROVIDER_DIDA365 || hit.content_type == "dida_task" {
                    include_tasks
                } else {
                    include_pages
                }
            })
            .map(|hit| {
                let document_title = hit.title.clone();
                let sub_matches = hit
                    .sub_hits
                    .iter()
                    .map(indexed_search_match)
                    .collect::<Vec<_>>();
                let mut title = if !hit.heading.is_empty() && hit.heading != hit.title {
                    hit.heading.clone()
                } else {
                    hit.title.clone()
                };
                if hit.content_type == "image_ocr" {
                    if let Ok((page_title, source_title, image_number)) = connection.query_row(
                        "SELECT d.title, s.title,
                                (SELECT COUNT(*) + 1 FROM source_items earlier
                                 WHERE earlier.space_id=s.space_id
                                   AND earlier.document_id=s.document_id
                                   AND (COALESCE(earlier.mime_type, '') LIKE 'image/%'
                                        OR COALESCE(json_extract(earlier.metadata_json, '$.linkKind'), '')='image')
                                   AND (earlier.created_at < s.created_at
                                        OR (earlier.created_at=s.created_at AND earlier.id < s.id)))
                         FROM content_items ci
                         JOIN source_items s ON s.id=ci.source_item_id
                         JOIN documents d ON d.space_id=ci.space_id AND d.id=ci.document_id
                         WHERE ci.id=?1",
                        params![hit.item_id],
                        |row| {
                            Ok((
                                row.get::<_, String>(0)?,
                                row.get::<_, String>(1)?,
                                row.get::<_, i64>(2)?,
                            ))
                        },
                    ) {
                        let source_title = source_title.trim();
                        title = if source_title.is_empty()
                            || source_title == "图片"
                            || source_title == "Craft 图片"
                        {
                            format!("{page_title} · 图片 {image_number}")
                        } else {
                            format!("{page_title} · {source_title}")
                        };
                    }
                }
                let path = if hit.content_type == "craft_subpage" {
                    hit.path.clone()
                } else if title != hit.title {
                    format!("{} / {}", hit.path, hit.title)
                } else {
                    hit.path.clone()
                };
                let (library_provider, library_name) = libraries
                    .get(&hit.space_id)
                    .cloned()
                    .unwrap_or_else(|| (PROVIDER_CRAFT.to_string(), "Craft".to_string()));
                let provider = if hit.provider.trim().is_empty() {
                    library_provider
                } else {
                    hit.provider.clone()
                };
                let source_type = indexed_source_type(&hit.content_type);
                let task_status = dida_task_status_for_result(
                    &connection,
                    &provider,
                    &hit.space_id,
                    &hit.document_id,
                );
                IndexedSearchResult {
                    id: hit.item_id,
                    entity_key: hit.entity_key,
                    block_id: hit.block_id,
                    document_id: hit.document_id,
                    source_type,
                    content_type: hit.content_type,
                    source_item_id: (!hit.source_item_id.is_empty()).then_some(hit.source_item_id),
                    source_title: (!hit.source_title.trim().is_empty())
                        .then_some(hit.source_title),
                    page_number: hit.page_number,
                    score: Some(hit.score),
                    provider,
                    library_id: hit.space_id.clone(),
                    library_name: library_name.clone(),
                    space_name: library_name,
                    space_id: hit.space_id,
                    title,
                    document_title,
                    path,
                    folder_id: hit.folder_id,
                    modified_at: hit.modified_at,
                    task_status,
                    snippet: make_search_snippet(&hit.body, &hit.match_terms),
                    match_terms: hit.match_terms,
                    match_field: hit.match_field,
                    match_count: hit.match_count,
                    sub_matches,
                }
            })
            .collect())
    })
    .await
    .map_err(|error| format!("本地搜索任务失败：{error}"))?
}

#[tauri::command]
async fn dynamic_search_facets(
    app: AppHandle,
    state: State<'_, AppState>,
    query: String,
    updated_after: Option<i64>,
    search_scope: Option<String>,
) -> Result<DynamicFacetCounts, String> {
    const FACET_LIMIT: usize = 2_000;
    let index = search_index_for(&app, &state)?;
    let database = database_path(&app)?;
    tokio::task::spawn_blocking(move || {
        let connection = open_database(&database)?;
        let visible=visible_library_ids(&database,&connection)?;
        let mut hits = if visible.is_empty() {Vec::new()} else {index.search_with_space_ids_and_field_scope(
            query.trim(),
            FACET_LIMIT,
            Some(visible.as_slice()),
            None,
            updated_after,
            true,
            true,
            true,
            true,
            true,
            search_scope.as_deref().unwrap_or("all"),
        )?};
        let hidden=hidden_library_ids(&database,&connection)?;
        hits.retain(|hit|!hidden.contains(&hit.space_id));
        let truncated = hits.len() == FACET_LIMIT;
        let mut sources = HashMap::<String, usize>::new();
        let mut libraries = HashMap::<String, usize>::new();
        let mut folders = HashMap::<String, usize>::new();
        let mut matching_documents = HashSet::<(String, String)>::new();
        for hit in &hits {
            let source = match hit.content_type.as_str() {
                "dida_task" => "task",
                "pdf_page" | "pdf_ocr" | "pdf_attachment" => "pdf",
                "image_ocr" | "media_attachment" => "media",
                "file_attachment" => "attachment",
                _ => "craft",
            };
            *sources.entry(source.to_string()).or_default() += 1;
            *libraries.entry(hit.space_id.clone()).or_default() += 1;
            if let Some(folder_id) = hit.folder_id.as_deref() {
                *folders
                    .entry(format!("{}\u{0}{}", hit.space_id, folder_id))
                    .or_default() += 1;
            }
            matching_documents.insert((hit.space_id.clone(), hit.document_id.clone()));
        }
        let mut tag_entities = HashMap::<String, HashSet<String>>::new();
        let mut statement = connection
            .prepare(
                "SELECT space_id, document_id, normalized_tag FROM craft_tags
                 UNION ALL SELECT space_id, document_id, normalized_tag FROM obsidian_tags
                 UNION ALL SELECT library_id, task_id, normalized_tag FROM dida_task_tags
                 UNION ALL SELECT library_id, document_id, normalized_tag FROM hub_content_tag_memberships",
            )
            .map_err(|error| format!("无法准备动态标签分面：{error}"))?;
        let rows = statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                ))
            })
            .map_err(|error| format!("无法读取动态标签分面：{error}"))?;
        for row in rows {
            let (space_id, document_id, normalized_tag) =
                row.map_err(|error| format!("无法收集动态标签分面：{error}"))?;
            if matching_documents.contains(&(space_id.clone(), document_id.clone())) {
                tag_entities
                    .entry(normalized_tag)
                    .or_default()
                    .insert(format!("{space_id}\u{0}{document_id}"));
            }
        }
        Ok(DynamicFacetCounts {
            total: hits.len(),
            truncated,
            sources,
            libraries,
            folders,
            tags: tag_entities
                .into_iter()
                .map(|(tag, entities)| (tag, entities.len()))
                .collect(),
        })
    })
    .await
    .map_err(|error| format!("动态分面统计任务失败：{error}"))?
}

fn make_search_snippet(body: &str, terms: &[String]) -> String {
    let body_lower = body.to_lowercase();
    let start = terms
        .iter()
        .filter(|term| !term.is_empty())
        .filter_map(|term| body_lower.find(&term.to_lowercase()))
        .min()
        .map(|byte_index| body[..byte_index].chars().count().saturating_sub(55))
        .unwrap_or(0);
    let snippet = body.chars().skip(start).take(190).collect::<String>();
    if start > 0 {
        format!("…{snippet}")
    } else {
        snippet
    }
}

