fn dida_combined_detail_text(content: &str, description: &str) -> String {
    let content = content.trim();
    let description = description.trim();
    match (
        content.is_empty(),
        description.is_empty(),
        content == description,
    ) {
        (true, true, _) => String::new(),
        (false, _, true) | (false, true, _) => content.to_string(),
        (true, false, _) => description.to_string(),
        (false, false, false) => format!("{content}\n{description}"),
    }
}

impl TaskSyncRecord {
    fn legacy_source_hash(&self) -> String {
        encode_digest_hex(&Sha256::digest(
            format!("{}\n{}", self.title.trim(), self.completed as u8).as_bytes(),
        ))
    }

    fn source_hash(&self) -> String {
        let detail = if self.provider == PROVIDER_DIDA365 {
            normalized_attachment_markdown(&dida_combined_detail_text(
                &self.content,
                &self.description,
            ))
        } else {
            normalized_attachment_markdown(&self.content)
        };
        encode_digest_hex(&Sha256::digest(
            format!(
                "{}\n{}\n{}\n{}\n{}",
                self.title.trim(),
                self.completed as u8,
                self.schedule_date,
                self.deadline_date,
                detail
            )
            .as_bytes(),
        ))
    }

    fn pre_content_source_hash(&self) -> String {
        encode_digest_hex(&Sha256::digest(
            format!(
                "{}\n{}\n{}\n{}",
                self.title.trim(),
                self.completed as u8,
                self.schedule_date,
                self.deadline_date
            )
            .as_bytes(),
        ))
    }
}

fn task_sync_record_key(record: &TaskSyncRecord) -> (String, String, String) {
    (
        record.provider.clone(),
        record.library_id.clone(),
        record.source_id.clone(),
    )
}

fn build_task_sync_log_entries(
    after: &[TaskSyncRecord],
    bindings: &[TaskSyncBindingPair],
    written_craft: &HashSet<String>,
    written_dida: &HashSet<String>,
    created_craft: &HashSet<String>,
    created_dida: &HashSet<String>,
    conflicts: usize,
    errors: &[String],
    full_reconcile: bool,
) -> Vec<TaskSyncLogDraft> {
    let after_map = after
        .iter()
        .filter(|record| record.provider == PROVIDER_CRAFT || record.provider == PROVIDER_DIDA365)
        .map(|record| (task_sync_record_key(record), record))
        .collect::<HashMap<_, _>>();
    let mut entries = Vec::new();
    entries.push(TaskSyncLogDraft {
        title: "同步检查".to_string(),
        action: "scan".to_string(),
        source_provider: "craft+dida365".to_string(),
        target_provider: String::new(),
        status: "success".to_string(),
        detail: if full_reconcile {
            "已读取两端远端清单，并完整核对全部目录、文档和任务".to_string()
        } else {
            "已读取两端远端清单，并处理新增或修改过的文档和任务".to_string()
        },
    });
    // Successful create/update rows come only from the IDs recorded at the
    // exact point where the remote write returned success. Cache differences
    // are observations, not proof that this run performed a write.
    for pair in bindings {
        for (provider, written, created, library_id, source_id) in [
            (
                PROVIDER_CRAFT,
                written_craft,
                created_craft,
                &pair.craft_library_id,
                &pair.craft_source_id,
            ),
            (
                PROVIDER_DIDA365,
                written_dida,
                created_dida,
                &pair.dida_library_id,
                &pair.dida_source_id,
            ),
        ] {
            if !written.contains(&pair.hub_task_id) && !created.contains(&pair.hub_task_id) {
                continue;
            }
            let Some(record) =
                after_map.get(&(provider.to_string(), library_id.clone(), source_id.clone()))
            else {
                continue;
            };
            let action = if created.contains(&pair.hub_task_id) {
                "create"
            } else {
                "update"
            };
            entries.push(TaskSyncLogDraft {
                title: record.title.clone(),
                action: action.to_string(),
                source_provider: if provider == PROVIDER_CRAFT {
                    PROVIDER_DIDA365.to_string()
                } else {
                    PROVIDER_CRAFT.to_string()
                },
                target_provider: provider.to_string(),
                status: "success".to_string(),
                detail: if action == "create" {
                    format!(
                        "本轮远端接口已成功在{}创建任务并写入标题、状态、日期、详情和附件",
                        if provider == PROVIDER_CRAFT {
                            "Craft"
                        } else {
                            "滴答清单"
                        }
                    )
                } else {
                    format!(
                        "本轮远端接口已成功更新{}中的任务内容或属性",
                        if provider == PROVIDER_CRAFT {
                            "Craft"
                        } else {
                            "滴答清单"
                        }
                    )
                },
            });
        }
    }
    // Deletions are logged only by the code path that received a successful
    // remote delete response. A before/after inventory difference alone is not
    // proof that Hub deleted the counterpart.
    if conflicts > 0 {
        entries.push(TaskSyncLogDraft {
            title: format!("{conflicts} 项任务冲突"),
            action: "conflict".to_string(),
            source_provider: "craft+dida365".to_string(),
            target_provider: String::new(),
            status: "review".to_string(),
            detail: "两端在上次同步后均有修改，已保留两端内容并等待用户选择".to_string(),
        });
    }
    for error in errors {
        entries.push(TaskSyncLogDraft {
            title: "同步失败".to_string(),
            action: "error".to_string(),
            source_provider: String::new(),
            target_provider: String::new(),
            status: "failed".to_string(),
            detail: error.clone(),
        });
    }
    entries
}

struct PendingTaskSyncRun {
    path: PathBuf,
    run_id: i64,
    finished: bool,
}

impl PendingTaskSyncRun {
    fn begin(path: &PathBuf, started_at: i64, full_reconcile: bool) -> Result<Self, String> {
        let (mut connection, _writer) = open_write_database(path)?;
        let transaction = connection
            .transaction()
            .map_err(|error| format!("无法开始同步运行日志：{error}"))?;
        let now = now_timestamp();
        transaction
            .execute(
                "INSERT INTO task_sync_run_entries
                   (run_id,occurred_at,title,action,source_provider,target_provider,status,detail)
                 SELECT id,?1,'同步中断','error','','','failed',
                        '应用在上一次同步完成前退出；请重新同步核对两端状态'
                 FROM task_sync_runs WHERE status='running'",
                [now],
            )
            .map_err(|error| format!("无法补记中断同步动作：{error}"))?;
        transaction
            .execute(
                "UPDATE task_sync_runs SET completed_at=?1,status='interrupted',
                   summary='同步在完成前中断；重新同步会继续核对两端状态'
                 WHERE status='running'",
                [now],
            )
            .map_err(|error| format!("无法关闭旧同步运行日志：{error}"))?;
        transaction
            .execute(
                "INSERT INTO task_sync_runs
                   (started_at,completed_at,full_reconcile,status,summary)
                 VALUES (?1,?1,?2,'running','正在读取两端清单并执行同步')",
                params![started_at, full_reconcile as i64],
            )
            .map_err(|error| format!("无法创建同步运行日志：{error}"))?;
        let run_id = transaction.last_insert_rowid();
        transaction
            .commit()
            .map_err(|error| format!("无法提交同步运行日志：{error}"))?;
        Ok(Self {
            path: path.clone(),
            run_id,
            finished: false,
        })
    }

    fn finish(&mut self) {
        self.finished = true;
    }
}

impl Drop for PendingTaskSyncRun {
    fn drop(&mut self) {
        if self.finished {
            return;
        }
        let Ok((mut connection, _writer)) = open_write_database(&self.path) else {
            return;
        };
        let Ok(transaction) = connection.transaction() else {
            return;
        };
        let now = now_timestamp();
        let _ = transaction.execute(
            "INSERT INTO task_sync_run_entries
               (run_id,occurred_at,title,action,source_provider,target_provider,status,detail)
             SELECT id,?2,'同步中断','error','','','failed',
                    '同步流程在完成前退出；可能已有部分远端操作，下次同步将重新核对'
             FROM task_sync_runs WHERE id=?1 AND status='running'",
            params![self.run_id, now],
        );
        let _ = transaction.execute(
            "UPDATE task_sync_runs SET completed_at=?2,status='interrupted',
               summary='同步在完成前中断；可能已有部分远端操作，请重新同步核对'
             WHERE id=?1 AND status='running'",
            params![self.run_id, now],
        );
        let _ = transaction.commit();
    }
}

fn finalize_latest_task_sync_error(
    path: &PathBuf,
    started_at: i64,
    error: &str,
) -> Result<(), String> {
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|db_error| format!("无法开始保存同步失败原因：{db_error}"))?;
    let run_id = transaction
        .query_row(
            "SELECT id FROM task_sync_runs
             WHERE status='interrupted' AND started_at>=?1
             ORDER BY id DESC LIMIT 1",
            [started_at],
            |row| row.get::<_, i64>(0),
        )
        .optional()
        .map_err(|db_error| format!("无法查找失败的同步运行：{db_error}"))?;
    let Some(run_id) = run_id else {
        return Ok(());
    };
    let now = now_timestamp();
    transaction
        .execute(
            "UPDATE task_sync_runs SET completed_at=?2,status='failed',summary=?3
             WHERE id=?1 AND status='interrupted'",
            params![run_id, now, format!("同步失败：{error}")],
        )
        .map_err(|db_error| format!("无法保存同步失败摘要：{db_error}"))?;
    transaction
        .execute(
            "UPDATE task_sync_run_entries
             SET occurred_at=?2,title='同步失败',status='failed',detail=?3
             WHERE id=(
               SELECT id FROM task_sync_run_entries
               WHERE run_id=?1 AND title='同步中断' ORDER BY id DESC LIMIT 1
             )",
            params![run_id, now, error],
        )
        .map_err(|db_error| format!("无法保存同步失败明细：{db_error}"))?;
    transaction
        .commit()
        .map_err(|db_error| format!("无法提交同步失败原因：{db_error}"))
}

fn save_task_sync_log(
    path: &PathBuf,
    run_id: i64,
    summary: &TaskSyncRunSummary,
    entries: &[TaskSyncLogDraft],
) -> Result<(), String> {
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法保存同步日志：{error}"))?;
    let completed_at = now_timestamp();
    let status = if summary.failed > 0 || entries.iter().any(|entry| entry.status == "failed") {
        "completed_with_errors"
    } else {
        "completed"
    };
    transaction
        .execute(
            "UPDATE task_sync_runs SET completed_at=?2,status=?3,summary=?4 WHERE id=?1",
            params![run_id, completed_at, status, summary.message],
        )
        .map_err(|error| format!("无法写入同步运行日志：{error}"))?;
    transaction
        .execute(
            "DELETE FROM task_sync_run_entries WHERE run_id=?1",
            [run_id],
        )
        .map_err(|error| format!("无法替换同步动作日志：{error}"))?;
    for entry in entries {
        transaction.execute(
            "INSERT INTO task_sync_run_entries (run_id,occurred_at,title,action,source_provider,target_provider,status,detail) VALUES (?1,?2,?3,?4,?5,?6,?7,?8)",
            params![run_id, completed_at, entry.title, entry.action, entry.source_provider, entry.target_provider, entry.status, entry.detail],
        ).map_err(|error| format!("无法写入同步动作日志：{error}"))?;
    }
    transaction.execute(
        "DELETE FROM task_sync_runs WHERE id NOT IN (SELECT id FROM task_sync_runs ORDER BY completed_at DESC,id DESC LIMIT 50)",
        [],
    ).map_err(|error| format!("无法清理旧同步日志：{error}"))?;
    transaction
        .commit()
        .map_err(|error| format!("无法提交同步日志：{error}"))
}

#[tauri::command]
fn list_task_sync_logs(
    app: AppHandle,
    limit: Option<usize>,
) -> Result<Vec<TaskSyncLogRun>, String> {
    let path = database_path(&app)?;
    let connection = open_database(&path)?;
    let limit = limit.unwrap_or(20).clamp(1, 50) as i64;
    let mut runs_statement = connection.prepare(
        "SELECT id,started_at,completed_at,full_reconcile,status,summary FROM task_sync_runs ORDER BY completed_at DESC,id DESC LIMIT ?1",
    ).map_err(|error| format!("无法读取同步日志：{error}"))?;
    let runs = runs_statement
        .query_map([limit], |row| {
            Ok((
                row.get::<_, i64>(0)?,
                row.get::<_, i64>(1)?,
                row.get::<_, i64>(2)?,
                row.get::<_, i64>(3)? != 0,
                row.get::<_, String>(4)?,
                row.get::<_, String>(5)?,
            ))
        })
        .map_err(|error| format!("同步日志查询失败：{error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("无法读取同步日志记录：{error}"))?;
    let mut result = Vec::new();
    for (id, started_at, completed_at, full_reconcile, status, summary) in runs {
        let mut entry_statement = connection.prepare(
            "SELECT id,occurred_at,title,action,source_provider,target_provider,status,detail FROM task_sync_run_entries WHERE run_id=?1 ORDER BY id",
        ).map_err(|error| format!("无法准备同步动作日志：{error}"))?;
        let entries = entry_statement
            .query_map([id], |row| {
                Ok(TaskSyncLogEntry {
                    id: row.get(0)?,
                    occurred_at: row.get(1)?,
                    title: row.get(2)?,
                    action: row.get(3)?,
                    source_provider: row.get(4)?,
                    target_provider: row.get(5)?,
                    status: row.get(6)?,
                    detail: row.get(7)?,
                })
            })
            .map_err(|error| format!("同步动作日志查询失败：{error}"))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法读取同步动作：{error}"))?;
        result.push(TaskSyncLogRun {
            id,
            started_at,
            completed_at,
            full_reconcile,
            status,
            summary,
            entries,
        });
    }
    Ok(result)
}

fn task_sync_attachment_identities(
    path: &PathBuf,
    task: &TaskSyncRecord,
) -> Result<Vec<String>, String> {
    let connection = open_database(path)?;
    if task.provider == PROVIDER_CRAFT {
        return discover_attachments(&task.content)
            .into_iter()
            .map(|attachment| {
                connection
                    .query_row(
                        "SELECT blob_hash FROM source_items
                         WHERE provider='craft' AND source_type='craft_attachment'
                           AND space_id=?1 AND document_id=?2
                           AND json_extract(metadata_json,'$.remoteUrl')=?3
                           AND blob_hash IS NOT NULL LIMIT 1",
                        params![task.library_id, task.document_id, attachment.url],
                        |row| row.get::<_, String>(0),
                    )
                    .optional()
                    .map(|stored| stored.unwrap_or_else(|| format!("pending:{}", attachment.url)))
                    .map_err(|error| format!("无法读取 Craft 任务附件身份：{error}"))
            })
            .collect();
    }
    if task.provider != PROVIDER_DIDA365 {
        return Ok(Vec::new());
    }
    let mut identities = Vec::new();
    let mut seen = HashSet::new();
    let current_refs = dida_attachment_refs(&task.content)
        .into_iter()
        .chain(dida_attachment_refs(&task.description));
    for attachment in current_refs {
        if !seen.insert(attachment.attachment_id.clone()) {
            continue;
        }
        let blob_hash = connection
            .query_row(
                "SELECT blob_hash FROM source_items
                 WHERE provider='dida365' AND source_type='dida_attachment'
                   AND space_id=?1 AND document_id=?2 AND remote_id=?3 LIMIT 1",
                params![task.library_id, task.source_id, attachment.attachment_id],
                |row| row.get::<_, Option<String>>(0),
            )
            .optional()
            .map_err(|error| format!("无法读取滴答任务附件身份：{error}"))?
            .flatten();
        identities
            .push(blob_hash.unwrap_or_else(|| format!("pending:{}", attachment.attachment_id)));
    }
    let mut statement = connection
        .prepare(
            "SELECT remote_id,blob_hash FROM source_items
             WHERE provider='dida365' AND source_type='dida_attachment'
               AND space_id=?1 AND document_id=?2 ORDER BY remote_id",
        )
        .map_err(|error| format!("无法准备滴答任务附件身份：{error}"))?;
    let rows = statement
        .query_map(params![task.library_id, task.source_id], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, Option<String>>(1)?))
        })
        .map_err(|error| format!("无法查询滴答任务附件身份：{error}"))?;
    for row in rows {
        let (attachment_id, blob_hash) =
            row.map_err(|error| format!("无法读取滴答任务附件身份：{error}"))?;
        if seen.insert(attachment_id.clone()) {
            identities.push(blob_hash.unwrap_or_else(|| format!("pending:{attachment_id}")));
        }
    }
    Ok(identities)
}

fn task_sync_source_hash(path: &PathBuf, task: &TaskSyncRecord) -> Result<String, String> {
    let attachment_identities = task_sync_attachment_identities(path, task)?;
    Ok(encode_digest_hex(&Sha256::digest(
        format!(
            "task-sync-v3-attachments-parent\n{}\n{}\n{}",
            task.source_hash(),
            task.parent_source_id,
            attachment_identities.join("\n")
        )
        .as_bytes(),
    )))
}

fn task_sync_semantically_equal(
    path: &PathBuf,
    craft: &TaskSyncRecord,
    dida: &TaskSyncRecord,
    parents_equivalent: bool,
) -> Result<bool, String> {
    if !parents_equivalent
        || craft.title.trim() != dida.title.trim()
        || craft.completed != dida.completed
        || craft.schedule_date != dida.schedule_date
        || craft.deadline_date != dida.deadline_date
    {
        return Ok(false);
    }
    let craft_detail = normalized_attachment_markdown(&craft.content);
    let dida_detail = normalized_attachment_markdown(&dida_combined_detail_text(
        &dida.content,
        &dida.description,
    ));
    if craft_detail != dida_detail {
        return Ok(false);
    }
    let mut craft_attachments = task_sync_attachment_identities(path, craft)?;
    let mut dida_attachments = task_sync_attachment_identities(path, dida)?;
    craft_attachments.sort_unstable();
    craft_attachments.dedup();
    dida_attachments.sort_unstable();
    dida_attachments.dedup();
    Ok(craft_attachments == dida_attachments)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MissingTaskSyncBaselineAction {
    SaveEquivalent,
    DeferNewCraftReadback,
    ReviewConflict,
}

fn missing_task_sync_baseline_action(
    semantically_equal: bool,
    craft_created_this_run: bool,
) -> MissingTaskSyncBaselineAction {
    if craft_created_this_run {
        // The in-memory Craft record was assembled before this run populated its
        // detail blocks, while the Dida record predates our managed source link
        // and tags. Neither representation is suitable as a baseline yet. The
        // final provider reread stores both normalized representations.
        MissingTaskSyncBaselineAction::DeferNewCraftReadback
    } else if semantically_equal {
        MissingTaskSyncBaselineAction::SaveEquivalent
    } else {
        MissingTaskSyncBaselineAction::ReviewConflict
    }
}

#[derive(Debug, Clone)]
struct TaskSyncBindingPair {
    hub_task_id: String,
    craft_library_id: String,
    craft_source_id: String,
    craft_document_id: String,
    dida_library_id: String,
    dida_source_id: String,
}

fn task_sync_inbox_project_id(connection: &Connection, library_id: &str) -> Result<String, String> {
    connection
        .query_row(
            "SELECT p.project_id FROM dida_projects p
             JOIN libraries l ON l.id=p.library_id
             WHERE p.library_id=?1 AND l.provider='dida365' AND l.enabled=1 AND p.closed=0
               AND (lower(p.project_id) GLOB 'inbox*' OR upper(p.kind)='INBOX')
             ORDER BY CASE WHEN lower(p.project_id)='inbox' THEN 0 ELSE 1 END,p.project_id
             LIMIT 1",
            [library_id],
            |row| row.get(0),
        )
        .optional()
        .map_err(|error| format!("无法读取滴答收件箱：{error}"))?
        .ok_or_else(|| "尚未读取到此滴答资料库的收件箱，请先刷新滴答资料库".to_string())
}

fn task_sync_new_dida_project_id(
    records: &[TaskSyncRecord],
    dida_library_id: &str,
    inbox_project_id: &str,
    parent_dida_id: Option<&str>,
) -> Result<String, String> {
    let Some(parent_id) = parent_dida_id else {
        return Ok(inbox_project_id.to_string());
    };
    records
        .iter()
        .find(|record| {
            record.provider == PROVIDER_DIDA365
                && record.library_id == dida_library_id
                && record.source_id == parent_id
                && !record.project_id.trim().is_empty()
        })
        .map(|parent| parent.project_id.clone())
        .ok_or_else(|| "无法确认已关联父任务当前所在的滴答清单，已暂缓创建子任务".to_string())
}

async fn task_sync_refresh_creation_parent(
    path: &PathBuf,
    client: &reqwest::Client,
    session: &McpSession,
    parent: &TaskSyncRecord,
    request_id: u64,
) -> Result<TaskSyncRecord, String> {
    let result = call_mcp_tool_raw(
        client,
        session,
        "get_task_by_id",
        json!({"task_id": parent.source_id}),
        request_id,
    )
    .await?;
    let mut tasks = Vec::new();
    collect_dida_tasks(&tool_result_json(&result), &parent.project_id, &mut tasks);
    let task = tasks
        .into_iter()
        .find(|task| task.id == parent.source_id && task.status != -1)
        .ok_or_else(|| "无法回读父任务的当前位置，已暂缓创建子任务".to_string())?;
    if value_string(&task.raw, &["projectId", "project_id"]).is_none() {
        return Err("父任务响应缺少所在清单，已暂缓创建子任务".to_string());
    }
    persist_direct_dida_task(path, &parent.library_id, &task)?;
    load_task_sync_records(path)?
        .into_iter()
        .find(|record| {
            record.provider == PROVIDER_DIDA365
                && record.library_id == parent.library_id
                && record.source_id == parent.source_id
        })
        .ok_or_else(|| "无法读取刚确认的滴答父任务，已暂缓创建子任务".to_string())
}

fn task_sync_existing_dida_parent_id(
    records: &[TaskSyncRecord],
    dida: &TaskSyncRecord,
    craft_parent_dida_id: Option<String>,
) -> Option<String> {
    let parent_in_another_list = craft_parent_dida_id.as_deref().is_some_and(|parent_id| {
        records.iter().any(|parent| {
            parent.provider == PROVIDER_DIDA365
                && parent.library_id == dida.library_id
                && parent.source_id == parent_id
                && !parent.project_id.is_empty()
                && parent.project_id != dida.project_id
                && !(is_dida_inbox_project_id(&parent.project_id)
                    && is_dida_inbox_project_id(&dida.project_id))
        })
    });
    if parent_in_another_list {
        // Moving an existing child to another list is a placement choice. Keep
        // its current Dida parent instead of attempting a cross-list reparent.
        (!dida.parent_source_id.is_empty()).then(|| dida.parent_source_id.clone())
    } else {
        craft_parent_dida_id
    }
}

const CRAFT_PROJECT_TAG: &str = "项目";
const CRAFT_PROJECT_SOURCE_PREFIX: &str = "craft-project-page:";

#[derive(Debug, Clone)]
struct CraftProjectPage {
    library_id: String,
    library_name: String,
    document_id: String,
    raw_document_id: String,
    document_title: String,
    page_id: String,
    title: String,
    path: String,
    modified_at: Option<i64>,
}

fn craft_project_source_id(document_id: &str) -> String {
    format!("{CRAFT_PROJECT_SOURCE_PREFIX}{document_id}")
}

fn is_craft_project_source_id(source_id: &str) -> bool {
    source_id.starts_with(CRAFT_PROJECT_SOURCE_PREFIX)
}

fn assign_craft_project_parent(
    records: &mut [TaskSyncRecord],
    child_indexes: &[usize],
    project_source_id: &str,
) {
    for index in child_indexes {
        if records[*index].parent_source_id.is_empty() {
            records[*index].parent_source_id = project_source_id.to_string();
        }
    }
}

fn craft_project_title(title: &str) -> Option<String> {
    if !craft_markdown_tags(title)
        .iter()
        .any(|tag| tag == CRAFT_PROJECT_TAG)
    {
        return None;
    }
    let characters = title.char_indices().collect::<Vec<_>>();
    let mut output = String::with_capacity(title.len());
    let mut cursor = 0;
    let marker = format!("#{CRAFT_PROJECT_TAG}");
    for (index, (byte_index, character)) in characters.iter().enumerate() {
        if *byte_index < cursor || *character != '#' || !title[*byte_index..].starts_with(&marker) {
            continue;
        }
        let previous = index.checked_sub(1).map(|value| characters[value].1);
        let after_byte = *byte_index + marker.len();
        let next = title[after_byte..].chars().next();
        let boundary_before = previous.is_none_or(|value| {
            value.is_whitespace()
                || matches!(
                    value,
                    '(' | '['
                        | '{'
                        | '（'
                        | '【'
                        | '「'
                        | '『'
                        | '，'
                        | '。'
                        | '；'
                        | '：'
                        | '！'
                        | '？'
                        | '、'
                )
        });
        let boundary_after = next.is_none_or(|value| {
            value.is_whitespace()
                || matches!(
                    value,
                    ')' | ']'
                        | '}'
                        | '）'
                        | '】'
                        | '」'
                        | '』'
                        | '，'
                        | '。'
                        | '；'
                        | '：'
                        | '！'
                        | '？'
                        | '、'
                )
        });
        if boundary_before && boundary_after {
            output.push_str(&title[cursor..*byte_index]);
            cursor = after_byte;
        }
    }
    output.push_str(&title[cursor..]);
    let cleaned = output
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .trim_matches(|character: char| {
            character.is_whitespace()
                || matches!(
                    character,
                    '，' | ',' | '；' | ';' | '：' | ':' | '、' | '-' | '—'
                )
        })
        .to_string();
    (!cleaned.is_empty()).then_some(cleaned)
}

fn load_craft_project_pages(connection: &Connection) -> Result<Vec<CraftProjectPage>, String> {
    load_craft_project_pages_scoped(connection, None)
}

fn load_craft_project_pages_scoped(
    connection: &Connection,
    allowed_libraries: Option<&[String]>,
) -> Result<Vec<CraftProjectPage>, String> {
    load_craft_project_pages_selected(connection, allowed_libraries, None)
}
fn load_craft_project_pages_selected(
    connection: &Connection,
    allowed_libraries: Option<&[String]>,
    documents: Option<&[(String, String)]>,
) -> Result<Vec<CraftProjectPage>, String> {
    let scope_json = allowed_libraries
        .map(serde_json::to_string)
        .transpose()
        .map_err(|e| e.to_string())?;
    let documents_json = documents
        .map(serde_json::to_string)
        .transpose()
        .map_err(|e| e.to_string())?;
    let mut candidates = Vec::new();
    {
        let mut statement = connection
            .prepare(
                "SELECT d.space_id,l.name,d.id,COALESCE(d.raw_document_id,''),d.title,d.id,
                        d.title,d.path,COALESCE(d.modified_at,d.indexed_at)
                 FROM documents d JOIN libraries l ON l.id=d.space_id
                 WHERE l.enabled=1 AND d.provider='craft' AND (?1 IS NULL OR l.id IN (SELECT value FROM json_each(?1)))
                   AND (?2 IS NULL OR EXISTS(SELECT 1 FROM json_each(?2) s WHERE json_extract(s.value,'$[0]')=d.space_id AND json_extract(s.value,'$[1]')=d.id))",
            )
            .map_err(|error| format!("无法准备 Craft 根项目页面查询：{error}"))?;
        let rows = statement
            .query_map(
                params![scope_json.as_deref(), documents_json.as_deref()],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, String>(2)?,
                        row.get::<_, String>(3)?,
                        row.get::<_, String>(4)?,
                        row.get::<_, String>(5)?,
                        row.get::<_, String>(6)?,
                        row.get::<_, String>(7)?,
                        row.get::<_, Option<i64>>(8)?,
                    ))
                },
            )
            .map_err(|error| format!("Craft 根项目页面查询失败：{error}"))?;
        candidates.extend(
            rows.collect::<Result<Vec<_>, _>>()
                .map_err(|error| format!("无法读取 Craft 根项目页面：{error}"))?,
        );
    }
    {
        let mut statement = connection
            .prepare(
                "SELECT d.space_id,l.name,d.id,COALESCE(d.raw_document_id,''),d.title,
                        ci.page_id,ci.page_title,d.path,COALESCE(d.modified_at,d.indexed_at)
                 FROM content_items ci
                 JOIN documents d ON d.space_id=ci.space_id AND d.id=ci.document_id
                 JOIN libraries l ON l.id=d.space_id
                 WHERE l.enabled=1 AND d.provider='craft' AND (?1 IS NULL OR l.id IN (SELECT value FROM json_each(?1)))
                   AND (?2 IS NULL OR EXISTS(SELECT 1 FROM json_each(?2) s WHERE json_extract(s.value,'$[0]')=d.space_id AND json_extract(s.value,'$[1]')=d.id))
                   AND length(trim(COALESCE(ci.page_id,'')))>0
                   AND length(trim(COALESCE(ci.page_title,'')))>0
                 GROUP BY d.space_id,d.id,ci.page_id,ci.page_title",
            )
            .map_err(|error| format!("无法准备 Craft 结构化项目页面查询：{error}"))?;
        let rows = statement
            .query_map(
                params![scope_json.as_deref(), documents_json.as_deref()],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, String>(2)?,
                        row.get::<_, String>(3)?,
                        row.get::<_, String>(4)?,
                        row.get::<_, String>(5)?,
                        row.get::<_, String>(6)?,
                        row.get::<_, String>(7)?,
                        row.get::<_, Option<i64>>(8)?,
                    ))
                },
            )
            .map_err(|error| format!("Craft 结构化项目页面查询失败：{error}"))?;
        candidates.extend(
            rows.collect::<Result<Vec<_>, _>>()
                .map_err(|error| format!("无法读取 Craft 结构化项目页面：{error}"))?,
        );
    }
    let mut projects = HashMap::new();
    for (
        library_id,
        library_name,
        document_id,
        raw_document_id,
        document_title,
        page_id,
        page_title,
        path,
        modified_at,
    ) in candidates
    {
        let Some(title) = craft_project_title(&page_title) else {
            continue;
        };
        projects.insert(
            (library_id.clone(), page_id.clone()),
            CraftProjectPage {
                library_id,
                library_name,
                document_id,
                raw_document_id,
                document_title,
                page_id,
                title,
                path,
                modified_at,
            },
        );
    }
    let mut projects = projects.into_values().collect::<Vec<_>>();
    projects.sort_by(|left, right| {
        left.library_id
            .cmp(&right.library_id)
            .then_with(|| left.document_id.cmp(&right.document_id))
            .then_with(|| left.page_id.cmp(&right.page_id))
    });
    Ok(projects)
}

fn load_craft_page_task_ids(
    connection: &Connection,
) -> Result<HashSet<(String, String, String)>, String> {
    let mut statement = connection
        .prepare(
            "SELECT DISTINCT b.space_id,b.document_id,b.block_id
             FROM craft_task_blocks b
             JOIN content_items ci
               ON ci.space_id=b.space_id
              AND ci.document_id=b.document_id
              AND (ci.block_id=b.block_id OR ci.page_id=b.block_id)
             WHERE ci.provider='craft' AND ci.content_type='craft_subpage'",
        )
        .map_err(|error| format!("无法准备 Craft 页面任务查询：{error}"))?;
    let rows = statement
        .query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
            ))
        })
        .map_err(|error| format!("Craft 页面任务查询失败：{error}"))?;
    rows.collect::<Result<HashSet<_>, _>>()
        .map_err(|error| format!("无法整理 Craft 页面任务：{error}"))
}

fn unified_task_id(provider: &str, library_id: &str, source_id: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(provider.as_bytes());
    hasher.update([0]);
    hasher.update(library_id.as_bytes());
    hasher.update([0]);
    hasher.update(source_id.as_bytes());
    let digest = hasher.finalize();
    format!("task-{:x}", digest)
}

fn task_title_from_markdown_line(line: &str) -> Option<(bool, String, usize)> {
    let indentation = line
        .chars()
        .take_while(|character| character.is_whitespace())
        .map(|character| if character == '\t' { 2 } else { 1 })
        .sum::<usize>();
    let trimmed = line.trim_start();
    let after_marker = ['-', '*', '+']
        .iter()
        .find_map(|marker| trimmed.strip_prefix(*marker))?
        .trim_start();
    let (completed, title) = if let Some(title) = after_marker.strip_prefix("[ ]") {
        (false, title)
    } else if let Some(title) = after_marker
        .strip_prefix("[x]")
        .or_else(|| after_marker.strip_prefix("[X]"))
    {
        (true, title)
    } else {
        return None;
    };
    let title = title.trim();
    if title.is_empty() {
        return None;
    }
    Some((completed, clean_task_display_title(title), indentation / 2))
}

fn clean_task_display_title(value: &str) -> String {
    // Craft sometimes returns the whole block markdown for a native task. Keep
    // Hub's presentation concise without changing the source block in Craft.
    let first_line = value
        .split(|character| character == '\r' || character == '\n')
        .flat_map(|line| line.split("\\n"))
        .map(str::trim)
        .find(|line| !line.is_empty())
        .unwrap_or_default();
    let cleaned = first_line
        .replace("**", "")
        .replace("__", "")
        .replace("~~", "")
        .replace('`', "");
    let mut task_text = cleaned.trim();
    // Craft can return a native task inside a quote as its full Markdown line,
    // e.g. `> - [ ] Task`. These structural markers are not part of the title
    // and must never be copied into TickTick.
    loop {
        let before = task_text;
        if let Some(rest) = task_text.strip_prefix('>') {
            task_text = rest.trim_start();
        }
        for marker in [
            "- [ ]", "- [x]", "- [X]", "* [ ]", "* [x]", "* [X]", "+ [ ]", "+ [x]", "+ [X]",
        ] {
            if let Some(rest) = task_text.strip_prefix(marker) {
                task_text = rest.trim_start();
                break;
            }
        }
        if task_text == before {
            break;
        }
    }
    task_text
        .trim()
        .trim_matches(|character| matches!(character, '~' | '*' | '_'))
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn craft_task_own_detail(markdown: &str) -> String {
    let mut lines = markdown.lines();
    let _ = lines.find(|line| !line.trim().is_empty());
    lines.collect::<Vec<_>>().join("\n").trim().to_string()
}

#[derive(Default)]
struct ManagedCraftExclusions {
    always_excluded_ids: HashSet<String>,
}

fn craft_task_details_excluding(
    hints: &[StructuredBlockHint],
    exclusions: &ManagedCraftExclusions,
) -> HashMap<String, String> {
    let mut details: HashMap<String, Vec<String>> = HashMap::new();
    for hint in hints {
        // The task's Craft content page is the source of truth. Blocks written
        // by a previous Dida sync remain visible user content and must be read
        // back together with later Craft edits. Excluding those managed blocks
        // produced a destructive partial mirror (for example, images without
        // the surrounding text). Only retired blocks pending deletion are
        // omitted.
        if exclusions.always_excluded_ids.contains(&hint.id) {
            continue;
        }
        if hint.task_completed.is_some() {
            let own_detail = craft_task_own_detail(&hint.markdown);
            if !own_detail.is_empty() {
                details.entry(hint.id.clone()).or_default().push(own_detail);
            }
            continue;
        }
        let Some(parent_task_id) = hint.parent_task_id.as_deref() else {
            continue;
        };
        let markdown = hint.markdown.trim();
        if !markdown.is_empty() {
            let task_details = details.entry(parent_task_id.to_string()).or_default();
            if !task_details.iter().any(|detail| detail == markdown) {
                task_details.push(markdown.to_string());
            }
        }
    }
    details
        .into_iter()
        .map(|(task_id, parts)| (task_id, parts.join("\n\n")))
        .collect()
}

#[cfg(test)]
fn craft_task_details(hints: &[StructuredBlockHint]) -> HashMap<String, String> {
    craft_task_details_excluding(hints, &ManagedCraftExclusions::default())
}

fn load_confirmed_craft_trash_documents(
    connection: &Connection,
) -> Result<HashSet<(String, String)>, String> {
    let mut statement = connection
        .prepare("SELECT library_id,document_id FROM task_sync_craft_trash_documents")
        .map_err(|error| format!("无法准备 Craft 废纸篓记录：{error}"))?;
    let rows = statement
        .query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
        })
        .map_err(|error| format!("无法读取 Craft 废纸篓记录：{error}"))?;
    rows.collect::<Result<HashSet<_>, _>>()
        .map_err(|error| format!("无法整理 Craft 废纸篓记录：{error}"))
}

fn exclude_confirmed_craft_trash_tasks(
    tasks: &mut Vec<UnifiedTaskItem>,
    trash_documents: &HashSet<(String, String)>,
) {
    tasks.retain(|task| {
        task.provider != PROVIDER_CRAFT
            || !trash_documents.contains(&(task.library_id.clone(), task.document_id.clone()))
    });
}

fn markdown_tasks(
    provider: &str,
    library_id: &str,
    library_name: &str,
    document_id: &str,
    document_title: &str,
    path: &str,
    markdown: &str,
    modified_at: Option<i64>,
) -> Vec<UnifiedTaskItem> {
    let mut tasks = Vec::new();
    let mut fenced = false;
    // Markdown exported by Craft can place a whole checkbox list underneath a
    // normal bullet. That gives every task leading whitespace, but does not
    // make those tasks children of another task. Keep the raw indentation as
    // parsing evidence and derive the visible depth only from preceding,
    // genuinely shallower task rows in the same task-list run.
    let mut task_indent_stack: Vec<(usize, String)> = Vec::new();
    for (line_index, line) in markdown.lines().enumerate() {
        if line.trim_start().starts_with("```") {
            fenced = !fenced;
            task_indent_stack.clear();
            continue;
        }
        if fenced {
            continue;
        }
        let Some((completed, title, raw_depth)) = task_title_from_markdown_line(line) else {
            if !line.trim().is_empty() {
                task_indent_stack.clear();
            }
            continue;
        };
        while task_indent_stack
            .last()
            .is_some_and(|(indent, _)| *indent >= raw_depth)
        {
            task_indent_stack.pop();
        }
        let depth = task_indent_stack.len();
        // The source locator stays outside both provider documents. It is never
        // appended to the task title, notes, tags, or description.
        let source_id = format!("{document_id}:line:{}", line_index + 1);
        let parent_task_id = task_indent_stack
            .last()
            .map(|(_, source_id)| source_id.clone())
            .unwrap_or_default();
        task_indent_stack.push((raw_depth, source_id.clone()));
        let id = unified_task_id(provider, library_id, &source_id);
        let dates = (provider == PROVIDER_OBSIDIAN).then(|| {
            // Date metadata is parsed before generic title cleanup removes code
            // delimiters; literal examples must not become task schedule dates.
            let source_title = line.trim_start().get(1..).unwrap_or_default().trim_start();
            let source_title = source_title.get(3..).unwrap_or_default().trim();
            task_dates::obsidian_dates(source_title, completed)
        });
        let mut task = UnifiedTaskItem {
            id,
            collection_id: String::new(),
            provider: provider.to_string(),
            library_id: library_id.to_string(),
            library_name: library_name.to_string(),
            source_id,
            parent_task_id,
            parent_page_id: document_id.to_string(),
            document_id: document_id.to_string(),
            document_title: document_title.to_string(),
            title,
            completed,
            status: if completed { "completed" } else { "open" }.to_string(),
            is_all_day: true,
            start_at: None,
            due_at: None,
            modified_at,
            path: path.to_string(),
            depth,
            is_project: false,
            linked_providers: vec![provider.to_string()],
            sync_state: "unlinked".to_string(),
            ..UnifiedTaskItem::default()
        };
        if let Some(dates) = dates {
            task_dates::apply_source_dates(&mut task, dates);
        }
        tasks.push(task);
    }
    tasks
}

fn compare_unified_task_roots(
    left: &UnifiedTaskItem,
    right: &UnifiedTaskItem,
) -> std::cmp::Ordering {
    left.completed
        .cmp(&right.completed)
        .then_with(|| left.due_at.cmp(&right.due_at))
        .then_with(|| right.modified_at.cmp(&left.modified_at))
        .then_with(|| right.is_project.cmp(&left.is_project))
        .then_with(|| left.title.cmp(&right.title))
}

fn is_markdown_task(task: &UnifiedTaskItem) -> bool {
    (task.provider == PROVIDER_OBSIDIAN || task.provider == PROVIDER_CRAFT)
        && task.source_id.contains(":line:")
}

fn sort_unified_tasks_preserving_markdown_trees(tasks: &mut Vec<UnifiedTaskItem>) {
    // A Markdown task tree is meaningful only in source-line order. Sorting
    // each checkbox independently (for example, open before completed) tears
    // children away from their parents. Keep every contiguous document tree as
    // one sortable unit, while retaining the dashboard's ordering between
    // independent units.
    let mut units: Vec<Vec<UnifiedTaskItem>> = Vec::new();
    let mut document_units: HashMap<(String, String, String), usize> = HashMap::new();
    for task in std::mem::take(tasks) {
        let group_document = task.provider == PROVIDER_CRAFT || is_markdown_task(&task);
        if group_document {
            let key = (
                task.provider.clone(),
                task.library_id.clone(),
                task.document_id.clone(),
            );
            if let Some(index) = document_units.get(&key).copied() {
                units[index].push(task);
            } else {
                document_units.insert(key, units.len());
                units.push(vec![task]);
            }
        } else {
            units.push(vec![task]);
        }
    }
    for unit in &mut units {
        if unit.len() < 2 {
            continue;
        }
        let source_ids = unit
            .iter()
            .map(|task| task.source_id.clone())
            .collect::<HashSet<_>>();
        let mut children: HashMap<String, Vec<usize>> = HashMap::new();
        let mut roots = Vec::new();
        for (index, task) in unit.iter().enumerate() {
            if !task.parent_task_id.is_empty() && source_ids.contains(&task.parent_task_id) {
                children
                    .entry(task.parent_task_id.clone())
                    .or_default()
                    .push(index);
            } else {
                roots.push(index);
            }
        }
        let mut ordered = Vec::with_capacity(unit.len());
        let mut visited = HashSet::new();
        fn append_task_tree(
            index: usize,
            source: &[UnifiedTaskItem],
            children: &HashMap<String, Vec<usize>>,
            visited: &mut HashSet<usize>,
            ordered: &mut Vec<UnifiedTaskItem>,
            depth: usize,
        ) {
            if !visited.insert(index) {
                return;
            }
            let mut task = source[index].clone();
            task.depth = depth;
            let source_id = task.source_id.clone();
            ordered.push(task);
            if let Some(child_indexes) = children.get(&source_id) {
                for child_index in child_indexes {
                    append_task_tree(*child_index, source, children, visited, ordered, depth + 1);
                }
            }
        }
        for root in roots {
            append_task_tree(root, unit, &children, &mut visited, &mut ordered, 0);
        }
        for index in 0..unit.len() {
            append_task_tree(index, unit, &children, &mut visited, &mut ordered, 0);
        }
        *unit = ordered;
    }
    units.sort_by(|left, right| compare_unified_task_roots(&left[0], &right[0]));
    *tasks = units.into_iter().flatten().collect();
}

fn apply_task_bindings(
    connection: &Connection,
    tasks: &mut Vec<UnifiedTaskItem>,
) -> Result<(), String> {
    let mut statement = connection
        .prepare(
            "SELECT hub_task_id,provider,library_id,source_id
             FROM unified_task_bindings",
        )
        .map_err(|error| format!("无法读取任务对应关系：{error}"))?;
    let rows = statement
        .query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, String>(3)?,
            ))
        })
        .map_err(|error| format!("任务对应关系查询失败：{error}"))?;
    let bindings = rows
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("无法收集任务对应关系：{error}"))?;
    let mut hub_by_source = HashMap::new();
    // Scope and provider facets describe sources that are actually present in
    // this snapshot. A disabled or missing source may leave a binding behind;
    // it must not make the surviving row appear in that source's library view.
    let materialized_sources = tasks
        .iter()
        .map(|task| {
            (
                task.provider.clone(),
                task.library_id.clone(),
                task.source_id.clone(),
            )
        })
        .collect::<HashSet<_>>();
    let mut providers_by_hub: HashMap<String, BTreeSet<String>> = HashMap::new();
    let mut libraries_by_hub: HashMap<String, BTreeSet<String>> = HashMap::new();
    for (hub_task_id, provider, library_id, source_id) in bindings {
        if !materialized_sources.contains(&(
            provider.clone(),
            library_id.clone(),
            source_id.clone(),
        )) {
            continue;
        }
        hub_by_source.insert(
            (provider.clone(), library_id.clone(), source_id),
            hub_task_id.clone(),
        );
        libraries_by_hub
            .entry(hub_task_id.clone())
            .or_default()
            .insert(library_id);
        providers_by_hub
            .entry(hub_task_id)
            .or_default()
            .insert(provider);
    }
    let review_states = {
        let mut statement = connection
            .prepare(
                "SELECT DISTINCT hub_task_id,action FROM task_sync_events
                 WHERE status='review' AND action='conflict'",
            )
            .map_err(|error| format!("无法读取任务同步冲突：{error}"))?;
        let rows = statement
            .query_map([], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })
            .map_err(|error| format!("任务同步冲突查询失败：{error}"))?;
        rows.collect::<Result<HashMap<_, _>, _>>()
            .map_err(|error| format!("无法收集任务同步冲突：{error}"))?
    };
    for task in tasks.iter_mut() {
        task.linked_library_ids = vec![task.library_id.clone()];
        task.linked_providers = vec![task.provider.clone()];
        if task.collection_name.is_empty() {
            task.collection_name = task.document_title.clone();
        }
        if let Some(hub_task_id) = hub_by_source.get(&(
            task.provider.clone(),
            task.library_id.clone(),
            task.source_id.clone(),
        )) {
            task.id = hub_task_id.clone();
            task.linked_providers = providers_by_hub
                .get(hub_task_id)
                .map(|providers| providers.iter().cloned().collect())
                .unwrap_or_else(|| vec![task.provider.clone()]);
            task.linked_library_ids = libraries_by_hub
                .get(hub_task_id)
                .map(|libraries| libraries.iter().cloned().collect())
                .unwrap_or_else(|| vec![task.library_id.clone()]);
            task.sync_state = if let Some(action) = review_states.get(hub_task_id) {
                if action == "project_tag_removed" {
                    "paused"
                } else {
                    "conflict"
                }
            } else if task.linked_providers.len() > 1 {
                "linked"
            } else {
                "unlinked"
            }
            .to_string();
        }
    }
    let excluded_craft_sources = {
        let mut statement = connection
            .prepare("SELECT library_id,source_id FROM task_sync_exclusions WHERE provider='craft'")
            .map_err(|error| format!("无法读取已停止同步的 Craft 任务：{error}"))?;
        let rows = statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    normalized_task_sync_source_id(&row.get::<_, String>(1)?),
                ))
            })
            .map_err(|error| format!("已停止同步的 Craft 任务查询失败：{error}"))?;
        rows.collect::<Result<HashSet<_>, _>>()
            .map_err(|error| format!("无法收集已停止同步的 Craft 任务：{error}"))?
    };
    for task in tasks.iter_mut().filter(|task| {
        task.provider == PROVIDER_CRAFT
            && excluded_craft_sources.contains(&(
                task.library_id.clone(),
                normalized_task_sync_source_id(&task.source_id),
            ))
    }) {
        task.sync_state = "paused".to_string();
    }
    // Craft exposes only dates. For a linked row keep Craft as the preview
    // source, while borrowing the exact TickTick range for display.
    let dida_ranges = tasks
        .iter()
        .filter(|task| task.provider == PROVIDER_DIDA365 && task.sync_state != "unlinked")
        .map(|task| {
            (
                task.id.clone(),
                (
                    task.start_at.clone(),
                    task.due_at.clone(),
                    task.is_all_day,
                    task.time_zone.clone(),
                    task.collection_name.clone(),
                    task.status_write_blocked_reason.clone(),
                    task.priority,
                    task.tags.clone(),
                    task.content_revision.clone(),
                ),
            )
        })
        .collect::<HashMap<_, _>>();
    for task in tasks
        .iter_mut()
        .filter(|task| task.provider == PROVIDER_CRAFT)
    {
        if let Some((
            start_at,
            due_at,
            is_all_day,
            time_zone,
            collection_name,
            blocked_reason,
            priority,
            tags,
            revision,
        )) = dida_ranges.get(&task.id)
        {
            task.start_at = start_at.clone();
            task.due_at = due_at.clone();
            task.is_all_day = *is_all_day;
            task.time_zone = time_zone.clone();
            task.collection_name = collection_name.clone();
            task.status_write_blocked_reason = blocked_reason.clone();
            task.priority = *priority;
            task.tags = tags.clone();
            task.content_revision = format!("{}:{}", task.content_revision, revision);
        }
    }
    task_dates::merge_linked_dates(tasks);
    // A linked task is represented once in the task workspace. Provider-specific
    // fields remain in their own source and are not copied into task content.
    let mut seen_linked = HashSet::new();
    task_source_refs::attach(tasks);
    tasks.retain(|task| task.sync_state == "unlinked" || seen_linked.insert(task.id.clone()));
    Ok(())
}

#[tauri::command]
fn resolve_unified_task_search_result(
    app: AppHandle,
    provider: String,
    library_id: String,
    document_id: String,
    source_id: String,
    parent_page_id: String,
    title: String,
    is_project: bool,
) -> Result<UnifiedTaskSearchLocator, String> {
    let connection = open_database(&database_path(&app)?)?;
    let page_id = if is_project || source_id.contains(":line:") {
        parent_page_id.as_str()
    } else {
        source_id.as_str()
    };
    let expected_dida_id = format!("dida_task:{library_id}:{document_id}");
    let indexed = connection
        .query_row(
            "SELECT id,document_id,block_id,
                    CASE WHEN heading=?7 THEN 'heading' ELSE 'body' END AS match_field
             FROM content_items
             WHERE provider=?1 AND space_id=?2 AND document_id=?3
               AND (id=?4 OR page_id=?5 OR block_id=?6 OR heading=?7 OR instr(body,?7)>0)
             ORDER BY CASE
                        WHEN id=?4 THEN 0
                        WHEN page_id=?5 THEN 1
                        WHEN block_id=?6 THEN 2
                        WHEN heading=?7 THEN 3
                        ELSE 4
                      END,
                      ordinal
             LIMIT 1",
            params![
                provider,
                library_id,
                document_id,
                expected_dida_id,
                page_id,
                source_id,
                title,
            ],
            |row| {
                Ok(UnifiedTaskSearchLocator {
                    result_id: row.get(0)?,
                    document_id: row.get(1)?,
                    block_id: row.get(2)?,
                    match_field: row.get(3)?,
                })
            },
        )
        .optional()
        .map_err(|error| format!("无法查询任务对应的 Hub 搜索结果：{error}"))?;
    let fallback_document_id = document_id.clone();
    Ok(indexed.unwrap_or_else(|| UnifiedTaskSearchLocator {
        result_id: String::new(),
        document_id,
        block_id: if provider == PROVIDER_CRAFT {
            source_id
        } else {
            fallback_document_id
        },
        match_field: String::new(),
    }))
}

#[tauri::command]
async fn list_unified_tasks(app: AppHandle) -> Result<UnifiedTaskDashboard, String> {
    let path = database_path(&app)?;
    tokio::task::spawn_blocking(move || {
        let connection = open_database(&path)?;
        let mut tasks = unified_task_read::load(&connection, None)?;
        task_dates::capture_source_history(&connection, &tasks)?;
        task_dates::attach_hub_history(&connection, &mut tasks)?;
        apply_task_bindings(&connection, &mut tasks)?;
        dida_task_status::decorate(&connection, &mut tasks)?;
        sort_unified_tasks_preserving_markdown_trees(&mut tasks);
        let projects = tasks.iter().filter(|task| task.is_project).count();
        let total = tasks.len() - projects;
        let completed = tasks.iter().filter(|task| !task.is_project && task.status == "completed").count();
        let open = tasks.iter().filter(|task| !task.is_project && task.status == "open").count();
        let craft = tasks
            .iter()
            .filter(|task| !task.is_project && task_source_refs::has_provider(task,PROVIDER_CRAFT))
            .count();
        let dida365 = tasks
            .iter()
            .filter(|task| !task.is_project && task_source_refs::has_provider(task,PROVIDER_DIDA365))
            .count();
        let obsidian = tasks
            .iter()
            .filter(|task| !task.is_project && task_source_refs::has_provider(task,PROVIDER_OBSIDIAN))
            .count();
        let linked = tasks
            .iter()
            .filter(|task| task.sync_state == "linked" || task.sync_state == "conflict")
            .count();
        let (sync_enabled, background_sync_interval_minutes) = connection
            .query_row(
                "SELECT enabled,background_sync_interval_minutes
                 FROM task_sync_settings WHERE id=1",
                [],
                |row| Ok((row.get::<_, i64>(0)? != 0, row.get::<_, i64>(1)?)),
            )
            .unwrap_or((false, 0));
        let (last_sync_at, last_sync_status, last_sync_failed) = connection
            .query_row(
                "SELECT started_at,status,
                        (SELECT COUNT(*) FROM task_sync_run_entries entry
                         WHERE entry.run_id=task_sync_runs.id AND entry.status='failed')
                 FROM task_sync_runs
                 ORDER BY started_at DESC,id DESC LIMIT 1",
                [],
                |row| {
                    Ok((
                        Some(row.get::<_, i64>(0)?),
                        Some(row.get::<_, String>(1)?),
                        row.get::<_, i64>(2)? as usize,
                    ))
                },
            )
            .unwrap_or((None, None, 0));
        let sync_reviews = {
            let mut statement = connection
                .prepare(
                    "SELECT e.id,e.hub_task_id,e.action,
                            COALESCE(NULLIF(json_extract(e.payload_json,'$.title'),''),
                                     NULLIF(c.title,''),NULLIF(d.title,''),'任务'),
                            COALESCE(NULLIF(e.last_error,''),'任务同步需要人工选择来源'),
                            CASE WHEN c.block_id IS NULL THEN 0 ELSE 1 END,e.status,
                            CASE WHEN json_extract(e.payload_json,'$.managedCraftSourceId') IS NOT NULL
                                 THEN 'identity' ELSE 'content' END,
                            cb.source_id,c.title,cd.title,c.modified_at,
                            json_extract(e.payload_json,'$.managedCraftSourceId'),
                            mc.title,md.title,mc.modified_at,
                            CASE
                              WHEN json_extract(e.payload_json,'$.managedCraftSourceId') IS NULL THEN NULL
                              WHEN mc.block_id IS NULL THEN 'missing'
                              WHEN mb.hub_task_id IS NOT NULL AND mb.hub_task_id<>e.hub_task_id
                                THEN 'linked_elsewhere'
                              ELSE 'available'
                            END
                     FROM task_sync_events e
                     LEFT JOIN unified_task_bindings cb
                       ON cb.hub_task_id=e.hub_task_id AND cb.provider='craft'
                     LEFT JOIN craft_task_blocks c
                       ON c.space_id=cb.library_id AND c.block_id=cb.source_id
                     LEFT JOIN documents cd
                       ON cd.space_id=cb.library_id AND cd.id=cb.document_id
                     LEFT JOIN unified_task_bindings db
                       ON db.hub_task_id=e.hub_task_id AND db.provider='dida365'
                     LEFT JOIN dida_tasks d
                       ON d.library_id=db.library_id AND d.task_id=db.source_id
                     LEFT JOIN craft_task_blocks mc
                       ON mc.space_id=cb.library_id
                      AND mc.block_id=json_extract(e.payload_json,'$.managedCraftSourceId')
                     LEFT JOIN documents md
                       ON md.space_id=mc.space_id AND md.id=mc.document_id
                     LEFT JOIN unified_task_bindings mb
                       ON mb.provider='craft' AND mb.library_id=cb.library_id
                      AND mb.source_id=json_extract(e.payload_json,'$.managedCraftSourceId')
                     WHERE e.status IN ('review','pending','failed')
                       AND e.action='conflict'
                       AND e.id=(
                         SELECT latest.id FROM task_sync_events latest
                         WHERE latest.hub_task_id=e.hub_task_id
                           AND latest.action=e.action AND latest.status IN ('review','pending','failed')
                         ORDER BY latest.updated_at DESC,latest.id DESC LIMIT 1
                       )
                     ORDER BY e.updated_at DESC,e.id DESC",
                )
                .map_err(|error| format!("无法准备项目同步待处理项：{error}"))?;
            let rows = statement
                .query_map([], |row| {
                    Ok(TaskSyncReviewItem {
                        id: row.get(0)?,
                        hub_task_id: row.get(1)?,
                        action: row.get(2)?,
                        title: row.get(3)?,
                        message: row.get(4)?,
                        merge_allowed: row.get::<_, i64>(5)? != 0,
                        status: row.get(6)?,
                        conflict_type: row.get(7)?,
                        bound_craft_source_id: row.get(8)?,
                        bound_craft_title: row.get(9)?,
                        bound_craft_document_title: row.get(10)?,
                        bound_craft_modified_at: row.get(11)?,
                        managed_craft_source_id: row.get(12)?,
                        managed_craft_title: row.get(13)?,
                        managed_craft_document_title: row.get(14)?,
                        managed_craft_modified_at: row.get(15)?,
                        managed_craft_state: row.get(16)?,
                    })
                })
                .map_err(|error| format!("项目同步待处理项查询失败：{error}"))?;
            rows.collect::<Result<Vec<_>, _>>()
                .map_err(|error| format!("无法读取项目同步待处理项：{error}"))?
        };
        Ok(UnifiedTaskDashboard {
            projects,
            tasks,
            total,
            open,
            completed,
            craft,
            dida365,
            obsidian,
            linked,
            sync_enabled,
            background_sync_interval_minutes,
            last_sync_at,
            last_sync_status,
            last_sync_failed,
            sync_reviews,
        })
    })
    .await
    .map_err(|error| format!("统一任务查询异常：{error}"))?
}

#[tauri::command]
async fn preview_task_sync(
    app: AppHandle,
    state: State<'_, AppState>,
) -> Result<TaskSyncPreview, String> {
    // The project picker must reflect TickTick now, not the last local index.
    // Refresh only Dida libraries here; this remains a read-only preview and
    // does not create, update, complete, or delete any remote task.
    let path = database_path(&app)?;
    let query_path = path.clone();
    let dida_library_ids = tokio::task::spawn_blocking(move || {
        let connection = open_database(&query_path)?;
        let mut statement = connection
            .prepare("SELECT id FROM libraries WHERE enabled=1 AND provider='dida365'")
            .map_err(|error| format!("无法准备滴答清单刷新：{error}"))?;
        let rows = statement
            .query_map([], |row| row.get::<_, String>(0))
            .map_err(|error| format!("无法读取滴答资料库：{error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法收集滴答资料库：{error}"))
    })
    .await
    .map_err(|error| format!("滴答资料库查询异常：{error}"))??;
    if dida_library_ids.is_empty() {
        return Err("尚未连接滴答清单资料库".to_string());
    }
    let sync_state = state.clone();
    let _guard = state.sync_guard.lock().await;
    for library_id in dida_library_ids {
        sync_library_with_outcome(app.clone(), library_id, sync_state.clone(), true)
            .await
            .map_err(|error| format!("无法刷新滴答清单列表：{error}"))?;
    }

    let dashboard = list_unified_tasks(app.clone()).await?;
    let mut craft_titles: HashMap<String, usize> = HashMap::new();
    let mut dida_titles: HashMap<String, usize> = HashMap::new();
    for task in dashboard
        .tasks
        .iter()
        .filter(|task| task.sync_state == "unlinked")
    {
        let normalized = task.title.trim().to_lowercase();
        if normalized.is_empty() {
            continue;
        }
        match task.provider.as_str() {
            PROVIDER_CRAFT => *craft_titles.entry(normalized).or_default() += 1,
            PROVIDER_DIDA365 => *dida_titles.entry(normalized).or_default() += 1,
            _ => {}
        }
    }
    // Only one-to-one equal titles are safe candidates. On enable they are
    // linked without overwriting either side; differing content goes to review.
    let exact_title_candidates = craft_titles
        .iter()
        .filter(|(title, craft_count)| {
            **craft_count == 1 && dida_titles.get(*title).copied() == Some(1)
        })
        .count();
    let (projects, libraries) = tokio::task::spawn_blocking(move || {
        let connection = open_database(&path)?;
        let mut statement = connection
            .prepare(
                "SELECT id,name FROM libraries
                 WHERE enabled=1 AND provider='dida365' ORDER BY name,id",
            )
            .map_err(|error| format!("无法读取滴答资料库：{error}"))?;
        let rows = statement
            .query_map([], |row| {
                Ok(TaskSyncLibraryOption {
                    library_id: row.get(0)?,
                    name: row.get(1)?,
                })
            })
            .map_err(|error| format!("滴答资料库查询失败：{error}"))?;
        let mut projects = Vec::new();
        let mut libraries = Vec::new();
        for row in rows {
            let library = row.map_err(|error| format!("无法读取滴答资料库：{error}"))?;
            if let Ok(project_id) = task_sync_inbox_project_id(&connection, &library.library_id) {
                projects.push(TaskSyncProjectOption {
                    library_id: library.library_id.clone(),
                    project_id,
                    name: "收件箱".to_string(),
                });
                libraries.push(library);
            }
        }
        Ok::<_, String>((projects, libraries))
    })
    .await
    .map_err(|error| format!("读取滴答资料库异常：{error}"))??;
    let craft_unlinked = dashboard
        .tasks
        .iter()
        .filter(|task| task.provider == PROVIDER_CRAFT && task.sync_state == "unlinked")
        .count();
    let dida_unlinked = dashboard
        .tasks
        .iter()
        .filter(|task| task.provider == PROVIDER_DIDA365 && task.sync_state == "unlinked")
        .count();
    let safe_to_enable = !projects.is_empty();
    Ok(TaskSyncPreview {
        craft_unlinked,
        dida_unlinked,
        linked: dashboard.linked,
        exact_title_candidates,
        projects,
        libraries,
        safe_to_enable,
        message: if safe_to_enable {
            "新建顶层任务进入滴答收件箱；移动到其他清单后继续同步，新增子任务跟随父任务所在清单。唯一同名任务会先建立关联，两端内容不同则进入冲突选择。".to_string()
        } else {
            "尚未读取到可用的滴答收件箱，请先同步滴答资料库。".to_string()
        },
    })
}

#[tauri::command]
async fn inspect_task_sync_capabilities(
    app: AppHandle,
    state: State<'_, AppState>,
) -> Result<TaskSyncCapabilities, String> {
    let path = database_path(&app)?;
    let provider_libraries = tokio::task::spawn_blocking(move || {
        let connection = open_database(&path)?;
        let mut statement = connection
            .prepare(
                "SELECT id,provider FROM libraries
                 WHERE enabled=1 AND provider IN ('craft','dida365')",
            )
            .map_err(|error| format!("无法准备同步能力查询：{error}"))?;
        let rows = statement
            .query_map([], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })
            .map_err(|error| format!("同步能力查询失败：{error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法读取同步资料库：{error}"))
    })
    .await
    .map_err(|error| format!("同步能力检查异常：{error}"))??;

    let sessions = state
        .sessions
        .lock()
        .map_err(|_| "同步连接状态暂时不可用".to_string())?
        .clone();
    let client = reqwest::Client::new();
    let mut craft_connected = false;
    let mut craft_write_available = false;
    let mut dida_connected = false;
    let mut dida_tools = BTreeSet::new();
    let mut request_id = 41_000_u64;
    let mut errors = Vec::new();
    for (library_id, provider) in provider_libraries {
        let Some(session) = sessions.get(&library_id) else {
            continue;
        };
        if provider == PROVIDER_CRAFT {
            craft_connected = true;
        } else if provider == PROVIDER_DIDA365 {
            dida_connected = true;
        }
        request_id += 1;
        match mcp_tool_summaries(&client, session, request_id).await {
            Ok(tools) if provider == PROVIDER_CRAFT => {
                craft_write_available |= tools.iter().any(|tool| tool.name == "craft_write");
            }
            Ok(tools) if provider == PROVIDER_DIDA365 => {
                dida_tools.extend(tools.into_iter().map(|tool| tool.name));
            }
            Ok(_) => {}
            Err(error) => errors.push(error),
        }
    }
    let required_dida = ["create_task", "update_task", "complete_task", "delete_task"];
    let dida_write_tools = required_dida
        .iter()
        .filter(|tool| dida_tools.contains(**tool))
        .map(|tool| (*tool).to_string())
        .collect::<Vec<_>>();
    let missing_dida_write_tools = required_dida
        .iter()
        .filter(|tool| !dida_tools.contains(**tool))
        .map(|tool| (*tool).to_string())
        .collect::<Vec<_>>();
    let ready_for_controlled_sync = craft_connected
        && craft_write_available
        && dida_connected
        && missing_dida_write_tools.is_empty();
    let message = if ready_for_controlled_sync {
        "Craft 与滴答写入能力已就绪；仍将先建立外部映射和快照，再允许首轮受控同步。".to_string()
    } else if !errors.is_empty() {
        format!("能力检查未完成：{}", errors.join("；"))
    } else {
        "至少一个写入连接尚未就绪；当前继续保持只读聚合，不会写入外部任务。".to_string()
    };
    Ok(TaskSyncCapabilities {
        craft_connected,
        craft_write_available,
        dida_connected,
        dida_write_tools,
        missing_dida_write_tools,
        ready_for_controlled_sync,
        message,
    })
}

fn load_task_sync_records(path: &PathBuf) -> Result<Vec<TaskSyncRecord>, String> {
    let connection = open_database(path)?;
    let trash_documents = load_confirmed_craft_trash_documents(&connection)?;
    let mut records = Vec::new();
    {
        let mut statement = connection
            .prepare(
                "SELECT b.space_id,l.name,b.block_id,b.parent_task_id,b.document_id,b.parent_page_id,
                        COALESCE(d.raw_document_id,''),b.title,b.completed,b.schedule_date,b.deadline_date,b.content
                 FROM craft_task_blocks b
                 JOIN libraries l ON l.id=b.space_id
                 JOIN documents d ON d.space_id=b.space_id AND d.id=b.document_id
                 WHERE l.enabled=1
                   AND NOT EXISTS (
                   SELECT 1 FROM task_sync_craft_trash_documents x
                   WHERE x.library_id=b.space_id AND x.document_id=b.document_id
                 )",
            )
            .map_err(|error| format!("无法准备 Craft 同步任务：{error}"))?;
        let rows = statement
            .query_map([], |row| {
                Ok(TaskSyncRecord {
                    provider: PROVIDER_CRAFT.to_string(),
                    library_id: row.get(0)?,
                    source_space_name: row.get(1)?,
                    source_id: row.get(2)?,
                    parent_source_id: row.get(3)?,
                    document_id: row.get(4)?,
                    parent_page_id: row.get(5)?,
                    raw_document_id: row.get(6)?,
                    title: clean_task_display_title(&row.get::<_, String>(7)?),
                    completed: row.get::<_, i64>(8)? != 0,
                    start_at: String::new(),
                    due_at: String::new(),
                    is_all_day: true,
                    time_zone: "Asia/Shanghai".to_string(),
                    schedule_date: row.get(9)?,
                    deadline_date: row.get(10)?,
                    project_id: String::new(),
                    content: row.get(11)?,
                    description: String::new(),
                    tags: Vec::new(),
                    is_project_page: false,
                })
            })
            .map_err(|error| format!("Craft 同步任务查询失败：{error}"))?;
        records.extend(
            rows.collect::<Result<Vec<_>, _>>()
                .map_err(|error| format!("无法读取 Craft 同步任务：{error}"))?,
        );
    }
    {
        for page in load_craft_project_pages(&connection)?
            .into_iter()
            .filter(|page| {
                !trash_documents.contains(&(page.library_id.clone(), page.document_id.clone()))
            })
        {
            let source_id = craft_project_source_id(&page.page_id);
            let child_indexes = records
                .iter()
                .enumerate()
                .filter(|(_, record)| {
                    record.provider == PROVIDER_CRAFT
                        && record.library_id == page.library_id
                        && record.document_id == page.document_id
                        && record.parent_page_id == page.page_id
                        && !record.is_project_page
                })
                .map(|(index, _)| index)
                .collect::<Vec<_>>();
            let completed = !child_indexes.is_empty()
                && child_indexes.iter().all(|index| records[*index].completed);
            assign_craft_project_parent(&mut records, &child_indexes, &source_id);
            records.push(TaskSyncRecord {
                provider: PROVIDER_CRAFT.to_string(),
                library_id: page.library_id,
                source_space_name: page.library_name,
                source_id,
                parent_source_id: String::new(),
                document_id: page.document_id,
                parent_page_id: page.page_id,
                raw_document_id: page.raw_document_id,
                title: page.title,
                completed,
                start_at: String::new(),
                due_at: String::new(),
                is_all_day: true,
                time_zone: "Asia/Shanghai".to_string(),
                schedule_date: String::new(),
                deadline_date: String::new(),
                project_id: String::new(),
                content: String::new(),
                description: String::new(),
                tags: Vec::new(),
                is_project_page: true,
            });
        }
    }
    {
        let mut statement = connection
            .prepare(
                "SELECT t.library_id,l.name,t.task_id,COALESCE(t.parent_id,''),t.project_id,
                        t.title,t.status,t.content,t.description,t.raw_json,
                        COALESCE(t.start_at,''),COALESCE(t.due_at,''),COALESCE(t.time_zone,'Asia/Shanghai')
                 FROM dida_tasks t JOIN libraries l ON l.id=t.library_id
                 WHERE l.enabled=1 AND (t.missing_syncs=0 OR t.status!=0)",
            )
            .map_err(|error| format!("无法准备滴答同步任务：{error}"))?;
        let rows = statement
            .query_map([], |row| {
                let raw_json = row.get::<_, String>(9)?;
                let tags = serde_json::from_str::<Value>(&raw_json)
                    .ok()
                    .and_then(|value| value.get("tags").and_then(Value::as_array).cloned())
                    .unwrap_or_default()
                    .into_iter()
                    .filter_map(|value| value.as_str().map(str::to_string))
                    .collect();
                let (schedule_date, deadline_date) = normalized_dida_task_dates(
                    &row.get::<_, String>(10)?,
                    &row.get::<_, String>(11)?,
                );
                Ok(TaskSyncRecord {
                    provider: PROVIDER_DIDA365.to_string(),
                    library_id: row.get(0)?,
                    source_space_name: row.get(1)?,
                    source_id: row.get(2)?,
                    parent_source_id: row.get(3)?,
                    document_id: String::new(),
                    parent_page_id: String::new(),
                    raw_document_id: String::new(),
                    project_id: row.get(4)?,
                    title: row.get(5)?,
                    completed: row.get::<_, i64>(6)? != 0,
                    start_at: row.get(10)?,
                    due_at: row.get(11)?,
                    is_all_day: serde_json::from_str::<Value>(&raw_json)
                        .ok()
                        .and_then(|value| value.get("isAllDay").and_then(Value::as_bool))
                        .unwrap_or(true),
                    time_zone: row.get(12)?,
                    schedule_date,
                    deadline_date,
                    content: row.get(7)?,
                    description: row.get(8)?,
                    tags,
                    is_project_page: false,
                })
            })
            .map_err(|error| format!("滴答同步任务查询失败：{error}"))?;
        records.extend(
            rows.collect::<Result<Vec<_>, _>>()
                .map_err(|error| format!("无法读取滴答同步任务：{error}"))?,
        );
    }
    Ok(records)
}

fn load_task_sync_pairs(path: &PathBuf) -> Result<Vec<TaskSyncBindingPair>, String> {
    let connection = open_database(path)?;
    let mut statement = connection
        .prepare(
            "SELECT c.hub_task_id,c.library_id,c.source_id,c.document_id,d.library_id,d.source_id
             FROM unified_task_bindings c
             JOIN unified_task_bindings d ON d.hub_task_id=c.hub_task_id
             JOIN libraries cl ON cl.id=c.library_id AND cl.enabled=1
             JOIN libraries dl ON dl.id=d.library_id AND dl.enabled=1
             WHERE c.provider='craft' AND d.provider='dida365'",
        )
        .map_err(|error| format!("无法准备任务同步关系：{error}"))?;
    let rows = statement
        .query_map([], |row| {
            Ok(TaskSyncBindingPair {
                hub_task_id: row.get(0)?,
                craft_library_id: row.get(1)?,
                craft_source_id: row.get(2)?,
                craft_document_id: row.get(3)?,
                dida_library_id: row.get(4)?,
                dida_source_id: row.get(5)?,
            })
        })
        .map_err(|error| format!("任务同步关系查询失败：{error}"))?;
    rows.collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("无法读取任务同步关系：{error}"))
}

fn remove_local_inactive_craft_tasks(
    path: &PathBuf,
    task_keys: &HashSet<(String, String)>,
) -> Result<(), String> {
    if task_keys.is_empty() {
        return Ok(());
    }
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始清理失效 Craft 任务缓存：{error}"))?;
    for (library_id, source_id) in task_keys {
        transaction
            .execute(
                "DELETE FROM craft_task_blocks WHERE space_id=?1 AND block_id=?2",
                params![library_id, source_id],
            )
            .map_err(|error| format!("无法清理失效 Craft 任务缓存：{error}"))?;
    }
    task_sync_library_commit(|| {
        transaction
            .commit()
            .map_err(|error| format!("无法提交失效 Craft 任务缓存清理：{error}"))
    })
}

fn craft_task_tree_for_deletion(
    records: &[TaskSyncRecord],
    library_id: &str,
    root_source_id: &str,
) -> Vec<TaskSyncRecord> {
    let craft_records = records
        .iter()
        .filter(|record| record.provider == PROVIDER_CRAFT && record.library_id == library_id)
        .collect::<Vec<_>>();
    let mut pending = vec![(root_source_id.to_string(), 0_usize)];
    let mut visited = HashSet::new();
    let mut found = Vec::new();
    while let Some((source_id, depth)) = pending.pop() {
        if !visited.insert(source_id.clone()) {
            continue;
        }
        if let Some(record) = craft_records
            .iter()
            .find(|record| record.source_id == source_id)
        {
            found.push(((*record).clone(), depth));
        }
        for child in craft_records
            .iter()
            .filter(|record| record.parent_source_id == source_id)
        {
            pending.push((child.source_id.clone(), depth + 1));
        }
    }
    found.sort_by(|left, right| right.1.cmp(&left.1));
    found.into_iter().map(|(record, _)| record).collect()
}

fn dida_task_tree_for_deletion(
    records: &[TaskSyncRecord],
    library_id: &str,
    root_source_id: &str,
) -> Vec<TaskSyncRecord> {
    let dida_records = records
        .iter()
        .filter(|record| record.provider == PROVIDER_DIDA365 && record.library_id == library_id)
        .collect::<Vec<_>>();
    let mut pending = vec![(root_source_id.to_string(), 0_usize)];
    let mut visited = HashSet::new();
    let mut found = Vec::new();
    while let Some((source_id, depth)) = pending.pop() {
        if !visited.insert(source_id.clone()) {
            continue;
        }
        if let Some(record) = dida_records
            .iter()
            .find(|record| record.source_id == source_id)
        {
            found.push(((*record).clone(), depth));
        }
        for child in dida_records
            .iter()
            .filter(|record| record.parent_source_id == source_id)
        {
            pending.push((child.source_id.clone(), depth + 1));
        }
    }
    found.sort_by(|left, right| right.1.cmp(&left.1));
    found.into_iter().map(|(record, _)| record).collect()
}

fn task_record_depth(records: &[TaskSyncRecord], record: &TaskSyncRecord) -> usize {
    let mut depth = 0;
    let mut parent = record.parent_source_id.as_str();
    let mut visited = HashSet::new();
    while !parent.is_empty() && visited.insert(parent.to_string()) {
        let Some(parent_record) = records.iter().find(|candidate| {
            candidate.provider == PROVIDER_CRAFT
                && candidate.library_id == record.library_id
                && candidate.source_id == parent
        }) else {
            break;
        };
        depth += 1;
        parent = parent_record.parent_source_id.as_str();
    }
    depth
}

fn error_confirms_missing(error: &str) -> bool {
    let lower = error.to_lowercase();
    lower.contains("404")
        || lower.contains("not found")
        || lower.contains("不存在")
        || lower.contains("未找到")
}

fn error_confirms_craft_document_deleted(error: &str) -> bool {
    let lower = error.to_lowercase();
    lower.contains("cannot modify document in trash")
        || lower.contains("restore trashed documents")
        || lower.contains("document is in trash")
        || lower.contains("文档已在废纸篓")
}

fn craft_document_has_trash_tombstone(
    connection: &Connection,
    library_id: &str,
    document_id: &str,
) -> Result<bool, String> {
    connection
        .query_row(
            "SELECT EXISTS(
               SELECT 1 FROM task_sync_craft_trash_documents
               WHERE library_id=?1 AND document_id=?2
             )",
            params![library_id, document_id],
            |row| row.get::<_, bool>(0),
        )
        .map_err(|error| format!("无法读取 Craft 废纸篓文档状态：{error}"))
}

fn remove_local_craft_document(
    path: &PathBuf,
    library_id: &str,
    document_id: &str,
) -> Result<(), String> {
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始清理已删除的 Craft 文档：{error}"))?;
    let timestamp = now_timestamp();
    transaction
        .execute(
            "INSERT INTO task_sync_craft_trash_documents
               (library_id,document_id,confirmed_at) VALUES (?1,?2,?3)
             ON CONFLICT(library_id,document_id) DO UPDATE SET confirmed_at=excluded.confirmed_at",
            params![library_id, document_id, timestamp],
        )
        .map_err(|error| format!("无法记录 Craft 废纸篓文档：{error}"))?;
    transaction
        .execute(
            "INSERT INTO index_jobs
         (job_key,space_id,source_id,source_type,job_type,status,priority,created_at,updated_at)
         VALUES (?1,?2,?3,'document','delete_lexical','pending',20,?4,?4)
         ON CONFLICT(job_key) DO UPDATE SET job_type='delete_lexical',status='pending',
           priority=20,attempts=0,updated_at=excluded.updated_at,last_error=NULL,
           next_attempt_at=0,worker_id=NULL,locked_at=NULL,lease_until=NULL",
            params![
                format!("lexical:{library_id}:{document_id}"),
                library_id,
                document_id,
                timestamp
            ],
        )
        .map_err(|error| format!("无法登记 Craft 文档删除索引：{error}"))?;
    transaction
        .execute(
            "DELETE FROM content_items WHERE space_id=?1 AND document_id=?2",
            params![library_id, document_id],
        )
        .map_err(|error| format!("无法删除 Craft 文档内容：{error}"))?;
    transaction.execute(
        "DELETE FROM index_jobs WHERE source_id IN (SELECT id FROM source_items WHERE space_id=?1 AND document_id=?2)",
        params![library_id, document_id],
    ).map_err(|error| format!("无法删除 Craft 文档附件任务：{error}"))?;
    transaction.execute(
        "DELETE FROM extractions WHERE source_item_id IN (SELECT id FROM source_items WHERE space_id=?1 AND document_id=?2)",
        params![library_id, document_id],
    ).map_err(|error| format!("无法删除 Craft 文档提取记录：{error}"))?;
    transaction
        .execute(
            "DELETE FROM source_items WHERE space_id=?1 AND document_id=?2",
            params![library_id, document_id],
        )
        .map_err(|error| format!("无法删除 Craft 文档附件来源：{error}"))?;
    transaction
        .execute(
            "DELETE FROM craft_tags WHERE space_id=?1 AND document_id=?2",
            params![library_id, document_id],
        )
        .map_err(|error| format!("无法删除 Craft 文档标签：{error}"))?;
    transaction
        .execute(
            "DELETE FROM craft_task_blocks WHERE space_id=?1 AND document_id=?2",
            params![library_id, document_id],
        )
        .map_err(|error| format!("无法删除 Craft 文档任务：{error}"))?;
    transaction
        .execute(
            "DELETE FROM documents WHERE space_id=?1 AND id=?2",
            params![library_id, document_id],
        )
        .map_err(|error| format!("无法删除 Craft 文档记录：{error}"))?;
    task_sync_library_commit(|| {
        transaction
            .commit()
            .map_err(|error| format!("无法提交 Craft 文档删除：{error}"))
    })
}

#[allow(clippy::too_many_arguments)]
async fn cascade_delete_dida_for_craft_document(
    path: &PathBuf,
    state: &State<'_, AppState>,
    client: &reqwest::Client,
    craft_library_id: &str,
    craft_document_id: &str,
    document_pairs: &[TaskSyncBindingPair],
    record_map: &HashMap<(String, String, String), TaskSyncRecord>,
    dida_project_id: &str,
    handled_pairs: &mut HashSet<String>,
    summary: &mut TaskSyncRunSummary,
    sync_errors: &mut Vec<String>,
    log_entries: &mut Vec<TaskSyncLogDraft>,
    request_id: &mut u64,
) -> Result<(), String> {
    let mut all_counterparts_deleted = true;
    for document_pair in document_pairs {
        if handled_pairs.contains(&document_pair.hub_task_id) {
            continue;
        }
        let craft_record = record_map.get(&(
            PROVIDER_CRAFT.to_string(),
            document_pair.craft_library_id.clone(),
            document_pair.craft_source_id.clone(),
        ));
        let dida_record = record_map.get(&(
            PROVIDER_DIDA365.to_string(),
            document_pair.dida_library_id.clone(),
            document_pair.dida_source_id.clone(),
        ));
        let task_title = craft_record
            .map(|record| record.title.clone())
            .or_else(|| dida_record.map(|record| record.title.clone()))
            .unwrap_or_else(|| document_pair.dida_source_id.clone());
        let project_id = dida_record
            .map(|record| record.project_id.as_str())
            .filter(|project_id| !project_id.is_empty())
            .unwrap_or(dida_project_id);
        let dida_session = session_for_space(state, &document_pair.dida_library_id)?;
        *request_id += 1;
        let deleted = call_dida_write_tool_raw(
            client,
            &dida_session,
            "delete_task",
            json!({"project_id": project_id, "task_id": document_pair.dida_source_id}),
            *request_id,
        )
        .await;
        if deleted.is_ok()
            || deleted
                .as_ref()
                .err()
                .is_some_and(|delete_error| error_confirms_missing(delete_error))
        {
            record_pair_craft_source_tombstones(
                path,
                document_pair,
                dida_record,
                "Craft 所在文档进入废纸篓",
            )?;
            remove_task_sync_pair(path, &document_pair.hub_task_id)?;
            handled_pairs.insert(document_pair.hub_task_id.clone());
            summary.deleted_in_dida += 1;
            log_entries.push(TaskSyncLogDraft {
                title: task_title,
                action: "delete".to_string(),
                source_provider: PROVIDER_CRAFT.to_string(),
                target_provider: PROVIDER_DIDA365.to_string(),
                status: "success".to_string(),
                detail: "Craft 所在文档已进入废纸篓；已级联删除对应滴答任务".to_string(),
            });
        } else if let Err(delete_error) = deleted {
            all_counterparts_deleted = false;
            summary.failed += 1;
            sync_errors.push(format!(
                "Craft 文档已进入废纸篓，但删除滴答任务“{task_title}”失败：{delete_error}"
            ));
        }
    }
    if all_counterparts_deleted {
        remove_local_craft_document(path, craft_library_id, craft_document_id)
    } else {
        // Keep the local Craft document and all still-bound pairs. A later run
        // can retry only the counterpart deletions that did not commit.
        Ok(())
    }
}

fn load_task_sync_snapshots(path: &PathBuf) -> Result<HashMap<(String, String), String>, String> {
    let connection = open_database(path)?;
    let mut statement = connection
        .prepare("SELECT hub_task_id,provider,source_hash FROM task_sync_snapshots")
        .map_err(|error| format!("无法准备任务同步快照：{error}"))?;
    let rows = statement
        .query_map([], |row| {
            Ok(((row.get(0)?, row.get(1)?), row.get::<_, String>(2)?))
        })
        .map_err(|error| format!("任务同步快照查询失败：{error}"))?;
    rows.collect::<Result<HashMap<_, _>, _>>()
        .map_err(|error| format!("无法读取任务同步快照：{error}"))
}

