// A successful remote create is an identity receipt, not a verified baseline.
// Keep it even when the operation was stopped while the response was in flight.
fn save_task_sync_identity_receipt(
    path: &PathBuf,
    hub_task_id: &str,
    craft: &TaskSyncRecord,
    dida_library_id: &str,
    dida_source_id: &str,
) -> Result<(), String> {
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法保存已创建任务身份：{error}"))?;
    for (provider, library_id, source_id, document_id) in [
        (
            PROVIDER_CRAFT,
            craft.library_id.as_str(),
            craft.source_id.as_str(),
            craft.document_id.as_str(),
        ),
        (PROVIDER_DIDA365, dida_library_id, dida_source_id, ""),
    ] {
        transaction.execute("DELETE FROM unified_task_bindings WHERE hub_task_id=?1 AND provider=?2 AND NOT (library_id=?3 AND source_id=?4)",params![hub_task_id,provider,library_id,source_id]).map_err(|error|format!("无法保存已创建任务身份：{error}"))?;
        transaction.execute("INSERT INTO unified_task_bindings(hub_task_id,provider,library_id,source_id,document_id,source_hash,last_seen_at,missing_syncs) VALUES (?1,?2,?3,?4,?5,'',?6,0) ON CONFLICT(provider,library_id,source_id) DO UPDATE SET hub_task_id=excluded.hub_task_id,document_id=excluded.document_id,last_seen_at=excluded.last_seen_at,missing_syncs=0",params![hub_task_id,provider,library_id,source_id,document_id,now_timestamp()]).map_err(|error|format!("无法保存已创建任务身份：{error}"))?;
    }
    transaction
        .commit()
        .map_err(|error| format!("无法提交已创建任务身份：{error}"))
}

fn clear_task_sync_identity_receipt_after_delete(
    path: &PathBuf,
    hub_task_id: &str,
    provider: &str,
    source_id: &str,
) -> Result<(), String> {
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法清理已回滚任务身份：{error}"))?;
    let matches:bool=transaction.query_row("SELECT EXISTS(SELECT 1 FROM unified_task_bindings WHERE hub_task_id=?1 AND provider=?2 AND source_id=?3)",params![hub_task_id,provider,source_id],|row|row.get(0)).map_err(|error|format!("无法核对已回滚任务身份：{error}"))?;
    if matches {
        transaction
            .execute(
                "DELETE FROM unified_task_bindings WHERE hub_task_id=?1",
                [hub_task_id],
            )
            .map_err(|error| format!("无法清理已回滚任务身份：{error}"))?;
    }
    transaction
        .commit()
        .map_err(|error| format!("无法提交已回滚任务身份清理：{error}"))
}

