fn save_new_task_sync_pair(
    path: &PathBuf,
    craft: &TaskSyncRecord,
    dida_library_id: &str,
    dida_source_id: &str,
) -> Result<(), String> {
    let hub_task_id = unified_task_id(PROVIDER_CRAFT, &craft.library_id, &craft.source_id);
    let source_hash = task_sync_source_hash(path, craft)?;
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始保存任务对应关系：{error}"))?;
    let now = now_timestamp();
    for (provider, library_id, source_id, document_id) in [
        (
            PROVIDER_CRAFT,
            craft.library_id.as_str(),
            craft.source_id.as_str(),
            craft.document_id.as_str(),
        ),
        (PROVIDER_DIDA365, dida_library_id, dida_source_id, ""),
    ] {
        // A source can be re-created with a new provider ID while retaining the
        // same Hub identity (for example after a remote create succeeded but a
        // later sync step failed).  The source-key UPSERT below cannot resolve
        // the table's other unique constraint by itself, so release the stale
        // provider slot before inserting the replacement binding.
        transaction
            .execute(
                "DELETE FROM unified_task_bindings
                 WHERE hub_task_id=?1 AND provider=?2
                   AND NOT (library_id=?3 AND source_id=?4)",
                params![hub_task_id, provider, library_id, source_id],
            )
            .map_err(|error| format!("无法替换旧任务对应关系：{error}"))?;
        transaction
            .execute(
                "INSERT INTO unified_task_bindings
                   (hub_task_id,provider,library_id,source_id,document_id,source_hash,last_seen_at,missing_syncs)
                 VALUES (?1,?2,?3,?4,?5,?6,?7,0)
                 ON CONFLICT(provider,library_id,source_id) DO UPDATE SET
                   hub_task_id=excluded.hub_task_id,document_id=excluded.document_id,
                   source_hash=excluded.source_hash,last_seen_at=excluded.last_seen_at,missing_syncs=0",
                params![hub_task_id, provider, library_id, source_id, document_id, source_hash, now],
            )
            .map_err(|error| format!("无法保存任务对应关系：{error}"))?;
        transaction
            .execute(
                "INSERT INTO task_sync_snapshots
                   (hub_task_id,provider,source_hash,applied_hash,synced_at)
                 VALUES (?1,?2,?3,?3,?4)
                 ON CONFLICT(hub_task_id,provider) DO UPDATE SET
                   source_hash=excluded.source_hash,applied_hash=excluded.applied_hash,
                   synced_at=excluded.synced_at",
                params![hub_task_id, provider, source_hash, now],
            )
            .map_err(|error| format!("无法保存新任务同步快照：{error}"))?;
    }
    task_sync_library_commit(|| {
        transaction
            .commit()
            .map_err(|error| format!("无法提交任务对应关系：{error}"))
    })
}

fn replace_project_binding_with_craft_task(
    path: &PathBuf,
    pair: &TaskSyncBindingPair,
    craft: &TaskSyncRecord,
) -> Result<(), String> {
    let source_hash = task_sync_source_hash(path, craft)?;
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始转换项目容器绑定：{error}"))?;
    let changed = transaction
        .execute(
            "UPDATE unified_task_bindings
             SET library_id=?2,source_id=?3,document_id=?4,source_hash=?5,
                 last_seen_at=?6,missing_syncs=0
             WHERE hub_task_id=?1 AND provider='craft'",
            params![
                pair.hub_task_id,
                craft.library_id,
                craft.source_id,
                craft.document_id,
                source_hash,
                now_timestamp()
            ],
        )
        .map_err(|error| format!("无法把虚拟项目绑定转换为 Craft 父任务：{error}"))?;
    if changed != 1 {
        return Err("虚拟项目绑定已不存在，未转换为 Craft 父任务".to_string());
    }
    transaction
        .execute(
            "DELETE FROM task_sync_tombstones WHERE hub_task_id=?1",
            [&pair.hub_task_id],
        )
        .map_err(|error| format!("无法清理项目容器删除候选：{error}"))?;
    transaction
        .execute(
            "DELETE FROM task_sync_events WHERE hub_task_id=?1 AND action='project_tag_removed'",
            [&pair.hub_task_id],
        )
        .map_err(|error| format!("无法清理项目容器旧提示：{error}"))?;
    transaction
        .execute(
            "INSERT INTO task_sync_snapshots
               (hub_task_id,provider,source_hash,applied_hash,synced_at)
             VALUES (?1,'craft',?2,?2,?3)
             ON CONFLICT(hub_task_id,provider) DO UPDATE SET
               source_hash=excluded.source_hash,applied_hash=excluded.applied_hash,
               synced_at=excluded.synced_at",
            params![pair.hub_task_id, source_hash, now_timestamp()],
        )
        .map_err(|error| format!("无法保存新 Craft 父任务基线：{error}"))?;
    let forced_dida = format!("force-conflict-resolution:dida_wins:{}", now_timestamp());
    transaction
        .execute(
            "INSERT INTO task_sync_snapshots
               (hub_task_id,provider,source_hash,applied_hash,synced_at)
             VALUES (?1,'dida365',?2,?2,?3)
             ON CONFLICT(hub_task_id,provider) DO UPDATE SET
               source_hash=excluded.source_hash,applied_hash=excluded.applied_hash,
               synced_at=excluded.synced_at",
            params![pair.hub_task_id, forced_dida, now_timestamp()],
        )
        .map_err(|error| format!("无法安排滴答容器详情写入新 Craft 父任务：{error}"))?;
    task_sync_library_commit(|| {
        transaction
            .commit()
            .map_err(|error| format!("无法提交项目容器绑定转换：{error}"))
    })
}

fn save_local_dida_parent(
    path: &PathBuf,
    library_id: &str,
    task_id: &str,
    parent_id: Option<&str>,
) -> Result<(), String> {
    let (connection, _writer) = open_write_database(path)?;
    task_sync_library_commit(|| {
        connection
            .execute(
                "UPDATE dida_tasks SET parent_id=?3 WHERE library_id=?1 AND task_id=?2",
                params![library_id, task_id, parent_id],
            )
            .map_err(|error| format!("无法保存滴答任务父级变化：{error}"))?;
        Ok(())
    })
}

fn record_task_sync_conflict(
    path: &PathBuf,
    hub_task_id: &str,
    craft_hash: &str,
    dida_hash: &str,
) -> Result<(), String> {
    let (connection, _writer) = open_write_database(path)?;
    task_sync_library_commit(|| {
        let now = now_timestamp();
        let key = format!("conflict:{hub_task_id}");
        connection
            .execute(
                "UPDATE task_sync_events SET status='resolved',updated_at=?2
             WHERE hub_task_id=?1 AND action='conflict' AND status='review'",
                params![hub_task_id, now],
            )
            .map_err(|error| format!("无法合并任务同步冲突：{error}"))?;
        connection
            .execute(
                "INSERT INTO task_sync_events
               (hub_task_id,origin_provider,target_provider,action,status,payload_json,
                idempotency_key,attempts,created_at,updated_at,last_error)
             VALUES (?1,'craft','dida365','conflict','review',?2,?3,0,?4,?4,
                     '两端在上次同步后均发生不同修改')
             ON CONFLICT(idempotency_key) DO UPDATE SET
               status='review',payload_json=excluded.payload_json,
               attempts=0,created_at=excluded.created_at,
               updated_at=excluded.updated_at,last_error=excluded.last_error",
                params![
                    hub_task_id,
                    json!({"craftHash": craft_hash, "didaHash": dida_hash}).to_string(),
                    key,
                    now
                ],
            )
            .map_err(|error| format!("无法记录任务同步冲突：{error}"))?;
        Ok(())
    })
}

fn record_task_sync_identity_conflict(
    path: &PathBuf,
    hub_task_id: &str,
    title: &str,
    bound_source_id: &str,
    managed_source_id: &str,
) -> Result<bool, String> {
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始保存任务身份冲突：{error}"))?;
    let key = format!("conflict:{hub_task_id}");
    let already_pending = transaction
        .query_row(
            "SELECT EXISTS(SELECT 1 FROM task_sync_events
             WHERE idempotency_key=?1 AND action='conflict'
               AND status IN ('review','pending','failed'))",
            [&key],
            |row| row.get::<_, i64>(0),
        )
        .map_err(|error| format!("无法检查任务身份冲突：{error}"))?
        != 0;
    let now = now_timestamp();
    let message = format!(
        "滴答任务记录的 Craft 来源为 {managed_source_id}，但当前绑定为 {bound_source_id}；已暂停自动写入和删除，请选择保留来源"
    );
    transaction
        .execute(
            "INSERT INTO task_sync_events
               (hub_task_id,origin_provider,target_provider,action,status,payload_json,
                idempotency_key,attempts,created_at,updated_at,last_error)
             VALUES (?1,'craft','dida365','conflict','review',?2,?3,0,?4,?4,?5)
             ON CONFLICT(idempotency_key) DO UPDATE SET
               status='review',payload_json=excluded.payload_json,attempts=0,
               updated_at=excluded.updated_at,last_error=excluded.last_error",
            params![
                hub_task_id,
                json!({
                    "conflictType": "identity",
                    "title": title,
                    "boundCraftSourceId": bound_source_id,
                    "managedCraftSourceId": managed_source_id
                })
                .to_string(),
                key,
                now,
                message
            ],
        )
        .map_err(|error| format!("无法记录任务身份冲突：{error}"))?;
    task_sync_library_commit(|| {
        transaction
            .commit()
            .map_err(|error| format!("无法提交任务身份冲突：{error}"))
    })?;
    Ok(!already_pending)
}

