fn reconcile_pending_task_conflicts(path: &PathBuf) -> Result<(), String> {
    let (connection, _writer) = open_write_database(path)?;
    task_sync_library_commit(|| {
        let now = now_timestamp();
        // A Dida task can be deleted remotely before the normal pair cleanup gets
        // a chance to remove its conflict event. Do not keep showing a retry banner
        // for an event whose Dida binding is already gone.
        connection
            .execute(
                "UPDATE task_sync_events
             SET status='resolved',updated_at=?1,last_error=NULL
             WHERE action='conflict' AND status IN ('pending','failed')
               AND NOT EXISTS(
                 SELECT 1 FROM unified_task_bindings binding
                 WHERE binding.hub_task_id=task_sync_events.hub_task_id
                   AND binding.provider='dida365'
               )
             OR (action='conflict' AND status IN ('pending','failed')
               AND EXISTS(
                 SELECT 1 FROM unified_task_bindings binding
                 WHERE binding.hub_task_id=task_sync_events.hub_task_id
                   AND binding.provider='dida365'
                   AND NOT EXISTS(
                     SELECT 1 FROM dida_tasks task
                     WHERE task.library_id=binding.library_id
                       AND task.task_id=binding.source_id
                   )
               ))",
                [now],
            )
            .map_err(|error| format!("无法清理已删除滴答任务的冲突提示：{error}"))?;
        connection
            .execute(
                "UPDATE task_sync_events
             SET status='resolved',updated_at=?1,last_error=NULL
             WHERE action='conflict' AND status='review'
               AND NOT EXISTS(
                 SELECT 1 FROM task_sync_snapshots marker
                 WHERE marker.hub_task_id=task_sync_events.hub_task_id
                   AND (marker.source_hash LIKE 'force-conflict-resolution:%'
                        OR marker.source_hash LIKE 'merge-request:%'
                        OR marker.source_hash LIKE 'identity-link-repair:%')
               )
               AND 2=(
                 SELECT COUNT(DISTINCT refreshed.provider)
                 FROM task_sync_snapshots refreshed
                 WHERE refreshed.hub_task_id=task_sync_events.hub_task_id
                   AND refreshed.provider IN ('craft','dida365')
                   AND refreshed.synced_at>task_sync_events.created_at
               )",
                [now],
            )
            .map_err(|error| format!("无法关闭远端回读后已过期的冲突：{error}"))?;
        connection
            .execute(
                "UPDATE task_sync_events
             SET status=CASE WHEN EXISTS(
                   SELECT 1 FROM task_sync_snapshots s
                   WHERE s.hub_task_id=task_sync_events.hub_task_id
                     AND (s.source_hash LIKE 'force-conflict-resolution:%'
                          OR s.source_hash LIKE 'merge-request:%'
                          OR s.source_hash LIKE 'identity-link-repair:%')
                 ) THEN 'failed' ELSE 'resolved' END,
                 updated_at=?1,
                 last_error=CASE WHEN EXISTS(
                   SELECT 1 FROM task_sync_snapshots s
                   WHERE s.hub_task_id=task_sync_events.hub_task_id
                     AND (s.source_hash LIKE 'force-conflict-resolution:%'
                          OR s.source_hash LIKE 'merge-request:%'
                          OR s.source_hash LIKE 'identity-link-repair:%')
                 ) THEN '所选冲突规则尚未成功写入两端；可以点击重试同步' ELSE NULL END
             WHERE action='conflict' AND status IN ('pending','failed')",
                [now],
            )
            .map_err(|error| format!("无法更新冲突执行状态：{error}"))?;
        Ok(())
    })
}

fn dismiss_pending_task_conflicts(path: &PathBuf, event_ids: &[i64]) -> Result<usize, String> {
    if event_ids.is_empty() {
        return Ok(0);
    }
    let (mut connection, _writer) = open_write_database(path)?;
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始清理冲突重试提示：{error}"))?;
    let now = now_timestamp();
    let mut dismissed = 0usize;
    for event_id in event_ids {
        let hub_task_id = transaction
            .query_row(
                "SELECT hub_task_id FROM task_sync_events
                 WHERE id=?1 AND action='conflict' AND status IN ('pending','failed')",
                [event_id],
                |row| row.get::<_, String>(0),
            )
            .optional()
            .map_err(|error| format!("无法读取待清理的冲突提示：{error}"))?;
        let Some(hub_task_id) = hub_task_id else {
            continue;
        };
        // A pending conflict stores a forced marker in both provider snapshots.
        // Replacing it with the last applied binding hash acknowledges the
        // current state without deleting either task or retrying a stale write.
        transaction
            .execute(
                "UPDATE task_sync_snapshots
                 SET source_hash=COALESCE((
                       SELECT binding.source_hash FROM unified_task_bindings binding
                       WHERE binding.hub_task_id=task_sync_snapshots.hub_task_id
                         AND binding.provider=task_sync_snapshots.provider
                     ),source_hash),
                     applied_hash=COALESCE((
                       SELECT binding.source_hash FROM unified_task_bindings binding
                       WHERE binding.hub_task_id=task_sync_snapshots.hub_task_id
                         AND binding.provider=task_sync_snapshots.provider
                     ),applied_hash),
                     source_modified_at=NULL,synced_at=?2
                 WHERE hub_task_id=?1
                   AND (source_hash LIKE 'force-conflict-resolution:%'
                        OR source_hash LIKE 'merge-request:%'
                        OR source_hash LIKE 'identity-link-repair:%')",
                params![hub_task_id, now],
            )
            .map_err(|error| format!("无法撤销冲突重试标记：{error}"))?;
        dismissed += transaction
            .execute(
                "UPDATE task_sync_events
                 SET status='resolved',updated_at=?2,last_error=NULL
                 WHERE id=?1 AND action='conflict' AND status IN ('pending','failed')",
                params![event_id, now],
            )
            .map_err(|error| format!("无法清除冲突重试提示：{error}"))?;
    }
    task_sync_library_commit(|| {
        transaction
            .commit()
            .map_err(|error| format!("无法提交冲突提示清理结果：{error}"))
    })?;
    Ok(dismissed)
}

