fn craft_page_title(
    path: &PathBuf,
    library_id: &str,
    document_id: &str,
    page_id: &str,
) -> Result<Option<String>, String> {
    let connection = open_database(path)?;
    let structured = connection
        .query_row(
            "SELECT page_title FROM content_items
             WHERE provider='craft' AND space_id=?1 AND document_id=?2 AND page_id=?3
               AND length(trim(page_title))>0
             ORDER BY ordinal LIMIT 1",
            params![library_id, document_id, page_id],
            |row| row.get(0),
        )
        .optional()
        .map_err(|error| format!("无法检查 Craft 结构化项目页面：{error}"))?;
    if structured.is_some() {
        return Ok(structured);
    }
    if page_id != document_id {
        return Ok(None);
    }
    connection
        .query_row(
            "SELECT title FROM documents WHERE provider='craft' AND space_id=?1 AND id=?2",
            params![library_id, document_id],
            |row| row.get(0),
        )
        .optional()
        .map_err(|error| format!("无法检查 Craft 根项目页面：{error}"))
}

fn mark_task_sync_missing(
    path: &PathBuf,
    hub_task_id: &str,
    provider: &str,
    source_id: &str,
) -> Result<i64, String> {
    let (connection, _writer) = open_write_database(path)?;
    task_sync_library_commit(|| {
        let now = now_timestamp();
        connection
            .execute(
                "INSERT INTO task_sync_tombstones
               (hub_task_id,provider,source_id,first_missing_at,missing_syncs,confirmed_at)
             VALUES (?1,?2,?3,?4,1,NULL)
             ON CONFLICT(provider,source_id) DO UPDATE SET
               missing_syncs=task_sync_tombstones.missing_syncs+1,
               confirmed_at=CASE WHEN task_sync_tombstones.missing_syncs+1>=2
                                 THEN excluded.first_missing_at ELSE NULL END",
                params![hub_task_id, provider, source_id, now],
            )
            .map_err(|error| format!("无法记录任务删除候选：{error}"))?;
        connection
            .query_row(
                "SELECT missing_syncs FROM task_sync_tombstones WHERE provider=?1 AND source_id=?2",
                params![provider, source_id],
                |row| row.get(0),
            )
            .map_err(|error| format!("无法读取任务删除确认次数：{error}"))
    })
}

