fn normalized_task_sync_source_id(source_id: &str) -> String {
    source_id.trim().to_lowercase()
}

fn load_task_sync_exclusions(path: &PathBuf) -> Result<HashSet<(String, String, String)>, String> {
    let connection = open_database(path)?;
    let mut statement = connection
        .prepare("SELECT provider,library_id,source_id FROM task_sync_exclusions")
        .map_err(|error| format!("无法准备任务同步排除查询：{error}"))?;
    let rows = statement
        .query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                normalized_task_sync_source_id(&row.get::<_, String>(2)?),
            ))
        })
        .map_err(|error| format!("无法读取任务同步排除记录：{error}"))?;
    rows.collect::<Result<HashSet<_>, _>>()
        .map_err(|error| format!("无法收集任务同步排除记录：{error}"))
}

