#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct CreateJournalOutcome {
    library_id: String,
    library_name: String,
    provider: String,
    action: String,
}

#[tauri::command]
async fn create_journals(
    app: AppHandle,
    date: String,
    library_ids: Vec<String>,
    state: State<'_, AppState>,
) -> Result<Vec<CreateJournalOutcome>, String> {
    let parsed_date = chrono::NaiveDate::parse_from_str(date.trim(), "%Y-%m-%d")
        .map_err(|_| "日志日期格式无效，应为 YYYY-MM-DD".to_string())?;
    if library_ids.is_empty() {
        return Err("请至少选择一个资料库".to_string());
    }
    let database = database_path(&app)?;
    let requested = library_ids.clone();
    let libraries = tokio::task::spawn_blocking(move || {
        let connection = open_database(&database)?;
        let ids = serde_json::to_string(&requested)
            .map_err(|error| format!("资料库选择无效：{error}"))?;
        let mut statement = connection
            .prepare(
                "SELECT id,provider,name,location FROM libraries
             WHERE enabled=1 AND id IN (SELECT value FROM json_each(?1))",
            )
            .map_err(|error| format!("无法读取资料库：{error}"))?;
        let rows = statement
            .query_map([ids], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, Option<String>>(3)?,
                ))
            })
            .map_err(|error| format!("无法查询资料库：{error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法读取资料库：{error}"))
    })
    .await
    .map_err(|error| format!("创建日志任务失败：{error}"))??;

    let mut outcomes = Vec::new();
    for (library_id, provider, library_name, location) in libraries {
        match provider.as_str() {
            PROVIDER_OBSIDIAN => {
                let root =
                    PathBuf::from(location.ok_or_else(|| format!("{library_name} 缺少本地路径"))?);
                let relative = PathBuf::from("Journals")
                    .join(format!("{}.md", parsed_date.format("%Y-%m-%d")));
                let absolute = root.join(&relative);
                if let Some(parent) = absolute.parent() {
                    fs::create_dir_all(parent).map_err(|error| {
                        format!("无法创建 {} 的 Journals 目录：{error}", library_name)
                    })?;
                }
                let action = if absolute.exists() {
                    "opened".to_string()
                } else {
                    fs::write(
                        &absolute,
                        format!("# {}\n\n", parsed_date.format("%Y-%m-%d")),
                    )
                    .map_err(|error| format!("无法在 {library_name} 创建日志：{error}"))?;
                    "created".to_string()
                };
                let relative_text = relative.to_string_lossy().replace('\\', "/");
                open_external(
                    &app,
                    &obsidian_open_url(&obsidian_vault_name(&root), &relative_text)?,
                )?;
                outcomes.push(CreateJournalOutcome {
                    library_id,
                    library_name,
                    provider,
                    action,
                });
            }
            PROVIDER_CRAFT => {
                let session = session_for_space(&state, &library_id)?;
                let client = reqwest::Client::new();
                let tools = craft_tool_names(&client, &session, 30_001).await?;
                if !tools.contains("craft_write") {
                    return Err(format!(
                        "{library_name} 的 MCP 连接没有写入权限。请在 Craft 的 Imagine/MCP 设置中启用写入权限后重新连接。"
                    ));
                }
                let title = parsed_date.format("%Y.%m.%d").to_string();
                let command = format!("documents create --title \"{title}\"");
                let result = call_craft_tool_raw(
                    &client,
                    &session,
                    "craft_write",
                    json!({ "command": command }),
                    30_002,
                )
                .await?;
                let payload = tool_result_json(&result);
                let document_id = find_created_craft_id(&payload)
                    .or_else(|| find_created_craft_id(&result))
                    .ok_or_else(|| format!(
                    "{library_name} 已返回创建成功，但没有提供新文档 ID，无法打开对应位置。MCP 返回：{}",
                    tool_result_text(&result)
                ))?;
                open_external(&app, &craft_deep_link(&library_id, &document_id, &state)?)?;
                outcomes.push(CreateJournalOutcome {
                    library_id,
                    library_name,
                    provider,
                    action: "created".to_string(),
                });
            }
            _ => return Err(format!("{library_name} 暂不支持新建日志")),
        }
    }
    Ok(outcomes)
}

#[tauri::command]
fn local_document(
    app: AppHandle,
    space_id: String,
    document_id: String,
    page_id: Option<String>,
    result_id: Option<String>,
    state: State<'_, AppState>,
) -> Result<String, String> {
    let path = database_path(&app)?;
    let connection = open_database(&path)?;
    if hidden_library_ids(&path, &connection)?.contains(&space_id) {
        return Err("资料库已移除或停用".into());
    }
    let (markdown, blob_hash, provider): (String, Option<String>, String) = connection
        .query_row(
            "SELECT markdown, blob_hash, provider FROM documents
             WHERE space_id = ?1 AND id = ?2 LIMIT 1",
            params![space_id, document_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .map_err(|error| format!("无法读取本地文档：{error}"))?;
    let indexed_page_id = result_id.as_deref().and_then(|result_id| {
        connection
            .query_row(
                "SELECT NULLIF(page_id, '') FROM content_items
             WHERE id=?1 AND space_id=?2 AND document_id=?3 LIMIT 1",
                params![result_id, space_id, document_id],
                |row| row.get::<_, Option<String>>(0),
            )
            .ok()
            .flatten()
    });
    if !markdown.is_empty() {
        if provider != PROVIDER_CRAFT {
            return Ok(markdown);
        }
        let requested_page_id = indexed_page_id
            .as_deref()
            .or(page_id.as_deref())
            .unwrap_or(&document_id);
        return Ok(craft_page_preview(
            &markdown,
            &document_id,
            requested_page_id,
        ));
    }
    let hash = blob_hash.ok_or_else(|| "本地文档没有可用正文".to_string())?;
    String::from_utf8(blob_store_for(&app, &state)?.read(&hash)?)
        .map_err(|error| format!("Blob 正文不是有效 UTF-8：{error}"))
}

#[tauri::command]
async fn local_ocr_image_preview(
    app: AppHandle,
    result_id: String,
    state: State<'_, AppState>,
) -> Result<OcrImagePreview, String> {
    let path = database_path(&app)?;
    let blob_store = blob_store_for(&app, &state)?;
    tokio::task::spawn_blocking(move || {
        let connection = open_database(&path)?;
        let (mime_type, blob_hash, ocr_text): (String, String, String) = connection
            .query_row(
                "SELECT COALESCE(s.mime_type, 'image/png'), s.blob_hash, ci.body
                 FROM content_items ci
                 JOIN source_items s ON s.id=ci.source_item_id
                 WHERE ci.id=?1 AND ci.content_type='image_ocr' AND s.blob_hash IS NOT NULL",
                params![result_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .map_err(|error| format!("无法读取图片 OCR 预览：{error}"))?;
        if !mime_type.starts_with("image/") {
            return Err("OCR 预览来源不是图片".to_string());
        }
        let bytes = blob_store.read(&blob_hash)?;
        const MAX_INLINE_PREVIEW_BYTES: usize = 25 * 1024 * 1024;
        let (image_data_url, note) = if bytes.len() <= MAX_INLINE_PREVIEW_BYTES {
            (
                Some(format!(
                    "data:{mime_type};base64,{}",
                    base64::engine::general_purpose::STANDARD.encode(bytes)
                )),
                None,
            )
        } else {
            (
                None,
                Some("原图超过 25 MB，为避免预览占用过多内存，已只显示 OCR 文字。".to_string()),
            )
        };
        Ok(OcrImagePreview {
            image_data_url,
            ocr_text,
            note,
        })
    })
    .await
    .map_err(|error| format!("图片 OCR 预览任务失败：{error}"))?
}

fn media_protocol_url(hash: &str) -> String {
    #[cfg(any(target_os = "windows", target_os = "android"))]
    {
        format!("http://craft-media.localhost/{hash}")
    }
    #[cfg(not(any(target_os = "windows", target_os = "android")))]
    {
        format!("craft-media://localhost/{hash}")
    }
}

fn inline_preview_image(
    bytes: Vec<u8>,
    declared_mime: &str,
) -> Result<MarkdownMediaPreview, String> {
    const MAX_INLINE_PREVIEW_BYTES: usize = 25 * 1024 * 1024;
    if bytes.len() > MAX_INLINE_PREVIEW_BYTES {
        return Err("图片超过 25 MB，无法嵌入预览".to_string());
    }
    let detected_mime = infer::get(&bytes).map(|kind| kind.mime_type());
    let mime_type = detected_mime
        .or_else(|| declared_mime.starts_with("image/").then_some(declared_mime))
        .ok_or_else(|| "预览资源不是受支持的图片".to_string())?;
    Ok(MarkdownMediaPreview {
        source: format!(
            "data:{mime_type};base64,{}",
            base64::engine::general_purpose::STANDARD.encode(bytes)
        ),
        mime_type: mime_type.to_string(),
        media_type: "image".to_string(),
    })
}

fn preview_media_from_blob(
    blob_store: &BlobStore,
    hash: &str,
    declared_mime: &str,
) -> Result<MarkdownMediaPreview, String> {
    if declared_mime.starts_with("video/") {
        return Ok(MarkdownMediaPreview {
            source: media_protocol_url(hash),
            mime_type: declared_mime.to_string(),
            media_type: "video".to_string(),
        });
    }
    let bytes = blob_store.read(hash)?;
    if infer::get(&bytes).is_some_and(|kind| kind.mime_type().starts_with("video/")) {
        let mime_type = infer::get(&bytes)
            .map(|kind| kind.mime_type())
            .unwrap_or("video/mp4");
        return Ok(MarkdownMediaPreview {
            source: media_protocol_url(hash),
            mime_type: mime_type.to_string(),
            media_type: "video".to_string(),
        });
    }
    inline_preview_image(bytes, declared_mime)
}

fn preview_media_from_bytes(
    blob_store: &BlobStore,
    bytes: Vec<u8>,
    declared_mime: &str,
) -> Result<MarkdownMediaPreview, String> {
    let detected_mime = infer::get(&bytes).map(|kind| kind.mime_type());
    let mime_type = detected_mime.unwrap_or(declared_mime);
    if mime_type.starts_with("video/") {
        let blob = blob_store.put(&bytes)?;
        return Ok(MarkdownMediaPreview {
            source: media_protocol_url(&blob.hash),
            mime_type: mime_type.to_string(),
            media_type: "video".to_string(),
        });
    }
    inline_preview_image(bytes, mime_type)
}

#[derive(Clone)]
struct PreviewDownloadCapture {
    database: PathBuf,
    source_id: String,
    space_id: String,
    document_id: String,
    provider: String,
    title: String,
    mime_type: String,
    metadata: String,
    blob_hash: Option<String>,
}

impl PreviewDownloadCapture {
    fn generation(&self) -> u64 {
        attachment_download_cache::resource_generation(&self.metadata)
    }

    fn matches_metadata(&self, current: &str) -> bool {
        let Ok(old) = serde_json::from_str::<Value>(&self.metadata) else {
            return false;
        };
        let Ok(new) = serde_json::from_str::<Value>(current) else {
            return false;
        };
        let revision = |value: &Value| {
            value
                .get("resourceRevision")
                .and_then(Value::as_str)
                .filter(|revision| !revision.trim().is_empty())
                .map(str::to_owned)
        };
        let size = |value: &Value| value.get("size").and_then(Value::as_u64);
        let revision_changed = match (revision(&old), revision(&new)) {
            (Some(previous), Some(current)) => previous != current,
            _ => false,
        };
        let size_changed = match (size(&old), size(&new)) {
            (Some(previous), Some(current)) => previous != current,
            _ => false,
        };
        self.generation() == attachment_download_cache::resource_generation(current)
            && (self.provider != PROVIDER_DIDA365 || old.get("remoteUrl") == new.get("remoteUrl"))
            && !revision_changed
            && !size_changed
    }

    fn current_metadata(&self, connection: &Connection) -> Result<Option<String>, String> {
        Ok(connection
            .query_row(
                "SELECT s.metadata_json FROM source_items s
             JOIN libraries l ON l.id=s.space_id AND l.enabled=1 AND l.provider=s.provider
             JOIN documents d ON d.space_id=s.space_id AND d.id=s.document_id
             WHERE s.id=?1 AND s.space_id=?2 AND s.document_id=?3 AND s.provider=?4
               AND s.source_type IN ('craft_attachment','dida_attachment')",
                params![
                    self.source_id,
                    self.space_id,
                    self.document_id,
                    self.provider
                ],
                |row| row.get(0),
            )
            .optional()
            .map_err(|error| format!("无法核对预览附件版本：{error}"))?
            .flatten())
    }
}

impl attachment_download_cache::DownloadCheckpoint for PreviewDownloadCapture {
    fn checkpoint(&self) -> Result<(), String> {
        let connection = open_database(&self.database)?;
        let Some(current) = self.current_metadata(&connection)? else {
            return Err("CONTENT_POLICY:附件已更新或移除，请重新打开预览".into());
        };
        if !self.matches_metadata(&current) {
            return Err("CONTENT_POLICY:附件已更新或移除，请重新打开预览".into());
        }
        attachment_download_failures::require_transfer(&connection, &self.source_id, &current)
    }
}

fn read_preview_download_capture(
    path: &PathBuf,
    provider: &str,
    space_id: &str,
    document_id: &str,
    source: &str,
    stable_id: Option<&str>,
) -> Result<PreviewDownloadCapture, String> {
    let attachment_id = if provider == PROVIDER_DIDA365 {
        Some(
            parse_dida_attachment_source(source)
                .ok_or("这不是可识别的滴答附件地址")?
                .attachment_id,
        )
    } else {
        None
    };
    let connection = open_database(path)?;
    let capture_row = |row: &Row<'_>| {
        Ok(PreviewDownloadCapture {
            database: path.clone(),
            source_id: row.get(0)?,
            space_id: space_id.into(),
            document_id: document_id.into(),
            provider: provider.into(),
            title: row.get(1)?,
            mime_type: row.get(2)?,
            metadata: row.get(3)?,
            blob_hash: row.get(4)?,
        })
    };
    let captured = connection.query_row(
        "SELECT s.id,s.title,COALESCE(s.mime_type,''),COALESCE(s.metadata_json,'{}'),s.blob_hash
         FROM source_items s JOIN libraries l ON l.id=s.space_id AND l.enabled=1 AND l.provider=s.provider
         JOIN documents d ON d.space_id=s.space_id AND d.id=s.document_id
         WHERE s.space_id=?1 AND s.document_id=?2 AND s.provider=?3
           AND s.source_type IN ('craft_attachment','dida_attachment')
           AND ((?4 IS NOT NULL AND s.id=?4) OR (?4 IS NULL AND
             ((s.source_type='craft_attachment' AND json_extract(s.metadata_json,'$.remoteUrl')=?5)
              OR (s.source_type='dida_attachment' AND s.remote_id=?6))))
         ORDER BY (s.blob_hash IS NOT NULL) DESC,s.id LIMIT 1",
        params![space_id,document_id,provider,stable_id,source,attachment_id],
        &capture_row,
    ).optional().map_err(|error| format!("无法读取预览附件：{error}"))?;
    if let Some(captured) = captured {
        return Ok(captured);
    }
    if provider == PROVIDER_CRAFT && stable_id.is_none() {
        let locator = craft_attachment_resource_locator(source);
        let mut statement = connection.prepare(
            "SELECT s.id,s.title,COALESCE(s.mime_type,''),COALESCE(s.metadata_json,'{}'),s.blob_hash
             FROM source_items s JOIN libraries l ON l.id=s.space_id AND l.enabled=1 AND l.provider=s.provider
             JOIN documents d ON d.space_id=s.space_id AND d.id=s.document_id
             WHERE s.space_id=?1 AND s.document_id=?2 AND s.provider='craft' AND s.source_type='craft_attachment'",
        ).map_err(|error|format!("无法准备当前 Craft 附件匹配：{error}"))?;
        let rows = statement
            .query_map(params![space_id, document_id], capture_row)
            .map_err(|error| format!("无法读取当前 Craft 附件匹配：{error}"))?;
        let mut matched = None;
        for row in rows {
            let candidate = row.map_err(|error| format!("无法读取当前 Craft 附件：{error}"))?;
            let same_locator = serde_json::from_str::<Value>(&candidate.metadata)
                .ok()
                .and_then(|value| {
                    value
                        .get("remoteUrl")
                        .and_then(Value::as_str)
                        .map(str::to_owned)
                })
                .is_some_and(|url| craft_attachment_resource_locator(&url) == locator);
            if !same_locator {
                continue;
            }
            if matched.is_some() {
                return Err("此地址对应多个附件，无法确定要预览的来源，请重新同步文档".into());
            }
            matched = Some(candidate);
        }
        if let Some(captured) = matched {
            return Ok(captured);
        }
    }
    Err("尚未索引此附件，请等待同步完成".into())
}

async fn acquire_preview_download_capture(
    path: &PathBuf,
    provider: &str,
    space_id: &str,
    document_id: &str,
    source: &str,
) -> Result<
    (
        PreviewDownloadCapture,
        attachment_resource_cache::SourceLease,
        attachment_resource_cache::ResourceLease,
    ),
    String,
> {
    let first = read_preview_download_capture(path, provider, space_id, document_id, source, None)?;
    let source_lease =
        attachment_resource_cache::acquire_source(path, space_id, provider, &first.source_id)
            .await?;
    for _ in 0..3 {
        let next = read_preview_download_capture(
            path,
            provider,
            space_id,
            document_id,
            source,
            Some(&first.source_id),
        )?;
        let lease =
            attachment_resource_cache::acquire(path, space_id, provider, &next.metadata).await?;
        let current = read_preview_download_capture(
            path,
            provider,
            space_id,
            document_id,
            source,
            Some(&first.source_id),
        )?;
        if lease.matches_metadata(space_id, provider, &current.metadata)? {
            return Ok((current, source_lease, lease));
        }
    }
    Err("CONTENT_POLICY:附件正在更新，请稍后重新打开预览".into())
}

fn verified_preview_source(
    capture: &PreviewDownloadCapture,
    store: &BlobStore,
) -> Result<Option<DownloadedSource>, String> {
    let Some(hash) = capture.blob_hash.as_deref() else {
        return Ok(None);
    };
    if capture.provider == PROVIDER_CRAFT {
        let cached_generation = serde_json::from_str::<Value>(&capture.metadata)
            .ok()
            .and_then(|value| {
                value
                    .get("cachedResourceGeneration")
                    .and_then(Value::as_u64)
            });
        if cached_generation.map_or(capture.generation() != 0, |generation| {
            generation != capture.generation()
        }) {
            return Ok(None);
        }
    }
    let descriptor: Option<(u64, String)> = open_database(&capture.database)?
        .query_row(
            "SELECT size,COALESCE(NULLIF(mime_type,''),?2) FROM blobs WHERE hash=?1",
            params![hash, capture.mime_type],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()
        .map_err(|error| format!("无法核对预览缓存：{error}"))?;
    let Some((size, mime)) = descriptor else {
        return Ok(None);
    };
    let expected = serde_json::from_str::<Value>(&capture.metadata)
        .ok()
        .and_then(|value| value.get("size").and_then(Value::as_u64));
    if expected.is_some_and(|expected| expected != size) {
        return Ok(None);
    }
    attachment_resource_cache::verified_blob(store, hash, size, &mime, None)
}

fn persist_preview_media_download(
    path: &PathBuf,
    capture: &PreviewDownloadCapture,
    _lease: &attachment_resource_cache::ResourceLease,
    downloaded: &DownloadedSource,
) -> Result<(), String> {
    let (mut connection, _writer) = open_write_database(path)?;
    let current = capture
        .current_metadata(&connection)?
        .ok_or("CONTENT_POLICY:附件已移除，预览结果已让出")?;
    if !capture.matches_metadata(&current) {
        return Err("CONTENT_POLICY:附件已更新，旧预览结果已让出".into());
    }
    let expected_size = serde_json::from_str::<Value>(&current)
        .ok()
        .and_then(|value| value.get("size").and_then(Value::as_u64));
    if expected_size.is_some_and(|size| size != downloaded.blob.size) {
        return Err("附件下载长度与资源元数据不一致，请稍后再试".into());
    }
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始媒体缓存事务：{error}"))?;
    let timestamp = now_timestamp();
    transaction
        .execute(
            "INSERT INTO blobs (hash,size,mime_type,relative_path,created_at,verified_at)
             VALUES (?1,?2,?3,?4,?5,?5)
             ON CONFLICT(hash) DO UPDATE SET
               mime_type=excluded.mime_type,verified_at=excluded.verified_at",
            params![
                downloaded.blob.hash,
                downloaded.blob.size as i64,
                downloaded.mime_type,
                downloaded.blob.relative_path,
                timestamp
            ],
        )
        .map_err(|error| format!("无法记录媒体缓存：{error}"))?;
    transaction
        .execute(
            "UPDATE source_items
             SET status=CASE WHEN blob_hash=?1 AND status IN ('indexed','stored','needs_ocr','ready') THEN status ELSE ?6 END,
                 blob_hash=?1,content_hash=?1,mime_type=?2,updated_at=?3,
                 metadata_json=json_set(metadata_json,'$.cachedResourceGeneration',?5)
             WHERE id=?4",
            params![
                downloaded.blob.hash,
                downloaded.mime_type,
                timestamp,
                capture.source_id,
                capture.generation(),
                if downloaded.mime_type.starts_with("image/") || downloaded.mime_type == "application/pdf" { "ready" } else { "stored" },
            ],
        )
        .map_err(|error| format!("无法关联媒体缓存：{error}"))?;
    // An explicit open can cache a file while automatic downloads are disabled.
    // Ordinary files have no extraction stage. Finish the same durable download
    // here, without stealing an in-flight worker; images/PDFs keep their pipeline.
    if !downloaded.mime_type.starts_with("image/") && downloaded.mime_type != "application/pdf" {
        transaction.execute("UPDATE index_jobs SET status='completed',updated_at=?1,last_error=NULL,next_attempt_at=0,worker_id=NULL,locked_at=NULL,lease_until=NULL
            WHERE source_id=?2 AND job_type='download_source' AND status IN ('pending','failed')",
            params![timestamp,capture.source_id]).map_err(|error|format!("无法结束已缓存的附件下载任务：{error}"))?;
    } else {
        // Verified bytes have repaired the transfer, including a former terminal
        // URL failure. Resume the existing local pipeline without reopening a
        // successful job or changing a running worker/user skip decision.
        transaction.execute("UPDATE index_jobs SET status='pending',attempts=0,updated_at=?1,last_error=NULL,next_attempt_at=0,
              worker_id=NULL,locked_at=NULL,lease_until=NULL
            WHERE source_id=?2 AND job_type='download_source' AND status IN ('pending','failed','completed','done')
              AND NULLIF(last_error,'') IS NOT NULL",
            params![timestamp,capture.source_id]).map_err(|error|format!("无法恢复已缓存附件的本地处理任务：{error}"))?;
    }
    transaction
        .commit()
        .map_err(|error| format!("无法提交媒体缓存：{error}"))
}

async fn load_preview_attachment<F>(
    path: &PathBuf,
    store: &BlobStore,
    provider: &str,
    space_id: &str,
    document_id: &str,
    source: &str,
    client: &reqwest::Client,
    cookies: F,
    allow_video: bool,
) -> Result<(DownloadedSource, String), String>
where
    F: FnOnce() -> Result<Option<String>, String> + Send,
{
    load_preview_attachment_resolving(
        path,
        store,
        provider,
        space_id,
        document_id,
        source,
        client,
        cookies,
        allow_video,
        |capture| attachment_url_from_metadata(&capture.metadata, &capture.provider),
    )
    .await
}

async fn load_preview_attachment_resolving<F, R>(
    path: &PathBuf,
    store: &BlobStore,
    provider: &str,
    space_id: &str,
    document_id: &str,
    source: &str,
    client: &reqwest::Client,
    cookies: F,
    allow_video: bool,
    resolve_url: R,
) -> Result<(DownloadedSource, String), String>
where
    F: FnOnce() -> Result<Option<String>, String> + Send,
    R: FnOnce(&PreviewDownloadCapture) -> Result<Url, String> + Send,
{
    load_cached_attachment_resolving(
        path,
        store,
        provider,
        space_id,
        document_id,
        source,
        client,
        cookies,
        allow_video,
        resolve_url,
        MAX_ATTACHMENT_BYTES,
    )
    .await
}

async fn load_cached_attachment_resolving<F, R>(
    path: &PathBuf,
    store: &BlobStore,
    provider: &str,
    space_id: &str,
    document_id: &str,
    source: &str,
    client: &reqwest::Client,
    cookies: F,
    allow_video: bool,
    resolve_url: R,
    maximum: u64,
) -> Result<(DownloadedSource, String), String>
where
    F: FnOnce() -> Result<Option<String>, String> + Send,
    R: FnOnce(&PreviewDownloadCapture) -> Result<Url, String> + Send,
{
    let (capture, _source_lease, lease) =
        acquire_preview_download_capture(path, provider, space_id, document_id, source).await?;
    let is_video = capture.mime_type.starts_with("video/")
        || preview_mime_from_name(&capture.title).starts_with("video/")
        || serde_json::from_str::<Value>(&capture.metadata)
            .ok()
            .is_some_and(|value| value.get("linkKind").and_then(Value::as_str) == Some("video"));
    if is_video && !allow_video {
        return Err("VIDEO_REQUIRES_ACTIVATION".into());
    }
    let cached = verified_preview_source(&capture, store)?;
    let cached = if cached.is_some() {
        cached
    } else {
        attachment_resource_cache::verified_resource(
            path,
            store,
            space_id,
            provider,
            &capture.metadata,
            None,
        )?
    };
    let downloaded = match cached {
        Some(cached) => cached,
        None => {
            let result = async {
                attachment_download_failures::require_preview_transfer(&capture)?;
                let url = resolve_url(&capture)?;
                let cookie_header = cookies()?;
                let operation = library_runtime::begin(
                    path.parent().ok_or("资料库路径不可用")?,
                    space_id,
                    "预览附件",
                )?;
                download_source_to_blob_with_limit(
                    client,
                    store,
                    url,
                    cookie_header.as_deref(),
                    Some(&operation),
                    Some(&capture),
                    maximum,
                )
                .await
            }
            .await;
            match result {
                Ok(downloaded) => downloaded,
                Err(error) => {
                    attachment_download_failures::record_preview_failure(&capture, &error)?;
                    return Err(attachment_download_failures::public_error(&error));
                }
            }
        }
    };
    if let Err(error) = persist_preview_media_download(path, &capture, &lease, &downloaded) {
        attachment_download_failures::record_preview_failure(&capture, &error)?;
        return Err(attachment_download_failures::public_error(&error));
    }
    Ok((downloaded, capture.title))
}

fn preview_mime_from_name(name: &str) -> String {
    let extension = Path::new(name)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    match extension.as_str() {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "svg" => "image/svg+xml",
        "mp4" | "m4v" => "video/mp4",
        "mov" => "video/quicktime",
        "webm" => "video/webm",
        "pdf" => "application/pdf",
        "docx" => "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "doc" => "application/msword",
        "xlsx" => "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "xls" => "application/vnd.ms-excel",
        "pptx" => "application/vnd.openxmlformats-officedocument.presentationml.presentation",
        "ppt" => "application/vnd.ms-powerpoint",
        "md" => "text/markdown",
        "txt" | "log" => "text/plain",
        "zip" => "application/zip",
        _ => "",
    }
    .to_string()
}

fn markdown_resource_info(
    title: String,
    mime_type: String,
    size: Option<i64>,
) -> MarkdownResourceInfo {
    let mime_type = if mime_type.trim().is_empty() {
        preview_mime_from_name(&title)
    } else {
        mime_type
    };
    let resource_type = if mime_type.starts_with("video/") {
        "video"
    } else if mime_type.starts_with("image/") {
        "image"
    } else {
        "file"
    };
    MarkdownResourceInfo {
        title,
        mime_type,
        resource_type: resource_type.to_string(),
        size: size.and_then(|value| u64::try_from(value).ok()),
    }
}

fn feishu_media_token(source: &str) -> Option<&str> {
    let token = source.strip_prefix("feishu-media://")?.trim();
    (!token.is_empty()
        && token.len() <= 256
        && token
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || matches!(character, '-' | '_')))
    .then_some(token)
}

fn decode_feishu_media_data(data: &str) -> Option<Vec<u8>> {
    let encoded = data
        .strip_prefix("data:")
        .and_then(|value| value.split_once(","))
        .map(|(_, encoded)| encoded)
        .unwrap_or(data)
        .trim();
    if encoded.is_empty() || encoded.len() > 40 * 1024 * 1024 {
        return None;
    }
    STANDARD
        .decode(encoded)
        .or_else(|_| URL_SAFE_NO_PAD.decode(encoded))
        .ok()
}

fn feishu_media_payload(value: &Value) -> Option<(Vec<u8>, String)> {
    match value {
        Value::Array(items) => items.iter().find_map(feishu_media_payload),
        Value::Object(object) => {
            let mime_type = ["mimeType", "mime_type", "contentType", "content_type"]
                .into_iter()
                .find_map(|key| object.get(key).and_then(Value::as_str))
                .unwrap_or("image/*")
                .to_string();
            let explicit_media = object
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(|kind| matches!(kind, "image" | "audio" | "resource" | "blob"))
                || mime_type.starts_with("image/")
                || mime_type.starts_with("video/");
            if explicit_media {
                for key in ["data", "base64", "blob", "content"] {
                    if let Some(bytes) = object
                        .get(key)
                        .and_then(Value::as_str)
                        .and_then(decode_feishu_media_data)
                    {
                        if infer::get(&bytes).is_some() || mime_type.starts_with("image/") {
                            return Some((bytes, mime_type));
                        }
                    }
                }
            }
            object.values().find_map(feishu_media_payload)
        }
        Value::String(text) => serde_json::from_str::<Value>(text)
            .ok()
            .as_ref()
            .and_then(feishu_media_payload),
        _ => None,
    }
}

async fn fetch_feishu_media(
    client: &reqwest::Client,
    session: &McpSession,
    token: &str,
) -> Result<(Vec<u8>, String), String> {
    let variants = [
        json!({ "resource_token": token }),
        json!({ "fileToken": token }),
        json!({ "file_token": token }),
        json!({ "token": token }),
    ];
    let mut errors = Vec::new();
    for (index, arguments) in variants.into_iter().enumerate() {
        match call_feishu_tool_raw(
            client,
            session,
            "fetch-file",
            arguments,
            40_001 + index as u64,
        )
        .await
        {
            Ok(result) => {
                if let Some(payload) = feishu_media_payload(&result) {
                    return Ok(payload);
                }
                let parsed = tool_result_json(&result);
                if let Some(payload) = feishu_media_payload(&parsed) {
                    return Ok(payload);
                }
                errors.push("返回内容中没有可识别的图片数据".to_string());
            }
            Err(error) => errors.push(error),
        }
    }
    Err(format!("无法读取飞书图片：{}", errors.join("；")))
}

fn persist_feishu_media(
    database: &PathBuf,
    space_id: &str,
    document_id: &str,
    token: &str,
    blob: &StoredBlob,
    mime_type: &str,
) -> Result<(), String> {
    let (mut connection, _writer) = open_write_database(database)?;
    let present: bool = connection
        .query_row(
            "SELECT EXISTS(SELECT 1 FROM documents d JOIN libraries l ON l.id=d.space_id
         WHERE d.space_id=?1 AND d.id=?2 AND l.provider='feishu' AND l.enabled=1)",
            params![space_id, document_id],
            |row| row.get(0),
        )
        .map_err(|error| format!("无法核对飞书图片所属文档：{error}"))?;
    if !present {
        return Err("CONTENT_POLICY:文档已移除或停用，图片结果已让出".into());
    }
    let transaction = connection
        .transaction()
        .map_err(|error| format!("无法开始飞书图片缓存事务：{error}"))?;
    let timestamp = now_timestamp();
    transaction
        .execute(
            "INSERT INTO blobs (hash,size,mime_type,relative_path,created_at,verified_at)
             VALUES (?1,?2,?3,?4,?5,?5)
             ON CONFLICT(hash) DO UPDATE SET
               mime_type=excluded.mime_type,verified_at=excluded.verified_at",
            params![
                blob.hash,
                blob.size as i64,
                mime_type,
                blob.relative_path,
                timestamp
            ],
        )
        .map_err(|error| format!("无法记录飞书图片 Blob：{error}"))?;
    transaction
        .execute(
            "INSERT INTO source_items
               (id,space_id,document_id,remote_id,source_type,title,mime_type,
                content_hash,blob_hash,status,metadata_json,created_at,updated_at,provider)
             VALUES (?1,?2,?3,?4,'feishu_media','飞书图片',?5,?6,?6,'stored',?7,?8,?8,'feishu')
             ON CONFLICT(space_id,remote_id,source_type) DO UPDATE SET
               document_id=excluded.document_id,mime_type=excluded.mime_type,
               content_hash=excluded.content_hash,blob_hash=excluded.blob_hash,
               status='stored',metadata_json=excluded.metadata_json,
               updated_at=excluded.updated_at,provider='feishu'",
            params![
                format!("feishu-media:{space_id}:{token}"),
                space_id,
                document_id,
                token,
                mime_type,
                blob.hash,
                json!({ "markdownSource": format!("feishu-media://{token}"), "remoteUrl": format!("feishu-media://{token}") }).to_string(),
                timestamp
            ],
        )
        .map_err(|error| format!("无法关联飞书图片缓存：{error}"))?;
    transaction
        .commit()
        .map_err(|error| format!("无法提交飞书图片缓存：{error}"))
}

#[tauri::command]
fn local_markdown_resource_info(
    app: AppHandle,
    provider: String,
    space_id: String,
    document_id: String,
    source: String,
) -> Result<MarkdownResourceInfo, String> {
    let source = source.trim().trim_matches(['<', '>']).to_string();
    if source.len() > 8_192 {
        return Err("附件地址过长".to_string());
    }
    let connection = open_database(&database_path(&app)?)?;
    if provider == PROVIDER_DIDA365 {
        if let Some(info) = connection
            .query_row(
                "SELECT s.title,COALESCE(s.mime_type,''),b.size
                 FROM source_items s
                 LEFT JOIN blobs b ON b.hash=s.blob_hash
                 WHERE s.space_id=?1 AND s.document_id=?2
                   AND s.source_type='dida_attachment' AND s.provider='dida365'
                   AND json_extract(s.metadata_json,'$.markdownSource')=?3
                 LIMIT 1",
                params![space_id, document_id, source],
                |row| {
                    Ok(markdown_resource_info(
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                    ))
                },
            )
            .optional()
            .map_err(|error| format!("无法读取滴答附件信息：{error}"))?
        {
            return Ok(info);
        }
        let attachment = parse_dida_attachment_source(&source)
            .ok_or_else(|| "这不是可识别的滴答附件地址".to_string())?;
        return Ok(markdown_resource_info(
            attachment.file_name,
            attachment.mime_type,
            None,
        ));
    }
    if provider == PROVIDER_CRAFT {
        if let Some(resource) =
            craft_backup_resources::lookup(&database_path(&app)?, &space_id, &document_id, &source)?
        {
            return Ok(markdown_resource_info(
                resource.title,
                resource.mime_type,
                Some(resource.size as i64),
            ));
        }
        return connection
            .query_row(
                "SELECT s.title,COALESCE(s.mime_type,''),
                        COALESCE(b.size,CAST(json_extract(s.metadata_json,'$.size') AS INTEGER))
                 FROM source_items s
                 LEFT JOIN blobs b ON b.hash=s.blob_hash
                 WHERE s.space_id=?1 AND s.document_id=?2
                   AND json_extract(s.metadata_json,'$.remoteUrl')=?3
                 LIMIT 1",
                params![space_id, document_id, source],
                |row| {
                    Ok(markdown_resource_info(
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                    ))
                },
            )
            .optional()
            .map_err(|error| format!("无法读取 Craft 附件信息：{error}"))?
            .ok_or_else(|| "尚未索引此 Craft 附件".to_string());
    }
    if provider == PROVIDER_FEISHU {
        feishu_media_token(&source).ok_or_else(|| "这不是可识别的飞书媒体地址".to_string())?;
        return Ok(markdown_resource_info(
            "飞书图片".to_string(),
            "image/*".to_string(),
            None,
        ));
    }
    if provider != PROVIDER_OBSIDIAN {
        return Err("未知的附件资料库类型".to_string());
    }
    let decoded = percent_encoding::percent_decode_str(&source)
        .decode_utf8_lossy()
        .replace('\\', "/");
    let target = decoded
        .split('#')
        .next()
        .unwrap_or_default()
        .trim_start_matches("./")
        .trim_start_matches('/');
    let target_name = Path::new(target)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(target);
    let mut statement = connection
        .prepare(
            "SELECT s.title,COALESCE(s.mime_type,''),b.size,s.metadata_json
             FROM source_items s
             LEFT JOIN blobs b ON b.hash=s.blob_hash
             WHERE s.space_id=?1 AND s.document_id=?2
               AND s.source_type='obsidian_attachment'
               AND s.provider='obsidian'",
        )
        .map_err(|error| format!("无法准备 Obsidian 附件信息查询：{error}"))?;
    let candidates = statement
        .query_map(params![space_id, document_id], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, Option<i64>>(2)?,
                row.get::<_, String>(3)?,
            ))
        })
        .map_err(|error| format!("无法查询 Obsidian 附件信息：{error}"))?;
    for candidate in candidates {
        let (title, mime_type, size, metadata) =
            candidate.map_err(|error| format!("无法读取 Obsidian 附件信息：{error}"))?;
        let relative_path = serde_json::from_str::<Value>(&metadata)
            .ok()
            .and_then(|value| {
                value
                    .get("localRelativePath")
                    .and_then(Value::as_str)
                    .map(str::to_string)
            })
            .unwrap_or_default()
            .replace('\\', "/");
        let relative_name = Path::new(&relative_path)
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or_default();
        if relative_path.eq_ignore_ascii_case(target)
            || relative_name.eq_ignore_ascii_case(target_name)
        {
            return Ok(markdown_resource_info(title, mime_type, size));
        }
    }
    Err("尚未索引此 Obsidian 附件".to_string())
}

#[tauri::command]
async fn open_dida_attachment(
    app: AppHandle,
    space_id: String,
    document_id: String,
    source: String,
    state: State<'_, AppState>,
) -> Result<(), String> {
    let attachment = parse_dida_attachment_source(&source)
        .ok_or_else(|| "这不是可识别的滴答附件地址".to_string())?;
    let database = database_path(&app)?;
    let blob_store = blob_store_for(&app, &state)?;
    let (downloaded, _) = load_preview_attachment(
        &database,
        &blob_store,
        PROVIDER_DIDA365,
        &space_id,
        &document_id,
        &source,
        &attachment_http_client()?,
        || dida_attachment_cookie_header(&app).map(|(header, _)| Some(header)),
        true,
    )
    .await
    .map_err(|error| {
        if error.contains("401") || error.contains("403") {
            format!("滴答网页会话无权读取附件，请重新登录后再试（{error}）")
        } else {
            error
        }
    })?;
    let hash = downloaded.blob.hash;
    let source_path = blob_store.path_for(&hash)?;
    let open_directory = blob_store.root_path().join("opened");
    fs::create_dir_all(&open_directory)
        .map_err(|error| format!("无法创建附件打开目录：{error}"))?;
    let target = open_directory.join(format!("{}-{}", &hash[..12], attachment.file_name));
    if !target.is_file() {
        fs::copy(&source_path, &target).map_err(|error| format!("无法准备滴答附件：{error}"))?;
    }
    tauri_plugin_opener::open_path(&target, None::<&str>)
        .map_err(|error| format!("无法打开滴答附件：{error}"))
}

#[tauri::command]
async fn open_craft_attachment(
    app: AppHandle,
    space_id: String,
    document_id: String,
    source: String,
    state: State<'_, AppState>,
) -> Result<bool, String> {
    let database = database_path(&app)?;
    let store = blob_store_for(&app, &state)?;
    let source = source.trim().trim_matches(['<', '>']);
    let resource = if let Some(resource) =
        craft_backup_resources::lookup(&database, &space_id, &document_id, source)?
    {
        Some((resource.hash, resource.title, resource.mime_type))
    } else {
        open_database(&database)?.query_row("SELECT blob_hash,title,COALESCE(mime_type,'') FROM source_items
            WHERE provider='craft' AND space_id=?1 AND document_id=?2 AND json_extract(metadata_json,'$.remoteUrl')=?3
            AND blob_hash IS NOT NULL LIMIT 1",params![space_id,document_id,source],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?,r.get::<_,String>(2)?)))
            .optional().map_err(|e|e.to_string())?
    };
    let Some((hash, title, mime)) = resource else {
        return Ok(false);
    };
    let original = store.path_for(&hash)?;
    if !original.is_file() {
        return Ok(false);
    }
    // Editable external viewers receive a working copy, never the immutable backup.
    let directory = store.root_path().join("opened");
    fs::create_dir_all(&directory).map_err(|e| e.to_string())?;
    let mut filename = PathBuf::from(craft_export::sanitize_component(&title, "附件"));
    if let Some(extension) = craft_export::extension_for_mime(&mime) {
        filename.set_extension(extension);
    }
    let target = directory.join(format!("{}-{}", &hash[..12], filename.to_string_lossy()));
    if !target.is_file() {
        fs::copy(original, &target).map_err(|e| e.to_string())?;
    }
    tauri_plugin_opener::open_path(target, None::<&str>).map_err(|e| e.to_string())?;
    Ok(true)
}

#[tauri::command]
async fn local_markdown_image(
    app: AppHandle,
    provider: String,
    space_id: String,
    document_id: String,
    source: String,
    allow_video: Option<bool>,
    state: State<'_, AppState>,
) -> Result<MarkdownMediaPreview, String> {
    let source = source.trim().trim_matches(['<', '>']).to_string();
    if source.len() > 8_192 {
        return Err("图片地址过长".to_string());
    }
    let database = database_path(&app)?;
    let blob_store = blob_store_for(&app, &state)?;

    if provider == PROVIDER_FEISHU {
        let token =
            feishu_media_token(&source).ok_or_else(|| "这不是可识别的飞书媒体地址".to_string())?;
        let _source_lease = attachment_resource_cache::acquire_source(
            &database,
            &space_id,
            PROVIDER_FEISHU,
            &format!("feishu-media:{space_id}:{token}"),
        )
        .await?;
        let _resource_lease = attachment_resource_cache::acquire(
            &database,
            &space_id,
            PROVIDER_FEISHU,
            &json!({"remoteUrl":source}).to_string(),
        )
        .await?;
        let stored =
            {
                let connection = open_database(&database)?;
                let present: bool=connection.query_row(
                "SELECT EXISTS(SELECT 1 FROM documents d JOIN libraries l ON l.id=d.space_id
                 WHERE d.space_id=?1 AND d.id=?2 AND l.provider='feishu' AND l.enabled=1)",
                params![space_id,document_id],|row|row.get(0),
            ).map_err(|error|format!("无法核对飞书图片所属文档：{error}"))?;
                if !present {
                    return Err("CONTENT_POLICY:文档已移除或停用，请重新打开预览".into());
                }
                connection
                    .query_row(
                        "SELECT COALESCE(s.mime_type,''),s.blob_hash,b.size FROM source_items s
                     JOIN blobs b ON b.hash=s.blob_hash
                     JOIN libraries l ON l.id=s.space_id AND l.enabled=1
                     WHERE s.space_id=?1 AND s.remote_id=?2
                       AND s.source_type='feishu_media' AND s.provider='feishu'
                       AND s.blob_hash IS NOT NULL LIMIT 1",
                        params![space_id, token],
                        |row| {
                            Ok((
                                row.get::<_, String>(0)?,
                                row.get::<_, String>(1)?,
                                row.get::<_, u64>(2)?,
                            ))
                        },
                    )
                    .optional()
                    .map_err(|error| format!("无法查找本地飞书图片：{error}"))?
            };
        if let Some((mime_type, hash, size)) = stored {
            if mime_type.starts_with("video/") && !allow_video.unwrap_or(false) {
                return Err("VIDEO_REQUIRES_ACTIVATION".into());
            }
            if let Some(cached) = attachment_resource_cache::verified_blob(
                &blob_store,
                &hash,
                size,
                &mime_type,
                None,
            )? {
                return preview_media_from_blob(&blob_store, &cached.blob.hash, &cached.mime_type);
            }
        }
        let session = session_for_space(&state, &space_id)?;
        let client = reqwest::Client::builder()
            .user_agent(concat!("Craft-Search/", env!("CARGO_PKG_VERSION")))
            .build()
            .map_err(|error| format!("飞书图片客户端初始化失败：{error}"))?;
        let (bytes, mime_type) = fetch_feishu_media(&client, &session, token).await?;
        let detected_mime = infer::get(&bytes)
            .map(|kind| kind.mime_type().to_string())
            .unwrap_or(mime_type);
        let blob = blob_store.put(&bytes)?;
        persist_feishu_media(
            &database,
            &space_id,
            &document_id,
            token,
            &blob,
            &detected_mime,
        )?;
        return preview_media_from_blob(&blob_store, &blob.hash, &detected_mime);
    }

    if provider == PROVIDER_DIDA365 {
        let (downloaded, _) = load_preview_attachment(
            &database,
            &blob_store,
            PROVIDER_DIDA365,
            &space_id,
            &document_id,
            &source,
            &attachment_http_client()?,
            || dida_attachment_cookie_header(&app).map(|(header, _)| Some(header)),
            allow_video.unwrap_or(false),
        )
        .await
        .map_err(|error| {
            if error.contains("401") || error.contains("403") {
                format!("滴答网页会话无权读取附件，请重新登录后再试（{error}）")
            } else {
                error
            }
        })?;
        return preview_media_from_blob(&blob_store, &downloaded.blob.hash, &downloaded.mime_type);
    }

    if provider == PROVIDER_CRAFT {
        if let Some(resource) =
            craft_backup_resources::lookup(&database, &space_id, &document_id, &source)?
        {
            if (resource.mime_type.starts_with("video/")
                || preview_mime_from_name(&resource.title).starts_with("video/"))
                && !allow_video.unwrap_or(false)
            {
                return Err("VIDEO_REQUIRES_ACTIVATION".into());
            }
            return preview_media_from_blob(&blob_store, &resource.hash, &resource.mime_type);
        }
        let (downloaded, _) = load_preview_attachment(
            &database,
            &blob_store,
            PROVIDER_CRAFT,
            &space_id,
            &document_id,
            &source,
            &attachment_http_client()?,
            || Ok(None),
            allow_video.unwrap_or(false),
        )
        .await?;
        return preview_media_from_blob(&blob_store, &downloaded.blob.hash, &downloaded.mime_type);
    }

    if provider != PROVIDER_OBSIDIAN {
        return Err("未知的图片资料库类型".to_string());
    }
    tokio::task::spawn_blocking(move || {
        let decoded = percent_encoding::percent_decode_str(&source)
            .decode_utf8_lossy()
            .replace('\\', "/");
        let target = decoded
            .split('#')
            .next()
            .unwrap_or_default()
            .trim_start_matches("./")
            .trim_start_matches('/');
        let target_name = Path::new(target)
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or(target);
        let connection = open_database(&database)?;
        let mut statement = connection
            .prepare(
                "SELECT COALESCE(s.mime_type,''),s.blob_hash,s.metadata_json,l.location
                 FROM source_items s
                 JOIN libraries l ON l.id=s.space_id
                 WHERE s.space_id=?1 AND s.document_id=?2
                   AND s.source_type='obsidian_attachment'
                   AND s.provider='obsidian' AND l.provider='obsidian'",
            )
            .map_err(|error| format!("无法准备 Obsidian 图片查询：{error}"))?;
        let candidates = statement
            .query_map(params![space_id, document_id], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, Option<String>>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                ))
            })
            .map_err(|error| format!("无法查询 Obsidian 图片：{error}"))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法读取 Obsidian 图片：{error}"))?;
        for (mime_type, blob_hash, metadata, location) in candidates {
            let relative_path = serde_json::from_str::<Value>(&metadata)
                .ok()
                .and_then(|value| {
                    value
                        .get("localRelativePath")
                        .and_then(Value::as_str)
                        .map(str::to_string)
                })
                .unwrap_or_default()
                .replace('\\', "/");
            let relative_name = Path::new(&relative_path)
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or_default();
            let matches = relative_path.eq_ignore_ascii_case(target)
                || relative_path
                    .to_ascii_lowercase()
                    .ends_with(&format!("/{}", target.to_ascii_lowercase()))
                || (!target.contains('/') && relative_name.eq_ignore_ascii_case(target_name));
            if !matches {
                continue;
            }
            if (mime_type.starts_with("video/")
                || preview_mime_from_name(&relative_path).starts_with("video/"))
                && !allow_video.unwrap_or(false)
            {
                return Err("VIDEO_REQUIRES_ACTIVATION".into());
            }
            if let Some(hash) = blob_hash {
                return preview_media_from_blob(&blob_store, &hash, &mime_type);
            }
            let root = PathBuf::from(location)
                .canonicalize()
                .map_err(|error| format!("无法读取 Obsidian Vault：{error}"))?;
            let image_path = root
                .join(&relative_path)
                .canonicalize()
                .map_err(|error| format!("无法定位 Obsidian 图片：{error}"))?;
            if !image_path.starts_with(&root) || !image_path.is_file() {
                return Err("Obsidian 图片路径超出 Vault".to_string());
            }
            let bytes = std::fs::read(&image_path)
                .map_err(|error| format!("无法读取 Obsidian 图片：{error}"))?;
            return preview_media_from_bytes(&blob_store, bytes, &mime_type);
        }
        Err("本地索引中没有找到这张图片".to_string())
    })
    .await
    .map_err(|error| format!("图片预览任务失败：{error}"))?
}

fn merge_preview_chunks(chunks: &[String]) -> String {
    let mut merged = Vec::<char>::new();
    for chunk in chunks {
        let next = chunk.chars().collect::<Vec<_>>();
        if next.is_empty() {
            continue;
        }
        if merged.is_empty() {
            merged = next;
            continue;
        }
        let maximum_overlap = merged.len().min(next.len()).min(1_000);
        let overlap = (1..=maximum_overlap)
            .rev()
            .find(|length| merged[merged.len() - length..] == next[..*length])
            .unwrap_or(0);
        if overlap == 0 && !merged.last().is_some_and(|character| *character == '\n') {
            merged.push('\n');
        }
        merged.extend_from_slice(&next[overlap..]);
    }
    merged.into_iter().collect()
}

fn pdf_page_preview_from_database(
    path: &PathBuf,
    blob_store: &BlobStore,
    result_id: &str,
    requested_page: u32,
) -> Result<PdfPagePreview, String> {
    let connection = open_database(path)?;
    let (source_item_id, blob_hash): (String, String) = connection
        .query_row(
            "SELECT s.id,s.blob_hash
             FROM content_items hit
             JOIN source_items s ON s.id=hit.source_item_id
             WHERE hit.id=?1 AND hit.content_type IN ('pdf_page','pdf_ocr')
               AND s.mime_type='application/pdf' AND s.blob_hash IS NOT NULL",
            params![result_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .map_err(|error| format!("无法读取 PDF 预览来源：{error}"))?;
    let page_count: i64 = connection
        .query_row(
            "SELECT MAX(
               COALESCE((SELECT MAX(page_count) FROM extractions WHERE source_item_id=?1),0),
               COALESCE((SELECT MAX(page_number) FROM content_items WHERE source_item_id=?1),1)
             )",
            params![source_item_id],
            |row| row.get(0),
        )
        .map_err(|error| format!("无法读取 PDF 预览页数：{error}"))?;
    let page_count = u32::try_from(page_count.max(1)).unwrap_or(u32::MAX);
    let page_number = requested_page.clamp(1, page_count);
    let (chunks, source_type) = {
        let mut statement = connection
            .prepare(
                "SELECT body,content_type FROM content_items
                 WHERE source_item_id=?1 AND page_number=?2
                   AND content_type IN ('pdf_page','pdf_ocr')
                 ORDER BY ordinal,id",
            )
            .map_err(|error| format!("无法准备 PDF 页面文字预览：{error}"))?;
        let rows = statement
            .query_map(params![source_item_id, page_number], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })
            .map_err(|error| format!("无法查询 PDF 页面文字预览：{error}"))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("无法读取 PDF 页面文字预览：{error}"))?;
        let source_type = if rows.iter().any(|(_, kind)| kind == "pdf_ocr") {
            "pdf_ocr"
        } else {
            "pdf_native"
        };
        (
            rows.into_iter().map(|(body, _)| body).collect::<Vec<_>>(),
            source_type.to_string(),
        )
    };
    let rendered = ocr::render_pdf_page_png(&blob_store.path_for(&blob_hash)?, page_number, 1_600);
    let (image_data_url, note) = match rendered {
        Ok(bytes) => (
            Some(format!(
                "data:image/png;base64,{}",
                base64::engine::general_purpose::STANDARD.encode(bytes)
            )),
            None,
        ),
        Err(error) => (None, Some(format!("{error}；已显示提取文字。"))),
    };
    Ok(PdfPagePreview {
        image_data_url,
        text: merge_preview_chunks(&chunks),
        page_number,
        page_count,
        source_type,
        note,
    })
}

#[tauri::command]
async fn local_pdf_page_preview(
    app: AppHandle,
    result_id: String,
    page_number: u32,
    state: State<'_, AppState>,
) -> Result<PdfPagePreview, String> {
    let path = database_path(&app)?;
    let blob_store = blob_store_for(&app, &state)?;
    tokio::task::spawn_blocking(move || {
        pdf_page_preview_from_database(&path, &blob_store, &result_id, page_number)
    })
    .await
    .map_err(|error| format!("PDF 页面预览任务失败：{error}"))?
}

#[tauri::command]
async fn set_craft_api_connection(
    app: AppHandle,
    api_url: String,
    api_key: String,
) -> Result<CraftApiConnectionSummary, String> {
    let api_base = craft_api_base_url(&api_url)?;
    let api_key = api_key.trim().to_string();
    if !api_key.is_empty() && !api_key.starts_with("pdk_") {
        return Err("Craft API Key 格式无效，应当以 pdk_ 开头".to_string());
    }
    let mut connection_url = api_base.clone();
    connection_url
        .path_segments_mut()
        .map_err(|_| "无法构造 Craft API 验证地址".to_string())?
        .push("connection");
    let client = task_sync_http_client()?;
    let request = client.get(connection_url);
    let request = if api_key.is_empty() {
        request
    } else {
        request.bearer_auth(&api_key)
    };
    let response = request
        .send()
        .await
        .map_err(|error| format!("无法验证 Craft API 连接：{error}"))?;
    let status = response.status();
    let response = response
        .json::<Value>()
        .await
        .map_err(|error| format!("Craft API 验证响应无法解析：{error}"))?;
    if !status.is_success() {
        let code = value_string(&response, &["code"]).unwrap_or_default();
        if status == reqwest::StatusCode::UNAUTHORIZED && code == "MISSING_AUTH_HEADER" {
            return Err("该 Craft API 连接要求 API Key。请在 Craft → Imagine → API Connection 中创建并复制以 pdk_ 开头的 Key".to_string());
        }
        let detail =
            value_string(&response, &["message", "error"]).unwrap_or_else(|| response.to_string());
        return Err(format!("Craft API 连接验证失败（HTTP {status}）：{detail}"));
    }
    let (space_id, space_name) =
        find_space_identity(&response).ok_or_else(|| "Craft API 没有返回空间信息".to_string())?;
    stored_secret_set(&app, &craft_api_credential_id(&space_id), api_base.as_str())
        .map_err(|error| format!("无法安全保存 Craft API 地址：{error}"))?;
    stored_secret_set(&app, &craft_api_key_credential_id(&space_id), &api_key)
        .map_err(|error| format!("无法安全保存 Craft API Key：{error}"))?;
    Ok(CraftApiConnectionSummary {
        space_id,
        space_name,
    })
}

#[tauri::command]
async fn connect_mcp(
    app: AppHandle,
    mcp_url: String,
    init_options: Option<LibraryAddOptions>,
    state: State<'_, AppState>,
) -> Result<ConnectionSummary, String> {
    if isolated_runtime::enabled() {
        return Err("隔离联调运行不连接外部资料库".into());
    }
    let endpoint = Url::parse(mcp_url.trim()).map_err(|error| format!("MCP 地址无效：{error}"))?;
    if endpoint.scheme() != "https" {
        return Err("MCP 地址必须使用 HTTPS".to_string());
    }

    let client = reqwest::Client::builder()
        .user_agent(concat!("Craft-Search/", env!("CARGO_PKG_VERSION")))
        .build()
        .map_err(|error| format!("HTTP 客户端初始化失败：{error}"))?;
    let (protected, authorization) = discover_oauth(&client, endpoint.as_str()).await?;

    #[cfg(not(mobile))]
    let listener = TcpListener::bind("127.0.0.1:0")
        .await
        .map_err(|error| format!("无法启动 OAuth 本地回调：{error}"))?;
    #[cfg(not(mobile))]
    let callback_port = listener
        .local_addr()
        .map_err(|error| format!("无法读取 OAuth 回调端口：{error}"))?
        .port();
    #[cfg(not(mobile))]
    let redirect_uri = format!("http://127.0.0.1:{callback_port}/oauth/callback");
    #[cfg(mobile)]
    let redirect_uri = MOBILE_OAUTH_REDIRECT_URI.to_string();
    let registration = register_client(&client, &authorization, &redirect_uri).await?;

    let state_token = random_url_safe(24);
    let code_verifier = random_url_safe(48);
    let code_challenge = URL_SAFE_NO_PAD.encode(Sha256::digest(code_verifier.as_bytes()));
    let mut authorization_url = Url::parse(&authorization.authorization_endpoint)
        .map_err(|error| format!("OAuth authorization endpoint 无效：{error}"))?;
    authorization_url
        .query_pairs_mut()
        .append_pair("response_type", "code")
        .append_pair("client_id", &registration.client_id)
        .append_pair("redirect_uri", &redirect_uri)
        .append_pair("code_challenge", &code_challenge)
        .append_pair("code_challenge_method", "S256")
        .append_pair("state", &state_token)
        .append_pair("resource", &protected.resource);

    #[cfg(mobile)]
    let mut callback = mobile_oauth::callbacks().begin(&state_token)?;
    open_external(&app, authorization_url.as_str())
        .map_err(|error| format!("无法打开 Craft 授权页面：{error}"))?;
    #[cfg(not(mobile))]
    let code = tokio::time::timeout(
        Duration::from_secs(600),
        wait_for_oauth_callback(listener, &state_token),
    )
    .await
    .map_err(|_| "Craft 授权等待超时，请重新连接".to_string())??;
    #[cfg(mobile)]
    let code = tokio::time::timeout(Duration::from_secs(600), callback.wait())
        .await
        .map_err(|_| "Craft 授权等待超时，请重新连接".to_string())??;
    let token = exchange_code(
        &client,
        &authorization,
        &registration,
        &code,
        &redirect_uri,
        &code_verifier,
        &protected.resource,
    )
    .await?;
    let mut credential = StoredCredential {
        mcp_url: endpoint.to_string(),
        resource: protected.resource,
        token_endpoint: authorization.token_endpoint,
        client_id: registration.client_id,
        client_secret: registration.client_secret,
        refresh_token: token.refresh_token,
        access_token: Some(token.access_token.clone()),
        expires_at: token
            .expires_in
            .and_then(|seconds| i64::try_from(seconds).ok())
            .map(|seconds| now_timestamp().saturating_add(seconds)),
    };
    let authenticated =
        match initialize_authenticated_connection(&client, endpoint.as_str(), token.access_token)
            .await
        {
            Ok(authenticated) => authenticated,
            Err(error)
                if is_remote_authentication_error(&error) && credential.refresh_token.is_some() =>
            {
                let refreshed = refresh_access_token(&client, &mut credential)
                    .await
                    .map_err(|refresh_error| {
                        format!("Craft 授权 token 无效，刷新访问 token 也失败：{refresh_error}")
                    })?;
                remember_access_token(&mut credential, &refreshed);
                initialize_authenticated_connection(
                    &client,
                    endpoint.as_str(),
                    refreshed.access_token,
                )
                .await
                .map_err(|retry_error| format!("Craft 授权 token 刷新后仍无效：{retry_error}"))?
            }
            Err(error) => return Err(error),
        };
    let space_id = authenticated.session.space_id.clone();
    let space_name = authenticated.session.space_name.clone();
    let can_open_craft = authenticated.session.deep_link_template.is_some();

    save_credential(&space_id, &credential)?;

    let path = database_path(&app)?;
    let saved_space_id = space_id.clone();
    let initialization_epoch = prepare_library_add(&path, &space_id)?;
    let saved_space_name = space_name.clone();
    let saved_url = endpoint.to_string();
    let saved_deep_link = authenticated.session.deep_link_template.clone();
    tokio::task::spawn_blocking(move || {
        let (connection, _writer) = open_write_database(&path)?;
        let added_at = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs() as i64;
        connection
            .execute(
                "INSERT INTO spaces (id, name, mcp_url, deep_link_template, added_at)
                 VALUES (?1, ?2, ?3, ?4, ?5)
                 ON CONFLICT(id) DO UPDATE SET
                   name = excluded.name,
                   mcp_url = excluded.mcp_url,
                   deep_link_template = excluded.deep_link_template",
                params![
                    saved_space_id,
                    saved_space_name,
                    saved_url,
                    saved_deep_link,
                    added_at
                ],
            )
            .map_err(|error| format!("无法保存 Craft 空间：{error}"))?;
        connection
            .execute(
                "INSERT INTO libraries
                   (id,provider,name,location,enabled,added_at,last_sync,metadata_json)
                 VALUES (?1,'craft',?2,?3,1,?4,NULL,?5)
                 ON CONFLICT(id) DO UPDATE SET
                   provider='craft',name=CASE WHEN COALESCE(json_extract(libraries.metadata_json,'$.displayNameCustomized'),0)=1 THEN libraries.name ELSE excluded.name END,location=excluded.location,
                   enabled=1,
                   metadata_json=json_patch(
                     COALESCE(libraries.metadata_json,'{}'),
                     excluded.metadata_json
                   )",
                params![
                    saved_space_id,
                    saved_space_name,
                    saved_url,
                    added_at,
                    json!({ "deepLinkTemplate": saved_deep_link }).to_string()
                ],
            )
            .map_err(|error| format!("无法登记 Craft 资料库：{error}"))?;
        connection.execute("UPDATE spaces SET name=(SELECT name FROM libraries WHERE id=?1) WHERE id=?1", [&saved_space_id])
            .map_err(|error| format!("无法保存 Craft 显示名称：{error}"))?;
        Ok::<(), String>(())
    })
    .await
    .map_err(|error| format!("保存空间任务失败：{error}"))??;

    state
        .sessions
        .lock()
        .map_err(|_| "MCP 会话状态不可用".to_string())?
        .insert(space_id.clone(), authenticated.session);

    finish_library_add(&app, &space_id, initialization_epoch, init_options).await?;

    Ok(ConnectionSummary {
        space_id,
        space_name,
        server_name: authenticated.server_name,
        server_version: authenticated.server_version,
        tools: authenticated.tools,
        can_open_craft,
    })
}

#[tauri::command]
async fn connect_dida365(
    app: AppHandle,
    init_options: Option<LibraryAddOptions>,
    state: State<'_, AppState>,
) -> Result<ConnectionSummary, String> {
    const DIDA_MCP_URL: &str = "https://mcp.dida365.com";
    let endpoint =
        Url::parse(DIDA_MCP_URL).map_err(|error| format!("滴答 MCP 地址无效：{error}"))?;
    let client = reqwest::Client::builder()
        .user_agent(concat!("Craft-Search/", env!("CARGO_PKG_VERSION")))
        .build()
        .map_err(|error| format!("HTTP 客户端初始化失败：{error}"))?;
    let (protected, authorization) = discover_oauth(&client, endpoint.as_str()).await?;
    let listener = TcpListener::bind("127.0.0.1:0")
        .await
        .map_err(|error| format!("无法启动 OAuth 本地回调：{error}"))?;
    let callback_port = listener
        .local_addr()
        .map_err(|error| format!("无法读取 OAuth 回调端口：{error}"))?
        .port();
    let redirect_uri = format!("http://127.0.0.1:{callback_port}/oauth/callback");
    let registration = register_client(&client, &authorization, &redirect_uri).await?;
    let state_token = random_url_safe(24);
    let code_verifier = random_url_safe(48);
    let code_challenge = URL_SAFE_NO_PAD.encode(Sha256::digest(code_verifier.as_bytes()));
    let mut authorization_url = Url::parse(&authorization.authorization_endpoint)
        .map_err(|error| format!("OAuth authorization endpoint 无效：{error}"))?;
    authorization_url
        .query_pairs_mut()
        .append_pair("response_type", "code")
        .append_pair("client_id", &registration.client_id)
        .append_pair("redirect_uri", &redirect_uri)
        .append_pair("code_challenge", &code_challenge)
        .append_pair("code_challenge_method", "S256")
        .append_pair("state", &state_token)
        .append_pair("resource", &protected.resource);
    let requested_scope = dida_oauth_scope(&protected.scopes_supported)?;
    authorization_url
        .query_pairs_mut()
        .append_pair("scope", &requested_scope);
    open_external(&app, authorization_url.as_str())
        .map_err(|error| format!("无法打开滴答清单授权页面：{error}"))?;
    let code = tokio::time::timeout(
        Duration::from_secs(600),
        wait_for_oauth_callback(listener, &state_token),
    )
    .await
    .map_err(|_| "滴答清单授权等待超时，请重新连接".to_string())??;
    let token = exchange_code(
        &client,
        &authorization,
        &registration,
        &code,
        &redirect_uri,
        &code_verifier,
        &protected.resource,
    )
    .await?;
    let mut authenticated = initialize_mcp_transport(
        &client,
        endpoint.as_str(),
        token.access_token.clone(),
        DIDA_MCP_PROTOCOL_VERSION,
    )
    .await?;
    for required in ["list_projects", "get_project_with_undone_tasks"] {
        if !authenticated.tools.iter().any(|tool| tool.name == required) {
            return Err(format!("滴答 MCP 没有提供只读工具 {required}"));
        }
    }
    let preference = if authenticated
        .tools
        .iter()
        .any(|tool| tool.name == "get_user_preference")
    {
        call_mcp_tool_raw(
            &client,
            &authenticated.session,
            "get_user_preference",
            json!({}),
            19_001,
        )
        .await
        .map(|value| tool_result_json(&value))
        .unwrap_or(Value::Null)
    } else {
        Value::Null
    };
    let discovered_account_name = dida_account_name(&preference);
    let database = database_path(&app)?;
    let lookup_database = database.clone();
    let endpoint_text = endpoint.to_string();
    let lookup_endpoint = endpoint_text.clone();
    let existing_library = tokio::task::spawn_blocking(move || {
        let connection = open_database(&lookup_database)?;
        connection
            .query_row(
                "SELECT id,name,metadata_json FROM libraries
                 WHERE provider='dida365' AND location=?1 ORDER BY added_at LIMIT 1",
                params![lookup_endpoint],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, Option<String>>(2)?,
                    ))
                },
            )
            .optional()
            .map_err(|error| format!("无法查找已有滴答资料库：{error}"))
    })
    .await
    .map_err(|error| format!("滴答资料库查询任务失败：{error}"))??;
    let (library_id, account_name) =
        if let Some((id, existing_name, metadata_json)) = existing_library {
            let customized = metadata_json
                .as_deref()
                .and_then(|value| serde_json::from_str::<Value>(value).ok())
                .and_then(|value| value.get("displayNameCustomized").cloned())
                .is_some_and(|value| value.as_bool() == Some(true) || value.as_i64() == Some(1));
            let name = if customized {
                existing_name
            } else if let Some(name) = discovered_account_name.clone() {
                name
            } else if existing_name == "我的滴答清单" {
                "滴答清单".to_string()
            } else {
                existing_name
            };
            (id, name)
        } else {
            (
                format!("dida365:{}", random_url_safe(12)),
                discovered_account_name.unwrap_or_else(|| "滴答清单".to_string()),
            )
        };
    authenticated.session.space_id = library_id.clone();
    authenticated.session.space_name = account_name.clone();
    let initialization_epoch = prepare_library_add(&database, &library_id)?;
    save_credential(
        &library_id,
        &StoredCredential {
            mcp_url: endpoint_text.clone(),
            resource: protected.resource,
            token_endpoint: authorization.token_endpoint,
            client_id: registration.client_id,
            client_secret: registration.client_secret,
            refresh_token: token.refresh_token,
            access_token: Some(token.access_token),
            expires_at: token
                .expires_in
                .and_then(|seconds| i64::try_from(seconds).ok())
                .map(|seconds| now_timestamp().saturating_add(seconds)),
        },
    )?;
    let saved_id = library_id.clone();
    let saved_name = account_name.clone();
    let saved_tools = authenticated
        .tools
        .iter()
        .map(|tool| tool.name.clone())
        .collect::<Vec<_>>();
    tokio::task::spawn_blocking(move || {
        let (connection, _writer) = open_write_database(&database)?;
        connection
            .execute(
                "INSERT INTO libraries
                   (id,provider,name,location,enabled,added_at,last_sync,metadata_json)
                 VALUES (?1,'dida365',?2,?3,1,?4,NULL,?5)
                 ON CONFLICT(id) DO UPDATE SET provider='dida365',name=excluded.name,
                   location=excluded.location,enabled=1,
                   metadata_json=json_patch(COALESCE(libraries.metadata_json,'{}'),
                                            excluded.metadata_json)",
                params![
                    saved_id,
                    saved_name,
                    endpoint_text,
                    now_timestamp(),
                    json!({
                        "preference": preference,
                        "tools": saved_tools
                    })
                    .to_string()
                ],
            )
            .map_err(|error| format!("无法登记滴答清单资料库：{error}"))?;
        connection
            .execute(
                "UPDATE spaces SET name=?1 WHERE id=?2",
                params![saved_name, saved_id],
            )
            .map_err(|error| format!("无法同步滴答资料库显示名称：{error}"))?;
        Ok::<(), String>(())
    })
    .await
    .map_err(|error| format!("保存滴答资料库任务失败：{error}"))??;
    state
        .sessions
        .lock()
        .map_err(|_| "MCP 会话状态不可用".to_string())?
        .insert(library_id.clone(), authenticated.session);
    finish_library_add(&app, &library_id, initialization_epoch, init_options).await?;
    Ok(ConnectionSummary {
        space_id: library_id,
        space_name: account_name,
        server_name: authenticated.server_name,
        server_version: authenticated.server_version,
        tools: authenticated.tools,
        can_open_craft: false,
    })
}

async fn list_feishu_knowledge_spaces(
    client: &reqwest::Client,
    access_token: &str,
    account_name: Option<&str>,
) -> Result<Vec<FeishuKnowledgeSpace>, String> {
    let mut spaces = Vec::new();
    let mut page_token = String::new();
    for _ in 0..200 {
        let mut request = client
            .get("https://open.feishu.cn/open-apis/wiki/v2/spaces")
            .bearer_auth(access_token)
            .header("Accept", "application/json")
            .query(&[("page_size", "50")]);
        if !page_token.is_empty() {
            request = request.query(&[("page_token", page_token.as_str())]);
        }
        let value = request
            .send()
            .await
            .map_err(|error| format!("读取飞书知识空间失败：{error}"))?
            .error_for_status()
            .map_err(|error| format!("飞书知识空间请求被拒绝：{error}"))?
            .json::<Value>()
            .await
            .map_err(|error| format!("飞书知识空间响应无法解析：{error}"))?;
        if value["code"].as_i64().unwrap_or_default() != 0 {
            return Err(format!(
                "读取飞书知识空间失败：{}",
                value["msg"].as_str().unwrap_or("未知错误")
            ));
        }
        if let Some(items) = value["data"]["items"].as_array() {
            for item in items {
                let space_id = item["space_id"].as_str().unwrap_or_default().trim();
                if space_id.is_empty() {
                    continue;
                }
                spaces.push(FeishuKnowledgeSpace {
                    space_id: space_id.to_string(),
                    name: item["name"]
                        .as_str()
                        .filter(|value| !value.trim().is_empty())
                        .unwrap_or("未命名知识空间")
                        .to_string(),
                    description: item["description"].as_str().unwrap_or_default().to_string(),
                });
            }
        }
        if !value["data"]["has_more"].as_bool().unwrap_or(false) {
            break;
        }
        let next = value["data"]["page_token"].as_str().unwrap_or_default();
        if next.is_empty() || next == page_token {
            break;
        }
        page_token = next.to_string();
    }
    spaces.sort_by(|left, right| left.name.to_lowercase().cmp(&right.name.to_lowercase()));
    spaces.dedup_by(|left, right| left.space_id == right.space_id);
    spaces.insert(
        0,
        FeishuKnowledgeSpace {
            space_id: "my_library".to_string(),
            name: account_name
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .unwrap_or("我的文档")
                .to_string(),
            description: "飞书云空间中的普通文档和多维表格；不属于知识库的内容从这里同步"
                .to_string(),
        },
    );
    Ok(spaces)
}

#[tauri::command]
async fn connect_feishu(
    app: AppHandle,
    app_id: String,
    app_secret: String,
    init_options: Option<LibraryAddOptions>,
    state: State<'_, AppState>,
) -> Result<FeishuAuthorizationSummary, String> {
    // The second step chooses the concrete libraries and their staged options.
    let _ = init_options;
    let app_id = app_id.trim().to_string();
    let app_secret = app_secret.trim().to_string();
    if app_id.is_empty() || app_secret.is_empty() {
        return Err("请填写飞书开放平台应用的 App ID 和 App Secret".to_string());
    }
    let ipv4_listener = TcpListener::bind("127.0.0.1:17653")
        .await
        .map_err(|error| format!("无法启动飞书 OAuth 回调端口 17653：{error}"))?;
    // Browsers commonly resolve `localhost` to IPv6 first. Keep the registered
    // OAuth redirect URI on IPv4, while accepting a loopback callback on either
    // address family so browser/OS normalization cannot strand the callback.
    let ipv6_listener = TcpListener::bind("[::1]:17653").await.ok();
    let state_token = random_url_safe(24);
    let mut authorization_url =
        Url::parse(FEISHU_AUTHORIZE_URL).map_err(|error| format!("飞书授权地址无效：{error}"))?;
    authorization_url
        .query_pairs_mut()
        .append_pair("response_type", "code")
        .append_pair("client_id", &app_id)
        .append_pair("redirect_uri", FEISHU_REDIRECT_URI)
        .append_pair("state", &state_token)
        .append_pair("scope", FEISHU_SCOPES);
    open_external(&app, authorization_url.as_str())
        .map_err(|error| format!("无法打开飞书授权页面：{error}"))?;
    let callback = async {
        if let Some(ipv6_listener) = ipv6_listener {
            tokio::select! {
                result = wait_for_oauth_callback(ipv4_listener, &state_token) => result,
                result = wait_for_oauth_callback(ipv6_listener, &state_token) => result,
            }
        } else {
            wait_for_oauth_callback(ipv4_listener, &state_token).await
        }
    };
    let code = tokio::time::timeout(Duration::from_secs(600), callback)
        .await
        .map_err(|_| "飞书授权等待超时，请重新连接".to_string())??;
    let client = reqwest::Client::builder()
        .user_agent(concat!("Hub/", env!("CARGO_PKG_VERSION")))
        .build()
        .map_err(|error| format!("飞书 HTTP 客户端初始化失败：{error}"))?;
    let token_value = client
        .post(FEISHU_TOKEN_URL)
        .header("Accept", "application/json")
        .json(&json!({
            "grant_type": "authorization_code",
            "client_id": app_id,
            "client_secret": app_secret,
            "code": code,
            "redirect_uri": FEISHU_REDIRECT_URI
        }))
        .send()
        .await
        .map_err(|error| format!("飞书 OAuth Token 请求失败：{}", reqwest_error_chain(&error)))?
        .error_for_status()
        .map_err(|error| format!("飞书 OAuth Token 请求被拒绝：{error}"))?
        .json::<Value>()
        .await
        .map_err(|error| format!("飞书 OAuth Token 响应无法读取：{error}"))?;
    let token = parse_feishu_token_response(token_value)?;
    let authenticated = initialize_feishu_transport(&client, token.access_token.clone()).await?;
    for required in ["list-docs", "fetch-doc"] {
        if !authenticated.tools.iter().any(|tool| tool.name == required) {
            return Err(format!("飞书 MCP 没有提供只读工具 {required}"));
        }
    }
    let user_result = call_feishu_tool_raw(
        &client,
        &authenticated.session,
        "get-user",
        json!({}),
        29_001,
    )
    .await
    .ok();
    let (user_name, user_avatar_url) = feishu_user_identity(user_result.as_ref());
    let spaces = list_feishu_knowledge_spaces(
        &client,
        &authenticated.session.access_token,
        user_name.as_deref(),
    )
    .await?;
    let authorization_id = random_url_safe(32);
    let credential = StoredCredential {
        mcp_url: FEISHU_MCP_URL.to_string(),
        resource: String::new(),
        token_endpoint: FEISHU_TOKEN_URL.to_string(),
        client_id: app_id.clone(),
        client_secret: Some(app_secret),
        refresh_token: token.refresh_token,
        access_token: Some(token.access_token),
        expires_at: token
            .expires_in
            .and_then(|seconds| i64::try_from(seconds).ok())
            .map(|seconds| now_timestamp().saturating_add(seconds)),
    };
    // Persist the account-level authorization immediately. Task sync is an
    // account capability and must not depend on whether the user also selects
    // a Wiki/Docs source in the following step.
    let identity = user_result
        .as_ref()
        .map(tool_result_json)
        .and_then(|value| {
            find_nested_string(
                &value,
                &[
                    "open_id", "openId", "user_id", "userId", "union_id", "unionId",
                ],
            )
        })
        .or_else(|| user_name.clone())
        .unwrap_or_else(|| "default".to_string());
    let authorization_digest = encode_digest_hex(&Sha256::digest(
        format!("{}\n{}\ntasks", app_id, identity).as_bytes(),
    ));
    let account_authorization_id = format!("feishu-auth:{}", &authorization_digest[..24]);
    save_credential(&account_authorization_id, &credential)?;
    let authorization_database = database_path(&app)?;
    let saved_authorization_id = account_authorization_id.clone();
    let saved_authorization_name = user_name
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "飞书账号".to_string());
    let saved_authorization_app_id = app_id.clone();
    let saved_authorization_avatar = user_avatar_url.clone();
    tokio::task::spawn_blocking(move || {
        let (connection, _writer) = open_write_database(&authorization_database)?;
        connection
            .execute(
                "INSERT INTO feishu_authorizations
                   (id,name,app_id,enabled,added_at,metadata_json)
                 VALUES (?1,?2,?3,1,?4,?5)
                 ON CONFLICT(id) DO UPDATE SET name=excluded.name,app_id=excluded.app_id,
                   enabled=1,metadata_json=excluded.metadata_json",
                params![
                    saved_authorization_id,
                    saved_authorization_name,
                    saved_authorization_app_id,
                    now_timestamp(),
                    json!({
                        "accountAvatarUrl": saved_authorization_avatar,
                        "callbackUrl": FEISHU_REDIRECT_URI
                    })
                    .to_string()
                ],
            )
            .map(|_| ())
            .map_err(|error| format!("无法保存飞书账号授权：{error}"))
    })
    .await
    .map_err(|error| format!("保存飞书账号授权任务失败：{error}"))??;
    state
        .pending_feishu
        .lock()
        .map_err(|_| "飞书授权状态不可用".to_string())?
        .insert(
            authorization_id.clone(),
            PendingFeishuAuthorization {
                app_id,
                credential,
                session: authenticated.session,
                account_name: user_name.clone(),
                account_avatar_url: user_avatar_url,
                server_name: authenticated.server_name,
                server_version: authenticated.server_version,
                tools: authenticated.tools,
                spaces: spaces.clone(),
            },
        );
    Ok(FeishuAuthorizationSummary {
        authorization_id,
        account_name: user_name,
        spaces,
    })
}

#[tauri::command]
async fn add_feishu_spaces(
    app: AppHandle,
    init_options: Option<LibraryAddOptions>,
    authorization_id: String,
    space_ids: Vec<String>,
    state: State<'_, AppState>,
) -> Result<Vec<ConnectionSummary>, String> {
    if space_ids.is_empty() {
        return Err("请至少选择一个飞书文档来源".to_string());
    }
    let pending = state
        .pending_feishu
        .lock()
        .map_err(|_| "飞书授权状态不可用".to_string())?
        .remove(&authorization_id)
        .ok_or_else(|| "飞书授权已经失效，请重新登录".to_string())?;
    let selected = space_ids.into_iter().collect::<HashSet<_>>();
    let spaces = pending
        .spaces
        .iter()
        .filter(|space| selected.contains(&space.space_id))
        .cloned()
        .collect::<Vec<_>>();
    if spaces.len() != selected.len() {
        return Err("所选飞书文档来源不属于当前授权账号".to_string());
    }
    let database = database_path(&app)?;
    let tool_names = pending
        .tools
        .iter()
        .map(|tool| tool.name.clone())
        .collect::<Vec<_>>();
    let mut summaries = Vec::new();
    for space in spaces {
        let digest = encode_digest_hex(&Sha256::digest(
            format!("{}\n{}", pending.app_id, space.space_id).as_bytes(),
        ));
        let library_id = format!("feishu:{}", &digest[..24]);
        let location = format!("space:{}", space.space_id);
        let mut credential = pending.credential.clone();
        credential.resource = location.clone();
        save_credential(&library_id, &credential)?;
        let saved_id = library_id.clone();
        let initialization_epoch = prepare_library_add(&database, &library_id)?;
        let saved_name = space.name.clone();
        let saved_location = location.clone();
        let app_id = pending.app_id.clone();
        let account_name = pending.account_name.clone();
        let account_avatar_url = pending.account_avatar_url.clone();
        let space_id = space.space_id.clone();
        let saved_tools = tool_names.clone();
        let database = database.clone();
        tokio::task::spawn_blocking(move || {
            let (connection, _writer) = open_write_database(&database)?;
            connection.execute(
                "INSERT INTO libraries
                   (id,provider,name,location,enabled,added_at,last_sync,metadata_json)
                 VALUES (?1,'feishu',?2,?3,1,?4,NULL,?5)
                 ON CONFLICT(id) DO UPDATE SET provider='feishu',
                   name=CASE
                     WHEN COALESCE(json_extract(libraries.metadata_json,'$.displayNameCustomized'),0)=1
                     THEN libraries.name ELSE excluded.name END,
                   location=excluded.location,enabled=1,
                   metadata_json=json_patch(COALESCE(libraries.metadata_json,'{}'),excluded.metadata_json)",
                params![saved_id, saved_name, saved_location, now_timestamp(), json!({
                    "appId": app_id,
                    "accountName": account_name,
                    "accountAvatarUrl": account_avatar_url,
                    "feishuSpaceId": space_id,
                    "tools": saved_tools,
                    "callbackUrl": FEISHU_REDIRECT_URI
                }).to_string()],
            ).map_err(|error| format!("无法登记飞书知识空间：{error}"))?;
            Ok::<(), String>(())
        }).await.map_err(|error| format!("保存飞书知识空间任务失败：{error}"))??;
        let mut session = pending.session.clone();
        session.space_id = library_id.clone();
        session.space_name = space.name.clone();
        state
            .sessions
            .lock()
            .map_err(|_| "MCP 会话状态不可用".to_string())?
            .insert(library_id.clone(), session);
        finish_library_add(
            &app,
            &library_id,
            initialization_epoch,
            init_options.clone(),
        )
        .await?;
        summaries.push(ConnectionSummary {
            space_id: library_id,
            space_name: space.name,
            server_name: pending.server_name.clone(),
            server_version: pending.server_version.clone(),
            tools: pending.tools.clone(),
            can_open_craft: false,
        });
    }
    Ok(summaries)
}

#[tauri::command]
async fn add_feishu_bitable(
    app: AppHandle,
    source_library_id: String,
    url: String,
    init_options: Option<LibraryAddOptions>,
    state: State<'_, AppState>,
) -> Result<ConnectionSummary, String> {
    let link = parse_feishu_bitable_link(&url)?;
    let mut session = session_for_space(&state, source_library_id.trim())?;
    let source_credential = load_credential(source_library_id.trim())?;
    let database = database_path(&app)?;
    let source_id = source_library_id.trim().to_string();
    let source_metadata = tokio::task::spawn_blocking(move || {
        let connection = open_database(&database)?;
        connection
            .query_row(
                "SELECT metadata_json FROM libraries
                 WHERE id=?1 AND provider='feishu' AND enabled=1",
                params![source_id],
                |row| row.get::<_, Option<String>>(0),
            )
            .optional()
            .map_err(|error| format!("无法验证飞书授权来源：{error}"))
    })
    .await
    .map_err(|error| format!("飞书授权来源验证任务失败：{error}"))??;
    let Some(source_metadata) = source_metadata else {
        return Err("请选择一个已连接的飞书资料库作为授权来源".to_string());
    };
    let account_avatar_url = default_icon_url_from_metadata(source_metadata.as_deref());
    let account_name = source_metadata
        .as_deref()
        .and_then(|raw| serde_json::from_str::<Value>(raw).ok())
        .and_then(|value| {
            value
                .get("accountName")
                .and_then(Value::as_str)
                .map(str::to_string)
        });

    let client = reqwest::Client::builder()
        .user_agent(concat!("Hub/", env!("CARGO_PKG_VERSION")))
        .build()
        .map_err(|error| format!("飞书 HTTP 客户端初始化失败：{error}"))?;
    let name = feishu_bitable_name(&client, &session, &link.app_token).await?;
    let digest = encode_digest_hex(&Sha256::digest(
        format!(
            "{}\n{}\n{}",
            source_credential.client_id, link.app_token, link.table_id
        )
        .as_bytes(),
    ));
    let library_id = format!("feishu-base:{}", &digest[..24]);
    let mut credential = source_credential;
    credential.resource = link.url.clone();
    save_credential(&library_id, &credential)?;

    let database = database_path(&app)?;
    let saved_id = library_id.clone();
    let initialization_epoch = prepare_library_add(&database, &library_id)?;
    let saved_name = name.clone();
    let saved_url = link.url.clone();
    let app_token = link.app_token.clone();
    let table_id = link.table_id.clone();
    let view_id = link.view_id.clone();
    tokio::task::spawn_blocking(move || {
        let (connection, _writer) = open_write_database(&database)?;
        connection
            .execute(
                "INSERT INTO libraries
                   (id,provider,name,location,enabled,added_at,last_sync,metadata_json)
                 VALUES (?1,'feishu',?2,?3,1,?4,NULL,?5)
                 ON CONFLICT(id) DO UPDATE SET provider='feishu',name=excluded.name,
                   location=excluded.location,enabled=1,
                   metadata_json=json_patch(COALESCE(libraries.metadata_json,'{}'),excluded.metadata_json)",
                params![
                    saved_id,
                    saved_name,
                    saved_url,
                    now_timestamp(),
                    json!({
                        "kind": "bitable",
                        "appToken": app_token,
                        "tableId": table_id,
                        "viewId": view_id,
                        "sourceLibraryId": source_library_id.trim(),
                        "accountName": account_name,
                        "accountAvatarUrl": account_avatar_url
                    })
                    .to_string()
                ],
            )
            .map_err(|error| format!("无法登记飞书多维表格：{error}"))?;
        Ok::<(), String>(())
    })
    .await
    .map_err(|error| format!("保存飞书多维表格任务失败：{error}"))??;

    session.space_id = library_id.clone();
    session.space_name = name.clone();
    state
        .sessions
        .lock()
        .map_err(|_| "MCP 会话状态不可用".to_string())?
        .insert(library_id.clone(), session);
    finish_library_add(&app, &library_id, initialization_epoch, init_options).await?;
    Ok(ConnectionSummary {
        space_id: library_id,
        space_name: name,
        server_name: "Feishu Open API".to_string(),
        server_version: FEISHU_MCP_PROTOCOL_VERSION.to_string(),
        tools: Vec::new(),
        can_open_craft: false,
    })
}

#[tauri::command]
async fn craft_read(
    space_id: String,
    command: String,
    state: State<'_, AppState>,
) -> Result<Value, String> {
    let session = session_for_space(&state, &space_id)?;
    let client = reqwest::Client::new();
    call_craft_read_raw(&client, &session, command.trim(), 10).await
}

fn valid_craft_block_id(block_id: &str) -> bool {
    !block_id.is_empty()
        && block_id
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || character == '-')
}

fn craft_deep_link(
    space_id: &str,
    block_id: &str,
    state: &State<'_, AppState>,
) -> Result<String, String> {
    let block_id = block_id.trim();
    if !valid_craft_block_id(space_id) || !valid_craft_block_id(block_id) {
        return Err("Block ID 格式无效".to_string());
    }
    let template = state
        .sessions
        .lock()
        .ok()
        .and_then(|sessions| {
            sessions
                .get(space_id)
                .and_then(|session| session.deep_link_template.clone())
        })
        .unwrap_or_else(|| "craftdocs://open?spaceId={spaceId}&blockId={blockId}".to_string());
    Ok(template
        .replace("{spaceId}", space_id)
        .replace("{blockId}", block_id))
}

fn craft_client_page_url_from_web_url(
    web_url: &str,
    fallback_space_id: &str,
    fallback_document_id: &str,
) -> Option<String> {
    let parsed = Url::parse(web_url).ok()?;
    if parsed.scheme() != "https" || parsed.host_str()? != "docs.craft.do" {
        return None;
    }
    let segments = parsed.path_segments()?.collect::<Vec<_>>();
    let space_id = segments
        .windows(2)
        .find(|pair| pair[0] == "d")
        .map(|pair| pair[1])
        .filter(|value| valid_craft_block_id(value))
        .unwrap_or(fallback_space_id);
    if !valid_craft_block_id(space_id) {
        return None;
    }
    let page_id = segments
        .windows(2)
        .find(|pair| pair[0] == "b")
        .map(|pair| pair[1])
        .filter(|value| valid_craft_block_id(value))
        .or_else(|| valid_craft_block_id(fallback_document_id).then_some(fallback_document_id))?;
    let mut deep_link = Url::parse("craftdocs://open").ok()?;
    deep_link
        .query_pairs_mut()
        .append_pair("spaceId", space_id)
        .append_pair("blockId", page_id);
    Some(deep_link.to_string())
}

fn craft_web_block_url(
    space_id: &str,
    raw_document_id: &str,
    root_document_id: &str,
    structured: &Value,
    block_id: &str,
) -> Option<String> {
    if !valid_craft_block_id(space_id)
        || !valid_craft_block_id(raw_document_id)
        || !valid_craft_block_id(block_id)
    {
        return None;
    }
    let location = structured_block_location(structured, root_document_id, block_id)?;
    let mut url = Url::parse("https://docs.craft.do/editor/d").ok()?;
    {
        let mut segments = url.path_segments_mut().ok()?;
        segments.pop_if_empty();
        segments.push(space_id);
        segments.push(raw_document_id);
        if let Some(page_id) = location.page_id {
            segments.push("b");
            segments.push(&page_id);
            for title in location.page_titles {
                segments.push(&title);
            }
        }
    }
    url.set_fragment(Some(block_id));
    Some(url.to_string())
}

fn craft_web_fallback_url(
    space_id: &str,
    raw_document_id: &str,
    document_id: &str,
    page_id: &str,
    block_id: &str,
) -> Option<String> {
    if !valid_craft_block_id(space_id)
        || !valid_craft_block_id(raw_document_id)
        || !valid_craft_block_id(document_id)
        || !valid_craft_block_id(page_id)
        || !valid_craft_block_id(block_id)
    {
        return None;
    }
    let mut url = Url::parse("https://docs.craft.do/editor/d").ok()?;
    {
        let mut segments = url.path_segments_mut().ok()?;
        segments.pop_if_empty();
        segments.push(space_id);
        segments.push(raw_document_id);
        if page_id != document_id {
            segments.push("b");
            segments.push(page_id);
        }
    }
    url.set_fragment(Some(block_id));
    Some(url.to_string())
}

fn structured_resource_block_id(structured: &Value, remote_url: &str) -> Option<String> {
    let remote_url = remote_url.trim();
    if remote_url.is_empty() {
        return None;
    }
    structured_block_hints(structured)
        .into_iter()
        .filter(|hint| hint.markdown.contains(remote_url))
        .min_by_key(|hint| hint.markdown.len())
        .map(|hint| hint.id)
}

async fn result_url(
    app: &AppHandle,
    library_id: &str,
    document_id: &str,
    result_id: Option<&str>,
    fallback_block_id: &str,
    fallback_page_id: Option<&str>,
    match_field: Option<&str>,
    match_terms: &[String],
    require_craft_https: bool,
    state: &State<'_, AppState>,
) -> Result<String, String> {
    let path = database_path(app)?;
    let connection = open_database(&path)?;
    let (provider, _library_name, document_path, mut raw_document_id): (
        String,
        String,
        String,
        Option<String>,
    ) = connection
        .query_row(
            "SELECT l.provider,l.name,d.path,d.raw_document_id
             FROM documents d JOIN libraries l ON l.id=d.space_id
             WHERE d.space_id=?1 AND d.id=?2",
            params![library_id, document_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .map_err(|error| format!("无法读取结果打开目标：{error}"))?;
    match provider.as_str() {
        PROVIDER_CRAFT => {
            let location_info =
                result_id
                    .filter(|value| !value.trim().is_empty())
                    .and_then(|result_id| {
                        if let Some(source_item_id) = result_id.strip_prefix("attachment-meta:") {
                            return connection
                                .query_row(
                                    "SELECT COALESCE(json_extract(metadata_json,'$.blockId'),''),
                                        COALESCE(json_extract(metadata_json,'$.remoteUrl'),'')
                                 FROM source_items
                                 WHERE id=?1 AND space_id=?2 AND document_id=?3",
                                    params![source_item_id, library_id, document_id],
                                    |row| {
                                        let page_id = row.get::<_, String>(0)?;
                                        Ok((
                                            page_id.clone(),
                                            page_id,
                                            String::new(),
                                            String::new(),
                                            row.get::<_, String>(1)?,
                                        ))
                                    },
                                )
                                .optional()
                                .ok()
                                .flatten();
                        }
                        connection
                            .query_row(
                                "SELECT ci.block_id,ci.page_id,ci.heading,ci.body,
                                    COALESCE(json_extract(s.metadata_json,'$.blockId'),''),
                                    COALESCE(json_extract(s.metadata_json,'$.remoteUrl'),'')
                             FROM content_items ci
                             LEFT JOIN source_items s ON s.id=ci.source_item_id
                             WHERE ci.id=?1 AND ci.space_id=?2 AND ci.document_id=?3",
                                params![result_id, library_id, document_id],
                                |row| {
                                    let content_block_id = row.get::<_, String>(0)?;
                                    let content_page_id = row.get::<_, String>(1)?;
                                    let stored_page_id = row.get::<_, String>(4)?;
                                    let remote_url = row.get::<_, String>(5)?;
                                    let page_id = if valid_craft_block_id(stored_page_id.trim()) {
                                        stored_page_id
                                    } else {
                                        content_page_id
                                    };
                                    let target_block_id = if remote_url.trim().is_empty() {
                                        content_block_id
                                    } else {
                                        page_id.clone()
                                    };
                                    Ok((
                                        target_block_id,
                                        page_id,
                                        row.get::<_, String>(2)?,
                                        row.get::<_, String>(3)?,
                                        remote_url,
                                    ))
                                },
                            )
                            .optional()
                            .ok()
                            .flatten()
                    });
            let mut target_block_id = location_info
                .as_ref()
                .map(|(target, _, _, _, _)| target.clone())
                .filter(|value| valid_craft_block_id(value.trim()))
                .unwrap_or_else(|| fallback_block_id.to_string());
            let fallback_page_id = location_info
                .as_ref()
                .map(|(_, page_id, _, _, _)| page_id.clone())
                .filter(|value| valid_craft_block_id(value.trim()))
                .or_else(|| {
                    fallback_page_id
                        .filter(|value| valid_craft_block_id(value.trim()))
                        .map(str::to_string)
                })
                .unwrap_or_else(|| document_id.to_string());
            // Search results already carry stable Craft block/page IDs, and a synced
            // document normally has its raw document ID. That is enough to build an
            // official HTTPS URL immediately. Previously every click waited for a
            // fresh `blocks get --depth -1` network request before opening it.
            if require_craft_https {
                if let Some(url) = raw_document_id.as_deref().and_then(|raw_document_id| {
                    craft_web_fallback_url(
                        library_id,
                        raw_document_id,
                        document_id,
                        &fallback_page_id,
                        &target_block_id,
                    )
                }) {
                    return Ok(url);
                }
            }
            drop(connection);
            if let Ok(session) = session_for_space(state, library_id) {
                let client = reqwest::Client::new();
                let parsed = call_craft_read_raw(
                    &client,
                    &session,
                    &format!("blocks get {document_id} --depth -1 --format json"),
                    80_001,
                )
                .await
                .ok()
                .map(|structured| parse_tool_json(&structured).unwrap_or(structured));
                if let Some(parsed) = parsed.as_ref() {
                    if let Some((_, parent_page_id, heading, body, remote_url)) =
                        location_info.as_ref()
                    {
                        if let Some(exact_block_id) =
                            structured_resource_block_id(&parsed, remote_url)
                        {
                            target_block_id = exact_block_id;
                        } else if match_field
                            .unwrap_or_default()
                            .split(',')
                            .any(|field| field.trim() == "body")
                        {
                            let hints = structured_block_hints(&parsed);
                            if let Some(exact_block_id) =
                                structured_body_block_id(parent_page_id, body, match_terms, &hints)
                            {
                                target_block_id = exact_block_id;
                            } else if let Some(exact_block_id) =
                                structured_block_id(parent_page_id, heading, body, &hints)
                            {
                                target_block_id = exact_block_id;
                            }
                        } else if !heading.trim().is_empty() || !body.trim().is_empty() {
                            if let Some(exact_block_id) = structured_block_id(
                                parent_page_id,
                                heading,
                                body,
                                &structured_block_hints(&parsed),
                            ) {
                                target_block_id = exact_block_id;
                            }
                        }
                    }
                    if let Some(url) = raw_document_id.as_deref().and_then(|raw_document_id| {
                        craft_web_block_url(
                            library_id,
                            raw_document_id,
                            document_id,
                            &parsed,
                            &target_block_id,
                        )
                    }) {
                        return Ok(url);
                    }
                    if let Some(url) = structured_block_url(&parsed, &target_block_id) {
                        return Ok(url);
                    }
                }
                if raw_document_id.is_none() {
                    if let Ok(documents) = list_all_documents(&client, &session).await {
                        let mappings = documents
                            .iter()
                            .filter_map(|document| {
                                document
                                    .raw_document_id
                                    .as_ref()
                                    .map(|raw_id| (document.id.clone(), raw_id.clone()))
                            })
                            .collect::<Vec<_>>();
                        raw_document_id = documents
                            .iter()
                            .find(|document| document.id == document_id)
                            .and_then(|document| document.raw_document_id.clone());
                        let _ = persist_craft_raw_document_ids(&path, library_id, &mappings);
                    }
                }
            }
            if let Some(url) = raw_document_id.as_deref().and_then(|raw_document_id| {
                craft_web_fallback_url(
                    library_id,
                    raw_document_id,
                    document_id,
                    &fallback_page_id,
                    &target_block_id,
                )
            }) {
                return Ok(url);
            }
            if require_craft_https {
                return Err(
                    "无法生成 Craft 官方 HTTPS 精准链接，请确认资料库已连接后重新同步".to_string(),
                );
            }
            craft_deep_link(library_id, &fallback_page_id, state)
        }
        PROVIDER_OBSIDIAN => obsidian_open_url(
            &library_location::vault_name(&connection, library_id)?,
            &document_path,
        ),
        PROVIDER_DIDA365 => connection
            .query_row(
                "SELECT project_id FROM dida_tasks
                 WHERE library_id=?1 AND task_id=?2",
                params![library_id, document_id],
                |row| row.get::<_, String>(0),
            )
            .optional()
            .map_err(|error| format!("无法读取滴答任务链接：{error}"))?
            .map(|project_id| dida_task_url(&project_id, document_id))
            .ok_or_else(|| "滴答任务没有可打开的链接".to_string()),
        PROVIDER_FEISHU => raw_document_id
            .as_deref()
            .and_then(|value| normalize_feishu_document_url(value, document_id))
            .or_else(|| normalize_feishu_document_url("", document_id))
            .ok_or_else(|| "飞书文档没有可打开的 HTTPS 链接".to_string()),
        _ => Err(format!("不支持的数据源：{provider}")),
    }
}

#[tauri::command]
async fn open_result(
    app: AppHandle,
    library_id: String,
    document_id: String,
    block_id: String,
    page_id: Option<String>,
    result_id: Option<String>,
    open_mode: Option<String>,
    match_field: Option<String>,
    match_terms: Option<Vec<String>>,
    state: State<'_, AppState>,
) -> Result<OpenResultOutcome, String> {
    let provider = {
        let path = database_path(&app)?;
        let connection = open_database(&path)?;
        connection
            .query_row(
                "SELECT provider FROM libraries WHERE id=?1 AND enabled=1",
                params![library_id],
                |row| row.get::<_, String>(0),
            )
            .map_err(|_| "找不到搜索结果所属的资料库".to_string())?
    };
    let open_mode =
        normalize_craft_open_mode(open_mode.as_deref().unwrap_or(CRAFT_OPEN_MODE_BRIDGE))
            .unwrap_or(CRAFT_OPEN_MODE_BRIDGE);
    // Android Craft opens official web links; desktop bridge/client settings do not apply.
    #[cfg(target_os = "android")]
    let open_mode = CRAFT_OPEN_MODE_WEB;
    let url = result_url(
        &app,
        &library_id,
        &document_id,
        result_id.as_deref(),
        &block_id,
        page_id.as_deref(),
        match_field.as_deref(),
        match_terms.as_deref().unwrap_or_default(),
        provider == PROVIDER_CRAFT && open_mode != CRAFT_OPEN_MODE_CLIENT,
        &state,
    )
    .await?;
    if provider == PROVIDER_CRAFT && open_mode == CRAFT_OPEN_MODE_BRIDGE {
        let action = open_craft_via_bridge(&url).await?;
        return Ok(OpenResultOutcome {
            craft_bridge_action: Some(action),
        });
    }
    let target = if provider == PROVIDER_CRAFT && open_mode == CRAFT_OPEN_MODE_CLIENT {
        craft_client_page_url_from_web_url(&url, &library_id, &document_id).unwrap_or(url)
    } else {
        url
    };
    open_external(&app, &target).map_err(|error| format!("无法打开搜索结果：{error}"))?;
    Ok(OpenResultOutcome {
        craft_bridge_action: None,
    })
}

#[tauri::command]
async fn open_craft_url(url: String) -> Result<OpenResultOutcome, String> {
    let action = open_craft_via_bridge(url.trim()).await?;
    Ok(OpenResultOutcome {
        craft_bridge_action: Some(action),
    })
}

#[tauri::command]
async fn get_craft_bridge_status() -> CraftBridgeStatus {
    let client = match craft_bridge_client() {
        Ok(client) => client,
        Err(error) => {
            return CraftBridgeStatus {
                available: false,
                version: None,
                message: error,
            }
        }
    };
    match check_craft_bridge_health(client).await {
        Ok(version) => CraftBridgeStatus {
            available: true,
            message: format!("CraftBridge {version} 已连接"),
            version: Some(version),
        },
        Err(error) => CraftBridgeStatus {
            available: false,
            version: None,
            message: error,
        },
    }
}

