    #[test]
    fn managed_craft_detail_blocks_remain_part_of_reverse_sync_source() {
        let hints = vec![
            StructuredBlockHint {
                id: "task".into(),
                parent_page_id: "page".into(),
                parent_task_id: None,
                markdown: "任务".into(),
                task_completed: Some(false),
                task_schedule_date: None,
                task_deadline_date: None,
                task_created_at: None,
                indentation_level: None,
            },
            StructuredBlockHint {
                id: "managed".into(),
                parent_page_id: "page".into(),
                parent_task_id: Some("task".into()),
                markdown: "来自滴答的镜像正文".into(),
                task_completed: None,
                task_schedule_date: None,
                task_deadline_date: None,
                task_created_at: None,
                indentation_level: None,
            },
            StructuredBlockHint {
                id: "user".into(),
                parent_page_id: "page".into(),
                parent_task_id: Some("task".into()),
                markdown: "用户在 Craft 新增的正文".into(),
                task_completed: None,
                task_schedule_date: None,
                task_deadline_date: None,
                task_created_at: None,
                indentation_level: None,
            },
        ];
        let exclusions = ManagedCraftExclusions {
            always_excluded_ids: HashSet::new(),
        };
        let details = craft_task_details_excluding(&hints, &exclusions);
        assert_eq!(
            details.get("task").map(String::as_str),
            Some("来自滴答的镜像正文\n\n用户在 Craft 新增的正文")
        );

        let mut edited_hints = hints;
        edited_hints[1].markdown = "用户在 Craft 修改了原镜像正文".into();
        let edited_details = craft_task_details_excluding(&edited_hints, &exclusions);
        assert_eq!(
            edited_details.get("task").map(String::as_str),
            Some("用户在 Craft 修改了原镜像正文\n\n用户在 Craft 新增的正文")
        );

        let image_hint = StructuredBlockHint {
            id: "managed-image".into(),
            parent_page_id: "page".into(),
            parent_task_id: Some("task".into()),
            markdown: "![Image](https://r.craft.do/old)".into(),
            task_completed: None,
            task_schedule_date: None,
            task_deadline_date: None,
            task_created_at: None,
            indentation_level: None,
        };
        let image_exclusions = ManagedCraftExclusions {
            always_excluded_ids: HashSet::new(),
        };
        assert_eq!(
            craft_task_details_excluding(&[image_hint.clone()], &image_exclusions)
                .get("task")
                .map(String::as_str),
            Some("![Image](https://r.craft.do/old)")
        );
        let mut replaced_image = image_hint;
        replaced_image.markdown = "![Image](https://r.craft.do/new)".into();
        assert_eq!(
            craft_task_details_excluding(&[replaced_image], &image_exclusions)
                .get("task")
                .map(String::as_str),
            Some("![Image](https://r.craft.do/new)")
        );
    }

    #[test]
    fn managed_craft_blocks_upgrade_legacy_ids_and_keep_item_mappings() {
        let legacy = decode_managed_craft_blocks("[\"old-image\",\"old-body\"]");
        assert!(legacy.legacy);
        assert_eq!(legacy.retired_block_ids.len(), 2);

        let state = ManagedCraftBlocks {
            body_hash: "body-hash".into(),
            body_block_ids: vec!["body-1".into(), "body-2".into()],
            body_block_hashes: BTreeMap::new(),
            attachments: BTreeMap::from([("blob-a".into(), "image-a".into())]),
            attachment_pending_moves: HashSet::new(),
            retired_block_ids: vec!["old".into()],
            legacy: false,
        };
        let decoded = decode_managed_craft_blocks(&serde_json::to_string(&state).unwrap());
        assert!(!decoded.legacy);
        assert_eq!(
            decoded.attachments.get("blob-a").map(String::as_str),
            Some("image-a")
        );
        assert_eq!(decoded.all_block_ids().count(), 4);
    }

