    #[tokio::test]
    async fn preview_cache_completion_preserves_running_and_source_scope() {
        let path = unique_test_path("hub-preview-cache-queue").with_extension("sqlite3");
        let root = path.with_extension("blobs");
        let store = BlobStore::open(&root).unwrap();
        let blob = store.put(b"downloaded ordinary attachment").unwrap();
        let c = open_database(&path).unwrap();
        c.execute("INSERT INTO spaces(id,name,mcp_url,added_at) VALUES('library','Library','https://example.test/mcp',1)",[]).unwrap();
        c.execute("INSERT INTO libraries(id,provider,name,enabled,added_at) VALUES('library','dida365','Library',1,1)",[]).unwrap();
        c.execute("INSERT INTO documents(space_id,id,title,path,markdown,indexed_at,content_hash,provider) VALUES('library','doc','Doc','Doc','body',1,'body','dida365')",[]).unwrap();
        for (id, status, remote) in [
            ("pending", "pending", "https://api.dida365.com/attachment"),
            ("failed", "failed", "https://api.dida365.com/attachment"),
            ("running", "running", "https://api.dida365.com/attachment"),
            ("other", "pending", "https://api.dida365.com/other"),
        ] {
            c.execute("INSERT INTO source_items(id,space_id,document_id,remote_id,source_type,title,mime_type,status,metadata_json,created_at,updated_at,provider) VALUES(?1,'library','doc',?1,'dida_attachment',?1,'video/mp4','discovered',?2,1,1,'dida365')",params![id,json!({"remoteUrl":remote}).to_string()]).unwrap();
            c.execute("INSERT INTO index_jobs(job_key,space_id,source_id,source_type,job_type,status,created_at,updated_at,worker_id) VALUES(?1,'library',?1,'dida_attachment','download_source',?2,1,1,'owner')",params![id,status]).unwrap();
        }
        let source = "0123456789abcdef01234567/video.mp4";
        let running = read_preview_download_capture(
            &path,
            PROVIDER_DIDA365,
            "library",
            "doc",
            source,
            Some("running"),
        )
        .unwrap();
        let running_lease = attachment_resource_cache::acquire(
            &path,
            "library",
            PROVIDER_DIDA365,
            &running.metadata,
        )
        .await
        .unwrap();
        let downloaded = DownloadedSource {
            blob,
            mime_type: "video/mp4".into(),
        };
        persist_preview_media_download(&path, &running, &running_lease, &downloaded).unwrap();
        drop(running_lease);
        for (id, status) in [
            ("pending", "pending"),
            ("failed", "failed"),
            ("running", "running"),
            ("other", "pending"),
        ] {
            assert_eq!(
                c.query_row(
                    "SELECT status FROM index_jobs WHERE source_id=?1",
                    [id],
                    |row| row.get::<_, String>(0)
                )
                .unwrap(),
                status
            );
        }
        assert_eq!(
            c.query_row(
                "SELECT worker_id FROM index_jobs WHERE source_id='running'",
                [],
                |row| row.get::<_, String>(0)
            )
            .unwrap(),
            "owner"
        );
        for id in ["pending", "failed", "other"] {
            assert!(c
                .query_row(
                    "SELECT blob_hash FROM source_items WHERE id=?1",
                    [id],
                    |row| row.get::<_, Option<String>>(0)
                )
                .unwrap()
                .is_none());
        }
        let pending = read_preview_download_capture(
            &path,
            PROVIDER_DIDA365,
            "library",
            "doc",
            source,
            Some("pending"),
        )
        .unwrap();
        let pending_lease = attachment_resource_cache::acquire(
            &path,
            "library",
            PROVIDER_DIDA365,
            &pending.metadata,
        )
        .await
        .unwrap();
        persist_preview_media_download(&path, &pending, &pending_lease, &downloaded).unwrap();
        drop(pending_lease);
        assert_eq!(
            c.query_row(
                "SELECT status FROM index_jobs WHERE source_id='pending'",
                [],
                |row| row.get::<_, String>(0)
            )
            .unwrap(),
            "completed"
        );
        assert_eq!(
            c.query_row(
                "SELECT status,worker_id FROM index_jobs WHERE source_id='running'",
                [],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            )
            .unwrap(),
            ("running".into(), "owner".into())
        );
        assert_eq!(
            c.query_row(
                "SELECT status FROM index_jobs WHERE source_id='failed'",
                [],
                |row| row.get::<_, String>(0)
            )
            .unwrap(),
            "failed"
        );
        for id in ["failed", "other"] {
            assert!(c
                .query_row(
                    "SELECT blob_hash FROM source_items WHERE id=?1",
                    [id],
                    |row| row.get::<_, Option<String>>(0)
                )
                .unwrap()
                .is_none());
        }
        drop(c);
        remove_test_database(&path);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn dida_attachment_discovery_queues_an_authenticated_download() {
        let path = unique_test_path("hub-dida-attachment-queue").with_extension("sqlite3");
        let (mut connection, _writer) = open_write_database(&path).unwrap();
        let transaction = connection.transaction().unwrap();
        let task = DidaTask {
            id: "task-1".into(),
            project_id: "project-1".into(),
            title: "图片任务".into(),
            content: "![image](0123456789abcdef01234567/photo.png)".into(),
            description: String::new(),
            kind: "TEXT".into(),
            status: 0,
            priority: 0,
            start_date: None,
            due_date: None,
            created_time: None,
            modified_time: None,
            completed_time: None,
            time_zone: None,
            column_id: None,
            column_name: None,
            parent_id: None,
            tags: Vec::new(),
            items: Vec::new(),
            attachments: Vec::new(),
            raw: json!({}),
        };
        upsert_dida_attachments(&transaction, "dida-library", &task, 1).unwrap();
        transaction.commit().unwrap();
        let job: (String, String, String) = connection
            .query_row(
                "SELECT source_type,job_type,status FROM index_jobs WHERE source_id LIKE 'dida_attachment:%'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(
            job,
            (
                "dida_attachment".into(),
                "download_source".into(),
                "pending".into()
            )
        );
        // Seeing the same attachment must preserve an in-flight owner and
        // durable retry state. Only a changed authenticated source may requeue.
        for state in ["pending", "running", "failed", "completed"] {
            connection.execute("UPDATE index_jobs SET status=?1,attempts=4,next_attempt_at=999,worker_id='owned-worker',last_error='saved failure'",[state]).unwrap();
            let transaction = connection.transaction().unwrap();
            upsert_dida_attachments(&transaction, "dida-library", &task, 2).unwrap();
            transaction.commit().unwrap();
            let saved: (String, i64, i64, String, String) = connection
                .query_row(
                    "SELECT status,attempts,next_attempt_at,worker_id,last_error FROM index_jobs",
                    [],
                    |row| {
                        Ok((
                            row.get(0)?,
                            row.get(1)?,
                            row.get(2)?,
                            row.get(3)?,
                            row.get(4)?,
                        ))
                    },
                )
                .unwrap();
            assert_eq!(
                saved,
                (
                    state.into(),
                    4,
                    999,
                    "owned-worker".into(),
                    "saved failure".into()
                )
            );
        }
        connection
            .execute("UPDATE source_items SET status='unavailable'", [])
            .unwrap();
        let transaction = connection.transaction().unwrap();
        upsert_dida_attachments(&transaction, "dida-library", &task, 3).unwrap();
        transaction.commit().unwrap();
        assert_eq!(
            connection
                .query_row("SELECT status FROM source_items", [], |row| row
                    .get::<_, String>(0))
                .unwrap(),
            "unavailable"
        );
        let changed = DidaTask {
            project_id: "moved-project".into(),
            ..task.clone()
        };
        let transaction = connection.transaction().unwrap();
        upsert_dida_attachments(&transaction, "dida-library", &changed, 4).unwrap();
        transaction.commit().unwrap();
        assert_eq!(
            connection
                .query_row(
                    "SELECT status,attempts,next_attempt_at FROM index_jobs",
                    [],
                    |row| Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, i64>(1)?,
                        row.get::<_, i64>(2)?
                    ))
                )
                .unwrap(),
            ("pending".into(), 0, 0)
        );
        let removed = DidaTask {
            content: String::new(),
            raw: json!({"attachments": []}),
            ..task.clone()
        };
        let transaction = connection.transaction().unwrap();
        upsert_dida_attachments(&transaction, "dida-library", &removed, 2).unwrap();
        transaction.commit().unwrap();
        let remaining: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM source_items WHERE provider='dida365' AND source_type='dida_attachment' AND document_id='task-1'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(remaining, 0);
        drop(connection);
        remove_test_database(&path);
    }

