    #[test]
    fn dida_empty_lookup_requires_inventory_absence_and_a_healthy_control_lookup() {
        let empty =
            "Error executing tool get_task_by_id: Expecting value: line 1 column 1 (char 0)";
        assert!(dida_empty_json_response_error(empty));
        assert!(dida_empty_lookup_confirms_missing(true, true, empty));
        assert!(!dida_empty_lookup_confirms_missing(false, true, empty));
        assert!(!dida_empty_lookup_confirms_missing(true, false, empty));
        assert!(!dida_empty_lookup_confirms_missing(
            true,
            true,
            "HTTP 503 Service Unavailable"
        ));
        assert!(dida_empty_success_lookup_confirms_missing(
            true, true, None, ""
        ));
        assert!(!dida_empty_success_lookup_confirms_missing(
            true, false, None, ""
        ));
        assert!(!dida_empty_success_lookup_confirms_missing(
            false, true, None, ""
        ));
        assert!(!dida_empty_success_lookup_confirms_missing(
            true,
            true,
            Some(2),
            ""
        ));
        assert!(!dida_empty_success_lookup_confirms_missing(
            true, true, None, "{}"
        ));
    }

    #[test]
    fn task_background_sync_scheduler_respects_interval_and_claims_once() {
        let path = unique_test_path("hub-task-background-sync").with_extension("sqlite3");
        let connection = open_database(&path).unwrap();
        let old = now_timestamp() - 16 * 60;
        connection
            .execute(
                "UPDATE task_sync_settings
                 SET enabled=1,background_sync_interval_minutes=15,
                     last_background_sync_attempt_at=?1,updated_at=?1 WHERE id=1",
                [old],
            )
            .unwrap();
        drop(connection);

        assert!(claim_task_background_sync_due(&path).unwrap());
        assert!(!claim_task_background_sync_due(&path).unwrap());

        let connection = open_database(&path).unwrap();
        connection
            .execute(
                "UPDATE task_sync_settings
                 SET background_sync_interval_minutes=0,
                     last_background_sync_attempt_at=?1 WHERE id=1",
                [old],
            )
            .unwrap();
        drop(connection);
        assert!(!claim_task_background_sync_due(&path).unwrap());
        remove_test_database(&path);
    }

