    #[test]
    fn excluded_craft_parent_effectively_excludes_descendants() {
        let mut parent = test_sync_record(PROVIDER_CRAFT, "craft-space", "project");
        parent.is_project_page = true;
        let mut child = test_sync_record(PROVIDER_CRAFT, "craft-space", "child");
        child.parent_source_id = parent.source_id.clone();
        let mut grandchild = test_sync_record(PROVIDER_CRAFT, "craft-space", "grandchild");
        grandchild.parent_source_id = child.source_id.clone();
        let records = vec![parent, child.clone(), grandchild.clone()];
        let exclusions = HashSet::from([(
            PROVIDER_CRAFT.to_string(),
            "craft-space".to_string(),
            "project".to_string(),
        )]);

        assert!(task_sync_source_or_ancestor_is_excluded(
            &records,
            &exclusions,
            &child
        ));
        assert!(task_sync_source_or_ancestor_is_excluded(
            &records,
            &exclusions,
            &grandchild
        ));
        assert!(!task_sync_source_or_ancestor_is_excluded(
            &records,
            &HashSet::new(),
            &grandchild
        ));
    }

    #[test]
    fn excluded_virtual_project_keeps_its_tasks_synced_as_roots() {
        let mut project = test_sync_record(PROVIDER_CRAFT, "craft-space", "project");
        project.is_project_page = true;
        let mut child = test_sync_record(PROVIDER_CRAFT, "craft-space", "child");
        child.parent_source_id = project.source_id.clone();
        let mut grandchild = test_sync_record(PROVIDER_CRAFT, "craft-space", "grandchild");
        grandchild.parent_source_id = child.source_id.clone();
        let mut other_project = test_sync_record(PROVIDER_CRAFT, "craft-space", "other-project");
        other_project.is_project_page = true;
        let mut other_child = test_sync_record(PROVIDER_CRAFT, "craft-space", "other-child");
        other_child.parent_source_id = other_project.source_id.clone();
        let mut records = vec![project, child, grandchild, other_project, other_child];
        let exclusions = HashSet::from([(
            PROVIDER_CRAFT.to_string(),
            "craft-space".to_string(),
            "project".to_string(),
        )]);

        assert_eq!(
            flatten_children_of_excluded_craft_projects(&mut records, &exclusions),
            1
        );
        assert_eq!(records[1].parent_source_id, "");
        assert_eq!(records[2].parent_source_id, "child");
        assert_eq!(records[4].parent_source_id, "other-project");
        assert!(!task_sync_source_or_ancestor_is_excluded(
            &records,
            &exclusions,
            &records[1]
        ));
        assert!(!task_sync_source_or_ancestor_is_excluded(
            &records,
            &exclusions,
            &records[2]
        ));
    }

    #[test]
    fn accepted_dida_metadata_normalization_is_idempotent_until_remote_changes() {
        let desired = task_sync_metadata_fingerprint(
            "[Craft 来源](https://docs.craft.do/source)",
            &["Craft".into(), "Car".into()],
            "parent",
        );
        let normalized = task_sync_metadata_fingerprint(
            "Craft 来源：https://docs.craft.do/source",
            &["craft".into(), "car".into()],
            "parent",
        );
        let token = task_sync_metadata_normalization_token(&desired, &normalized);

        assert!(task_sync_metadata_normalization_accepted(
            Some(&token),
            &desired,
            &normalized,
            true
        ));
        let changed = task_sync_metadata_fingerprint(
            "用户修改了详情",
            &["craft".into(), "car".into()],
            "parent",
        );
        assert!(!task_sync_metadata_normalization_accepted(
            Some(&token),
            &desired,
            &changed,
            true
        ));
        assert!(!task_sync_metadata_normalization_accepted(
            Some(&token),
            &desired,
            &normalized,
            false
        ));
    }

    #[test]
    fn pending_conflict_is_failed_until_forced_snapshot_is_replaced() {
        let path = unique_test_path("hub-pending-conflict-state").with_extension("sqlite3");
        let (connection, writer) = open_write_database(&path).unwrap();
        connection
            .execute(
                "INSERT INTO task_sync_events
                   (hub_task_id,origin_provider,target_provider,action,status,payload_json,
                    idempotency_key,attempts,created_at,updated_at,last_error)
                 VALUES ('hub','craft','dida365','conflict','pending','{}','conflict:hub',0,1,1,NULL)",
                [],
            )
            .unwrap();
        connection
            .execute(
                "INSERT INTO task_sync_snapshots(hub_task_id,provider,source_hash,applied_hash,synced_at)
                 VALUES ('hub','craft','force-conflict-resolution:craft_wins:1','x',1)",
                [],
            )
            .unwrap();
        connection
            .execute_batch(
                "INSERT INTO unified_task_bindings
                   (hub_task_id,provider,library_id,source_id,document_id,source_hash,last_seen_at,missing_syncs)
                 VALUES ('hub','dida365','dida-lib','dida-task','','actual',1,0);
                 INSERT INTO dida_tasks
                   (library_id,task_id,project_id,title,raw_json,last_seen_at)
                 VALUES ('dida-lib','dida-task','project','Task','{}',1);",
            )
            .unwrap();
        drop(connection);
        drop(writer);
        reconcile_pending_task_conflicts(&path).unwrap();
        let (connection, writer) = open_write_database(&path).unwrap();
        let status: String = connection
            .query_row(
                "SELECT status FROM task_sync_events WHERE hub_task_id='hub'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(status, "failed");
        connection
            .execute(
                "UPDATE task_sync_snapshots SET source_hash='actual' WHERE hub_task_id='hub'",
                [],
            )
            .unwrap();
        drop(connection);
        drop(writer);
        reconcile_pending_task_conflicts(&path).unwrap();
        let connection = open_database(&path).unwrap();
        let status: String = connection
            .query_row(
                "SELECT status FROM task_sync_events WHERE hub_task_id='hub'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(status, "resolved");
        drop(connection);
        remove_test_database(&path);
    }

    #[test]
    fn dismissing_pending_conflict_clears_retry_marker_without_removing_bindings() {
        let path = unique_test_path("hub-dismiss-pending-conflict").with_extension("sqlite3");
        let (connection, writer) = open_write_database(&path).unwrap();
        connection
            .execute_batch(
                "INSERT INTO unified_task_bindings
                   (hub_task_id,provider,library_id,source_id,document_id,source_hash,last_seen_at,missing_syncs)
                 VALUES ('hub','craft','craft-lib','craft-task','doc','craft-applied',1,0);
                 INSERT INTO unified_task_bindings
                   (hub_task_id,provider,library_id,source_id,document_id,source_hash,last_seen_at,missing_syncs)
                 VALUES ('hub','dida365','dida-lib','dida-task','','dida-applied',1,0);
                 INSERT INTO task_sync_snapshots
                   (hub_task_id,provider,source_hash,applied_hash,synced_at)
                 VALUES ('hub','craft','merge-request:1','merge-request:1',1);
                 INSERT INTO task_sync_snapshots
                   (hub_task_id,provider,source_hash,applied_hash,synced_at)
                 VALUES ('hub','dida365','merge-request:1','merge-request:1',1);
                 INSERT INTO task_sync_events
                   (hub_task_id,origin_provider,target_provider,action,status,payload_json,
                    idempotency_key,attempts,created_at,updated_at,last_error)
                 VALUES ('hub','craft','dida365','conflict','failed','{}','conflict:hub',0,1,1,'retry');",
            )
            .unwrap();
        let event_id: i64 = connection
            .query_row(
                "SELECT id FROM task_sync_events WHERE hub_task_id='hub'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        drop(connection);
        drop(writer);

        assert_eq!(
            dismiss_pending_task_conflicts(&path, &[event_id]).unwrap(),
            1
        );
        let connection = open_database(&path).unwrap();
        let event: (String, Option<String>) = connection
            .query_row(
                "SELECT status,last_error FROM task_sync_events WHERE id=?1",
                [event_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(event, ("resolved".to_string(), None));
        let snapshots = connection
            .prepare(
                "SELECT provider,source_hash,applied_hash FROM task_sync_snapshots
                 WHERE hub_task_id='hub' ORDER BY provider",
            )
            .unwrap()
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                ))
            })
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(
            snapshots,
            vec![
                (
                    "craft".to_string(),
                    "craft-applied".to_string(),
                    "craft-applied".to_string()
                ),
                (
                    "dida365".to_string(),
                    "dida-applied".to_string(),
                    "dida-applied".to_string()
                ),
            ]
        );
        let bindings: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM unified_task_bindings WHERE hub_task_id='hub'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(bindings, 2);
        drop(connection);
        remove_test_database(&path);
    }

