    #[test]
    fn ordinary_craft_inventory_does_not_restore_a_trashed_document() {
        let root = std::env::temp_dir().join(format!(
            "craft-search-trash-inventory-{:016x}",
            rand::thread_rng().next_u64()
        ));
        std::fs::create_dir_all(&root).unwrap();
        let path = root.join("craft-search.sqlite3");
        let blob_store = BlobStore::open(&root.join("blobs")).unwrap();
        let connection = open_database(&path).unwrap();
        connection
            .execute(
                "INSERT INTO task_sync_craft_trash_documents
                   (library_id,document_id,confirmed_at) VALUES ('craft-space','trash-doc',1)",
                [],
            )
            .unwrap();
        drop(connection);

        persist_document_batch(
            &path,
            &blob_store,
            vec![IndexedDocument {
                space_id: "craft-space".into(),
                id: "trash-doc".into(),
                title: "Still returned by broad inventory".into(),
                path: "Trash".into(),
                folder_id: None,
                markdown: "- [ ] must not return".into(),
                modified_at: Some(2),
                indexed_at: 2,
                content_hash: "trash-doc-hash".into(),
                attachments: Vec::new(),
                block_hints: Vec::new(),
            }],
        )
        .unwrap();

        let connection = open_database(&path).unwrap();
        let remaining: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM task_sync_craft_trash_documents
                 WHERE library_id='craft-space' AND document_id='trash-doc'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let reindexed: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM documents
                 WHERE space_id='craft-space' AND id='trash-doc'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(remaining, 1);
        assert_eq!(reindexed, 0);
        drop(connection);
        let _ = std::fs::remove_dir_all(root);
    }

