    #[test]
    fn only_unbound_dida_children_with_a_bound_craft_parent_are_imported() {
        let dida_task = |source_id: &str, parent_source_id: &str| TaskSyncRecord {
            provider: PROVIDER_DIDA365.into(),
            library_id: "dida-space".into(),
            source_space_name: "滴答清单".into(),
            source_id: source_id.into(),
            parent_source_id: parent_source_id.into(),
            document_id: String::new(),
            parent_page_id: String::new(),
            raw_document_id: String::new(),
            title: source_id.into(),
            completed: false,
            start_at: String::new(),
            due_at: String::new(),
            is_all_day: true,
            time_zone: "Asia/Shanghai".into(),
            schedule_date: String::new(),
            deadline_date: String::new(),
            project_id: "project".into(),
            content: String::new(),
            description: String::new(),
            tags: Vec::new(),
            is_project_page: false,
        };
        let craft_parent = TaskSyncRecord {
            provider: PROVIDER_CRAFT.into(),
            library_id: "craft-space".into(),
            source_space_name: "main".into(),
            source_id: "craft-parent".into(),
            parent_source_id: String::new(),
            document_id: "document".into(),
            parent_page_id: "page".into(),
            raw_document_id: String::new(),
            title: "Craft 父任务".into(),
            completed: false,
            start_at: String::new(),
            due_at: String::new(),
            is_all_day: true,
            time_zone: "Asia/Shanghai".into(),
            schedule_date: String::new(),
            deadline_date: String::new(),
            project_id: String::new(),
            content: String::new(),
            description: String::new(),
            tags: Vec::new(),
            is_project_page: false,
        };
        let parents = HashMap::from([(
            ("dida-space".to_string(), "dida-parent".to_string()),
            craft_parent,
        )]);
        let child = dida_task("new-child", "dida-parent");

        assert!(should_import_unbound_dida_child(
            &child,
            &HashSet::new(),
            &parents
        ));
        assert!(!should_import_unbound_dida_child(
            &dida_task("root", ""),
            &HashSet::new(),
            &parents
        ));
        assert!(!should_import_unbound_dida_child(
            &dida_task("orphan", "unbound-parent"),
            &HashSet::new(),
            &parents
        ));
        assert!(!should_import_unbound_dida_child(
            &child,
            &HashSet::from([("dida-space".to_string(), "new-child".to_string())]),
            &parents
        ));
    }

