    #[test]
    fn task_sync_hash_changes_when_same_named_craft_image_is_replaced() {
        let path = unique_test_path("hub-task-attachment-hash").with_extension("sqlite3");
        let (connection, writer) = open_write_database(&path).unwrap();
        for (id, url, blob_hash) in [
            ("old", "https://r.craft.do/old", "blob-old"),
            ("new", "https://r.craft.do/new", "blob-new"),
        ] {
            connection
                .execute(
                    "INSERT INTO source_items
                     (id,space_id,document_id,remote_id,source_type,title,status,metadata_json,
                      blob_hash,created_at,updated_at,last_seen_at,missing_syncs,provider)
                     VALUES (?1,'craft-space','doc',?1,'craft_attachment','Image','stored',?2,?3,1,1,1,0,'craft')",
                    params![id, json!({"remoteUrl": url}).to_string(), blob_hash],
                )
                .unwrap();
        }
        let task = TaskSyncRecord {
            provider: PROVIDER_CRAFT.into(),
            library_id: "craft-space".into(),
            source_space_name: "Craft".into(),
            source_id: "task".into(),
            parent_source_id: String::new(),
            document_id: "doc".into(),
            parent_page_id: "page".into(),
            raw_document_id: String::new(),
            title: "任务".into(),
            completed: false,
            start_at: String::new(),
            due_at: String::new(),
            is_all_day: true,
            time_zone: "Asia/Shanghai".into(),
            schedule_date: String::new(),
            deadline_date: String::new(),
            project_id: String::new(),
            content: "![Image](https://r.craft.do/old)".into(),
            description: String::new(),
            tags: Vec::new(),
            is_project_page: false,
        };
        let old_hash = task_sync_source_hash(&path, &task).unwrap();
        let replaced = TaskSyncRecord {
            content: "![Image](https://r.craft.do/new)".into(),
            ..task
        };
        assert_eq!(
            normalized_attachment_markdown(&replaced.content),
            normalized_attachment_markdown("![Image](https://r.craft.do/old)")
        );
        assert_ne!(old_hash, task_sync_source_hash(&path, &replaced).unwrap());
        drop(connection);
        drop(writer);
        remove_test_database(&path);
    }

