    #[test]
    fn repeated_task_sync_conflict_keeps_one_pending_review() {
        let path = unique_test_path("hub-task-conflict-dedup").with_extension("sqlite3");
        let (connection, writer) = open_write_database(&path).unwrap();
        drop(connection);
        drop(writer);

        record_task_sync_conflict(&path, "hub-task", "craft-a", "dida-a").unwrap();
        let (connection, writer) = open_write_database(&path).unwrap();
        connection
            .execute(
                "UPDATE task_sync_events SET created_at=1
                 WHERE hub_task_id='hub-task' AND action='conflict'",
                [],
            )
            .unwrap();
        drop(connection);
        drop(writer);
        record_task_sync_conflict(&path, "hub-task", "craft-b", "dida-b").unwrap();

        let connection = open_database(&path).unwrap();
        let pending: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM task_sync_events
                 WHERE hub_task_id='hub-task' AND action='conflict' AND status='review'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let payload: String = connection
            .query_row(
                "SELECT payload_json FROM task_sync_events
                 WHERE hub_task_id='hub-task' AND action='conflict' AND status='review'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(pending, 1);
        assert!(payload.contains("craft-b"));
        assert!(payload.contains("dida-b"));
        let refreshed_created_at: i64 = connection
            .query_row(
                "SELECT created_at FROM task_sync_events
                 WHERE hub_task_id='hub-task' AND action='conflict' AND status='review'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert!(refreshed_created_at > 1);
        drop(connection);
        remove_test_database(&path);
    }

    #[test]
    fn repeated_identity_conflict_is_reported_only_once() {
        let path = unique_test_path("hub-task-identity-conflict-dedup").with_extension("sqlite3");
        let (connection, writer) = open_write_database(&path).unwrap();
        drop(connection);
        drop(writer);

        assert!(record_task_sync_identity_conflict(
            &path,
            "hub-task",
            "任务",
            "bound-source",
            "managed-source"
        )
        .unwrap());
        assert!(!record_task_sync_identity_conflict(
            &path,
            "hub-task",
            "任务",
            "bound-source",
            "managed-source"
        )
        .unwrap());

        let connection = open_database(&path).unwrap();
        let pending: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM task_sync_events
                 WHERE hub_task_id='hub-task' AND action='conflict' AND status='review'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(pending, 1);
        let payload: Value = connection
            .query_row(
                "SELECT payload_json FROM task_sync_events
                 WHERE hub_task_id='hub-task' AND action='conflict'",
                [],
                |row| row.get::<_, String>(0),
            )
            .map(|payload| serde_json::from_str(&payload).unwrap())
            .unwrap();
        assert_eq!(payload["conflictType"], "identity");
        assert_eq!(payload["boundCraftSourceId"], "bound-source");
        assert_eq!(payload["managedCraftSourceId"], "managed-source");
        connection
            .execute(
                "UPDATE task_sync_events SET status='pending'
                 WHERE hub_task_id='hub-task' AND action='conflict'",
                [],
            )
            .unwrap();
        drop(connection);
        assert!(task_sync_conflict_resolution_requested(&path, "hub-task").unwrap());
        remove_test_database(&path);
    }

    #[test]
    fn unresolved_identity_link_repair_remains_retryable() {
        let path =
            unique_test_path("hub-task-identity-link-repair-retry").with_extension("sqlite3");
        let (connection, writer) = open_write_database(&path).unwrap();
        connection
            .execute(
                "INSERT INTO task_sync_events
                   (hub_task_id,origin_provider,target_provider,action,status,payload_json,
                    idempotency_key,attempts,created_at,updated_at,last_error)
                 VALUES ('hub','craft','dida365','conflict','pending','{}','conflict:hub',0,1,1,NULL)",
                [],
            )
            .unwrap();
        for provider in [PROVIDER_CRAFT, PROVIDER_DIDA365] {
            connection
                .execute(
                    "INSERT INTO task_sync_snapshots
                       (hub_task_id,provider,source_hash,applied_hash,synced_at)
                     VALUES ('hub',?1,'identity-link-repair:1','identity-link-repair:1',1)",
                    [provider],
                )
                .unwrap();
        }
        connection
            .execute_batch(
                "INSERT INTO unified_task_bindings
                   (hub_task_id,provider,library_id,source_id,document_id,source_hash,last_seen_at,missing_syncs)
                 VALUES ('hub','dida365','dida-lib','dida-task','','actual',1,0);
                 INSERT INTO dida_tasks
                   (library_id,task_id,project_id,title,raw_json,last_seen_at)
                 VALUES ('dida-lib','dida-task','project','Task','{}',1);",
            )
            .unwrap();
        drop(connection);
        drop(writer);

        reconcile_pending_task_conflicts(&path).unwrap();
        let connection = open_database(&path).unwrap();
        let (status, error): (String, String) = connection
            .query_row(
                "SELECT status,last_error FROM task_sync_events WHERE hub_task_id='hub'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(status, "failed");
        assert!(error.contains("重试"));
        drop(connection);
        remove_test_database(&path);
    }

