    #[test]
    fn dida_craft_source_metadata_is_appended_without_overwriting_user_content() {
        let url = "https://docs.craft.do/editor/d/space/document#task";
        assert_eq!(
            dida_content_with_craft_source("用户自己的说明", url),
            format!("用户自己的说明\n\n[Craft 来源]({url})")
        );
        assert_eq!(
            dida_content_with_craft_source(&format!("说明\n\nCraft 来源：{url}"), url),
            format!("说明\n\n[Craft 来源]({url})")
        );
        assert_eq!(
            dida_content_with_craft_source(&format!("说明\n\n[Craft 来源]({url})"), url),
            format!("说明\n\n[Craft 来源]({url})")
        );
        let old_url = "https://docs.craft.do/editor/d/space/old-document#old-task";
        assert_eq!(
            dida_content_with_craft_source(
                &format!("说明\n\n[Craft 来源]({old_url})\n\nCraft 来源：{old_url}"),
                url
            ),
            format!("说明\n\n[Craft 来源]({url})")
        );
        assert_eq!(
            managed_craft_source_url(&format!("说明\n\n[Craft 来源]({url})")),
            Some(url.to_string())
        );
        assert_eq!(
            dida_tags_with_craft_source(&["工作".to_string()], "产品空间", false),
            vec![
                "工作".to_string(),
                "craft".to_string(),
                "产品空间".to_string()
            ]
        );
        assert_eq!(
            dida_tags_with_craft_source(&["Craft".to_string()], "#产品空间", false),
            vec!["Craft".to_string(), "产品空间".to_string()]
        );
        assert_eq!(
            dida_tags_with_craft_source(&[], "产品空间", true),
            vec![
                "craft".to_string(),
                "产品空间".to_string(),
                "项目".to_string()
            ]
        );
        assert!(dida_tags_equivalent(
            &["craft".to_string(), "Main".to_string()],
            &["main".to_string(), "#Craft".to_string()]
        ));
        assert!(dida_content_equivalent("正文\r\n", "正文\n"));
    }

