    #[test]
    fn task_dates_are_normalized_and_can_be_set_or_cleared_in_craft() {
        assert_eq!(
            normalized_task_date("2026-08-22T02:30:00+0000"),
            "2026-08-22"
        );
        assert_eq!(normalized_task_date("not-a-date"), "");
        assert_eq!(
            normalized_dida_task_dates("2026-08-22T00:00:00+0000", "2026-08-22T00:00:00+0000"),
            ("2026-08-22".to_string(), String::new())
        );
        assert_eq!(
            dida_due_datetime("2026-08-22", "").as_deref(),
            Some("2026-08-22T00:00:00.000+0000")
        );
        assert_eq!(
            dida_task_datetime("2026-08-22").as_deref(),
            Some("2026-08-22T00:00:00.000+0000")
        );
        let set_command =
            craft_task_dates_update_command("task-id", false, "2026-08-22", "2026-08-24");
        assert!(set_command.contains("\\\"scheduleDate\\\":\\\"2026-08-22\\\""));
        assert!(set_command.contains("\\\"deadlineDate\\\":\\\"2026-08-24\\\""));
        let clear_command = craft_task_dates_update_command("task-id", false, "", "");
        assert!(clear_command.contains("\\\"scheduleDate\\\":null"));
        assert!(clear_command.contains("\\\"deadlineDate\\\":null"));
    }

