    #[test]
    fn hub_flashcards_v1_manifest_and_jsonl_are_parsed() {
        let root = unique_test_path("hub-flashcards-v1");
        std::fs::create_dir_all(&root).unwrap();
        let manifest = root.join("manifest.json");
        let cards = root.join("cards.jsonl");
        std::fs::write(
            &manifest,
            r#"{"format":"hub-flashcards-v1","version":1,"deckName":"测试牌组","cardsFile":"cards.jsonl","generator":{"agent":"codex"}}"#,
        ).unwrap();
        std::fs::write(
            &cards,
            "{\"question\":\"RPM 表示什么？\",\"answer\":\"Requests Per Minute\",\"cardType\":\"qa\",\"confidence\":0.9}\n",
        ).unwrap();

        let (deck_name, generation, values) = parse_flashcard_bundle(&manifest).unwrap();
        assert_eq!(deck_name, "测试牌组");
        assert_eq!(
            generation.get("agent").and_then(Value::as_str),
            Some("codex")
        );
        assert_eq!(values.len(), 1);
        let draft =
            flashcard_draft_from_value(&values[0], "batch-test", &deck_name, &generation, 1)
                .unwrap();
        assert_eq!(draft.answer, "Requests Per Minute");
        assert_eq!(draft.confidence, Some(0.9));

        let _ = std::fs::remove_dir_all(root);
    }

