    #[test]
    fn flashcard_editor_fields_are_trimmed_limited_and_type_checked() {
        let (question, answer, explanation, card_type, card_data) =
            normalize_flashcard_editor_fields(
                "  什么是 RPM？  ",
                " 每分钟请求数 ",
                " 解释 ",
                "cloze",
                None,
            )
            .unwrap();
        assert_eq!(question, "什么是 RPM？");
        assert_eq!(answer, "每分钟请求数");
        assert_eq!(explanation, "解释");
        assert_eq!(card_type, "cloze");
        assert_eq!(card_data, json!({}));
        assert!(normalize_flashcard_editor_fields("短", "答案", "", "qa", None).is_err());
        assert!(normalize_flashcard_editor_fields("有效问题？", "", "", "qa", None).is_err());
        assert!(
            normalize_flashcard_editor_fields("有效问题？", "答案", "", "video", None).is_err()
        );

        let (_, choice_answer, _, choice_type, choice_data) = normalize_flashcard_editor_fields(
            "HTTP 404 表示什么？",
            "未找到资源",
            "",
            "multiple_choice",
            Some(&json!({"options":["成功","未找到资源","服务器错误"],"correctIndex":1})),
        )
        .unwrap();
        assert_eq!(choice_type, "multiple_choice");
        assert_eq!(choice_answer, "未找到资源");
        assert_eq!(choice_data["correctIndex"], 1);

        let (_, ordering_answer, _, ordering_type, ordering_data) =
            normalize_flashcard_editor_fields(
                "按顺序排列请求流程",
                "解析域名\n建立连接\n发送请求",
                "",
                "ordering",
                None,
            )
            .unwrap();
        assert_eq!(ordering_type, "ordering");
        assert_eq!(ordering_answer.lines().count(), 3);
        assert_eq!(ordering_data["items"].as_array().unwrap().len(), 3);

        let (_, _, _, occlusion_type, occlusion_data) = normalize_flashcard_editor_fields(
            "识别被遮挡的零件",
            "查看原图",
            "",
            "image_occlusion",
            Some(&json!({"occlusions":[{"x":0.1,"y":0.2,"width":0.3,"height":0.25}]})),
        )
        .unwrap();
        assert_eq!(occlusion_type, "image_occlusion");
        assert_eq!(occlusion_data["occlusions"].as_array().unwrap().len(), 1);
        assert!(normalize_flashcard_editor_fields(
            "识别被遮挡的零件",
            "查看原图",
            "",
            "image_occlusion",
            Some(&json!({"occlusions":[{"x":0.9,"y":0.2,"width":0.3,"height":0.25}]})),
        )
        .is_err());
    }

