    #[test]
    fn flashcard_import_batch_must_exist_before_its_drafts() {
        let database = unique_test_path("hub-flashcard-import-fk").with_extension("sqlite3");
        let mut connection = open_database(&database).unwrap();
        let insert_draft = |connection: &Connection, id: &str, batch_id: &str| {
            connection.execute(
                "INSERT INTO flashcard_drafts
                   (id,batch_id,deck_name,question,answer,idempotency_key,created_at,updated_at)
                 VALUES (?1,?2,'测试牌组','有效问题？','有效答案',?1,1,1)",
                params![id, batch_id],
            )
        };
        assert!(insert_draft(&connection, "draft-before", "missing-batch").is_err());

        let transaction = connection.transaction().unwrap();
        transaction.execute(
            "INSERT INTO flashcard_import_batches
               (id,format,source_path,deck_name,imported_at,total_count,valid_count,duplicate_count,invalid_count)
             VALUES ('batch-ok','hub-flashcards-v1','','测试牌组',1,1,0,0,0)",
            [],
        ).unwrap();
        insert_draft(&transaction, "draft-after", "batch-ok").unwrap();
        transaction.commit().unwrap();
        let count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM flashcard_drafts WHERE batch_id='batch-ok'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 1);
        drop(connection);
        remove_test_database(&database);
    }

    fn seed_flashcard_safety_database(path: &PathBuf) -> Connection {
        let connection = open_database(path).unwrap();
        connection
            .execute(
                "INSERT INTO flashcard_decks (id,name,created_at,updated_at)
             VALUES ('deck-safe','数据安全牌组',10,10)",
                [],
            )
            .unwrap();
        for (id, question, answer) in [
            ("card-a", "卡片 A 的问题", "卡片 A 的答案"),
            ("card-b", "卡片 B 的问题", "卡片 B 的答案"),
        ] {
            connection
                .execute(
                    "INSERT INTO flashcards
                   (id,deck_id,question,answer,media_json,status,created_at,updated_at,due_at)
                 VALUES (?1,'deck-safe',?2,?3,'[]','active',10,100,10)",
                    params![id, question, answer],
                )
                .unwrap();
        }
        connection
    }

    fn add_flashcard_safety_review(
        connection: &Connection,
        review_id: &str,
        card_id: &str,
        rating: i64,
        reviewed_at: i64,
    ) {
        connection
            .execute(
                "INSERT INTO flashcard_reviews
               (id,card_id,rating,reviewed_at,previous_due_at,next_due_at,
                previous_interval_days,next_interval_days,elapsed_ms)
             VALUES (?1,?2,?3,?4,10,?5,0,1,250)",
                params![
                    review_id,
                    card_id,
                    rating,
                    reviewed_at,
                    reviewed_at + 86_400
                ],
            )
            .unwrap();
        recompute_flashcard_schedule(connection, card_id).unwrap();
    }

    #[test]
    fn flashcard_scheduler_handles_again_and_first_success() {
        let again = legacy_scheduled_flashcard_values(1, 8.0, 2.5, 4, 1, 1_000);
        assert_eq!(again.0, 1_600);
        assert_eq!(again.1, 0.0);
        assert_eq!(again.3, 0);
        assert_eq!(again.4, 2);

        let good = legacy_scheduled_flashcard_values(3, 0.0, 2.5, 0, 0, 1_000);
        assert_eq!(good.0, 1_000 + 86_400);
        assert_eq!(good.1, 1.0);
        assert_eq!(good.3, 1);

        let hard = legacy_scheduled_flashcard_values(2, 10.0, 2.5, 3, 1, 1_000);
        assert_eq!(hard.0, 1_000 + 12 * 86_400);
        assert_eq!(hard.1, 12.0);
        assert_eq!(hard.2, 2.35);
        assert_eq!(hard.3, 4);

        let easy = legacy_scheduled_flashcard_values(4, 10.0, 2.5, 3, 1, 1_000);
        assert_eq!(easy.0, 1_000 + (32.5_f64 * 86_400.0).round() as i64);
        assert_eq!(easy.1, 32.5);
        assert_eq!(easy.2, 2.65);
        assert_eq!(easy.3, 4);
    }

    #[test]
    fn flashcard_review_undo_restores_schedule_and_syncs_tombstone() {
        let database_a = unique_test_path("hub-flashcard-undo-a").with_extension("sqlite3");
        let database_b = unique_test_path("hub-flashcard-undo-b").with_extension("sqlite3");
        let mut device_a = seed_flashcard_safety_database(&database_a);
        let mut device_b = seed_flashcard_safety_database(&database_b);
        add_flashcard_safety_review(&device_a, "review-undo", "card-a", 3, 200);
        let reviewed = local_flashcard_snapshot(&device_a).unwrap();
        assert_eq!(
            merge_flashcard_snapshot(&mut device_b, &reviewed).unwrap(),
            (1, 1)
        );

        let transaction = device_a.transaction().unwrap();
        assert_eq!(
            restore_flashcard_after_review_delete(&transaction, "review-undo", 300).unwrap(),
            Some("card-a".to_string())
        );
        record_flashcard_tombstone(&transaction, "review", "review-undo", 300).unwrap();
        transaction.commit().unwrap();

        let undone = local_flashcard_snapshot(&device_a).unwrap();
        assert_eq!(
            merge_flashcard_snapshot(&mut device_b, &undone).unwrap(),
            (0, 0)
        );
        let state = device_b
            .query_row(
                "SELECT due_at,interval_days,ease,repetitions,lapses,
                    (SELECT COUNT(*) FROM flashcard_reviews WHERE card_id='card-a')
             FROM flashcards WHERE id='card-a'",
                [],
                |row| {
                    Ok((
                        row.get::<_, i64>(0)?,
                        row.get::<_, f64>(1)?,
                        row.get::<_, f64>(2)?,
                        row.get::<_, i64>(3)?,
                        row.get::<_, i64>(4)?,
                        row.get::<_, i64>(5)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(state, (10, 0.0, 2.5, 0, 0, 0));

        drop(device_a);
        drop(device_b);
        remove_test_database(&database_a);
        remove_test_database(&database_b);
    }

    #[test]
    fn flashcard_paused_state_and_daily_limit_converge_between_devices() {
        let database_a = unique_test_path("hub-flashcard-pause-a").with_extension("sqlite3");
        let database_b = unique_test_path("hub-flashcard-pause-b").with_extension("sqlite3");
        let device_a = seed_flashcard_safety_database(&database_a);
        let mut device_b = seed_flashcard_safety_database(&database_b);
        device_a
            .execute(
                "UPDATE flashcards SET status='suspended',updated_at=300 WHERE id='card-a'",
                [],
            )
            .unwrap();
        for (key, value) in [
            ("flashcard_daily_new_limit", "5"),
            ("flashcard_daily_new_limit_updated_at", "1000"),
        ] {
            device_a
                .execute(
                    "INSERT INTO metadata(key,value) VALUES (?1,?2) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                    params![key, value],
                )
                .unwrap();
        }
        let paused = local_flashcard_snapshot(&device_a).unwrap();
        merge_flashcard_snapshot(&mut device_b, &paused).unwrap();
        assert_eq!(
            flashcard_by_id(&device_b, "card-a").unwrap().status,
            "suspended"
        );
        assert_eq!(read_flashcard_study_settings(&device_b).daily_new_limit, 5);

        device_a
            .execute(
                "UPDATE flashcards SET status='active',updated_at=400 WHERE id='card-a'",
                [],
            )
            .unwrap();
        for (key, value) in [
            ("flashcard_daily_new_limit", "20"),
            ("flashcard_daily_new_limit_updated_at", "2000"),
        ] {
            device_a
                .execute(
                    "UPDATE metadata SET value=?1 WHERE key=?2",
                    params![value, key],
                )
                .unwrap();
        }
        merge_flashcard_snapshot(&mut device_b, &local_flashcard_snapshot(&device_a).unwrap())
            .unwrap();
        assert_eq!(
            flashcard_by_id(&device_b, "card-a").unwrap().status,
            "active"
        );
        assert_eq!(read_flashcard_study_settings(&device_b).daily_new_limit, 20);

        drop(device_a);
        drop(device_b);
        remove_test_database(&database_a);
        remove_test_database(&database_b);
    }

