    #[test]
    fn flashcard_management_migration_and_custom_fields_are_available() {
        let database = std::env::temp_dir().join(format!(
            "hub-flashcard-management-{}.sqlite3",
            random_url_safe(8)
        ));
        let connection = open_database(&database).unwrap();
        for column in [
            "tags_json",
            "evidence",
            "confidence",
            "custom_fields_json",
            "generation_json",
        ] {
            let exists: bool = connection
                .query_row(
                    "SELECT EXISTS(SELECT 1 FROM pragma_table_info('flashcards') WHERE name=?1)",
                    params![column],
                    |row| row.get(0),
                )
                .unwrap();
            assert!(exists, "missing flashcards.{column}");
        }
        let history_exists: bool = connection
            .query_row(
                "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='flashcard_sync_history')",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert!(history_exists);
        for column in ["folder_id", "sort_order"] {
            let exists: bool = connection.query_row(
                "SELECT EXISTS(SELECT 1 FROM pragma_table_info('flashcard_decks') WHERE name=?1)",
                params![column], |row| row.get(0),
            ).unwrap();
            assert!(exists, "missing flashcard_decks.{column}");
        }
        let folders_exist: bool = connection.query_row(
            "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='flashcard_deck_folders')",
            [], |row| row.get(0),
        ).unwrap();
        assert!(folders_exist);
        let tombstones_exist: bool = connection.query_row(
            "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='flashcard_sync_tombstones')",
            [], |row| row.get(0),
        ).unwrap();
        assert!(tombstones_exist);
        assert_eq!(
            normalize_flashcard_custom_fields(Some(&json!({
                "  Priority  ": " high ",
                "score": 3,
                "nested": {"ignored": true}
            }))),
            json!({"Priority":"high","score":3})
        );
        drop(connection);
        let reopened = open_database(&database).unwrap();
        assert_eq!(
            metadata_u64(&reopened, "schema_version", 0),
            DATABASE_SCHEMA_VERSION as u64
        );
        drop(reopened);
        let _ = std::fs::remove_file(database);
    }

