    #[test]
    fn flashcard_auto_sync_claim_respects_configuration_and_retry_guard() {
        let database = std::env::temp_dir().join(format!(
            "hub-flashcard-auto-sync-{}.sqlite3",
            random_url_safe(8)
        ));
        let connection = open_database(&database).unwrap();
        for (key, value) in [
            ("flashcard_webdav_url", "https://dav.example.test/cards/"),
            ("flashcard_sync_auto", "1"),
            ("flashcard_sync_dirty", "1"),
        ] {
            connection.execute("INSERT INTO metadata (key,value) VALUES (?1,?2) ON CONFLICT(key) DO UPDATE SET value=excluded.value", params![key, value]).unwrap();
        }
        drop(connection);
        {
            let c = open_database(&database).unwrap();
            c.execute(
                "INSERT INTO metadata(key,value) VALUES('cloud_sync_enabled','0')",
                [],
            )
            .unwrap();
        }
        assert!(!claim_flashcard_auto_sync_due(&database).unwrap());
        {
            let c = open_database(&database).unwrap();
            assert_eq!(metadata_u64(&c, "flashcard_sync_last_attempt", 0), 0);
            assert!(metadata_bool(&c, "flashcard_sync_dirty", false));
            c.execute(
                "UPDATE metadata SET value='1' WHERE key='cloud_sync_enabled'",
                [],
            )
            .unwrap();
            c.execute(
                "UPDATE metadata SET value='0' WHERE key='cloud_sync_flashcards'",
                [],
            )
            .unwrap();
        }
        assert!(!claim_flashcard_auto_sync_due(&database).unwrap());
        {
            let c = open_database(&database).unwrap();
            // Retired settings cannot admit a background transfer, even with all gates open.
            assert!(flashcard_cloud_sync::legacy_retired(&c));
            assert!(!flashcard_cloud_sync::configured(&c));
            assert!(reading_sync::object_store::configuration_for(&c, "webdav").is_err());
            c.execute("INSERT OR REPLACE INTO metadata(key,value) VALUES('flashcard_cloud_provider','oss')", []).unwrap();
            c.execute("INSERT OR REPLACE INTO metadata(key,value) VALUES('flashcard_oss_config',?1)", [r#"{"bucket":"test-bucket","region":"cn-hangzhou","prefix":"HubFlashcards","accessKeyId":"EXAMPLE"}"#]).unwrap();
            c.execute(
                "UPDATE metadata SET value='1' WHERE key='cloud_sync_flashcards'",
                [],
            )
            .unwrap();
        }
        assert!(claim_flashcard_auto_sync_due(&database).unwrap());
        assert!(!claim_flashcard_auto_sync_due(&database).unwrap());
        forget_initialized_database(&database);
        let _ = std::fs::remove_file(database);
    }

