    #[test]
    fn collection_media_streaming_supports_large_files_seek_head_and_missing() {
        let dir = std::env::temp_dir().join(format!("hub-media-test-{}", random_url_safe(12)));
        fs::create_dir(&dir).unwrap();
        let path = dir.join("video.mp4");
        {
            let mut file = fs::File::create(&path).unwrap();
            std::io::Write::write_all(
                &mut file,
                b"\x00\x00\x00\x18ftypmp42\x00\x00\x00\x00mp42isom",
            )
            .unwrap();
            file.set_len(80 * 1024 * 1024).unwrap();
        }
        let request = |range: Option<&str>, method: &str| {
            let mut builder = tauri::http::Request::builder().method(method);
            if let Some(range) = range {
                builder = builder.header("Range", range);
            }
            builder.body(Vec::new()).unwrap()
        };
        let response =
            media_file_response(path.clone(), request(Some("bytes=0-"), "GET"), None, true);
        assert_eq!(response.status(), 206);
        assert_eq!(response.body().len(), 8 * 1024 * 1024);
        assert_eq!(response.headers()["content-type"], "video/mp4");
        assert_eq!(
            response.headers()["content-range"],
            "bytes 0-8388607/83886080"
        );
        let seek = media_file_response(
            path.clone(),
            request(Some("bytes=83886070-"), "GET"),
            None,
            true,
        );
        assert_eq!(seek.body().len(), 10);
        let head = media_file_response(
            path.clone(),
            request(Some("bytes=0-99"), "HEAD"),
            None,
            true,
        );
        assert!(head.body().is_empty());
        assert_eq!(head.headers()["content-length"], "100");
        assert_eq!(
            media_file_response(
                path.clone(),
                request(Some("bytes=999999999-"), "GET"),
                None,
                true
            )
            .status(),
            416
        );
        assert_eq!(
            media_file_response(path.clone(), request(None, "GET"), None, true)
                .body()
                .len(),
            8 * 1024 * 1024
        );
        fs::remove_file(&path).unwrap();
        assert_eq!(
            media_file_response(path, request(None, "GET"), None, true).status(),
            404
        );
        fs::remove_dir(dir).unwrap();
    }

