    #[test]
    fn feishu_oauth_covers_all_task_v2_capabilities() {
        let granted_scopes = FEISHU_SCOPES
            .split_ascii_whitespace()
            .collect::<HashSet<_>>();
        let required_task_scopes = [
            "task:attachment:read",
            "task:attachment:write",
            "task:comment:read",
            "task:comment:write",
            "task:custom_field:read",
            "task:custom_field:write",
            "task:section:read",
            "task:section:write",
            "task:task:read",
            "task:task:write",
            "task:tasklist:read",
            "task:tasklist:write",
        ];

        for scope in required_task_scopes {
            assert!(
                granted_scopes.contains(scope),
                "Feishu OAuth is missing task scope {scope}"
            );
        }
        assert!(
            granted_scopes.contains("im:message:readonly"),
            "Feishu OAuth must be able to read the source message behind chat-created tasks"
        );
        for scope in [
            "search:message",
            "im:chat:readonly",
            "im:message.group_msg:get_as_user",
            "im:message.p2p_msg:get_as_user",
        ] {
            assert!(
                granted_scopes.contains(scope),
                "Feishu OAuth is missing source-message scope {scope}"
            );
        }
    }

    #[test]
    fn feishu_oauth_avoids_unavailable_alternative_task_scopes() {
        let granted_scopes = FEISHU_SCOPES
            .split_ascii_whitespace()
            .collect::<HashSet<_>>();
        let unavailable_alternatives = [
            "task:custom_field:writeonly",
            "task:personnel:writeonly",
            "task:section:delete",
            "task:section:writeonly",
            "task:task:delete",
            "task:task:writeonly",
            "task:tasklist:delete",
            "task:tasklist:writeonly",
        ];

        for scope in unavailable_alternatives {
            assert!(
                !granted_scopes.contains(scope),
                "Feishu OAuth includes unavailable alternative task scope {scope}"
            );
        }
    }

