    #[test]
    fn incomplete_feishu_pagination_never_looks_like_a_complete_snapshot() {
        assert_eq!(
            feishu_next_page(&json!({"has_more":false}), "", 0).unwrap(),
            None
        );
        assert_eq!(
            feishu_next_page(&json!({"has_more":true,"page_token":"next"}), "old", 0).unwrap(),
            Some("next".into())
        );
        for data in [
            json!({}),
            json!({"has_more":true}),
            json!({"has_more":true,"page_token":"old"}),
        ] {
            assert!(feishu_next_page(&data, "old", 0).is_err());
        }
        assert!(
            feishu_next_page(&json!({"has_more":true,"page_token":"next"}), "old", 199).is_err()
        );
    }

    #[test]
    fn feishu_task_sync_schema_has_durable_binding_authority() {
        let path = unique_test_path("hub-feishu-task-sync-schema").with_extension("sqlite3");
        let connection = open_database(&path).unwrap();
        let columns = connection
            .prepare("SELECT name FROM pragma_table_info('feishu_task_bindings')")
            .unwrap()
            .query_map([], |row| row.get::<_, String>(0))
            .unwrap()
            .collect::<Result<HashSet<_>, _>>()
            .unwrap();
        assert!(columns.contains("feishu_task_guid"));
        assert!(columns.contains("dida_task_id"));
        assert!(columns.contains("feishu_hash"));
        assert!(columns.contains("dida_hash"));
        assert!(columns.contains("feishu_detail_hash"));
        let attachment_table = connection
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master
                 WHERE type='table' AND name='feishu_task_attachments'",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap();
        assert_eq!(attachment_table, 1);
        let authorization_table = connection
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master
                 WHERE type='table' AND name='feishu_authorizations'",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap();
        assert_eq!(authorization_table, 1);
        drop(connection);
        let _ = fs::remove_file(path);
    }

