    fn unique_test_path(prefix: &str) -> PathBuf {
        std::env::temp_dir().join(format!("{prefix}-{}", random_url_safe(8)))
    }

    fn remove_test_database(path: &PathBuf) {
        forget_initialized_database(path);
        let _ = std::fs::remove_file(path);
        let _ = std::fs::remove_file(path.with_extension("sqlite3-wal"));
        let _ = std::fs::remove_file(path.with_extension("sqlite3-shm"));
    }

    #[test]
    fn craft_subpages_are_indexed_as_independent_pages_with_parent_paths() {
        let path = unique_test_path("hub-craft-subpages").with_extension("sqlite3");
        let connection = open_database(&path).expect("create current database");
        connection
            .execute(
                "INSERT INTO spaces (id,name,mcp_url,added_at,provider)
                 VALUES ('craft-a','Car','https://example.test/mcp',1,'craft')",
                [],
            )
            .unwrap();
        connection
            .execute(
                "INSERT INTO documents
                   (space_id,id,title,path,markdown,indexed_at,content_hash,provider)
                 VALUES ('craft-a','root','1 线束','未分类','',1,'hash','craft')",
                [],
            )
            .unwrap();
        for (id, block_id, page_id, page_title, heading, body, ordinal) in [
            (
                "craft-a:root:0",
                "material-block",
                "material-page",
                "物料选型",
                "物料选型",
                "供应商物料选型",
                0_i64,
            ),
            (
                "craft-a:root:1",
                "standard-block",
                "standard-page",
                "标准件",
                "标准件",
                "标准件正文",
                1_i64,
            ),
        ] {
            connection
                .execute(
                    "INSERT INTO content_items
                       (id,space_id,document_id,block_id,page_id,page_title,content_type,
                        heading,body,ordinal,source_hash,provider)
                     VALUES (?1,'craft-a','root',?2,?3,?4,'craft_subpage',
                             ?5,?6,?7,?1,'craft')",
                    params![id, block_id, page_id, page_title, heading, body, ordinal],
                )
                .unwrap();
        }
        connection
            .execute(
                "INSERT INTO source_items
                   (id,space_id,document_id,remote_id,source_type,title,status,
                    metadata_json,created_at,updated_at,provider)
                 VALUES ('attachment-a','craft-a','root','remote-a','craft_attachment',
                         'Craft 附件','deferred',
                         '{\"blockId\":\"material-page\",\"remoteUrl\":\"https://r.craft.do/a\"}',
                         1,1,'craft')",
                [],
            )
            .unwrap();

        let records = collect_index_records(&connection, None).unwrap();
        assert_eq!(records.len(), 3);
        assert_eq!(records[0].title, "物料选型");
        assert_eq!(records[0].path, "未分类 / 1 线束");
        assert_eq!(records[0].entity_key, "page:craft-a:root:material-page");
        assert_eq!(records[0].block_id, "material-block");
        assert_ne!(records[0].entity_key, records[1].entity_key);
        let attachment = records
            .iter()
            .find(|record| record.item_id == "attachment-meta:attachment-a")
            .unwrap();
        assert_eq!(attachment.title, "物料选型");
        assert_eq!(attachment.path, "未分类 / 1 线束");

        drop(connection);
        remove_test_database(&path);
    }

