    #[test]
    fn library_management_obsidian_changed_paths_update_only_touched_documents() {
        let root = unique_test_path("craft-search-obsidian-path-sync");
        let database =
            unique_test_path("craft-search-obsidian-path-sync").with_extension("sqlite3");
        std::fs::create_dir_all(&root).unwrap();
        let page = root.join("页面.md");
        let untouched = root.join("未修改.md");
        std::fs::write(&page, "# 页面\n第一版").unwrap();
        std::fs::write(&untouched, "# 未修改\n保持不变").unwrap();
        let library_id = obsidian_library_id(&root).unwrap();
        let connection = open_database(&database).unwrap();
        connection
            .execute(
                "INSERT INTO libraries
                   (id,provider,name,location,enabled,added_at,metadata_json)
                 VALUES (?1,'obsidian','增量测试',?2,1,1,'{}')",
                params![library_id, root.to_string_lossy()],
            )
            .unwrap();
        drop(connection);
        sync_obsidian_library_database(&database, &library_id, &root).unwrap();

        std::fs::write(&page, "---\nalias: 页面别名\n---\n# 页面\n第二版").unwrap();
        let summary = sync_obsidian_changed_paths_database(
            &database,
            &library_id,
            &root,
            &HashSet::from([page.clone()]),
        )
        .unwrap();
        assert_eq!(
            (summary.indexed, summary.skipped, summary.deleted),
            (1, 0, 0)
        );
        let connection = open_database(&database).unwrap();
        let alias_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM obsidian_aliases
                 WHERE space_id=?1 AND normalized_alias=?2",
                params![library_id, "页面别名"],
                |row| row.get(0),
            )
            .unwrap();
        let untouched_hash: String = connection
            .query_row(
                "SELECT content_hash FROM documents WHERE space_id=?1 AND path='未修改.md'",
                params![library_id],
                |row| row.get(0),
            )
            .unwrap();
        drop(connection);
        assert_eq!(alias_count, 1);

        let renamed = root.join("重命名.md");
        std::fs::rename(&page, &renamed).unwrap();
        let renamed_summary = sync_obsidian_changed_paths_database(
            &database,
            &library_id,
            &root,
            &HashSet::from([page, renamed.clone()]),
        )
        .unwrap();
        assert_eq!((renamed_summary.indexed, renamed_summary.deleted), (1, 1));

        let archive = root.join("归档");
        std::fs::create_dir_all(&archive).unwrap();
        let moved = archive.join("重命名.md");
        std::fs::rename(&renamed, &moved).unwrap();
        let moved_summary = sync_obsidian_changed_paths_database(
            &database,
            &library_id,
            &root,
            &HashSet::from([renamed, moved.clone()]),
        )
        .unwrap();
        assert_eq!((moved_summary.indexed, moved_summary.deleted), (1, 1));

        let connection = open_database(&database).unwrap();
        let moved_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM documents
                 WHERE space_id=?1 AND path='归档/重命名.md'",
                params![library_id],
                |row| row.get(0),
            )
            .unwrap();
        let stale_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM documents
                 WHERE space_id=?1 AND path IN ('页面.md','重命名.md')",
                params![library_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!((moved_count, stale_count), (1, 0));
        drop(connection);

        std::fs::remove_file(&moved).unwrap();
        let deleted = sync_obsidian_changed_paths_database(
            &database,
            &library_id,
            &root,
            &HashSet::from([moved]),
        )
        .unwrap();
        assert_eq!((deleted.indexed, deleted.deleted), (0, 1));
        let connection = open_database(&database).unwrap();
        let after_hash: String = connection
            .query_row(
                "SELECT content_hash FROM documents WHERE space_id=?1 AND path='未修改.md'",
                params![library_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(after_hash, untouched_hash);

        drop(connection);
        remove_test_database(&database);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn obsidian_watcher_queues_markdown_changes() {
        let root = unique_test_path("craft-search-obsidian-watcher");
        std::fs::create_dir_all(&root).unwrap();
        let state = AppState::default();
        register_obsidian_watcher(&state, "watcher-library", &root).unwrap();
        let page = root.join("监听.md");
        std::thread::sleep(Duration::from_millis(250));
        std::fs::write(&page, "# 监听\n保存后更新").unwrap();
        let attachment = root.join("监听.pdf");
        std::fs::write(&attachment, b"%PDF-1.4\n%%EOF").unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        let mut queued = false;
        while Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(100));
            queued = state
                .obsidian_changes
                .lock()
                .ok()
                .and_then(|changes| {
                    changes
                        .get("watcher-library")
                        .map(|pending| pending.paths.clone())
                })
                .is_some_and(|paths| {
                    [&page, &attachment].iter().all(|expected| {
                        paths.iter().any(|path| {
                            display_local_path(path)
                                .eq_ignore_ascii_case(&display_local_path(expected))
                        })
                    })
                });
            if queued {
                break;
            }
        }
        assert!(
            queued,
            "Obsidian watcher did not queue Markdown and attachment changes"
        );
        drop(state);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn failed_obsidian_watch_changes_merge_back_into_pending_queue() {
        let state = AppState::default();
        let existing = PathBuf::from("existing.md");
        let retried = PathBuf::from("retried.md");
        {
            let mut changes = state.obsidian_changes.lock().unwrap();
            changes.insert(
                "vault-a".to_string(),
                PendingVaultChanges {
                    paths: HashSet::from([existing.clone()]),
                    last_event: None,
                },
            );
        }

        requeue_obsidian_changes(
            &state,
            "vault-a".to_string(),
            HashSet::from([retried.clone()]),
        );
        set_obsidian_watch_error(&state, "vault-a", Some("临时监听错误".to_string()));

        let changes = state.obsidian_changes.lock().unwrap();
        let pending = changes.get("vault-a").unwrap();
        assert_eq!(pending.paths, HashSet::from([existing, retried]));
        assert!(pending.last_event.is_some());
        drop(changes);
        let statuses = obsidian_watch_statuses(&state).unwrap();
        assert_eq!(statuses.len(), 1);
        assert_eq!(statuses[0].library_id, "vault-a");
        assert!(!statuses[0].watching);
        assert_eq!(statuses[0].pending_paths, 2);
        assert_eq!(statuses[0].last_error.as_deref(), Some("临时监听错误"));
    }

    #[test]
    fn live_v10_migration_and_bounded_ocr_backfill_probe() {
        let Some(path) = std::env::var_os("CRAFT_SEARCH_V10_MIGRATION_COPY") else {
            return;
        };
        let path = PathBuf::from(path);
        let before = Connection::open(&path).expect("open migration copy");
        let document_count: i64 = before
            .query_row("SELECT COUNT(*) FROM documents", [], |row| row.get(0))
            .expect("count documents before migration");
        let content_count: i64 = before
            .query_row("SELECT COUNT(*) FROM content_items", [], |row| row.get(0))
            .expect("count content before migration");
        drop(before);

        let migrated = open_database(&path).expect("migrate database copy to schema 11");
        let schema_version: String = migrated
            .query_row(
                "SELECT value FROM metadata WHERE key='schema_version'",
                [],
                |row| row.get(0),
            )
            .expect("read schema version");
        let migrated_document_count: i64 = migrated
            .query_row("SELECT COUNT(*) FROM documents", [], |row| row.get(0))
            .expect("count documents after migration");
        let migrated_content_count: i64 = migrated
            .query_row("SELECT COUNT(*) FROM content_items", [], |row| row.get(0))
            .expect("count content after migration");
        drop(migrated);

        assert_eq!(schema_version, DATABASE_SCHEMA_VERSION.to_string());
        assert_eq!(migrated_document_count, document_count);
        assert_eq!(migrated_content_count, content_count);
        let backfilled = backfill_ocr_pipeline(&path, 25).expect("run bounded OCR backfill");
        assert!(backfilled <= 25, "OCR backfill exceeded its per-run limit");
    }

    #[test]
    fn migration_fixture_preserves_documents_and_builds_durable_work() {
        let Some(path) = std::env::var_os("CRAFT_SEARCH_MIGRATION_FIXTURE") else {
            return;
        };
        let path = PathBuf::from(path);
        let before = Connection::open(&path).expect("open migration fixture");
        let document_count: i64 = before
            .query_row("SELECT COUNT(*) FROM documents", [], |row| row.get(0))
            .expect("count fixture documents");
        let markdown_chars: i64 = before
            .query_row(
                "SELECT COALESCE(SUM(length(markdown)), 0) FROM documents",
                [],
                |row| row.get(0),
            )
            .expect("measure fixture markdown");
        drop(before);

        let migrated = open_database(&path).expect("migrate fixture database");
        let migrated_document_count: i64 = migrated
            .query_row("SELECT COUNT(*) FROM documents", [], |row| row.get(0))
            .expect("count migrated documents");
        let migrated_markdown_chars: i64 = migrated
            .query_row(
                "SELECT COALESCE(SUM(length(markdown)), 0) FROM documents",
                [],
                |row| row.get(0),
            )
            .expect("measure migrated markdown");
        let content_count: i64 = migrated
            .query_row("SELECT COUNT(*) FROM content_items", [], |row| row.get(0))
            .expect("count migrated content items");
        let job_count: i64 = migrated
            .query_row("SELECT COUNT(*) FROM index_jobs", [], |row| row.get(0))
            .expect("count migrated index jobs");
        let schema_version: String = migrated
            .query_row(
                "SELECT value FROM metadata WHERE key='schema_version'",
                [],
                |row| row.get(0),
            )
            .expect("read migrated schema version");
        let missing_sync_column: i64 = migrated
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('documents') WHERE name='missing_syncs'",
                [],
                |row| row.get(0),
            )
            .expect("verify missing document guard column");

        assert_eq!(migrated_document_count, document_count);
        assert_eq!(migrated_markdown_chars, markdown_chars);
        assert!(content_count >= document_count);
        assert_eq!(job_count, document_count);
        assert_eq!(schema_version, DATABASE_SCHEMA_VERSION.to_string());
        assert_eq!(missing_sync_column, 1);
        let blob_tables: i64 = migrated
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master
                 WHERE type='table' AND name IN ('blobs','source_items','extractions')",
                [],
                |row| row.get(0),
            )
            .expect("verify blob architecture tables");
        assert_eq!(blob_tables, 3);
        let generation_table: i64 = migrated
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master
                 WHERE type='table' AND name='search_index_generations'",
                [],
                |row| row.get(0),
            )
            .expect("verify search generation table");
        assert_eq!(generation_table, 1);

        if let Some(blob_root) = std::env::var_os("CRAFT_SEARCH_MIGRATION_BLOB_ROOT") {
            drop(migrated);
            let store =
                BlobStore::open(&PathBuf::from(blob_root)).expect("open fixture blob store");
            while backfill_document_blobs(&path, &store, 500).expect("backfill fixture blobs") > 0 {
            }
            while backfill_attachment_discovery(&path, 500)
                .expect("backfill fixture attachment discovery")
                > 0
            {}
            let migrated = open_database(&path).expect("reopen backfilled fixture");
            let linked_documents: i64 = migrated
                .query_row(
                    "SELECT COUNT(*) FROM documents WHERE blob_hash IS NOT NULL",
                    [],
                    |row| row.get(0),
                )
                .expect("count linked fixture documents");
            let source_items: i64 = migrated
                .query_row("SELECT COUNT(*) FROM source_items", [], |row| row.get(0))
                .expect("count fixture source items");
            let attachment_items: i64 = migrated
                .query_row(
                    "SELECT COUNT(*) FROM source_items WHERE source_type='craft_attachment'",
                    [],
                    |row| row.get(0),
                )
                .expect("count fixture attachments");
            let pdf_download_jobs: i64 = migrated
                .query_row(
                    "SELECT COUNT(*) FROM index_jobs WHERE job_type='download_source'",
                    [],
                    |row| row.get(0),
                )
                .expect("count fixture PDF download jobs");
            assert_eq!(linked_documents, document_count);
            assert_eq!(source_items, document_count + attachment_items);
            assert!(attachment_items > 0);
            assert!(pdf_download_jobs > 0);
        }
    }

