    #[test]
    fn search_filters_ocr_without_hiding_native_pdf_text() {
        let index_path = std::env::temp_dir().join(format!(
            "craft-search-ocr-filter-index-{}",
            random_url_safe(8)
        ));
        let index = SearchIndex::open(&index_path).unwrap();
        let records = [
            ("doc", "markdown_section"),
            ("image", "image_ocr"),
            ("scan", "pdf_ocr"),
            ("native", "pdf_page"),
        ]
        .into_iter()
        .map(|(document_id, content_type)| IndexRecord {
            provider: "craft".to_string(),
            item_id: format!("item-{document_id}"),
            document_key: format!("space-a:{document_id}"),
            entity_key: format!("document:space-a:{document_id}"),
            space_id: "space-a".to_string(),
            document_id: document_id.to_string(),
            block_id: document_id.to_string(),
            content_type: content_type.to_string(),
            source_item_id: String::new(),
            source_title: String::new(),
            page_number: 0,
            title: document_id.to_string(),
            heading: String::new(),
            aliases: String::new(),
            tags: String::new(),
            body: "ocrfiltertoken".to_string(),
            path: "测试".to_string(),
            folder_id: String::new(),
            modified_at: 100,
        })
        .collect::<Vec<_>>();
        index.apply_changes(&[], &records).unwrap();

        assert_eq!(
            index
                .search(
                    "ocrfiltertoken",
                    10,
                    None,
                    None,
                    None,
                    true,
                    true,
                    true,
                    true
                )
                .unwrap()
                .len(),
            4
        );
        let filtered = index
            .search(
                "ocrfiltertoken",
                10,
                None,
                None,
                None,
                true,
                false,
                true,
                false,
            )
            .unwrap();
        assert_eq!(filtered.len(), 2);
        assert!(filtered.iter().any(|hit| hit.content_type == "pdf_page"));
        assert!(!filtered
            .iter()
            .any(|hit| matches!(hit.content_type.as_str(), "image_ocr" | "pdf_ocr")));
        let no_pdf = index
            .search(
                "ocrfiltertoken",
                10,
                None,
                None,
                None,
                true,
                true,
                false,
                true,
            )
            .unwrap();
        assert_eq!(no_pdf.len(), 2);
        assert!(!no_pdf
            .iter()
            .any(|hit| matches!(hit.content_type.as_str(), "pdf_page" | "pdf_ocr")));

        let _ = std::fs::remove_dir_all(index_path);
    }

    #[test]
    fn library_management_index_jobs_are_leased_retried_and_completed_by_their_worker() {
        let path =
            std::env::temp_dir().join(format!("craft-search-jobs-{}.sqlite3", random_url_safe(8)));
        let mut connection = open_database(&path).unwrap();
        connection
            .execute(
                "INSERT INTO spaces (id, name, mcp_url, added_at)
                 VALUES ('space-a', '工作', 'https://example.test/mcp', 1)",
                [],
            )
            .unwrap();
        connection
            .execute(
                "INSERT INTO documents
                 (space_id,id,title,path,markdown,indexed_at,content_hash)
                 VALUES ('space-a','doc-a','标题','未分类','正文',1,'hash')",
                [],
            )
            .unwrap();
        connection
            .execute(
                "INSERT INTO content_items
                 (id,space_id,document_id,block_id,content_type,heading,body,ordinal,source_hash)
                 VALUES ('space-a:doc-a:0','space-a','doc-a','doc-a','markdown_section','标题','正文',0,'hash')",
                [],
            )
            .unwrap();
        connection
            .execute(
                "INSERT INTO index_jobs
                 (job_key,space_id,source_id,source_type,job_type,status,created_at,updated_at)
                 VALUES ('lexical:space-a:doc-a','space-a','doc-a','document','upsert_lexical','pending',1,1)",
                [],
            )
            .unwrap();

        let first = claim_index_batch(&mut connection, false, "worker-one").unwrap();
        assert_eq!(first.job_ids.len(), 1);
        assert_eq!(first.records.len(), 1);
        fail_index_jobs(
            &connection,
            &first.job_ids,
            "worker-one",
            "temporary failure",
        )
        .unwrap();
        let (status, attempts, retry_at): (String, i64, i64) = connection
            .query_row(
                "SELECT status, attempts, next_attempt_at FROM index_jobs",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(status, "pending");
        assert_eq!(attempts, 1);
        assert!(retry_at > now_timestamp());

        connection
            .execute("UPDATE index_jobs SET next_attempt_at=0", [])
            .unwrap();
        let second = claim_index_batch(&mut connection, false, "worker-two").unwrap();
        complete_index_jobs(&connection, &second.job_ids, "worker-two").unwrap();
        let (status, attempts, worker_id): (String, i64, Option<String>) = connection
            .query_row(
                "SELECT status, attempts, worker_id FROM index_jobs",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(status, "completed");
        assert_eq!(attempts, 2);
        assert!(worker_id.is_none());

        drop(connection);
        let _ = std::fs::remove_file(path);
    }

