    fn ocr_pages_are_queued_independently_and_resumably() {
        let database = std::env::temp_dir().join(format!(
            "craft-search-ocr-queue-{}.sqlite3",
            random_url_safe(8)
        ));
        let connection = open_database(&database).unwrap();
        connection
            .execute(
                "INSERT INTO spaces (id, name, mcp_url, added_at)
                 VALUES ('space-a', '测试', 'https://example.test/mcp', 1)",
                [],
            )
            .unwrap();
        connection
            .execute(
                "INSERT INTO source_items
                 (id,space_id,remote_id,source_type,title,mime_type,status,created_at,updated_at)
                 VALUES ('scan','space-a','remote','craft_attachment','扫描件.pdf',
                         'application/pdf','needs_ocr',1,1)",
                [],
            )
            .unwrap();
        let transaction = connection.unchecked_transaction().unwrap();
        queue_ocr_pages(&transaction, "space-a", "scan", 3, &[1, 2, 3], 10).unwrap();
        transaction.commit().unwrap();

        let jobs = claim_pipeline_jobs(&database, "ocr_page", 2).unwrap();
        assert_eq!(jobs.len(), 2);
        assert_eq!(ocr_page_payload(&jobs[0]).unwrap().page_number, 1);
        complete_index_jobs(&connection, &[jobs[0].id], &jobs[0].worker_id).unwrap();
        fail_pipeline_job(&database, &jobs[1], "temporary OCR failure", false).unwrap();
        connection
            .execute(
                "UPDATE index_jobs SET next_attempt_at=0 WHERE job_type='ocr_page'",
                [],
            )
            .unwrap();
        let resumed = claim_pipeline_jobs(&database, "ocr_page", 10).unwrap();
        let resumed_pages = resumed
            .iter()
            .map(|job| ocr_page_payload(job).unwrap().page_number)
            .collect::<Vec<_>>();
        assert_eq!(resumed_pages, vec![2, 3]);

        drop(connection);
        let _ = std::fs::remove_file(database);
    }

