    fn insert_scheduled_download(
        connection: &Connection,
        id: &str,
        space_id: &str,
        size: i64,
        created_at: i64,
    ) {
        connection.execute("INSERT INTO libraries(id,provider,name,enabled,added_at) VALUES (?1,'craft',?1,1,1) ON CONFLICT(id) DO NOTHING",[space_id]).unwrap();
        connection
            .execute(
                "INSERT INTO source_items
                   (id,space_id,remote_id,source_type,title,mime_type,status,metadata_json,
                    created_at,updated_at)
                 VALUES (?1,?2,?1,'craft_attachment',?1,'image/png','discovered',?3,?4,?4)",
                params![
                    id,
                    space_id,
                    json!({ "size": size }).to_string(),
                    created_at
                ],
            )
            .unwrap();
        connection
            .execute(
                "INSERT INTO index_jobs
                   (job_key,space_id,source_id,source_type,job_type,status,priority,
                    created_at,updated_at)
                 VALUES (?1,?2,?3,'craft_attachment','download_source','pending',30,?4,?4)",
                params![format!("download:{id}"), space_id, id, created_at],
            )
            .unwrap();
    }

    #[test]
    fn attachment_admission_stops_at_the_ocr_limit_and_shares_import_download_capacity() {
        for (backlog, expected) in [(49, 1), (50, 0), (51, 0), (100, 0)] {
            assert_eq!(attachment_admission_capacity(backlog), expected);
        }
        assert_eq!(attachment_admission_capacity(-1), PIPELINE_JOB_BATCH_SIZE);
        for backlog in [0, 30, 49, 50, 51, 100] {
            let capacity = attachment_admission_capacity(backlog);
            for imports in 0..=capacity {
                let downloads = capacity.saturating_sub(imports);
                assert_eq!(imports + downloads, capacity);
                assert!(backlog + capacity as i64 <= OCR_BACKPRESSURE_LIMIT || capacity == 0);
            }
        }
    }

