    #[test]
    fn index_flush_yields_with_unclaimed_jobs_pending_and_resumes_without_loss() {
        let root = std::env::temp_dir().join(format!("hub-index-budget-{}", random_url_safe(10)));
        std::fs::create_dir(&root).unwrap();
        let database = root.join("hub.sqlite3");
        let index_root = root.join("search-index");
        let mut connection = open_database(&database).unwrap();
        connection.execute("INSERT INTO libraries(id,provider,name,enabled,added_at) VALUES('budget','craft','budget',1,1)",[]).unwrap();
        let total = INDEX_JOB_BATCH_SIZE * 2 + 1;
        {
            let transaction = connection.transaction().unwrap();
            for number in 0..total {
                transaction.execute("INSERT INTO index_jobs(job_key,space_id,source_id,source_type,job_type,status,created_at,updated_at)
                    VALUES(?1,'budget',?2,'document','delete_lexical','pending',1,1)",
                    params![format!("budget:{number}"),format!("document-{number}")]).unwrap();
            }
            transaction.commit().unwrap();
        }
        let index = open_or_create_active_search_index(&mut connection, &index_root).unwrap();
        flush_index_jobs_budgeted(&database, index.clone(), &index_root, 2, Duration::ZERO)
            .unwrap();
        let counts = || {
            connection
                .query_row(
                    "SELECT
            SUM(status='completed'),SUM(status='pending'),SUM(status='running') FROM index_jobs",
                    [],
                    |r| {
                        Ok((
                            r.get::<_, usize>(0)?,
                            r.get::<_, usize>(1)?,
                            r.get::<_, usize>(2)?,
                        ))
                    },
                )
                .unwrap()
        };
        assert_eq!(
            counts(),
            (INDEX_JOB_BATCH_SIZE, INDEX_JOB_BATCH_SIZE + 1, 0)
        );
        flush_index_jobs_budgeted(
            &database,
            index.clone(),
            &index_root,
            1,
            Duration::from_secs(30),
        )
        .unwrap();
        assert_eq!(counts(), (INDEX_JOB_BATCH_SIZE * 2, 1, 0));
        flush_index_jobs_budgeted(
            &database,
            index.clone(),
            &index_root,
            2,
            Duration::from_secs(30),
        )
        .unwrap();
        assert_eq!(counts(), (total, 0, 0));
        assert_eq!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM index_jobs WHERE attempts<>1",
                    [],
                    |r| r.get::<_, usize>(0)
                )
                .unwrap(),
            0
        );
        drop(index);
        drop(connection);
        forget_initialized_database(&database);
        let _ = std::fs::remove_dir_all(root);
    }

