    #[test]
    fn wal_readers_continue_while_writes_are_serialized() {
        let database = std::env::temp_dir().join(format!(
            "craft-search-wal-writer-{}.sqlite3",
            random_url_safe(8)
        ));
        {
            let (connection, _writer) = open_write_database(&database).unwrap();
            connection
                .execute(
                    "INSERT INTO metadata (key,value) VALUES ('concurrency-test','before')",
                    [],
                )
                .unwrap();
        }

        let (mut first_connection, first_writer) = open_write_database(&database).unwrap();
        let first_transaction = first_connection.transaction().unwrap();
        first_transaction
            .execute(
                "UPDATE metadata SET value='during' WHERE key='concurrency-test'",
                [],
            )
            .unwrap();

        let read_path = database.clone();
        let (read_tx, read_rx) = mpsc::channel();
        let reader = std::thread::spawn(move || {
            let connection = open_database(&read_path).unwrap();
            let value: String = connection
                .query_row(
                    "SELECT value FROM metadata WHERE key='concurrency-test'",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            read_tx.send(value).unwrap();
        });
        assert_eq!(
            read_rx.recv_timeout(Duration::from_secs(1)).unwrap(),
            "before"
        );
        reader.join().unwrap();

        let write_path = database.clone();
        let (write_tx, write_rx) = mpsc::channel();
        let second_writer = std::thread::spawn(move || {
            write_tx.send("waiting").unwrap();
            let (connection, _writer) = open_write_database(&write_path).unwrap();
            connection
                .execute(
                    "UPDATE metadata SET value='after' WHERE key='concurrency-test'",
                    [],
                )
                .unwrap();
            write_tx.send("completed").unwrap();
        });
        assert_eq!(
            write_rx.recv_timeout(Duration::from_secs(1)).unwrap(),
            "waiting"
        );
        assert!(write_rx.recv_timeout(Duration::from_millis(100)).is_err());

        first_transaction.commit().unwrap();
        drop(first_writer);
        assert_eq!(
            write_rx.recv_timeout(Duration::from_secs(1)).unwrap(),
            "completed"
        );
        second_writer.join().unwrap();

        let connection = open_database(&database).unwrap();
        let value: String = connection
            .query_row(
                "SELECT value FROM metadata WHERE key='concurrency-test'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(value, "after");

        drop(connection);
        let _ = std::fs::remove_file(database);
    }

