    #[test]
    fn live_pdf_search_probe() {
        let Some(database) = std::env::var_os("CRAFT_SEARCH_LIVE_DATABASE") else {
            return;
        };
        let index_root = std::env::var_os("CRAFT_SEARCH_LIVE_INDEX_ROOT")
            .map(PathBuf::from)
            .expect("CRAFT_SEARCH_LIVE_INDEX_ROOT is required");
        let connection = Connection::open(database).expect("open live database");
        let relative_path: String = connection
            .query_row(
                "SELECT relative_path FROM search_index_generations WHERE status='active'",
                [],
                |row| row.get(0),
            )
            .expect("read active search generation");
        let index = SearchIndex::open(&index_root.join(relative_path)).expect("open live index");
        let (space_id, document_id, body): (String, String, String) = connection
            .query_row(
                "SELECT space_id, document_id, body FROM content_items
                 WHERE content_type='pdf_page' AND length(trim(body)) >= 20
                 ORDER BY length(body) DESC LIMIT 1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("find searchable PDF page");
        let candidates = body
            .split(|character: char| !character.is_alphanumeric())
            .filter(|word| (6..=40).contains(&word.chars().count()))
            .take(100)
            .collect::<Vec<_>>();
        assert!(
            !candidates.is_empty(),
            "PDF fixture has no safe search token"
        );
        let found = candidates.into_iter().any(|query| {
            index
                .search(
                    query,
                    50,
                    Some(&space_id),
                    None,
                    None,
                    true,
                    true,
                    true,
                    true,
                )
                .is_ok_and(|hits| {
                    hits.iter()
                        .any(|hit| hit.document_id == document_id && hit.content_type == "pdf_page")
                })
        });
        assert!(found, "Tantivy did not return an indexed PDF page");
    }

    #[test]
    fn live_mcp_attachment_capability_probe() {
        if std::env::var_os("CRAFT_SEARCH_LIVE_MCP_PROBE").is_none() {
            return;
        }
        let database = PathBuf::from(
            std::env::var_os("CRAFT_SEARCH_LIVE_DATABASE")
                .expect("CRAFT_SEARCH_LIVE_DATABASE is required"),
        );
        let requested_document_id = std::env::var("CRAFT_SEARCH_LIVE_DOCUMENT_ID").ok();
        let requested_space_id = std::env::var("CRAFT_SEARCH_LIVE_SPACE_ID").ok();
        let target_attachment_url = std::env::var("CRAFT_SEARCH_LIVE_ATTACHMENT_URL").ok();
        let target_markdown_text = std::env::var("CRAFT_SEARCH_LIVE_MARKDOWN_TEXT").ok();
        let target_block_id = std::env::var("CRAFT_SEARCH_LIVE_BLOCK_ID").ok();
        let probe_command = std::env::var("CRAFT_SEARCH_LIVE_COMMAND").ok();
        let write_probe_command = std::env::var("CRAFT_SEARCH_LIVE_WRITE_COMMAND").ok();
        let (space_id, document_id) = {
            let connection = Connection::open(&database).expect("open live database");
            if let Some(document_id) = requested_document_id.as_deref() {
                connection
                    .query_row(
                        "SELECT d.space_id, d.id FROM documents d WHERE d.id=?1 LIMIT 1",
                        params![document_id],
                        |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
                    )
                    .optional()
                    .expect("query requested Craft document")
                    .or_else(|| {
                        requested_space_id
                            .as_ref()
                            .map(|space_id| (space_id.clone(), document_id.to_string()))
                    })
                    .expect("find requested Craft document or provide its space")
            } else {
                connection
                    .query_row(
                        "SELECT d.space_id, d.id FROM documents d
                         WHERE lower(d.markdown) LIKE '%.pdf](https://r.craft.do/%' LIMIT 1",
                        [],
                        |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
                    )
                    .expect("find a document containing a Craft PDF")
            }
        };
        let search_chunk = target_markdown_text.as_deref().and_then(|needle| {
            let connection = Connection::open(&database).ok()?;
            connection
                .query_row(
                    "SELECT block_id,heading,body FROM content_items
                     WHERE space_id=?1 AND document_id=?2
                       AND source_item_id IS NULL AND instr(heading,?3)>0
                     ORDER BY ordinal LIMIT 1",
                    params![space_id, document_id, needle],
                    |row| {
                        Ok((
                            row.get::<_, String>(0)?,
                            row.get::<_, String>(1)?,
                            row.get::<_, String>(2)?,
                        ))
                    },
                )
                .optional()
                .ok()
                .flatten()
        });
        tauri::async_runtime::block_on(async move {
            let client = reqwest::Client::builder()
                .user_agent(concat!(
                    "Craft-Search/",
                    env!("CARGO_PKG_VERSION"),
                    "-probe"
                ))
                .build()
                .expect("create probe client");
            let mut credential = load_credential(&space_id).expect("load stored credential");
            let token = refresh_access_token(&client, &mut credential)
                .await
                .expect("refresh probe token");
            save_credential(&space_id, &credential).expect("save rotated refresh credential");
            let authenticated = initialize_authenticated_connection(
                &client,
                &credential.mcp_url,
                token.access_token,
            )
            .await
            .expect("initialize probe connection");
            let available_tools = authenticated
                .tools
                .iter()
                .map(|tool| {
                    json!({
                        "name": tool.name,
                        "description": tool.description,
                        "inputs": tool.inputs,
                    })
                })
                .collect::<Vec<_>>();

            let help = call_craft_read_raw(&client, &authenticated.session, "help", 90_001)
                .await
                .map(|value| tool_result_text(&value))
                .unwrap_or_else(|error| error);
            let help_lines = help
                .lines()
                .filter(|line| {
                    let lower = line.to_ascii_lowercase();
                    [
                        "attachment",
                        "asset",
                        "download",
                        "file",
                        "image",
                        "resource",
                    ]
                    .iter()
                    .any(|needle| lower.contains(needle))
                })
                .take(80)
                .collect::<Vec<_>>();
            let command_output = if let Some(command) = probe_command.as_deref() {
                call_craft_read_raw(&client, &authenticated.session, command, 90_000)
                    .await
                    .map(|value| tool_result_text(&value))
                    .unwrap_or_else(|error| error)
            } else {
                String::new()
            };
            let write_command_output = if let Some(command) = write_probe_command.as_deref() {
                call_craft_tool_raw(
                    &client,
                    &authenticated.session,
                    "craft_write",
                    json!({"command": command}),
                    90_004,
                )
                .await
                .map(|value| tool_result_text(&value))
                .unwrap_or_else(|error| error)
            } else {
                String::new()
            };

            let command = format!("blocks get {document_id} --depth -1 --format json");
            let json_result =
                call_craft_read_raw(&client, &authenticated.session, &command, 90_002).await;
            let mut key_paths = BTreeSet::new();
            let mut url_hosts = BTreeSet::new();
            let mut file_nodes = Vec::<Value>::new();
            let mut discovered_attachments = Vec::<DiscoveredAttachment>::new();
            let mut matching_markdown_nodes = Vec::<Value>::new();
            let mut resolved_search_block = None::<String>;
            let mut resolved_block_url = None::<String>;
            let mut editor_url_nodes = Vec::<Value>::new();
            fn collect_editor_url_nodes(value: &Value, matches: &mut Vec<Value>) {
                match value {
                    Value::Object(map) => {
                        for (key, child) in map {
                            if let Some(text) = child.as_str() {
                                if Url::parse(text).ok().is_some_and(|url| {
                                    url.host_str() == Some("docs.craft.do")
                                        && url.path().starts_with("/editor/")
                                }) {
                                    matches.push(json!({
                                        "id": map.get("id").or_else(|| map.get("blockId")),
                                        "type": map.get("type"),
                                        "key": key,
                                        "url": text,
                                        "keys": map.keys().collect::<BTreeSet<_>>(),
                                    }));
                                }
                            }
                            collect_editor_url_nodes(child, matches);
                        }
                    }
                    Value::Array(items) => {
                        for child in items {
                            collect_editor_url_nodes(child, matches);
                        }
                    }
                    Value::String(text) => {
                        if let Ok(parsed) = serde_json::from_str::<Value>(text) {
                            collect_editor_url_nodes(&parsed, matches);
                        }
                    }
                    _ => {}
                }
            }
            fn collect_matching_markdown_nodes(
                value: &Value,
                needle: Option<&str>,
                ancestors: &[String],
                matching: &mut Vec<Value>,
            ) {
                match value {
                    Value::Object(map) => {
                        let current_id = map
                            .get("id")
                            .or_else(|| map.get("blockId"))
                            .and_then(Value::as_str)
                            .map(str::to_string);
                        let mut next_ancestors = ancestors.to_vec();
                        if let Some(id) = current_id.as_ref() {
                            next_ancestors.push(id.clone());
                        }
                        if let (Some(needle), Some(markdown)) =
                            (needle, map.get("markdown").and_then(Value::as_str))
                        {
                            if markdown.contains(needle) {
                                matching.push(json!({
                                    "id": current_id,
                                    "type": map.get("type"),
                                    "markdown": markdown,
                                    "ancestors": next_ancestors,
                                }));
                            }
                        }
                        for child in map.values() {
                            collect_matching_markdown_nodes(
                                child,
                                needle,
                                &next_ancestors,
                                matching,
                            );
                        }
                    }
                    Value::Array(items) => {
                        for child in items {
                            collect_matching_markdown_nodes(child, needle, ancestors, matching);
                        }
                    }
                    Value::String(text) => {
                        if let Ok(parsed) = serde_json::from_str::<Value>(text) {
                            collect_matching_markdown_nodes(&parsed, needle, ancestors, matching);
                        }
                    }
                    _ => {}
                }
            }
            fn inspect_value(
                value: &Value,
                path: &str,
                key_paths: &mut BTreeSet<String>,
                url_hosts: &mut BTreeSet<String>,
                file_nodes: &mut Vec<Value>,
            ) {
                match value {
                    Value::Object(map) => {
                        if map.get("fileName").and_then(Value::as_str).is_some()
                            && map.get("url").and_then(Value::as_str).is_some()
                        {
                            file_nodes.push(Value::Object(map.clone()));
                        }
                        for (key, child) in map {
                            let next = if path.is_empty() {
                                key.clone()
                            } else {
                                format!("{path}.{key}")
                            };
                            key_paths.insert(format!(
                                "{}:{}",
                                next,
                                match child {
                                    Value::Null => "null",
                                    Value::Bool(_) => "bool",
                                    Value::Number(_) => "number",
                                    Value::String(_) => "string",
                                    Value::Array(_) => "array",
                                    Value::Object(_) => "object",
                                }
                            ));
                            inspect_value(child, &next, key_paths, url_hosts, file_nodes);
                        }
                    }
                    Value::Array(items) => {
                        for child in items.iter().take(50) {
                            inspect_value(
                                child,
                                &format!("{path}[]"),
                                key_paths,
                                url_hosts,
                                file_nodes,
                            );
                        }
                    }
                    Value::String(text) => {
                        if let Ok(url) = Url::parse(text) {
                            if let Some(host) = url.host_str() {
                                url_hosts.insert(host.to_ascii_lowercase());
                            }
                        }
                        if let Ok(parsed) = serde_json::from_str::<Value>(text) {
                            inspect_value(&parsed, path, key_paths, url_hosts, file_nodes);
                        }
                    }
                    _ => {}
                }
            }
            let json_status = match json_result {
                Ok(value) => {
                    let parsed = parse_tool_json(&value).unwrap_or_else(|| value.clone());
                    discovered_attachments = discover_attachments_from_json(&parsed);
                    collect_editor_url_nodes(&parsed, &mut editor_url_nodes);
                    if let Some((parent_page_id, heading, body)) = search_chunk.as_ref() {
                        resolved_search_block = structured_block_id(
                            parent_page_id,
                            heading,
                            body,
                            &structured_block_hints(&parsed),
                        );
                    }
                    if let Some(block_id) = target_block_id
                        .as_deref()
                        .or(resolved_search_block.as_deref())
                    {
                        resolved_block_url = structured_block_url(&parsed, block_id);
                    }
                    collect_matching_markdown_nodes(
                        &parsed,
                        target_markdown_text.as_deref(),
                        &[],
                        &mut matching_markdown_nodes,
                    );
                    inspect_value(
                        &value,
                        "result",
                        &mut key_paths,
                        &mut url_hosts,
                        &mut file_nodes,
                    );
                    "ok".to_string()
                }
                Err(error) => error,
            };
            let pdf_node = file_nodes.iter().find(|node| {
                node.get("fileName")
                    .and_then(Value::as_str)
                    .is_some_and(|name| name.to_ascii_lowercase().ends_with(".pdf"))
            });
            let mut pdf_http = Value::Null;
            let mut pdf_images_view = Value::Null;
            if let Some(url) = pdf_node
                .and_then(|node| node.get("url"))
                .and_then(Value::as_str)
            {
                pdf_http = match client.get(url).header("Range", "bytes=0-31").send().await {
                    Ok(response) => {
                        let status = response.status().as_u16();
                        let mime = response
                            .headers()
                            .get(CONTENT_TYPE)
                            .and_then(|value| value.to_str().ok())
                            .map(str::to_string);
                        let mut stream = response.bytes_stream();
                        let magic = stream.next().await.and_then(Result::ok).map(|bytes| {
                            bytes
                                .iter()
                                .take(8)
                                .map(|byte| format!("{byte:02x}"))
                                .collect::<String>()
                        });
                        json!({ "status": status, "mime": mime, "magic": magic })
                    }
                    Err(error) => json!({ "error": error.to_string() }),
                };
                let view_command = format!("images view {url}");
                pdf_images_view = match call_craft_read_raw(
                    &client,
                    &authenticated.session,
                    &view_command,
                    90_003,
                )
                .await
                {
                    Ok(value) => json!({
                        "ok": true,
                        "contentTypes": value.get("content").and_then(Value::as_array)
                            .into_iter().flatten()
                            .filter_map(|item| item.get("type").and_then(Value::as_str))
                            .collect::<BTreeSet<_>>()
                    }),
                    Err(error) => json!({ "ok": false, "error": error }),
                };
            }
            let file_shapes = file_nodes
                .iter()
                .map(|node| {
                    let map = node.as_object().expect("file node object");
                    json!({
                        "keys": map.keys().collect::<BTreeSet<_>>(),
                        "extension": map.get("fileName").and_then(Value::as_str)
                            .and_then(|name| name.rsplit_once('.').map(|(_, ext)| ext.to_ascii_lowercase())),
                        "urlHost": map.get("url").and_then(Value::as_str)
                            .and_then(|url| Url::parse(url).ok())
                            .and_then(|url| url.host_str().map(str::to_string)),
                        "urlPathLength": map.get("url").and_then(Value::as_str)
                            .and_then(|url| Url::parse(url).ok()).map(|url| url.path().len()),
                    })
                })
                .take(30)
                .collect::<Vec<_>>();
            println!(
                "{}",
                json!({
                    "availableTools": available_tools,
                    "helpLines": help_lines,
                    "commandOutput": command_output,
                    "writeCommandOutput": write_command_output,
                    "jsonStatus": json_status,
                    "keyPaths": key_paths.into_iter().filter(|path| {
                        let lower = path.to_ascii_lowercase();
                        ["attachment", "asset", "download", "file", "image", "resource", "url"]
                            .iter().any(|needle| lower.contains(needle))
                    }).take(200).collect::<Vec<_>>(),
                    "urlHosts": url_hosts,
                    "fileShapes": file_shapes,
                    "targetAttachment": discovered_attachments.iter()
                        .filter(|attachment| target_attachment_url.as_deref()
                            .is_none_or(|target| attachment.url == target))
                        .map(|attachment| json!({
                            "url": attachment.url,
                            "blockId": attachment.block_id,
                            "title": attachment.title,
                            "linkKind": attachment.link_kind,
                        }))
                        .collect::<Vec<_>>(),
                    "matchingMarkdownNodes": matching_markdown_nodes,
                    "resolvedSearchBlock": resolved_search_block,
                    "resolvedBlockUrl": resolved_block_url,
                    "editorUrlNodes": editor_url_nodes.into_iter().take(50).collect::<Vec<_>>(),
                    "pdfHttp": pdf_http,
                    "pdfImagesView": pdf_images_view,
                })
            );
        });
    }

    #[test]
    fn live_refresh_structured_attachment_sources() {
        if std::env::var_os("CRAFT_SEARCH_LIVE_APPLY_ATTACHMENT_REFRESH").is_none() {
            return;
        }
        let database = PathBuf::from(
            std::env::var_os("CRAFT_SEARCH_LIVE_DATABASE")
                .expect("CRAFT_SEARCH_LIVE_DATABASE is required"),
        );
        let blob_root = PathBuf::from(
            std::env::var_os("CRAFT_SEARCH_LIVE_BLOB_ROOT")
                .expect("CRAFT_SEARCH_LIVE_BLOB_ROOT is required"),
        );
        let documents = {
            let connection = Connection::open(&database).expect("open live database");
            let mut statement = connection
                .prepare(
                    "SELECT DISTINCT d.space_id, d.id, d.title, d.path, d.folder_id,
                            d.markdown, d.modified_at, d.indexed_at, d.content_hash
                     FROM documents d JOIN source_items si
                       ON si.space_id=d.space_id AND si.document_id=d.id
                     WHERE si.source_type='craft_attachment'
                       AND si.status IN ('unavailable','rejected','discovered')",
                )
                .expect("prepare live refresh query");
            let rows = statement
                .query_map([], |row| {
                    Ok(IndexedDocument {
                        space_id: row.get(0)?,
                        id: row.get(1)?,
                        title: row.get(2)?,
                        path: row.get(3)?,
                        folder_id: row.get(4)?,
                        markdown: row.get(5)?,
                        modified_at: row.get(6)?,
                        indexed_at: row.get(7)?,
                        content_hash: row.get(8)?,
                        attachments: Vec::new(),
                        block_hints: Vec::new(),
                    })
                })
                .expect("query live refresh documents");
            rows.collect::<Result<Vec<_>, _>>()
                .expect("read live refresh documents")
        };
        tauri::async_runtime::block_on(async move {
            let client = reqwest::Client::builder()
                .user_agent(concat!(
                    "Craft-Search/",
                    env!("CARGO_PKG_VERSION"),
                    "-live-refresh"
                ))
                .build()
                .expect("create live refresh client");
            let mut by_space = HashMap::<String, Vec<IndexedDocument>>::new();
            for document in documents {
                by_space
                    .entry(document.space_id.clone())
                    .or_default()
                    .push(document);
            }
            let mut refreshed = Vec::new();
            let mut request_id = 95_000_u64;
            for (space_id, space_documents) in by_space {
                let mut credential = load_credential(&space_id).expect("load refresh credential");
                let token = refresh_access_token(&client, &mut credential)
                    .await
                    .expect("refresh access token");
                save_credential(&space_id, &credential).expect("save rotated credential");
                let authenticated = initialize_authenticated_connection(
                    &client,
                    &credential.mcp_url,
                    token.access_token,
                )
                .await
                .expect("initialize refresh connection");
                for mut document in space_documents {
                    request_id += 1;
                    let result = call_craft_read_raw(
                        &client,
                        &authenticated.session,
                        &format!("blocks get {} --depth -1 --format json", document.id),
                        request_id,
                    )
                    .await
                    .expect("read structured document");
                    let parsed = parse_tool_json(&result).unwrap_or(result);
                    let attachments = discover_attachments_from_json(&parsed);
                    if !attachments.is_empty() {
                        document.attachments = attachments;
                        refreshed.push(document);
                    }
                }
            }
            persist_attachment_refresh_batch(&database, &refreshed)
                .expect("persist fresh attachment URLs");
            let blob_store = BlobStore::open(&blob_root).expect("open live Blob store");
            for _ in 0..100 {
                if process_download_jobs(&database, &blob_store, PIPELINE_JOB_BATCH_SIZE, None)
                    .await
                    .expect("process live downloads")
                    == 0
                {
                    break;
                }
            }
            for _ in 0..100 {
                if process_pdf_jobs(&database, &blob_store)
                    .await
                    .expect("process live PDFs")
                    == 0
                {
                    break;
                }
            }
            let connection = open_database(&database).expect("read live refresh result");
            println!(
                "{}",
                json!({
                    "documentsRefreshed": refreshed.len(),
                    "pdfSources": connection.query_row(
                        "SELECT COUNT(*) FROM source_items WHERE mime_type='application/pdf'",
                        [], |row| row.get::<_, i64>(0)).unwrap_or(0),
                    "indexedPdfSources": connection.query_row(
                        "SELECT COUNT(*) FROM source_items WHERE mime_type='application/pdf' AND status='indexed'",
                        [], |row| row.get::<_, i64>(0)).unwrap_or(0),
                    "pdfNeedsOcr": connection.query_row(
                        "SELECT COUNT(*) FROM source_items WHERE mime_type='application/pdf' AND status='needs_ocr'",
                        [], |row| row.get::<_, i64>(0)).unwrap_or(0),
                    "pdfChunks": connection.query_row(
                        "SELECT COUNT(*) FROM content_items WHERE content_type='pdf_page'",
                        [], |row| row.get::<_, i64>(0)).unwrap_or(0),
                    "pendingJobs": connection.query_row(
                        "SELECT COUNT(*) FROM index_jobs WHERE status IN ('pending','running')",
                        [], |row| row.get::<_, i64>(0)).unwrap_or(0),
                    "failedJobs": connection.query_row(
                        "SELECT COUNT(*) FROM index_jobs WHERE status='failed'",
                        [], |row| row.get::<_, i64>(0)).unwrap_or(0),
                })
            );
        });
    }

    #[test]
    fn search_rebuild_claim_does_not_materialize_all_bodies() {
        let root =
            std::env::temp_dir().join(format!("hub-streaming-rebuild-{}", random_url_safe(8)));
        std::fs::create_dir_all(&root).unwrap();
        let database = root.join("test.sqlite3");
        let mut c = open_database(&database).unwrap();
        c.execute("INSERT INTO spaces(id,name,mcp_url,added_at) VALUES('stream','Stream','https://example.test',1)", []).unwrap();
        c.execute("INSERT INTO documents(space_id,id,title,path,markdown,indexed_at,content_hash) VALUES('stream','doc','Streaming','test','body',1,'hash')", []).unwrap();
        for n in 0..32 {
            c.execute("INSERT INTO content_items(id,space_id,document_id,block_id,content_type,heading,body,ordinal,source_hash) VALUES(?1,'stream','doc','doc','markdown_section','Streaming',?2,?3,'hash')",
                params![format!("stream:{n}"), "body ".repeat(8192), n]).unwrap();
        }
        let batch = claim_index_batch(&mut c, true, "streaming-test").unwrap();
        assert!(batch.rebuild);
        assert!(
            batch.records.is_empty(),
            "full rebuild must stream bodies from a pinned snapshot"
        );
        let snapshot = batch.rebuild_snapshot.as_ref().unwrap();
        c.execute(
            "UPDATE content_items SET body='later committed content'",
            [],
        )
        .unwrap();
        let mut read = 0;
        visit_index_records(
            &snapshot.connection,
            None,
            &snapshot.excluded,
            &mut |record| {
                assert_eq!(record.body, "body ".repeat(8192));
                read += 1;
                Ok(())
            },
        )
        .unwrap();
        assert_eq!(
            read, 32,
            "snapshot must preserve every body across later writes"
        );
        assert_eq!(
            c.query_row("SELECT body FROM content_items LIMIT 1", [], |r| r
                .get::<_, String>(0))
                .unwrap(),
            "later committed content"
        );
        drop(batch);
        drop(c);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn search_rebuild_streams_snapshot_and_replays_later_committed_document() {
        let root = std::env::temp_dir().join(format!("hub-rebuild-replay-{}", random_url_safe(8)));
        std::fs::create_dir_all(&root).unwrap();
        let database = root.join("test.sqlite3");
        let index_root = root.join("index");
        let mut c = open_database(&database).unwrap();
        c.execute("INSERT INTO spaces(id,name,mcp_url,added_at) VALUES('stream','Stream','https://example.test',1)", []).unwrap();
        let blobs = BlobStore::open(&root.join("blobs")).unwrap();
        let write = |body: &str| {
            persist_document_batch(
                &database,
                &blobs,
                vec![IndexedDocument {
                    space_id: "stream".into(),
                    id: "doc".into(),
                    title: "Snapshot".into(),
                    path: "test".into(),
                    folder_id: None,
                    markdown: body.into(),
                    modified_at: Some(1),
                    indexed_at: 1,
                    content_hash: format!("{:x}", Sha256::digest(body.as_bytes())),
                    attachments: vec![],
                    block_hints: vec![],
                }],
            )
        };
        write("snapshotoriginal").unwrap();
        let initial = open_or_create_active_search_index(&mut c, &index_root).unwrap();
        let batch = claim_index_batch(&mut c, true, "snapshot-worker").unwrap();
        assert!(batch.rebuild && batch.records.is_empty());
        write("snapshotupdated").unwrap();
        let rebuilt = batch
            .rebuild_snapshot
            .as_ref()
            .unwrap()
            .activate(&mut c, &index_root)
            .unwrap();
        let hits = |index: &SearchIndex, query| {
            index
                .search(query, 10, None, None, None, true, true, true, true)
                .unwrap()
        };
        assert_eq!(hits(&rebuilt, "snapshotoriginal").len(), 1);
        assert!(hits(&rebuilt, "snapshotupdated").is_empty());
        complete_index_jobs(&c, &batch.job_ids, "snapshot-worker").unwrap();
        assert_eq!(
            c.query_row(
                "SELECT status FROM index_jobs WHERE job_key='lexical:stream:doc'",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "pending",
            "an old snapshot may not complete the later producer's job"
        );
        drop(batch);
        flush_index_jobs_budgeted(
            &database,
            rebuilt.clone(),
            &index_root,
            2,
            Duration::from_secs(30),
        )
        .unwrap();
        assert!(hits(&rebuilt, "snapshotoriginal").is_empty());
        assert_eq!(hits(&rebuilt, "snapshotupdated").len(), 1);
        assert_eq!(
            c.query_row(
                "SELECT status FROM index_jobs WHERE job_key='lexical:stream:doc'",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "completed"
        );
        drop(rebuilt);
        drop(initial);
        drop(c);
        drop(blobs);
        forget_initialized_database(&database);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn library_management_search_rebuild_activates_a_new_generation_and_keeps_the_old_one() {
        let database = std::env::temp_dir().join(format!(
            "craft-search-generation-{}.sqlite3",
            random_url_safe(8)
        ));
        let root =
            std::env::temp_dir().join(format!("craft-search-generation-{}", random_url_safe(8)));
        std::fs::create_dir_all(root.join("generations")).unwrap();
        let mut connection = open_database(&database).unwrap();
        let initial = open_or_create_active_search_index(&mut connection, &root).unwrap();
        assert_eq!(initial.num_docs(), 0);
        let (initial_id, initial_relative): (String, String) = connection
            .query_row(
                "SELECT id, relative_path FROM search_index_generations WHERE status='active'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        let records = vec![IndexRecord {
            provider: "craft".to_string(),
            item_id: "space-a:doc-a:0".to_string(),
            document_key: "space-a:doc-a".to_string(),
            entity_key: "document:space-a:doc-a".to_string(),
            space_id: "space-a".to_string(),
            document_id: "doc-a".to_string(),
            block_id: "doc-a".to_string(),
            content_type: "markdown_section".to_string(),
            source_item_id: String::new(),
            source_title: String::new(),
            page_number: 0,
            title: "代际索引".to_string(),
            heading: "安全重建".to_string(),
            aliases: String::new(),
            tags: String::new(),
            body: "新索引构建完成后才会切换".to_string(),
            path: "测试".to_string(),
            folder_id: String::new(),
            modified_at: 1,
        }];
        let rebuilt = build_and_activate_search_generation(&mut connection, &root, |index| {
            index.rebuild(&records)?;
            Ok(records.len())
        })
        .unwrap();
        let active_id: String = connection
            .query_row(
                "SELECT id FROM search_index_generations WHERE status='active'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let retired_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM search_index_generations WHERE status='retired'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_ne!(active_id, initial_id);
        assert_eq!(retired_count, 1);
        assert!(safe_generation_path(&root, &initial_relative)
            .unwrap()
            .exists());
        assert_eq!(
            rebuilt
                .search("安全重建", 10, None, None, None, true, true, true, true)
                .unwrap()
                .len(),
            1
        );

        let failed = build_and_activate_search_generation(&mut connection, &root, |index| {
            index.rebuild_from(|append| {
                append(records[0].clone())?;
                Err("injected streaming read failure".into())
            })
        });
        assert!(failed
            .err()
            .unwrap()
            .contains("injected streaming read failure"));
        let still_active: String = connection
            .query_row(
                "SELECT id FROM search_index_generations WHERE status='active'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(still_active, active_id);
        assert_eq!(
            connection
                .query_row(
                    "SELECT count(*) FROM search_index_generations WHERE status='failed'",
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .unwrap(),
            1
        );
        assert_eq!(
            rebuilt
                .search("安全重建", 10, None, None, None, true, true, true, true)
                .unwrap()
                .len(),
            1
        );
        drop(rebuilt);
        drop(initial);

        drop(connection);
        let _ = std::fs::remove_file(database);
        let _ = std::fs::remove_dir_all(root);
    }

