    #[test]
    fn storage_migration_copies_nested_data_and_omits_bootstrap_file() {
        let root = std::env::temp_dir().join(format!(
            "craft-search-storage-test-{:016x}",
            rand::thread_rng().next_u64()
        ));
        let source = root.join("source");
        let target = root.join("target");
        fs::create_dir_all(source.join("blobs-v1/ab")).unwrap();
        fs::write(source.join("craft-search.sqlite3"), b"database").unwrap();
        fs::write(source.join("blobs-v1/ab/blob"), b"attachment").unwrap();
        fs::write(source.join(STORAGE_CONFIG_FILE), b"bootstrap").unwrap();

        let copied = copy_storage_tree(&source, &target).unwrap();
        assert_eq!(copied, (2, 18));
        assert_eq!(
            fs::read(target.join("craft-search.sqlite3")).unwrap(),
            b"database"
        );
        assert_eq!(
            fs::read(target.join("blobs-v1/ab/blob")).unwrap(),
            b"attachment"
        );
        assert!(!target.join(STORAGE_CONFIG_FILE).exists());

        let _ = fs::remove_dir_all(root);
    }

